const TIPOS=[['RPC','RPC'],['CTN','CTN'],['CTN10','CTN 10 lb'],['PLT','PLT']];
const TIPO_L={RPC:'RPC',CTN:'CTN',CTN10:'CTN 10 lb',PLT:'PLT'};
function tipoOf(p){const t=p&&p.tipo;return TIPO_L[t]?t:'RPC'}
/* v5: un productor puede llevar varios tipos de empaque; cada tipo tiene su propio conteo acumulado en la línea.
   El primer tipo usa p.acc (como antes) y los demás p.accX[tipo]. */
function tiposOf(p){const a=[];(Array.isArray(p&&p.tipos)?p.tipos:[]).forEach(t=>{if(TIPO_L[t]&&a.indexOf(t)<0)a.push(t)});if(!a.length)a.push(tipoOf(p));return a}
function accOf(p,t,mk){
  if(t===tiposOf(p)[0]){if(mk&&!p.acc)p.acc={};return p.acc||{}}
  if(mk){p.accX=p.accX||{};p.accX[t]=p.accX[t]||{}}
  return (p.accX&&p.accX[t])||{};
}
function tiposTxt(p){return tiposOf(p).map(t=>TIPO_L[t]).join(' y ')}
/* v6: cada calidad (hoja 1 = primera, hoja 1.5 = uno y medio) lleva un manifiesto propio por tipo de empaque.
   Línea = calidad + tipo: de 1 (solo RPC de primera) hasta 2 x 4 = 8. */
const TIPO_K=TIPOS.map(x=>x[0]);
const TIPO_CH={RPC:'RPC',CTN:'CTN (cartón)',CTN10:'CTN (10 lb)',PLT:'PLT'};
const CALIDAD_L={'1':'Primera','1.5':'Uno y medio'},CALIDAD_S={'1':'1ª','1.5':'1½'};
const lineKey=(q,t)=>q+'|'+t;
function lineLabel(L,short){const a=String(L).split('|');return short?(CALIDAD_S[a[0]]||a[0])+' '+(TIPO_L[a[1]]||a[1]):(CALIDAD_L[a[0]]||a[0])+' · '+(TIPO_CH[a[1]]||a[1])}
/* la antigua fila 230 CTN siempre cuenta como cartón */
const lineType=(t0,k)=>k==='ctn'?'CTN':t0;
function lineOrd(a,b){const x=a.split('|'),y=b.split('|');return (x[0]===y[0]?0:(x[0]==='1'?-1:1))||(TIPO_K.indexOf(x[1])-TIPO_K.indexOf(y[1]))}
/* o.manifiesto queda como la suma de los manifiestos por tipo (lo usan pedidos viejos, el Excel y la sincronización) */
function syncManSum(o){const s={};Object.keys(o.manT||{}).forEach(t=>{const m=o.manT[t]||{};CAL.forEach(c=>{const v=num(m[c.k]);if(v!=null)s[c.k]=(s[c.k]||0)+v})});o.manifiesto=s}
/* "RPC", "RPC y CTN", "CTN 10 lb"… según los tipos que usan los productores del pedido */
function tipoText(o){
  const ks=[];(o.productores||[]).forEach(p=>tiposOf(p).forEach(t=>{if(ks.indexOf(t)<0)ks.push(t)}));
  if(!ks.length)ks.push('RPC');
  ks.sort((a,b)=>TIPOS.findIndex(x=>x[0]===a)-TIPOS.findIndex(x=>x[0]===b));
  return ks.map(k=>TIPO_L[k]).join(' y ');
}
/* la fila "230 CTN" ya no se usa; solo se muestra en pedidos viejos que la tienen capturada, para no esconder datos */
function legacyCtn(o){return !!(o&&((o.productores||[]).some(p=>p.acc&&p.acc.ctn!=null)||(o.manifiesto&&o.manifiesto.ctn!=null)))}
function usesMM(o){return !!o&&((o.productores||[]).some(p=>tiposOf(p).indexOf('CTN10')>=0)||!!(o.manT&&o.manT.CTN10))}
function calUI(o){const s=legacyCtn(o)?CAL_STD:CAL_STD.filter(c=>c.k!=='ctn');return usesMM(o)?s.concat(CAL_MM):s}
/* calibres que se capturan por tipo: CTN 10 lb con su propia medida (más los de tamaño que un pedido viejo ya tenga capturados) */
function calsFor(t,o,first){
  if(t==='CTN10'){
    const old=CAL_STD.filter(c=>c.k!=='ctn'&&((o.productores||[]).some(p=>tiposOf(p).indexOf('CTN10')>=0&&accOf(p,'CTN10')[c.k]!=null)||!!(o.manT&&o.manT.CTN10&&o.manT.CTN10[c.k]!=null)));
    return CAL_MM.concat(old);
  }
  return CAL_STD.filter(c=>c.k!=='ctn'||(first&&legacyCtn(o)));
}
