function loadStatsF(){
  const d={emp:null,cal:'ALL',year:'ALL',month:'ALL',week:'ALL',desde:'',hasta:'',view:'rend',dir:'desc',_cache:null,_per:false};
  try{
    const j=JSON.parse(localStorage.getItem(LS_STATS)||'null');
    if(j&&typeof j==='object'){
      if(j.emp==='VL'||j.emp==='EC'||j.emp==='ALL')d.emp=j.emp;
      if(['ALL','1','1.5'].indexOf(String(j.cal))>=0)d.cal=String(j.cal);
      if(/^\d{4}$/.test(String(j.year)))d.year=String(j.year);
      if(/^(0[1-9]|1[0-2])$/.test(String(j.month)))d.month=String(j.month);
      if(/^\d{4}-\d{2}-\d{2}$/.test(String(j.desde||'')))d.desde=j.desde;
      if(/^\d{4}-\d{2}-\d{2}$/.test(String(j.hasta||'')))d.hasta=j.hasta;
      if(['rend','kilos','cal'].indexOf(j.view)>=0)d.view=j.view;
      if(j.dir==='asc')d.dir='asc';
      if(j.tab==='fin'||j.tab==='bi')d.tab=j.tab;if(['res','cxc','cxp','fin','emb','pre','ctb','bi'].indexOf(j.ftab)>=0)d.ftab=j.ftab;if(j.cxG==='grp')d.cxG='grp';if(j.pmode==='M')d.pmode='M';if(typeof j.csub==='string')d.csub=j.csub;if(['fecha','neto','margen'].indexOf(j.esort)>=0)d.esort=j.esort;if(/^\d{4}-S\d{2}$/.test(String(j.week||'')))d.week=j.week;if(typeof j.kpi==='string')d.kpi=j.kpi;if(['util','margen','pago'].indexOf(j.fsort)>=0)d.fsort=j.fsort;
    }
  }catch(e){}
  if(d.year==='ALL')d.month='ALL';
  if(d.desde&&d.hasta&&d.desde>d.hasta){const t=d.desde;d.desde=d.hasta;d.hasta=t}
  return d;
}
