/* ---------- utilidades ---------- */
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7);
const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>{if(v===null||v===undefined||v==='')return null;const n=typeof v==='number'?v:parseFloat(String(v).replace(/,/g,''));return isFinite(n)?n:null};
const n0=v=>num(v)||0;
const fmt=(v,d)=>v==null?'–':v.toLocaleString('es-MX',{minimumFractionDigits:d||0,maximumFractionDigits:d||0});
const clone=o=>JSON.parse(JSON.stringify(o));
const norm=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
/* SEC-002: pad() se usa al pintar códigos de productor con innerHTML; su salida va escapada.
   Con códigos numéricos (los reales) el resultado es idéntico al de antes. */
const pad=(n,l)=>esc(String(n).padStart(l,'0'));
/* SEC-002: lo que llega de la nube, de otro dispositivo o de un respaldo no se confía.
   Un id o código con comillas, < > ` o \ podría romper el HTML; esos valores la app no los genera nunca. */
const BAD_TXT=/["'<>`\\\u0000-\u001f]/,BAD_TXT_G=new RegExp(BAD_TXT.source,'g');
/* id corregido de forma estable (siempre el mismo para el mismo valor): cada carácter peligroso se cambia por _código_ */
const fixId=v=>typeof v==='string'&&v.length<=200?v.replace(BAD_TXT_G,c=>'_'+c.charCodeAt(0).toString(16)+'_'):uid();
function okId(v){return (typeof v==='string'&&v.length>0&&v.length<=200&&!BAD_TXT.test(v))||(typeof v==='number'&&isFinite(v))}
function okEmp(v){return v==null||(typeof v==='string'&&/^[A-Z]{1,4}$/.test(v))}
/* recorre el registro: un id inválido se reemplaza y un código inválido se vacía; lo demás queda igual */
function cleanRec(r,d){
  d=d||0;if(!r||typeof r!=='object'||d>20)return r;
  if(Array.isArray(r)){for(let i=0;i<r.length;i++)cleanRec(r[i],d+1);return r}
  for(const k of Object.keys(r)){
    const v=r[k];
    if(k==='id'&&v!=null&&!okId(v))r[k]=fixId(v);
    else if(k==='codigo'&&v!=null&&BAD_TXT.test(String(v)))r[k]=null;
    else if(v&&typeof v==='object')cleanRec(v,d+1);
  }
  return r;
}
function todayISO(){const d=new Date();return d.getFullYear()+'-'+pad(d.getMonth()+1,2)+'-'+pad(d.getDate(),2)}
function isoWeek(s){const d=new Date(s+'T12:00:00');if(isNaN(d))return '';const t=new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate()));const day=t.getUTCDay()||7;t.setUTCDate(t.getUTCDate()+4-day);const y0=new Date(Date.UTC(t.getUTCFullYear(),0,1));return Math.ceil(((t-y0)/86400000+1)/7)}
function fmtDate(s){if(!s)return '';const p=s.split('-');return p.length===3?p[2]+'/'+p[1]+'/'+p[0]:s}
function fmtUS(s){if(!s)return '';const p=s.split('-');return p.length===3?p[1]+'/'+p[2]+'/'+p[0]:s}

