const EYE_ON='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg>';
const EYE_OFF='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 3l18 18"/><path d="M10.6 5.2A10.6 10.6 0 0 1 12 5c6.4 0 10 7 10 7a17 17 0 0 1-3.2 4.1M6.5 6.6A17 17 0 0 0 2 12s3.6 7 10 7a10 10 0 0 0 4.4-1"/><path d="M9.9 9.9a3 3 0 0 0 4.2 4.2"/></svg>';
function PWI(inp){return '<span class="pwbox">'+inp+'<button type="button" class="eye" data-eye="1" aria-label="Mostrar contraseña" aria-pressed="false">'+EYE_ON+'</button></span>'}
document.addEventListener('mousedown',e=>{if(e.target.closest&&e.target.closest('[data-eye]'))e.preventDefault()});
document.addEventListener('click',e=>{
  const b=e.target.closest&&e.target.closest('[data-eye]');if(!b)return;
  const inp=b.parentNode.querySelector('input');if(!inp)return;
  const show=inp.type==='password';
  inp.type=show?'text':'password';
  b.setAttribute('aria-pressed',show?'true':'false');
  b.setAttribute('aria-label',show?'Ocultar contraseña':'Mostrar contraseña');
  b.innerHTML=show?EYE_OFF:EYE_ON;
  try{inp.focus({preventScroll:true});const l=inp.value.length;inp.setSelectionRange(l,l)}catch(x){}
},true);

