const EMPAQUES=[['RPC','RPC'],['1.5','1-1/2 (segunda)'],['CTN','CTN (cartón)'],['CTN10','CTN 10 lb'],['PLT','PLT']];
const EMP_PL={'RPC':'RPC','1.5':'RPC','CTN':'CARTON','CTN10':'CARTON 10 LBS','PLT':'PLT'};
