  try{(sheetsOf(o)||[o]).forEach(x=>(x.productores||[]).forEach(p=>{const k=prodKey(x,p),ts=tiposOf(p);if(k&&!m[k]&&ts.length===1)m[k]=ts[0]}))}catch(e){}
