(function(){try{const r=JSON.parse(localStorage.getItem(LS_REG)||'null');if(r&&typeof r==='object')REG=Object.assign(REG,r)}catch(e){}if(!Array.isArray(REG.transportistas))REG.transportistas=[{id:'t-jlr',n:'JESUS LAGUNES RODRIGUEZ',tel:'271 177 0112'}];if(!Array.isArray(REG.trailers))REG.trailers=[];if(!Array.isArray(REG.clientes))REG.clientes=CAT_SEED.cliente.map((n,i)=>({id:'c-seed'+i,n:n}))})();
