  for(const o of sheetsList){for(const p of o.productores){
    const k=prodKey(o,p);
    if(norm(k)===n||norm(p.nombre)===n||(digits!=null&&p.codigo===digits)||(/^(vl|ec)-?\d+$/.test(n)&&p.codigo&&norm(o.emp+'-'+pad(p.codigo,3))===n.replace(/^(vl|ec)-?/,m=>m.slice(0,2)+'-').replace(/-(\d+)$/,(x,d)=>'-'+pad(+d,3))))return k;
  }}
