/* tipo de empaque de la tarima (1-1/2 es RPC de segunda) y línea calidad|tipo de una línea de tarima */
function palTipo(p){const e=palEmp(p);return e==='1.5'?'RPC':e}
/* v7.9: la calidad va por línea (en una tarima puede ir primera y 1-1/2); la presentación es una sola por tarima. Las tarimas viejas toman la calidad de la marca */
function lineQ(p,l){return l&&(l.q==='1'||l.q==='1.5')?l.q:qualityOfMarca(p.marca)}
function lineOfCal(p,ck,l,q){return lineKey(q||lineQ(p,l),lineType(palTipo(p),ck||''))}
