function palQs(p){const s=[];(p.lines||[]).forEach(l=>{if(!(n0(l.cant)>0)&&!l.cal)return;const q=lineQ(p,l);if(s.indexOf(q)<0)s.push(q)});if(!s.length)s.push(qualityOfMarca(p.marca));return s.sort()}
