    ws.send(JSON.stringify({topic:RT_TOPIC,event:'phx_join',ref:RT.jref,join_ref:RT.jref,payload:{config:{broadcast:{self:false,ack:false},presence:{key:RT.dev},postgres_changes:[{event:'*',schema:'public'}]},access_token:RT.tok}}));
