  if(m.event==='presence_diff'){Object.keys(P.leaves||{}).forEach(k=>delete RT.who[k]);Object.keys(P.joins||{}).forEach(k=>{const a=(P.joins[k].metas||[])[0];if(a)RT.who[k]=a});setSync();return}
