function roleRaw(tok){try{const p=JSON.parse(atob(String(tok).split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));return (p.app_metadata&&p.app_metadata.rol)||''}catch(e){return ''}}
const ROL_EF={superadmin:'admin',inocuidad:'jefe'};
function roleOf(tok){const r=roleRaw(tok);return ROL_EF[r]||r}
let roRole=false;
function applyRole(){const rr=session?roleOf(session.access_token):'';ro=roRole=rr==='lector'||rr==='contador'||rr==='tarima'||rr==='segundas'||(typeof authUser!=='undefined'&&!!authUser&&(authUser.rol==='lector'||authUser.rol==='contador'||authUser.rol==='tarima'||authUser.rol==='segundas'))}
function saveSession(s){session=s;applyRole();try{localStorage.setItem(LS_SESSION,JSON.stringify(s))}catch(e){}}
function sessionFrom(j){return{access_token:j.access_token,refresh_token:j.refresh_token,expires_at:Date.now()+(j.expires_in||3600)*1000-30000,email:(j.user&&j.user.email)||(session&&session.email)||''}}
async function login(email,pw){const j=await sb('/auth/v1/token?grant_type=password',{method:'POST',body:{email:email,password:pw},auth:false});saveSession(sessionFrom(j))}
async function ensureSession(){
  if(!session)throw Object.assign(new Error('login'),{code:'login'});
  if(Date.now()<session.expires_at)return;
  try{
    const j=await sb('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:{refresh_token:session.refresh_token},auth:false});
    saveSession(sessionFrom(j));
  }catch(e){
    if(e&&(e.status===400||e.status===401||e.status===403)){session=null;ro=roRole=false;try{localStorage.removeItem(LS_SESSION)}catch(x){}throw Object.assign(new Error('login'),{code:'login'})}
    throw e;
  }
}
async function doSync(auto){
  if(syncing)return;
  syncing=true;setSync();
  let pulled=0,pushed=0,ok=false;const rn0=remoteN;
  try{
    if(!LOCAL.on)await ensureSession(); /* v8.41: en modo local no hace falta renovar la sesión por internet */
    /* 1. bajar lo que esta mas nuevo en la nube (o en la HP, en modo local) */
    const idx=await sbAll('/rest/v1/orders?select=id,updated_at&order=updated_at.desc');
    let merged=0;
    const need=idx.filter(r=>okId(r.id)).filter(r=>{const l=orders.find(x=>x.id===r.id),t=Number(r.updated_at)||0;return !l||(SYNCB.so[r.id]!=null?t!==SYNCB.so[r.id]:t>(l.updatedAt||0)||dirty.has(r.id))});
    for(let i=0;i<need.length;i+=20){
      const ids=need.slice(i,i+20).map(r=>r.id).join(',');
      const rows=(await sb('/rest/v1/orders?select=id,updated_at,data&id=in.('+ids+')'))||[];
      rows.forEach(r=>{
        if(!r.data||!Array.isArray(r.data.productores)||!okId(r.id))return;
        const t=Number(r.updated_at)||0,k=orders.findIndex(x=>x.id===r.id);
        const d=JSON.parse(JSON.stringify(r.data||{}));d.id=r.id;d.updatedAt=t;
        if(k>=0&&dirty.has(r.id)){
          /* los dos dispositivos cambiaron este pedido: se juntan y se vuelve a subir */
          const m=merge3(SYNCB.o[r.id],orders[k],d);m.id=r.id;m.updatedAt=Math.max(Date.now(),t+1);orders[k]=m;merged++;pulled++;
        }else if(k<0||t!==(orders[k].updatedAt||0)){
          if(k<0)orders.push(d);else orders[k]=d;
          dirty.delete(r.id);pulled++;
        }
        SYNCB.so[r.id]=t;setBase('o',r.id,d);
      });
    }
    if(pulled)normOrders();
    if(pulled)accRepairAll();
    if(pulled&&typeof tdsSnapAll==='function')tdsSnapAll();
    /* 2. subir lo pendiente de este dispositivo */
    /* v8.4: solo se escribe si el servidor sigue en la versión que conoce este dispositivo; si otro usuario guardó
       en medio, se baja la suya, se junta campo por campo y se vuelve a intentar (nadie pisa lo del otro) */
    const sent=ro?[]:[...dirty].map(id=>orders.find(o=>o.id===id)).filter(Boolean).map(o=>({o:o,t:o.updatedAt}));
    const oDone=x=>{SYNCB.so[x.o.id]=x.t;setBase('o',x.o.id,x.o);if(x.o.updatedAt===x.t)dirty.delete(x.o.id);pushed++};
    const oPull=async id=>{const r=((await sb('/rest/v1/orders?select=id,updated_at,data&id=eq.'+encodeURIComponent(id)))||[])[0],k=orders.findIndex(x=>x.id===id);if(!r||!r.data||k<0)return null;
      const t=Number(r.updated_at)||0,d=JSON.parse(JSON.stringify(r.data));d.id=id;d.updatedAt=t;const m=merge3(SYNCB.o[id],orders[k],d);m.id=id;m.updatedAt=Math.max(Date.now(),t+1);orders[k]=m;SYNCB.so[id]=t;setBase('o',id,d);merged++;pulled++;return {o:m,t:m.updatedAt}};
    const conf=await pushCas('orders',sent.map(x=>({x:x,id:x.o.id,t:x.t,d:x.o,base:SYNCB.so[x.o.id]})),oDone);
    for(const id of conf){for(let n=0;n<3;n++){const x=await oPull(id);if(!x)break;if(await pushOne('orders',{id:id,t:x.t,d:x.o,base:SYNCB.so[id]})){oDone(x);break}}}
    if(merged&&typeof tdsSnapAll==='function')tdsSnapAll();
    if(!LOCAL.on){ /* nube: todo. HP (v8.46): ver la rama «else» abajo; precios, finanzas y catálogos esperan a la nube */
    /* 3. lista de productores (v8.29: lo que no se pudo mandar ya no frena la descarga) */
    try{await flushLista()}catch(e){}
    try{await prodPull()}catch(e){}
    await syncReg();
    await syncPer();
    await syncPar();
    await syncFin();
    await syncPesos();
    await syncPres();
    await syncCtb();
    await syncMovTab(COB,'cobros');
    await syncMovTab(PAG,'pagos');
    await syncInv();
    await syncLog();
    try{await syncEvi()}catch(e){} /* v8.43 · fotos y tickets */
    await syncCont();
    await avSync();avPushInit();
    meta.lastSync=Date.now();saveMeta();NET.ok=true;NET.down=0;provCheck();saveLocal();ok=true;
    }else{
      /* v8.46: entradas, conteos, registro de cambios y fotos también pasan por la HP, en vivo */
      lanMark();
      await syncInv();await syncCont();await syncLog();
      try{await lanFotosUp()}catch(e){errNote('fotos a la HP',e)}
      await syncEvi();
      LOCAL.ok=Date.now();LOCAL.fail=0;LOCAL.err='';saveLocal();ok=true}
    saveSyncB();
    if(!auto){const o=RT.st==='on'?rtNames():[];toast('Listo: '+pushed+' enviados, '+pulled+' recibidos'+(merged?' · '+merged+(merged===1?' pedido unido':' pedidos unidos')+' con cambios de otro dispositivo':'')+(RT.st==='on'?' · en vivo'+(o.length?' con '+o.join(', '):''):''))}
    else if(merged)toast(merged===1?'Se juntó un pedido con cambios de otro dispositivo':'Se juntaron '+merged+' pedidos con cambios de otro dispositivo');
  }catch(e){
    if(e&&(e.status||!e.local)&&!(e&&e.code==='login')&&(e.status||LOCAL.on))errNote(LOCAL.on?'sincronizar con la HP':'sincronizar con la nube',e);
    if(LOCAL.on){LOCAL.fail++;if(!auto)toast(hubErr(e))}
    else{if(!(e&&e.code==='login')){NET.ok=false;if(!NET.down)NET.down=Date.now()}
    if(e&&e.code==='login'){if(!auto){sheet={kind:'login',lf:{email:(session&&session.email)||'',pw:''},err:'Tu sesión venció. Vuelve a entrar.'};renderSheet()}}
    else if(!auto)toast(e&&e.status?'El servidor respondió '+e.status+'. Revisa la configuración.':'Sin conexión. Tus datos siguen guardados aquí.');}
  }finally{syncing=false;if(ok&&!LOCAL.on)setTimeout(eviPump,500);autoFail=ok?0:Math.min(autoFail+1,6);invalidateStats();saveLocal();setSync();if(!auto||pulled>0||remoteN>rn0)softRender();if(ok)rtStart();if(RT.pend){RT.pend=false;rtPull()}}
}
async function doSheetLogin(){
  if(!sheet||sheet.kind!=='login'||sheet.busy)return;
  const lf=sheet.lf||{};
  if(!lf.email||!lf.pw){sheet.err='Escribe el correo y la contraseña.';renderSheet();return}
  sheet.busy=true;sheet.err='';renderSheet();
  try{await login(String(lf.email).trim(),lf.pw);sheet=null;renderSheet();doSync()}
  catch(e){
    if(!sheet||sheet.kind!=='login')return;
    sheet.busy=false;
    sheet.err=(e&&(e.status===400||e.status===401))?'Correo o contraseña incorrectos.':(e&&e.status?'El servidor respondió '+e.status+'. Revisa la configuración.':'Sin conexión. Intenta cuando tengas red.');
    renderSheet();
  }
}
function loginHtml(){
  const lf=sheet.lf||{email:'',pw:''};
  return '<h3>Entrar para sincronizar</h3><p class="note" style="margin-bottom:10px">Usa el correo y la contraseña que se creó para el equipo. Solo hace falta una vez por teléfono.</p>'
   +'<label class="fld" for="lf-email"><span>Correo</span><input class="in txt" id="lf-email" type="email" autocomplete="username" autocapitalize="none" data-lf="email" value="'+esc(lf.email)+'"></label>'
   +'<label class="fld" for="lf-pw"><span>Contraseña</span>'+PWI('<input class="in txt" id="lf-pw" type="password" autocomplete="current-password" data-lf="pw" value="'+esc(lf.pw)+'">')+'</label>'
   +(sheet.err?'<p class="note" style="color:var(--crit);margin-bottom:8px" role="alert">'+esc(sheet.err)+'</p>':'')
   +'<div class="srow2"><button class="btn" data-act="closesheet">Cancelar</button><button class="btn primary" data-act="dologin"'+(sheet.busy?' disabled':'')+'>'+(sheet.busy?'Entrando…':'Entrar y sincronizar')+'</button></div>';
}
function syncInfoHtml(){
  return '<h3>Sincronización sin configurar</h3><p class="note">Falta poner la dirección y la clave pública de la base de datos en el archivo config.js. La guía incluida explica cómo. Mientras tanto la app guarda todo en este teléfono y puedes usar el respaldo.</p><div class="srow2"><button class="btn primary" data-act="closesheet">Entendido</button></div>';
}
function backupPanel(){
  const last=meta.lastSync?new Date(meta.lastSync).toLocaleString('es-MX',{dateStyle:'medium',timeStyle:'short'}):'nunca';
  return '<div class="sec">Sincronización y respaldo</div><div class="panel"><div class="kv"><span>Última sincronización</span><b>'+esc(last)+'</b></div><div class="kv" style="border-bottom:0"><span>Pendientes de enviar</span><b>'+dirty.size+'</b></div>'
   +(cfgOK()?'':'<p class="note" style="margin-top:8px">La sincronización aún no está configurada. Mientras tanto, usa el respaldo.</p>')
   +'<p class="note" style="margin-top:8px">'+(canFin()?'El respaldo completo incluye pedidos, entradas, precios, cierres, cobros, pagos, presupuesto y contabilidad, sin cifrar: guárdalo solo en equipos o carpetas de la empresa y no lo compartas por WhatsApp ni correo.':'El respaldo incluye pedidos, entradas y catálogos.')+' El respaldo diario automático queda pendiente para el plan Pro de Supabase; mientras tanto, descárgalo al cerrar cada semana.</p>'
   +'<div class="pact"><button class="btn sm" data-act="exportjson">'+(canFin()?'Descargar respaldo completo':'Descargar respaldo')+'</button>'+(isAdmin()?'<button class="btn sm" data-act="importjson">Importar respaldo</button>':'')+(session?'<button class="btn sm" data-act="logout">Cerrar sesión</button>':'')+'</div><input type="file" id="impfile" accept=".json,application/json" hidden></div>';
}
/* v8.16: respaldo completo. Con permisos de Finanzas incluye precios, versiones, cierres, cobros, pagos, presupuesto y contabilidad;
   el jefe de empaque respalda pedidos, entradas y catálogos sin dinero. El respaldo diario automático queda para el plan Pro de Supabase. */
async function exportBackup(){
  /* v8.37 · SEC-010: el respaldo completo lleva precios, cobros, pagos y contabilidad sin cifrar; se avisa antes de bajarlo */
  if(canFin()&&!window.confirm('El respaldo completo incluye precios, costos, cobros, pagos, presupuesto y contabilidad, sin contraseña.\n\nGuárdalo solo en la computadora o carpeta de la empresa. No lo mandes por WhatsApp ni por correo.\n\n¿Descargarlo?'))return;
  const f=canFin(),d={app:'registro-empaque',v:2,exportado:new Date().toISOString(),version:APP_VER,por:(authUser&&(authUser.name||authUser.user))||'',completo:f,
    orders:orders,entradas:INV.entradas,pesos:PESOS.kg,decisiones:DEC.m,preciosSeg:PSG.m,periodos:PER.list,registros:REG,productores:LISTA};
  if(f)Object.assign(d,{finanzas:{VL:FIN.VL,EC:FIN.EC},parametros:PAR.list,cierres:CIE.list,cobros:COB.list,pagos:PAG.list,presupuesto:PPTO.d,contable:CTB.d,bitacora:LOG.list});
  await saveFile('Respaldo_Empaque_'+(f?'completo_':'')+todayISO()+'.json',new Blob([JSON.stringify(d)],{type:'application/json'}));
}
/* v8.37 · SEC-004: un respaldo es un archivo que pudo pasar por WhatsApp o correo; no se confía en él.
   Solo la administración importa; cada pedido y entrada se valida; la fecha del archivo no decide (un updatedAt
   adelantado ya no pisa lo de los demás) y antes de reemplazar se pide confirmación con el conteo. */
const IMP_MAX=5e6;
function impOk(r,d){/* estructura sana: sin textos enormes ni anidamiento excesivo, números finitos */
  d=d||0;if(d>20)return false;if(r==null)return true;const t=typeof r;
  if(t==='string')return r.length<=5000;if(t==='number')return isFinite(r);if(t==='boolean')return true;
  if(Array.isArray(r))return r.length<=5000&&r.every(x=>impOk(x,d+1));
  if(t==='object'){const k=Object.keys(r);return k.length<=500&&k.every(x=>x.length<=100&&impOk(r[x],d+1))}
  return false;
}
function impOrder(r){return !!r&&typeof r==='object'&&!Array.isArray(r)&&okId(r.id)&&okEmp(r.emp)&&Array.isArray(r.productores)&&r.productores.length<=500&&r.productores.every(p=>p&&typeof p==='object')&&impOk(r)}
function impEntrada(r){return !!r&&typeof r==='object'&&!Array.isArray(r)&&okId(r.id)&&impOk(r)}
function importBackup(inp){
  const f=inp.files&&inp.files[0];if(!f)return;
  if(!isAdmin()){toast('Solo la administración importa respaldos');inp.value='';return}
  if(f.size>IMP_MAX*4){toast('El archivo es demasiado grande para ser un respaldo');inp.value='';return}
  const rd=new FileReader();
  rd.onload=function(){
    try{
      const j=JSON.parse(rd.result);const list=Array.isArray(j)?j:(j&&j.orders);
      if(!Array.isArray(list))throw new Error('formato');
      const now=Date.now();let bad=0;
      const os=list.filter(r=>{const k=impOrder(r);if(!k)bad++;return k}).map(r=>cleanRec(clone(r)));
      const es=(j&&Array.isArray(j.entradas)?j.entradas:[]).filter(r=>{const k=impEntrada(r);if(!k)bad++;return k}).map(r=>cleanRec(clone(r)));
      /* la fecha del archivo se acota a «ahora»: un respaldo no puede ganarle a un cambio más reciente */
      const tOf=r=>Math.min(+r.updatedAt||0,now);
      const oNew=os.filter(r=>!orders.some(x=>x.id===r.id)),oRep=os.filter(r=>{const x=orders.find(y=>y.id===r.id);return x&&tOf(r)>(x.updatedAt||0)});
      const eNew=es.filter(r=>!INV.entradas.some(x=>x.id===r.id)),eRep=es.filter(r=>{const x=INV.entradas.find(y=>y.id===r.id);return x&&tOf(r)>(x.updatedAt||0)});
      if(!oNew.length&&!oRep.length&&!eNew.length&&!eRep.length){toast(bad?'El respaldo no trae cambios válidos ('+bad+' registros descartados)':'El respaldo no trae nada más nuevo que lo que ya tienes');inp.value='';return}
      const msg='Importar respaldo:\n· '+oNew.length+' pedidos nuevos y '+oRep.length+' pedidos que REEMPLAZAN a los actuales\n· '+eNew.length+' entradas nuevas y '+eRep.length+' que reemplazan'+(bad?'\n· '+bad+' registros no válidos se descartan':'')+'\n\nLo importado se sube a la base y lo verán todos. ¿Continuar?';
      if(!window.confirm(msg)){toast('Importación cancelada');inp.value='';return}
      /* lo importado queda como un cambio de ahora: la sincronización lo junta con el servidor como cualquier edición */
      oNew.concat(oRep).forEach(r=>{r.updatedAt=now;const i=orders.findIndex(x=>x.id===r.id);if(i<0)orders.push(r);else orders[i]=r;dirty.add(r.id)});
      eNew.concat(eRep).forEach(r=>{r.updatedAt=now;const i=INV.entradas.findIndex(x=>x.id===r.id);if(i<0)INV.entradas.push(r);else INV.entradas[i]=r;if(INV.dirty.indexOf(r.id)<0)INV.dirty.push(r.id)});
      const n=oNew.length+oRep.length,ne=eNew.length+eRep.length;
      if(ne)saveInv();
      logAdd({k:'note',where:'Respaldo',ctx:{t:'r',id:'import',cod:'Respaldo'},lab:'Respaldo importado',o:'',n:n+' pedidos y '+ne+' entradas'+(bad?' · '+bad+' descartados':'')});
      normOrders();invalidateStats();saveLocal();setSync();render();toast(n+' pedidos'+(ne?' y '+ne+' entradas':'')+' importados'+(bad?' · '+bad+' descartados':''));
    }catch(e){toast('El archivo no es un respaldo válido')}
    inp.value='';
  };
  rd.readAsText(f);
}
function registerSW(){
  try{
    const C=window.Capacitor;if(C&&C.isNativePlatform&&C.isNativePlatform())return;
    if(navigator.storage&&navigator.storage.persist)navigator.storage.persist().catch(()=>{});
    if('serviceWorker' in navigator&&(location.protocol==='https:'||location.hostname==='localhost'))navigator.serviceWorker.register('sw.js').catch(()=>{});
  }catch(e){}
}


