const NAV_ITEMS=[['menu','Inicio'],['inv','Recepción','Recep.'],['alm','Almacén'],['orders','Empaque'],['traz','Trazabilidad','Trazab.'],['dv','Documentos','Docs'],['adm','Administración','Admin.']];
