/* v8.31: saludo del menú principal según la hora: días hasta las 12, tardes hasta las 8 de la noche */
function greet(){const h=new Date().getHours(),s=h>=5&&h<12?'Buenos días':h>=12&&h<20?'Buenas tardes':'Buenas noches';const n=authUser&&(authUser.name||authUser.user)||'';return s+(n?', '+n:'')}
function topbar(title,back,sub){
  return `<header class="top"><div class="topin">${back?`<button class="icon back" data-act="${back}" aria-label="Volver" title="Volver"><svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true"><path d="M15 5l-7 7 7 7" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></svg></button>`:''}<span class="empchip" title="${esc(EMPS[emp].name)}"><img src="${ICO[emp]}" alt=""><span class="ect">${emp}</span></span><div class="ttl">${esc(title)}${sub?`<small class="greet">${esc(sub)}</small>`:''}</div>${canAdm()?'<button class="icon hist" data-act="logopen" aria-label="Registro de cambios" title="Registro de cambios"><svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true"><path d="M3 12a9 9 0 1 0 3-6.7" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><path d="M3 4v4h4" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><path d="M12 7v5l3 2" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></button>':''}<button class="sbtn" id="syncpill" data-act="sync" data-s="${syncState()}" aria-label="${esc(syncLabel())}" title="${esc(syncLabel())}"><span class="sring"><b>S</b></span><i class="sdot"></i><i class="scnt"${rtCount()?'':' hidden'}>${rtCount()||''}</i></button></div>${netbarHtml()}</header>`;
}
/* v8.33.1: cuando hay barra de navegación abajo (teléfono y tablet) y además una barra de botón (dock), el dock se apila
   encima de la navegación; antes la navegación lo tapaba (Entrada de Fruta › «+ Agregar productor»). */
function navDockFit(){
  const n=$app.querySelector('.bnav'),R=document.documentElement;let h=0;
  if(n){const r=n.getBoundingClientRect();if(r.width>=innerWidth*0.9&&r.top>innerHeight/2)h=Math.round(r.height)}
  R.style.setProperty('--bnh',h+'px');
}
window.addEventListener('resize',()=>{if(typeof navDockFit==='function')navDockFit()});
function render(){
  needsRender=false;
  normOrders();applyTheme();
  if(!authUser){$app.className='';document.body.classList.remove('hasnav');$app.innerHTML=loginView();return}
  /* v8.0: el FIN vigente sigue a las versiones; sin base de datos, el administrador migra al abrir */
  if(!render.fp){render.fp=1;try{finFromPar()}catch(e){}}
  if(!cfgOK()&&isAdmin()&&parNeedsMig())try{parMigrate()}catch(e){}
  if((view==='order'||view==='trazo'||view==='docs'||view==='dvt')&&!cur()){curId=null;view=view==='trazo'?'traz':view==='dvt'?'dv':'orders'}
  /* dentro de un pedido, los colores y logotipos son los de la empresa por la que sale */
  if((view==='order'||view==='trazo'||view==='docs'||view==='dvt')&&cur()&&cur().emp!==emp&&EMPS[cur().emp])setEmp(cur().emp);
  /* una semana cerrada deja sus pedidos en solo lectura */
  /* el contador captura cobros y pagos en Finanzas; fuera de ahí sigue en solo lectura */
  if(isTarima()&&view!=='conteo'&&view!=='menu'){view='menu';curId=null}
  if(view==='adm'&&!canAdm())view='menu';
  if(view==='log'&&rolReal()==='jefe')view='menu';
  if(isSegC()&&view!=='segcnt'){view='segcnt';curId=null}
  if((view==='conteo'||view==='segcnt')&&!isTarima()&&!isSegC()&&!supOK()){view='menu';SUP=null}
  ro=(view==='fin'&&isContador())||(view==='conteo'&&isTarima())||(view==='segcnt'&&isSegC())?false:roRole||((view==='order'||view==='trazo'||view==='docs'||view==='dvt')&&orderLocked(cur()))||(view==='trazo'&&manClosed(cur()));
  /* v8.36.1: inocuidad vuelve a editar como jefe de empaque (además de productores y logística); solo no borra pedidos (lo cuida la base) */
  $app.className=ro?'ro':'';
  if(view==='stats'&&!canStats())view='menu';
  if(isContador()&&['order','orders','traz','trazo','docs','inv','prods','log','dv','dvt','alm','esp'].indexOf(view)>=0){view='fin';curId=null}
  if(view==='fin'&&!canFin())view='menu';
  const fp=view==='trazo'&&render.vk&&render.vk.indexOf('trazo|')===0?(flipPrev||flipSnap()):null;flipPrev=null;
  /* v8.28: si es la misma pantalla, se conserva lo que estaba a la vista (listas desplazadas, secciones abiertas, foco y posición) */
  const ui0=render.vk===[view,curId,tab,docTab,statsF.ftab,statsF.tab].join('|')?uiSnap($app):null,sy0=window.scrollY;
  $app.innerHTML=view==='order'?orderView(cur()):view==='orders'?listView():view==='stats'?statsView():view==='fin'?finSecView():view==='traz'?trazList():view==='trazo'?trazView(cur()):view==='docs'?docsView(cur()):view==='inv'?invView():view==='prods'?prodsView():view==='log'?logView():view==='dv'?dvView():view==='dvt'?dvtView(cur()):view==='conteo'?conteoView():view==='segcnt'?scView():view==='alm'?almView():view==='esp'?espView():view==='adm'?admView():menuView();
  if((view==='order'||view==='docs'||view==='trazo'||view==='dvt')&&cur()){const bn=provBanner(cur());if(bn){const hd=$app.querySelector('header.top');if(hd)hd.insertAdjacentHTML('afterend',bn)}}
  if(ro)$app.querySelectorAll('input.in,select.in').forEach(i=>{i.readOnly=true;if(i.tagName==='SELECT')i.disabled=true});
  if(navOn()&&view!=='prods'&&view!=='log')$app.insertAdjacentHTML('beforeend',navHtml());
  document.body.classList.toggle('hasnav',!!$app.querySelector('.bnav'));
  navDockFit();
  /* v8.11: animación al cambiar de pantalla o pestaña y al abrir una tarima (no en cada redibujo) */
  {const vk=[view,curId,tab,docTab,statsF.ftab,statsF.tab].join('|');if(render.vk!==undefined&&render.vk!==vk){const m=$app.querySelector('main');if(m)m.classList.add('vin')}render.vk=vk;
   if(view==='trazo'&&palOpen&&render.po!==palOpen){const el=document.getElementById('pal-'+palOpen);if(el&&el.classList.contains('pal'))el.classList.add('pin')}render.po=view==='trazo'?palOpen:null}
  if(ui0){if(focusId)ui0.foc=null;uiRestore($app,ui0);if(Math.abs(window.scrollY-sy0)>1)window.scrollTo(0,sy0)}
  updateDerived();if(view==='trazo'){updateTraz();if(fp)flipPlay(fp)}if(view==='docs')liveSched(0);xlvAll();
  if(typeof tdsSnapAll==='function')tdsSnapAll();
  $app.querySelectorAll('[data-cs]').forEach(cs=>cardPage(cs,+cs.dataset.pg0||0,false));
  if(scrollToP){const el=document.getElementById('pc-'+scrollToP);if(el)el.scrollIntoView({block:'start',behavior:'smooth'});scrollToP=null}
  if(focusId){const el=document.getElementById(focusId);if(el){el.scrollIntoView({block:'center'});try{el.focus({preventScroll:true})}catch(x){}}focusId=null}
}
/* v8.28: la sincronización no redibuja mientras hay una ventana abierta o se escribe; lo hace al cerrar o al salir del campo */
function softRender(){const a=document.activeElement;if(sheet||(a&&a.matches&&a.matches('input,textarea,select')&&$app.contains(a))){needsRender=true}else render()}
/* v8.28: foto de lo que el usuario tiene a la vista, para devolverlo igual después de redibujar */
function uiSig(el){return el.id?'#'+el.id:el.tagName+'.'+(el.getAttribute('class')||'')}
function uiIdx(root,sel){const m=new Map(),out=[];root.querySelectorAll(sel).forEach(el=>{const g=uiSig(el),i=m.get(g)||0;m.set(g,i+1);out.push([g+'@'+i,el])});return out}
function uiDetK(k,el){const su=el.querySelector('summary');return k+'|'+(su?su.textContent.trim().slice(0,60):'')}
function uiSnap(root){
  const S={sc:[],det:[],foc:null};
  uiIdx(root,'*').forEach(([k,el])=>{if(el.scrollTop||el.scrollLeft)S.sc.push([k,el.scrollTop,el.scrollLeft])});
  uiIdx(root,'details').forEach(([k,el])=>S.det.push([uiDetK(k,el),el.open]));
  const a=document.activeElement;
  if(a&&a!==document.body&&root.contains(a)){let ss=null,se=null;try{ss=a.selectionStart;se=a.selectionEnd}catch(x){}S.foc={id:a.id,tag:a.tagName,data:Object.assign({},a.dataset),ss:ss,se:se}}
  return S;
}
function uiRestore(root,S){
  if(!S)return;
  if(S.det.length){const D=new Map(S.det);uiIdx(root,'details').forEach(([k,el])=>{const v=D.get(uiDetK(k,el));if(v!=null&&el.open!==v)el.open=v})}
  if(S.sc.length){const M=new Map(uiIdx(root,'*'));S.sc.forEach(([k,t,l])=>{const el=M.get(k);if(el){el.scrollTop=t;el.scrollLeft=l}})}
  const f=S.foc;if(!f)return;
  let el=f.id?root.querySelector('#'+CSS.escape(f.id)):null;
  if(!el){const ks=Object.keys(f.data);if(!ks.length)return;const sel=f.tag.toLowerCase()+ks.map(k=>'[data-'+k.replace(/[A-Z]/g,m=>'-'+m.toLowerCase())+'="'+CSS.escape(f.data[k])+'"]').join('');el=root.querySelector(sel)}
  if(!el||el===document.activeElement)return;
  try{el.focus({preventScroll:true});if(f.ss!=null&&el.setSelectionRange)el.setSelectionRange(f.ss,f.se)}catch(x){}
}
document.addEventListener('focusout',()=>{setTimeout(()=>{const a=document.activeElement;if(needsRender&&!(a&&a.matches&&a.matches('input,textarea,select')))render()},60)});

function lastCod(e){
  const l=visible().filter(o=>o.emp===e).sort((a,b)=>(b.anio-a.anio)||((b.cons||0)-(a.cons||0)))[0];
  return l?l.cod:'';
}
