    ensureTraz(m).tarimas.filter(P=>palPL(m,P)).forEach(P=>(P.lines||[]).forEach(l=>{const c=n0(l.cant),ck=PCAL_KEY[l.cal];if(!(c>0)||!ck)return;const tp=lineType(palTipo(P),ck),q=lineQ(P,l),k=tp+'|'+ck+'|'+q;pl[k]=(pl[k]||0)+c;lines.push({k:k,tp:tp,ck:ck,q:q,n:c,prod:String(l.prod||''),de:!!l.de})}));
