const wkClosed=k=>!!(PER.list[k]&&PER.list[k].closed);
function orderLocked(o){return !!o&&wkClosed(wkOf(o))}
function perAdmin(){return !roRole&&!!authUser&&authUser.rol==='admin'&&(!cfgOK()||(!!session&&roleOf(session.access_token)==='admin'))}
function weekKeys(withNow){const s=new Set();visible().forEach(o=>{const k=wkOf(o);if(k)s.add(k)});Object.keys(PER.list).forEach(k=>s.add(k));if(withNow)s.add(wkOfDate(todayISO()));return [...s].filter(Boolean).sort().reverse()}
