/* segundas que siguen en almacén al cerrar la semana: las de esa semana y anteriores pasan a Juguera (v8.13: la semana de una segunda es la del empaque donde salió) */
function jugCandidates(k){const out=[];seg2Lots().forEach(l=>{if(l.av<=0)return;const lk=l.wk||(l.fecha?wkOfDate(l.fecha):'');if(!lk||lk<=k)out.push(l)});return out.sort((a,b)=>a.nombre.localeCompare(b.nombre)||(a.fecha||'').localeCompare(b.fecha||''))}
