  P.forEach(p=>{L.cajasAll+=p.cajas;L.rech+=p.rech;if(!biPar(p.emp,'oee',p.wk))return;const h=num(p.bi.horas)||biPar(p.emp,'horas',p.wk),pe=num(p.bi.personas)||biPar(p.emp,'personas',p.wk);if(!(h>0&&pe>0))return;const pa=num(p.bi.paro)!=null?num(p.bi.paro):biPar(p.emp,'paro',p.wk),op=Math.max(0,h-pa/60);p.hE=h;p.peE=pe;p.paroE=pa;
    L.ped++;L.cajas+=p.cajas;L.horas+=h;L.horasOp+=op;L.personas+=pe;L.hh+=pe*h;L.costMO+=pe*h*biPar(p.emp,'salHr',p.wk);L.metaH+=op*biPar(p.emp,'meta',p.wk);p.cph=op>0?p.cajas/op:null});
  L.cph=L.horasOp>0?L.cajas/L.horasOp:null;L.cpp=L.personas>0?L.cajas/L.personas:null;L.cphh=L.hh>0?L.cajas/L.hh:null;
  L.disp=L.horas>0?L.horasOp/L.horas:null;L.perf=L.metaH>0?Math.min(1,L.cajas/L.metaH):null;L.cal=L.cajasAll>0?1-L.rech/L.cajasAll:null;
  L.oee=L.disp!=null&&L.perf!=null&&L.cal!=null?L.disp*L.perf*L.cal:null;L.moCaja=L.cajas>0?L.costMO/L.cajas:null;
  /* logística */
  const G={ped:P.length,flete:0,dem:0,demMXN:0,cajas:0,eta:0,ontime:0,delay:0,nav:new Map()};
  P.forEach(p=>{G.flete+=p.flete;G.cajas+=p.cajas;const dm=n0(p.bi.demora);G.dem+=dm;G.demMXN+=dm*p.tc;if(p.bi.eta&&p.bi.llegada){const d=dayDiff(p.bi.eta,p.bi.llegada);G.eta++;if(d<=0)G.ontime++;G.delay+=Math.max(0,d)}
    const nv=String(p.bi.naviera||'').trim();if(nv){let x=G.nav.get(nv);if(!x){x={n:nv,ped:0,delay:0,eta:0,dem:0};G.nav.set(nv,x)}x.ped++;x.dem+=dm;if(p.bi.eta&&p.bi.llegada){x.eta++;x.delay+=Math.max(0,dayDiff(p.bi.eta,p.bi.llegada))}}});
