  const proj=[];if(S.length>=3&&fc){let k=S[S.length-1].k;for(let i=1;i<=4;i++){k=wkNext(k);proj.push({k:k,l:wkLab(k,true),cajas:Math.max(0,Math.round(fc.at(S.length-1+i))),util:fu?fu.at(S.length-1+i):null})}}
