function regVals(prefix,S){S=S||sheet;const sp=REGSPEC[S.rt];return sp.f.map((f,i)=>{let v=String((document.getElementById(prefix+i)||{}).value||'').trim().replace(/\s+/g,' ');return f[0]==='tel'?v:v.toUpperCase()})}
function regSave(id,S){
  S=S||sheet;const sp=REGSPEC[S.rt],v=regVals(id?'re-':'rn-',S);
  if(v[0].length<1)return 'Escribe '+(S.rt==='cajas'?'el número del termo.':S.rt==='trailers'?'el número económico.':'el nombre.');
  const L=REG[S.rt],ti=sp.f.findIndex(f=>f[3]==='transp');
  if(id){const x=L.find(y=>y.id===id);if(!x)return '';
    if(L.some(y=>y.id!==id&&norm(y.n).trim()===norm(v[0]).trim()&&(ti<0||norm(y.transporte||'')===norm(v[ti]))))return 'Ya existe «'+v[0]+'».';
    sp.f.forEach((f,i)=>{x[f[0]]=v[i]})}
  else{
    if(L.some(y=>norm(y.n).trim()===norm(v[0]).trim()&&(ti<0||norm(y.transporte||'')===norm(v[ti]))))return 'Ya existe «'+v[0]+'». Usa Editar para cambiarlo.';
    const x={id:uid()};sp.f.forEach((f,i)=>{x[f[0]]=v[i]});L.push(x);
  }
  L.sort((a,b)=>String(a.n).localeCompare(String(b.n),'es',{numeric:true}));
  saveReg(true);return '';
}
async function syncReg(){
  try{
    if(REG.dirty&&!ro&&canCat()){
      await sb('/rest/v1/catalogos?on_conflict=clave',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:[{clave:'registros',updated_at:REG.ts,data:{vendedores:REG.vendedores,conductores:REG.conductores,cajas:REG.cajas,transportistas:REG.transportistas,trailers:REG.trailers,clientes:REG.clientes}}]});
      REG.dirty=false;saveReg(false);
    }
    const r=await sb('/rest/v1/catalogos?select=updated_at,data&clave=eq.registros');
    if(r&&r[0]&&r[0].data&&Number(r[0].updated_at)>(REG.ts||0)&&!REG.dirty){
      const d=r[0].data;remoteN++;REG.vendedores=d.vendedores||[];REG.conductores=d.conductores||[];REG.cajas=d.cajas||[];if(Array.isArray(d.transportistas))REG.transportistas=d.transportistas;if(Array.isArray(d.trailers))REG.trailers=d.trailers;if(Array.isArray(d.clientes))REG.clientes=d.clientes;REG.ts=Number(r[0].updated_at);saveReg(false);
    }
  }catch(e){}
}
