function setBind(b,val,isNum){
  const o=cur();if(!o||ro)return;const p=b.split('.');const v=isNum?num(val):val;
  if(p[0]==='o'){o[p[1]]=v;if(p[1]==='cod'){const m=String(val).match(/(\d+)\s*$/);if(m&&m[1].length<=4)o.cons=+m[1]}if(p[1]==='fecha'&&val){const P=wkPick(val);o.semana=P?P.w:isoWeek(val);if(P)o.wkY=P.y;const s=document.getElementById('f-o-semana');if(s)s.value=o.semana}}
  else if(p[0]==='m'){if(p.length===3){o.manT=o.manT||{};(o.manT[p[1]]=o.manT[p[1]]||{})[p[2]]=v;syncManSum(o)}else{o.manifiesto=o.manifiesto||{};o.manifiesto[p[1]]=v}}
  else if(p[0]==='p'){const pr=o.productores.find(x=>x.id===p[1]);if(!pr)return;if(p[2]==='acc'){if(tdMode(o)&&tdRowOk(pr))return;accOf(pr,p[3],true)[p[4]]=v}else pr[p[2]]=v}
  else if(p[0]==='ob'){const m=mainOf(o);m.bi=m.bi||{};m.bi[p[1]]=v;if(m!==o)touch(m)}
  else if(p[0]==='z'){const m=mainOf(o);ensureTraz(m).hdr[p[1]]=val;hdrDocClear(m,p[1])}
  else if(p[0]==='t'){const pl=ensureTraz(mainOf(o)).tarimas.find(x=>x.id===p[1]);if(pl&&!palLk(pl))pl[p[2]]=val}
  else if(p[0]==='tl'){const pl=ensureTraz(mainOf(o)).tarimas.find(x=>x.id===p[1]);const l=pl&&!palLk(pl)&&pl.lines.find(x=>x.id===p[2]);if(!l)return;TDS.edit=true;
    if(l.de){if(p[3]!=='cal'&&p[3]!=='cant')return;const ock=PCAL_KEY[l.cal]||null,on=n0(l.cant);l[p[3]]=p[3]==='cant'?v:val;sobLineSync(mainOf(o),pl,l,ock,on);if(p[3]==='cant'&&n0(v)<on)toast(fmt(on-n0(v))+' cajas vuelven a contar en '+lineFrom(pl,l).cod+'. Para cambiarlas de tarima usa «Pasar cajas a otra tarima»');return}
    l[p[3]]=p[3]==='cant'?v:val}
}
