/* casillas del acumulado: funcionan como una mini hoja de cálculo que solo suma y resta (+50+50-10).
   Al salir de la casilla se guarda el total; al tocarla otra vez vuelve a mostrar la operación. */
const OPS_RE=/[+\-−–—＋－]/;
function normOps(s){return String(s==null?'':s).replace(/＋/g,'+').replace(/[−–—－]/g,'-').replace(/[,\s]/g,'')}
function sumExpr(s){
  let t=normOps(s).replace(/[+\-]+$/,'');
  if(!t)return null;
  const m=t.match(/[+-]?\d+(?:\.\d+)?/g);
  if(!m||m.join('')!==t)return NaN;
  let tot=0;m.forEach(x=>{tot+=parseFloat(x)});
  return Math.round(tot*100)/100;
}
function accRef(el){
  const bp=String((el&&el.dataset&&el.dataset.bind)||'').split('.');
  if(bp[0]!=='p'||bp[2]!=='acc')return null;
  const o=cur(),pr=o&&o.productores.find(x=>x.id===bp[1]);
  return pr?{o:o,pr:pr,t:bp[3],k:bp[4],xk:bp[3]+':'+bp[4]}:null;
}
function settleSum(el){
  if(!el||!el.dataset||!el.dataset.sum||ro)return;
  const ref=accRef(el);if(!ref)return;
  let t=normOps(el.value);const pr=ref.pr,k=ref.k,xk=ref.xk,acc=accOf(pr,ref.t);
  if(!/[+-]/.test(t)){
    if(pr.accx&&pr.accx[xk]!=null){delete pr.accx[xk];touch(ref.o)}
    return;
  }
  let tot=sumExpr(t);
  if(tot!==null&&isNaN(tot)){t=t.replace(/[^\d+\-.]/g,'');tot=sumExpr(t)}  /* si hay letras u otros signos, se descartan */
  if(tot==null||isNaN(tot)||tot<0){
    const prev=acc[k];
    el.value=prev==null?'':String(prev);
    toast(tot!=null&&!isNaN(tot)&&tot<0?'El total no puede ser menor que 0':'Operación no válida: solo sumas y restas');
    return;
  }
  const expr=t.replace(/[+\-]+$/,''),newX=/^\+?\d+(\.\d+)?$/.test(expr)?null:expr;
  const prevX=(pr.accx&&pr.accx[xk])||null,prevV=acc[k];
  el.value=String(tot);
  if(prevX===newX&&prevV!=null&&Number(prevV)===tot)return;  /* solo se tocó la casilla: no hay cambio que guardar */
  setBind(el.dataset.bind,el.value,true);
  pr.accx=pr.accx||{};
  if(newX==null)delete pr.accx[xk];else pr.accx[xk]=newX;
  touch(ref.o);
  if(view==='trazo')updateTraz();else updateDerived();
}
$app.addEventListener('focusout',e=>settleSum(e.target));
$app.addEventListener('focusin',e=>{
  const el=e.target;if(!(el&&el.dataset&&el.dataset.sum))return;
  const ref=accRef(el),x=ref&&ref.pr.accx&&ref.pr.accx[ref.xk];
  if(x&&sumExpr(x)===sumExpr(el.value)){el.value=x;setTimeout(()=>{try{el.setSelectionRange(x.length,x.length)}catch(e){}},0)}
});
$app.addEventListener('mousedown',e=>{if(e.target.closest&&e.target.closest('.plus'))e.preventDefault()});
$app.addEventListener('focusout',e=>{const t=e.target;if(t.dataset&&t.dataset.psearch)setTimeout(()=>{closePdds();settleProd(t)},220)});
