/* v8.37 · SEC-007: contraseñas del modo local con PBKDF2 (150 000 vueltas) y sal aleatoria segura.
   Las contraseñas ya guardadas con el formato anterior siguen entrando y se convierten solas al entrar. */
const PW_IT=150000;
const hexOf=b=>Array.prototype.map.call(new Uint8Array(b),x=>x.toString(16).padStart(2,'0')).join('');
async function pbkdf2(pw,salt,it){const te=new TextEncoder(),k=await crypto.subtle.importKey('raw',te.encode(pw),'PBKDF2',false,['deriveBits']);return 'p'+it+'$'+hexOf(await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:te.encode(salt),iterations:it},k,256))}
async function hashPwOld(pw,salt){
  const s=salt+'|'+pw;
  try{if(window.crypto&&crypto.subtle){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return 'a'+hexOf(b)}}catch(e){}
  let h=5381;for(let i=0;i<s.length;i++)h=((h<<5)+h+s.charCodeAt(i))|0;return 'b'+(h>>>0).toString(16);
}
/* contraseña nueva; solo si el navegador no tiene criptografía (abierto como archivo o sin https) usa el formato anterior */
async function hashPw(pw,salt){try{if(window.crypto&&crypto.subtle)return await pbkdf2(pw,salt,PW_IT)}catch(e){}return hashPwOld(pw,salt)}
async function pwMatch(x,pw){
  if(!x||!x.hash||typeof pw!=='string')return false;const h=String(x.hash),m=/^p(\d+)\$/.exec(h);let ok=false;
  try{ok=m?(await pbkdf2(pw,x.salt,+m[1]))===h:(await hashPwOld(pw,x.salt))===h}catch(e){ok=false}
  if(ok&&!m){try{const nh=await hashPw(pw,x.salt);if(/^p\d+\$/.test(nh)){x.hash=nh;const u=USERS.find(y=>y.id===x.id);if(u&&u!==x)u.hash=nh;saveUsers()}}catch(e){}}
  return ok;
}
const newSalt=()=>{try{const a=new Uint8Array(16);crypto.getRandomValues(a);return hexOf(a.buffer)}catch(e){return Math.random().toString(36).slice(2)+Date.now().toString(36)}};
