function manAcctHtml(){
  const L=manRoles(),MN=window.MANUALES;if(!L.length)return '';
  const one=L.length===1;
  return `<div class="sec">Manual de usuario</div><div class="panel lpanel mnacc">${one?`<p class="note" style="margin-bottom:6px">${esc(MN.M[L[0]].sub)}.</p>`:'<p class="note" style="margin-bottom:6px">Manuales de cada puesto, para capacitar y resolver dudas.</p>'}${L.map(k=>`<button class="lrow" data-act="manual:${k}"><span>${esc(one?'Abrir mi manual · '+MN.M[k].puesto:MN.M[k].puesto)}</span><span aria-hidden="true">›</span></button>`).join('')}</div>`;
}
function manualHtml(){
  const MN=window.MANUALES,L=manRoles();if(!MN||!L.length)return '<h3>Manual de usuario</h3><p class="note">No hay manual para este puesto.</p><div class="srow2"><button class="btn primary" data-act="closesheet">Cerrar</button></div>';
  const k=L.indexOf(sheet.rol)>=0?sheet.rol:L[0],D=MN.M[k],n=D.caps.length,c=sheet.cap;
  const tabs=L.length>1?`<div class="ltabs" role="tablist">${L.map(x=>`<button class="chipbtn ltb" role="tab" aria-selected="${x===k}" data-act="manual:${x}">${esc(MN.M[x].puesto)}</button>`).join('')}</div>`:'';
  const meta=`<p class="lmeta lvig">Versión ${esc(MN.ver)} · vigente desde el ${esc(MN.vig)} · app ${esc(APP_VER)}</p>`;
  const foot=`<div class="srow2"><button class="btn" data-act="mandl:${k}">Descargar manual</button><button class="btn primary" data-act="closesheet">Cerrar</button></div>`;
  if(c==null||!(c>=0&&c<n)){
    return `<h3>${esc(D.titulo)}</h3>${tabs}<p class="note" style="margin-bottom:4px">${esc(D.sub)}.</p>${meta}<div class="panel lpanel mnidx" aria-label="Índice">${D.caps.map((x,i)=>`<button class="lrow" data-act="manual:${k}:${i}"><span><span class="mnum mono">${i+1}</span>${esc(x.t)}</span><span aria-hidden="true">›</span></button>`).join('')}</div>${foot}`;
  }
  const C=D.caps[c];
  const nav=`<div class="mnnav"><button class="btn sm" data-act="manual:${k}:${c-1<0?'':c-1}">${c>0?'‹ Anterior':'‹ Índice'}</button><button class="btn sm" data-act="manual:${k}">Índice</button>${c<n-1?`<button class="btn sm" data-act="manual:${k}:${c+1}">Siguiente ›</button>`:''}</div>`;
  return `<h3>${esc(D.puesto)}</h3>${tabs}<p class="lmeta">Capítulo ${c+1} de ${n}</p><div class="ldoc mndoc"><h4 class="mnh">${c+1}. ${esc(C.t)}</h4>${C.h}</div>${nav}${foot}`;
}
function manDocHtml(k){
  const MN=window.MANUALES,D=MN.M[k],hoy=new Date().toLocaleDateString('es-MX',{dateStyle:'long'});
  const css='body{font:15px/1.55 system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:#14202b;max-width:760px;margin:24px auto;padding:0 18px}h1{font-size:24px;margin:0 0 4px}h2{font-size:19px;margin:28px 0 8px;padding-top:12px;border-top:1px solid #d5dbe1;break-after:avoid}h4{font-size:16px;margin:16px 0 6px}.sub{color:#4a5763;margin:0 0 4px}.meta{color:#6b7782;font-size:13px;margin:0 0 18px}table{border-collapse:collapse;width:100%;margin:6px 0 12px;font-size:14px}th,td{border:1px solid #d5dbe1;padding:6px 8px;text-align:left;vertical-align:top}thead th{background:#eef2f5}blockquote{margin:0 0 10px;padding:10px 12px;border-left:3px solid #1d6b3a;background:#f3f7f4}ol.toc{columns:2;font-size:14px}li{margin-bottom:4px}@media print{body{margin:0}h2{break-before:page;border-top:0}h2.first{break-before:auto}}';
  return '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(D.titulo)+'</title><style>'+css+'</style></head><body>'+
    '<h1>'+esc(D.titulo)+'</h1><p class="sub">'+esc(D.sub)+'.</p><p class="meta">Versión '+esc(MN.ver)+' · vigente desde el '+esc(MN.vig)+' · app '+esc(APP_VER)+' · descargado el '+esc(hoy)+'. Documento de uso interno.</p>'+
    '<ol class="toc">'+D.caps.map(x=>'<li>'+esc(x.t)+'</li>').join('')+'</ol>'+
    D.caps.map((x,i)=>'<h2'+(i?'':' class="first"')+'>'+(i+1)+'. '+esc(x.t)+'</h2>'+x.h).join('')+'</body></html>';
}
async function manDownload(k){
  const MN=window.MANUALES;if(!MN||manRoles().indexOf(k)<0)return;
  const nm='Manual_'+MN.M[k].puesto.replace(/\s+/g,'_')+'_v'+MN.ver+'.html';
  try{await saveFile(nm,new Blob([manDocHtml(k)],{type:'text/html'}),MN.M[k].titulo)}catch(e){toast('No se pudo descargar el manual')}
}
function acctHtml(){
  const u=authUser;if(!u)return '';
  if(u.remote)return `<h3>Mi cuenta</h3><p class="note" style="margin-bottom:8px">${esc(u.user)} · ${u.sinRol?'Sin rol asignado (solo lectura)':(ROLES[rolReal()]||ROLES[u.rol])}</p>${manAcctHtml()}<p class="note">La contraseña y las cuentas se administran en Supabase (Authentication → Users). Si necesitas cambiarla, pídelo a administración.</p>${bioAcctHtml()}<div class="srow2"><button class="btn primary" data-act="closesheet">Cerrar</button></div>`;
  return `<h3>Mi cuenta</h3><p class="note" style="margin-bottom:8px">${esc(u.name)} · ${esc(u.user)} · ${ROLES[rolReal()]||ROLES[u.rol]||u.rol}</p>${manAcctHtml()}${u.defPw?'<div class="warnbox" role="alert"><strong>Cambia la contraseña inicial</strong><div>Esta cuenta todavía usa la contraseña de prueba.</div></div>':''}
<label class="fld" for="ac-c"><span>Contraseña actual</span>${PWI(`<input class="in txt" id="ac-c" type="password" autocomplete="current-password">`)}</label><label class="fld" for="ac-n"><span>Contraseña nueva</span>${PWI(`<input class="in txt" id="ac-n" type="password" autocomplete="new-password">`)}</label><label class="fld" for="ac-n2"><span>Repite la nueva</span>${PWI(`<input class="in txt" id="ac-n2" type="password" autocomplete="new-password">`)}</label>${sheet.err?`<p class="note" style="color:var(--crit)" role="alert">${esc(sheet.err)}</p>`:''}
${bioAcctHtml()}<div class="srow2"><button class="btn" data-act="closesheet">Cerrar</button><button class="btn primary" data-act="acsave">Cambiar contraseña</button></div>`;
}
async function changePw(){
  const u=authUser;if(!u)return;
  const c=gv('ac-c'),n=gv('ac-n'),n2=gv('ac-n2');
  if(!(await pwMatch(u,c)))sheet.err='La contraseña actual no es correcta.';
  else if(n.length<10)sheet.err='La nueva necesita al menos 10 caracteres.';
  else if(n!==n2)sheet.err='Las contraseñas nuevas no coinciden.';
  else{u.salt=newSalt();u.hash=await hashPw(n,u.salt);u.defPw=false;saveUsers();bioSync(u.user,n);sheet=null;renderSheet();render();toast('Contraseña actualizada');return}
  renderSheet();
}
function adminOnly(){return authUser&&authUser.rol==='admin'}
function rolReal(){return !authUser?'':(authUser.rol2||authUser.rol||'')}
/* v8.31: Administración (pendientes, registro de cambios, usuarios y respaldo) es solo para administrador y superadministrador */
function canAdm(){return !!authUser&&authUser.rol==='admin'}
function isInocR(){return !!authUser&&rolReal()==='inocuidad'}
function isTarima(){return !!authUser&&authUser.rol==='tarima'}
/* sin base de datos, el administrador local hace también lo del superadmin */
function isSuper(){if(!authUser)return false;if(!cfgOK())return authUser.rol==='admin';return rolReal()==='superadmin'&&!!session&&roleRaw(session.access_token)==='superadmin'}
function isInoc(){return !!authUser&&rolReal()==='inocuidad'&&!ro&&(!cfgOK()||(!!session&&roleRaw(session.access_token)==='inocuidad'))}
/* productores (nombre y clasificación) y catálogos de logística: administración e inocuidad */
function canCat(){return isAdmin()||isInoc()}
function userAct(act,arg,rol){
  if(act==='ulogout'){if(cfgOK()){rtStop();session=null;try{localStorage.removeItem(LS_SESSION)}catch(x){}}setAuth(null);view='menu';curId=null;sheet=null;renderSheet();lg={tab:'in',err:'',msg:''};render();return}
  if(act==='usersopen'){if(adminOnly()){sheet={kind:'users'};renderSheet()}return}
  if(act==='acctopen'){sheet={kind:'acct',err:''};renderSheet();return}
  if(act==='acsave'){changePw();return}
  if(!adminOnly())return;
  const x=USERS.find(y=>y.id===arg);if(!x)return;
  if(act==='uok'){x.estado='activo';x.rol=rol;toast(x.name+' autorizado')}
  else if(act==='urej'){USERS=USERS.filter(y=>y.id!==arg);toast('Solicitud rechazada')}
  else if(act==='ublk'){x.estado=x.estado==='activo'?'bloqueado':'activo'}
  else if(act==='udel'){if(confirmKey==='udel:'+arg){confirmKey=null;USERS=USERS.filter(y=>y.id!==arg)}else armConfirm('udel:'+arg)}
  if(!USERS.some(y=>y.rol==='admin'&&y.estado==='activo')){x.rol='admin';x.estado='activo';toast('Debe quedar al menos un administrador')}
  saveUsers();renderSheet();render();
}
/* ---------- documentos del embarque: Manifiesto y Packing List, PDF y PowerPoint (fusionado de la Fase 2) ---------- */
const DIR_US=['4900 W Expressway 83','Suite 226  +1 (956) 4585194'];
const DOC_EMP={EC:{prov:'CITRICOS J&C LLC',h:['Citricos J&C LLC'].concat(DIR_US)},VL:{prov:'VERA LIMES USA LLC',h:['Vera Limes USA LLC'].concat(DIR_US)}};
const CAL_ASC=['c110','c150','c175','c200','c230','c250','ctn','m28','m36','m42','m48','m54','m60','m63'];
const CAL_LAB={ctn:'230 CTN',c250:'250',c230:'230',c200:'200',c175:'175',c150:'150',c110:'110'};CAL_MM.forEach(c=>{CAL_LAB[c.k]=c.l.toUpperCase()});
let docTab='man',docFrom='order';
const DIAS_U=['DOMINGO','LUNES','MARTES','MIÉRCOLES','JUEVES','VIERNES','SÁBADO'],MESES_U=['ENERO','FEBRERO','MARZO','ABRIL','MAYO','JUNIO','JULIO','AGOSTO','SEPTIEMBRE','OCTUBRE','NOVIEMBRE','DICIEMBRE'];
function fechaLarga(iso){
  const p=String(iso||'').split('-');if(p.length!==3)return iso||'';
  const d=new Date(+p[0],+p[1]-1,+p[2]);if(isNaN(d))return iso;
  return DIAS_U[d.getDay()]+' '+(+p[2])+' DE '+MESES_U[+p[1]-1]+' DE '+p[0];
}
function docMain(o){return mainOf(o||cur())}
/* valores de los documentos: lo capturado en Código de Trazabilidad, corregible en la pantalla de documentos */
function docDef(m){
  const t=ensureTraz(m),h=t.hdr||{},E=DOC_EMP[m.emp]||DOC_EMP.EC,cli=h.cliente||m.customer||'';
  return {salida:h.salida||m.fecha||'',llegada:h.llegada||'',hora:h.hora||'',cliente:cli,factura:h.factura||m.factura||'',poCli:h.poCliente||m.po||'',
    poLinea:((cli?cli.split(/\s+/)[0]:'')+(h.pOrder?' '+h.pOrder:'')).trim(),cantTxt:'',
    linea:h.transporte||'',operador:h.conductor||'',placasT:h.placas||'',placasF:h.placasCaja||'',coment:'',
    alpha:h.alpha||'',caat:h.caat||'',eco:h.trailer||h.caja||'',cert:'',h1:E.h[0],h2:E.h[1],h3:E.h[2],
    viaje:m.cons!=null?String(m.cons):'',prov:h.plProv||PL_PROV[m.emp]||E.prov,vend:h.vendedor||'',pOrder:h.pOrder||'',tel:h.tel||'',sello:h.sello||'',manTipo:'ALL'};
}
function dv(m,k){const d=m.docs||{};return d[k]!==undefined&&d[k]!==null&&!(/^h[123]$/.test(k)&&String(d[k]).trim()==='')?d[k]:docDef(m)[k]}
/* ---------- v8.26 · varios manifiestos por viaje (uno por venta) ----------
   La venta 1 es la del viaje (encabezado de Trazabilidad). Las demás (m.ventas) llevan su propio cliente, P.O., factura y P. Order.
   Cada tarima es de una venta (p.venta; sin marca = venta 1). Cada venta tiene su manifiesto y su packing list con sus tarimas.
   El manifiesto interno y el Código de Trazabilidad siguen siendo del viaje completo. v = id de la venta ('' = venta 1; null = viaje completo). */
const VFIELDS=['cliente','factura','poCli','poLinea','pOrder','cantTxt'];
function ventas(m){return (m&&Array.isArray(m.ventas))?m.ventas:[]}
function multiV(m){return ventas(m).length>0}
function ventaOf(m,v){return v?ventas(m).find(x=>x.id===v)||null:null}
function palV(m,p){const v=p&&p.venta;return v&&ventaOf(m,v)?v:''}
function ventaN(m,v){return v?ventas(m).findIndex(x=>x.id===v)+2:1}
function palsOfV(m,v){return ensureTraz(m).tarimas.filter(p=>palPL(m,p)&&palV(m,p)===v)}
/* v8.36 · manifiesto a nombre de la otra empresa: la venta lleva su empresa (V.emp), su propio código (V.cod, del consecutivo de esa empresa)
   y su factura, sin crear un empaque. Cambian membrete, logotipo y proveedor del packing list; la carga, marcas y etiquetas son las del viaje.
   Su cuenta por cobrar va a la empresa del manifiesto (ver accData). */
const VEMPF=['h1','h2','h3','prov'];
function ventaEmp(m,v){const V=ventaOf(m,v);return V&&V.emp&&EMPS[V.emp]?V.emp:m.emp}
function ventaX(m,v){return !!v&&ventaEmp(m,v)!==m.emp}
function docEmp(m,v){return v?ventaEmp(m,v):m.emp}
function ventaEmpSet(m,e){
  const v=docV(m),V=ventaOf(m,v);if(!V||!EMPS[e]||ventaEmp(m,v)===e)return;
  if(!ventaCan(m)){toast(manClosed(m)?'El manifiesto está cerrado':'No se puede cambiar');return}
  const was=V.cod||'';VEMPF.forEach(k=>delete V[k]);
  if(e===m.emp){delete V.emp;delete V.cod;delete V.cons;delete V.anio}
  else{const y=+m.anio||+String(m.fecha||'').slice(0,4)||+todayISO().slice(0,4),c=nextCons(e,y);V.emp=e;V.anio=y;V.cons=c;V.cod=codOf(e,y,c)}
  touch(m);
  logAdd({k:'edit',ctx:ctxOf(m),lab:'Manifiesto '+ventaN(m,v)+' · empresa',o:was,n:V.cod?V.cod+' a nombre de '+EMPS[e].name:'de '+EMPS[m.emp].name+' como el viaje'});
  render();toast(V.cod?'Manifiesto '+ventaN(m,v)+' a nombre de '+EMPS[e].name+' · '+V.cod:'Manifiesto '+ventaN(m,v)+' de '+EMPS[m.emp].name);
}
/* cuánto vale en USD lo de una venta: sus tarimas por calidad y calibre, al precio de su empresa en la semana del viaje (o al del viaje si no hay) */
function ventaUSD(m,v){
  const wk=wkOf(m),Fd=parsDe(ventaEmp(m,v),wk),Fo=parsDe(m.emp,wk);let s=0;
  palsOfV(m,v).forEach(p=>(p.lines||[]).forEach(l=>{const c=n0(l.cant),key=PCAL_KEY[l.cal];if(!(c>0)||!key)return;const tp=lineType(palTipo(p),key),q=lineQ(p,l);s+=c*(precioUSD(Fd,tp,q,key)||precioUSD(Fo,tp,q,key))}));
  return r2(s);
}
/* manifiestos de otra empresa que salen en viajes ajenos: [{m,V}] */
function ventasX(e){const r=[];visible().forEach(o=>{if(!isLeader(o))return;const m=mainOf(o);if(m!==o)return;ventas(m).forEach(V=>{if(V.cod&&V.emp===e&&V.emp!==m.emp)r.push({m:m,V:V})})});return r}
function dvv(m,k,v){
  if(ventaX(m,v)&&VEMPF.indexOf(k)>=0){const V=ventaOf(m,v),x=V[k];if(x!=null&&String(x).trim()!=='')return x;const e=ventaEmp(m,v),E=DOC_EMP[e]||DOC_EMP.EC;return k==='prov'?(PL_PROV[e]||E.prov):E.h[+k.slice(1)-1]}
  if(v&&VFIELDS.indexOf(k)>=0){const V=ventaOf(m,v);if(V){const x=V[k];if(x!=null&&String(x).trim()!=='')return x;
    if(k==='poLinea'){const c=String(V.cliente||'').trim();return ((c?c.split(/\s+/)[0]:'')+(V.pOrder?' '+V.pOrder:'')).trim()}return ''}}
  return dv(m,k);
}
function ventaCli(m,v){return String(dvv(m,'cliente',v)||'').trim()}
function ventaLab(m,v){const c=ventaCli(m,v),V=ventaX(m,v)?ventaOf(m,v):null;return 'Manifiesto '+ventaN(m,v)+(V?' · '+V.cod:'')+(c?' · '+c:'')}
let docVS={oid:null,v:''};
function docV(m){return m&&docVS.oid===m.id&&(docVS.v===''||!!ventaOf(m,docVS.v))?docVS.v:''}
function setDocV(m,v){docVS={oid:m.id,v:v||''}}
function ventaCan(m){return !ro&&!orderLocked(m)&&!manClosed(m)}
function ventaAdd(m){
  if(!ventaCan(m)){toast(manClosed(m)?'El manifiesto está cerrado':'No se puede cambiar');return}
  const n=ensureTraz(m).tarimas.length;if(n&&ventas(m).length+1>=n){toast('Ya hay un manifiesto por tarima');return}
  const V={id:uid(),cliente:'',factura:'',poCli:'',pOrder:''};m.ventas=ventas(m).concat([V]);setDocV(m,V.id);touch(m);
  logAdd({k:'add',ctx:ctxOf(m),lab:'Manifiesto '+ventaN(m,V.id)+' agregado',o:'',n:'venta a otro cliente'});
  render();toast('Manifiesto '+ventaN(m,V.id)+' agregado. Escribe su cliente y asígnale sus tarimas');
}
function ventaDel(m){
  const v=docV(m);if(!v||!ventaCan(m))return;const k='vdel:'+v;if(confirmKey!==k){armConfirm(k);render();return}confirmKey=null;
  const lab=ventaLab(m,v);let c=0;ensureTraz(m).tarimas.forEach(p=>{if(p.venta===v){delete p.venta;c++}});
  m.ventas=ventas(m).filter(x=>x.id!==v);if(!m.ventas.length)delete m.ventas;setDocV(m,'');touch(m);
  logAdd({k:'del',ctx:ctxOf(m),lab:'Manifiesto quitado',o:lab,n:c?c+(c===1?' tarima regresó':' tarimas regresaron')+' al manifiesto 1':''});
  render();toast(lab+' quitado'+(c?'. Sus tarimas regresaron al manifiesto 1':''));
}
function ventaSet(m,p,v){if(v)p.venta=v;else delete p.venta}
function ventaAsg(m,pid){
  if(!ventaCan(m)){toast(manClosed(m)?'El manifiesto está cerrado':'No se puede cambiar');return}
  const p=ensureTraz(m).tarimas.find(x=>x.id===pid);if(!p)return;const v=docV(m),cv=palV(m,p);
  ventaSet(m,p,cv===v&&v?'':v);touch(m);render();
}
function ventaRng(m){
  if(!ventaCan(m))return;const T=ensureTraz(m).tarimas,a=Math.floor(n0((document.getElementById('vr-a')||{}).value)),b0=(document.getElementById('vr-b')||{}).value,b=b0===''||b0==null?a:Math.floor(n0(b0));
  if(!(a>=1)||!(b>=a)||b>T.length){toast('Escribe las tarimas: de 1 a '+T.length);return}
  const v=docV(m);for(let i=a-1;i<b;i++)ventaSet(m,T[i],v);touch(m);
  logAdd({k:'edit',ctx:ctxOf(m),lab:'Tarimas asignadas',o:'',n:'Tarimas '+a+(b>a?' a '+b:'')+' al manifiesto '+ventaN(m,v)});
  render();toast('Tarimas '+a+(b>a?' a '+b:'')+' en el manifiesto '+ventaN(m,v));
}
function ventasHtml(m){
  const v=docV(m),T=ensureTraz(m).tarimas,can=ventaCan(m),ids=[''].concat(ventas(m).map(x=>x.id));
  const add=can?`<button class="btn sm" data-act="dx:vadd">+ Agregar manifiesto</button>`:'';
  if(!multiV(m))return `<div class="panel vbox"><div class="vhead"><strong>Manifiestos de este viaje</strong>${add}</div><p class="note">Un manifiesto por venta. Si parte de la carga se vende a otro cliente, agrega otro manifiesto y asígnale sus tarimas: cada uno sale con su cliente y su packing list. El manifiesto interno sigue siendo uno solo.</p></div>`;
  const chips=ids.map((id,k)=>{const n=palsOfV(m,id).length;return `<button class="vchip vc${k%6}" data-act="dx:vsel:${id||'0'}" aria-pressed="${id===v}"><b>Manifiesto ${k+1}</b><small>${ventaX(m,id)?'<img class="vico" src="'+ICO[ventaEmp(m,id)]+'" alt="">'+esc(ventaOf(m,id).cod)+' · ':''}${esc(ventaCli(m,id)||'sin cliente')} · ${n} ${n===1?'tarima':'tarimas'}</small></button>`}).join('');
  const grid=T.length?`<div class="vgrid" role="group" aria-label="Tarimas del viaje por lugar">${T.map((p,i)=>{const pv=palV(m,p),k=ids.indexOf(pv);return `<button class="vpal vc${k%6}" data-act="dx:vasg:${p.id}" aria-pressed="${pv===v}"${can?'':' disabled'} aria-label="Tarima ${i+1}, ${esc(ventaLab(m,pv))}"><b>${i+1}</b><small>M${k+1}</small></button>`}).join('')}</div>`:'<p class="note">Todavía no hay tarimas en Código de Trazabilidad.</p>';
  const rng=can&&T.length?`<div class="vrng"><span>Tarimas de</span><input class="in" id="vr-a" type="text" inputmode="numeric" aria-label="Primera tarima"><span>a</span><input class="in" id="vr-b" type="text" inputmode="numeric" aria-label="Última tarima"><button class="btn sm" data-act="dx:vrng">Pasar al manifiesto ${ventaN(m,v)}</button></div>`:'';
  const ve=ventaEmp(m,v),vx=ventaX(m,v),esw=v?`<div class="vemp">${empToggle(ve,'dx:vemp:'+(ve==='VL'?'EC':'VL'),'A nombre de',can)}<p class="note">${vx?`Sale como <b>${esc(ventaOf(m,v).cod)}</b> de ${esc(EMPS[ve].name)}, con su membrete, su logotipo y su factura, sin crear un empaque. La venta se cobra en ${esc(EMPS[ve].name)}. El empaque y su Código de Trazabilidad siguen siendo de ${esc(m.cod)}.`:`Es de ${esc(EMPS[m.emp].name)}, como el viaje. Cámbialo si esta parte de la carga se vende a nombre de ${esc(EMPS[m.emp==='VL'?'EC':'VL'].name)}: toma su propio código y su factura.`}</p></div>`:'';
  const del=can&&v?`<div class="pact"><button class="btn sm danger" data-act="dx:vdel">${confirmKey==='vdel:'+v?'Toca otra vez':'Quitar manifiesto '+ventaN(m,v)}</button></div>`:'';
  return `<div class="panel vbox"><div class="vhead"><strong>Manifiestos de este viaje</strong>${add}</div><div class="vchips" role="group" aria-label="Manifiesto que estás editando">${chips}</div>${esw}<p class="note">Estás editando el <b>manifiesto ${ventaN(m,v)}</b>: los datos de abajo, su manifiesto y su packing list son solo de sus tarimas. ${can?'Toca una tarima para pasarla a este manifiesto'+(v?' (si ya es de este, regresa al manifiesto 1)':'')+', o pasa varias por número de lugar.':'Con el manifiesto cerrado las tarimas ya no cambian de manifiesto.'}</p>${grid}${rng}${del}</div>`;
}
/* v8.7: Manifiesto, Packing List y Código de Trazabilidad comparten los datos del embarque (por empaque).
   Lo que se escribe en un documento se guarda en el encabezado de Trazabilidad y aparece en los otros dos. */
const DOC2HDR={salida:'salida',llegada:'llegada',hora:'hora',cliente:'cliente',factura:'factura',poCli:'poCliente',linea:'transporte',operador:'conductor',placasT:'placas',placasF:'placasCaja',alpha:'alpha',caat:'caat',eco:'trailer',prov:'plProv',vend:'vendedor',pOrder:'pOrder',tel:'tel',sello:'sello'};
function setDocVal(k,v){
  if(!cur())return;const m=docMain(cur());if(!m||ro)return;
  {const vi=docV(m),V=vi&&(VFIELDS.indexOf(k)>=0||(ventaX(m,vi)&&VEMPF.indexOf(k)>=0))?ventaOf(m,vi):null;if(V){V[k]=v;touch(m);return}}
  const hk=DOC2HDR[k];
  if(hk){ensureTraz(m).hdr[hk]=v;if(m.docs&&k in m.docs)delete m.docs[k]}
  else{m.docs=m.docs||{};m.docs[k]=v}
  touch(m);
}
/* al cambiar el encabezado de Trazabilidad, deja de valer lo que se había corregido aparte en los documentos */
function ordSync(m,f,v){v=String(v||'').trim();if(!v||!m)return;sheetsOf(m).forEach(x=>{if(x[f]!==v){x[f]=v;touch(x)}})}
/* v8.44: estos datos no se quedan vacíos en los documentos: si se borran se toma el del pedido. Se avisa para que se verifique ahí */
const DOC_FB={cliente:['Compañía','el cliente del Registro de Empaque'],factura:['No. de factura','la factura del Registro de Empaque'],poCli:['P.O.','el PO del Registro de Empaque'],salida:['Fecha de salida','la fecha del Registro de Empaque'],eco:['Número económico','el termo de Código de Trazabilidad'],prov:['Proveedor','el proveedor de la empresa']};
function docBlankWarn(m,k){
  const f=DOC_FB[k];if(!f||!m||docV(m))return;const d=String(docDef(m)[k]||'').trim();if(!d)return;
  toast('«'+f[0]+'» no puede quedar en blanco: se toma '+f[1]+' ('+(k==='salida'?fmtDate(d):d)+'). Verifica que sea el correcto.',7000);
}
function hdrDocClear(m,hk){if(!m||!m.docs)return;Object.keys(DOC2HDR).forEach(k=>{if(DOC2HDR[k]===hk&&k in m.docs)delete m.docs[k]})}
/* pedidos anteriores: lo corregido solo en un documento pasa al encabezado si ahí está vacío (no se pierde ni se pisa nada) */
function docLink(m){
  if(!m||ro||!m.docs)return false;const h=ensureTraz(m).hdr;let ch=false;
  Object.keys(DOC2HDR).forEach(k=>{const hk=DOC2HDR[k],v=m.docs[k];if(v==null||String(v).trim()==='')return;
    if(!String(h[hk]||'').trim()){h[hk]=v;delete m.docs[k];ch=true}else if(String(h[hk]).trim()===String(v).trim()){delete m.docs[k];ch=true}});
  if(ch)touch(m);return ch;
}
/* cantidades por tipo de empaque y calidad: de las tarimas si ya hay, si no de lo empacado contra el manifiesto */
/* de dónde salen las cantidades de los documentos: las tarimas; si aún no hay, lo empacado; si tampoco, el manifiesto capturado en Resumen */
/* el manifiesto (y el manifiesto interno) salen del manifiesto capturado en Resumen, aunque todavía no haya tarimas ni código de trazabilidad */
function docSrc(m,pref,v){
  const z=trazCalc(m);
  if(v!=null&&multiV(m)){/* v8.26: con varios manifiestos, cada uno lleva solo las tarimas de su venta */
    const P=palsOfV(m,v),src={};P.forEach(p=>(p.lines||[]).forEach(l=>{const c=n0(l.cant),key=PCAL_KEY[l.cal];if(!(c>0)||!key)return;const L=lineOfCal(p,key,l);src[L]=src[L]||{};src[L][key]=(src[L][key]||0)+c}));
    return {src:src,z:Object.assign({},z,{nPal:P.length,t:Object.assign({},z.t,{tarimas:P})}),from:'pal'};
  }
  const sum=o=>Object.keys(o).reduce((a,L)=>a+CAL.reduce((s,c)=>s+((o[L]||{})[c.k]||0),0),0);
  const src={};
  sheetsOf(m).forEach(x=>{const q=x.variante==='1.5'?'1.5':'1';const mt=x.manT&&Object.keys(x.manT).length?x.manT:(x.manifiesto?{RPC:x.manifiesto}:{});Object.keys(mt).forEach(t=>{if(!TIPO_L[t])return;const v=mt[t]||{};CAL.forEach(c=>{const n=n0(v[c.k]);if(!n)return;const L=lineKey(q,lineType(t,c.k));src[L]=src[L]||{};src[L][c.k]=(src[L][c.k]||0)+n})})});
  if(pref==='man'&&sum(src)>0)return {src:src,z:z,from:'man'};
  if(z.nPal)return {src:z.palL,z:z,from:'pal'};
  if(sum(z.expL)>0)return {src:z.expL,z:z,from:'emp'};
  return sum(src)>0?{src:src,z:z,from:'man'}:{src:z.expL,z:z,from:'emp'};
}
function docQty(m,tp,v){
  const S=docSrc(m,undefined,v),z=S.z,src=S.src;
  const tot=(q,t)=>CAL.reduce((a,c)=>a+((src[lineKey(q,t)]||{})[c.k]||0),0);
  const all=TIPO_K.filter(t=>tot('1',t)||tot('1.5',t)),types=tp?[tp]:all,rows=[];
  const g=(q,k)=>types.reduce((a,t)=>a+((src[lineKey(q,t)]||{})[k]||0),0);
  CAL_ASC.forEach(k=>{const a=g('1',k),b=g('1.5',k);if(a||b)rows.push({k:k,l:CAL_LAB[k],a:a,b:b})});
  const ta=rows.reduce((s,r)=>s+r.a,0),tb=rows.reduce((s,r)=>s+r.b,0),byT={};
  all.forEach(t=>{byT[t]=tot('1',t)+tot('1.5',t)});
  return {rows:rows,ta:ta,tb:tb,t:ta+tb,types:all,byT:byT,tipo:tp||null,fromPal:!!z.nPal,nPal:z.nPal};
}
function cantAuto(q){
  const p=[];if(q.ta)p.push(fmt(q.ta)+' CALIDAD PRIMERA');if(q.tb)p.push(fmt(q.tb)+' CALIDAD UNO Y MEDIO');
  return p.join(' Y ');
}
/* tipos de empaque que salen en el manifiesto: todos (una hoja por tipo) o el elegido */
function manTypes(m){const q=docQty(m),s=dv(m,'manTipo');return q.types.indexOf(s)>=0?[s]:(q.types.length?q.types:['RPC'])}
/* tarimas agrupadas por empaque y calidad, para el pie del packing list */
/* resumen al final del Packing List: cajas por calibre de cada calidad, total de tarimas y de cajas */
function plCalRes(z){
  const Q={'PRIMERA':{},'UNO Y MEDIO':{}},STD=['110','150','175','200','230','250'];
  z.t.tarimas.forEach(p=>{(p.lines||[]).forEach(l=>{const q=lineQ(p,l)==='1.5'?'UNO Y MEDIO':'PRIMERA';const c=n0(l.cant);if(!(c>0))return;const k=String(l.cal||'').replace(/\s*[^\d\s].*$/,'').trim()||String(l.cal||'').trim()||'S/C';Q[q][k]=(Q[q][k]||0)+c})});
  return Object.keys(Q).filter(q=>q==='PRIMERA'||Object.keys(Q[q]).length).map(q=>{
    const ks=STD.concat(Object.keys(Q[q]).filter(k=>STD.indexOf(k)<0).sort((a,b)=>(parseFloat(a)||0)-(parseFloat(b)||0)));
    const rows=ks.map(k=>({cal:k,n:Q[q][k]||0}));return{q:q,label:'CALIDAD '+q,rows:rows,tot:rows.reduce((a,r)=>a+r.n,0)};
  });
}
/* si el contenido no cabe en la hoja, se reduce todo parejo para que salga en una sola página */
function fitOnePage(ops,W,H,top){
  let mx=0;ops.forEach(o=>{mx=Math.max(mx,(o.y||0)+(o.h||0))});
  const k=Math.min(1,(H-top)/mx);if(k>=1)return ops;
  const dx=(W-W*k)/2;
  return ops.map(o=>{const c=Object.assign({},o);c.x=o.x*k+dx;c.y=o.y*k;if(o.w!=null)c.w=o.w*k;if(o.h!=null)c.h=o.h*k;if(o.size)c.size=o.size*k;if(o.min)c.min=o.min*k;if(o.lw)c.lw=Math.max(1,o.lw*k);return c});
}
function plSummary(rows){const g={},out=[];rows.forEach(r=>{const k=r.tipo+' · '+r.cal;if(!g[k]){g[k]={l:k,n:0,cajas:0};out.push(g[k])}g[k].n++;g[k].cajas+=r.cajas});return out}

/* ===== lienzo / PDF / PPTX a partir de una lista de operaciones de dibujo (unidades a 150 ppp) ===== */
const DPI=150;
/* foto del tráiler (22 lugares en dos filas): c0 = centro de la primera fila de lugares y p = distancia entre filas, en pixeles de la foto */
const TRL={f:'img/trailer.jpg',w:305,h:933,c0:313.5,p:57.15,n:22};
async function trailerData(){try{return Object.assign({},await asset(TRL.f),{c0:TRL.c0,p:TRL.p,n:TRL.n})}catch(e){return null}}
/* v8.8: Packing List con la misma foto del tractor y la caja dibujada con un lugar por tarima (como Trazabilidad) */
async function plTrailer(m,v){
  const z=trazCalc(m),ph=await trailerComposite(z.nPal,v!=null&&multiV(m)?z.t.tarimas.map(p=>palV(m,p)===v):null);
  if(!ph)return trailerData();
  return Object.assign(ph,{c0:TRC.top+TRC.pad/2+TRC.pitch/2,p:TRC.pitch,n:z.nPal>0?z.nPal:TRC.std});
}
/* pone la foto a un costado de una tabla con una fila por tarima: cada fila de la foto (2 tarimas) mide lo mismo que 2 filas de la tabla */
function trailerOps(ops,tr,x,y0,rh){const k=2*rh/tr.p,w=tr.w*k,h=tr.h*k,y=y0+rh-tr.c0*k;ops.push({t:'i',b64:tr.b64,x:x,y:y,w:w,h:h});return{w:w,top:y,bottom:y+h}}
async function loadLogoData(e){try{return await asset(LOGO_F2[e])}catch(x){return null}}
function imgFromB64(b64){return new Promise(res=>{const im=new Image();im.onload=()=>res(im);im.onerror=()=>res(null);im.src='data:image/jpeg;base64,'+b64})}
function fitFont(x,s,w,size,bold,min){
  size=size||28;
  do{x.font=(bold?'bold ':'')+size+'px Arial,Helvetica,sans-serif'}while(x.measureText(s).width>w&&(size-=1)>(min||12));
  return size;
}
const _mc=document.createElement('canvas').getContext('2d');
function opSize(op){return op.wrap?op.size:fitFont(_mc,op.s,op.w-6,op.size,op.bold,op.min)}
/* letra más grande (hasta «size») con la que el texto cabe completo en varias líneas dentro del cuadro */
function fitWrap(s,w,h,size,min){for(let z=size;z>(min||9);z--){_mc.font='bold '+z+'px Arial,Helvetica,sans-serif';if(wrapLines(_mc,s,w-8).length*z*1.25<=h+2)return z}return min||9}
function wrapLines(x,s,w){
  const out=[];String(s).split('\n').forEach(par=>{
    let line='';par.split(/\s+/).forEach(wd=>{const t=line?line+' '+wd:wd;if(x.measureText(t).width>w&&line){out.push(line);line=wd}else line=t});out.push(line);
  });return out;
}
async function renderPage(pg,dpi){
  dpi=dpi||200;const k=dpi/DPI,cv=document.createElement('canvas');cv.width=Math.round(pg.w*k);cv.height=Math.round(pg.h*k);
  const x=cv.getContext('2d');x.scale(k,k);x.fillStyle='#ffffff';x.fillRect(0,0,pg.w,pg.h);
  for(const op of pg.ops){
    if(op.t==='r'){
      if(op.rad){const r=op.rad;x.beginPath();x.moveTo(op.x+r,op.y);x.arcTo(op.x+op.w,op.y,op.x+op.w,op.y+op.h,r);x.arcTo(op.x+op.w,op.y+op.h,op.x,op.y+op.h,r);x.arcTo(op.x,op.y+op.h,op.x,op.y,r);x.arcTo(op.x,op.y,op.x+op.w,op.y,r);x.closePath();
        if(op.fill){x.fillStyle=op.fill;x.fill()}if(op.line){x.strokeStyle=op.line;x.lineWidth=op.lw||2;x.stroke()}}
      else{
      if(op.fill){x.fillStyle=op.fill;x.fillRect(op.x,op.y,op.w,op.h)}
      if(op.line){x.strokeStyle=op.line;x.lineWidth=op.lw||2;x.strokeRect(op.x,op.y,op.w,op.h)}}
    }else if(op.t==='l'){
      x.strokeStyle=op.line||'#000';x.lineWidth=op.lw||2;x.beginPath();x.moveTo(op.x,op.y);x.lineTo(op.x+op.w,op.y+op.h);x.stroke();
    }else if(op.t==='i'){
      if(op.b64){const im=await imgFromB64(op.b64);if(im)x.drawImage(im,op.x,op.y,op.w,op.h)}
    }else if(op.t==='t'&&op.s!==''){
      x.fillStyle=op.color||'#111';x.textBaseline='middle';
      const al=op.align||'left';x.textAlign=al==='center'?'center':al==='right'?'right':'left';
      const tx=al==='center'?op.x+op.w/2:al==='right'?op.x+op.w-4:op.x+4;
      if(op.wrap){
        x.font=(op.bold?'bold ':'')+op.size+'px Arial,Helvetica,sans-serif';
        const ls=wrapLines(x,op.s,op.w-8),lh=op.size*1.25;
        /* v8.18.4: si ni una línea cabe de alto (celda baja con letra grande, como la fecha del registro), se dibuja en una línea en vez de omitirla */
        if(lh>op.h+2&&ls.length<=1){const sz=Math.max(op.min||8,Math.min(opSize(op),(op.h+2)/1.05));x.font=(op.bold?'bold ':'')+sz+'px Arial,Helvetica,sans-serif';x.fillText(op.s,tx,op.y+op.h/2+1)}
        else if(lh>op.h+2){x.fillText(ls[0],tx,op.y+op.h/2+1)}
        else{
        const y0=op.vm?op.y+Math.max(0,(op.h-Math.min(ls.length,Math.floor((op.h+2)/lh))*lh)/2):op.y;
        ls.forEach((l,i)=>{if(i*lh+lh<=op.h+2)x.fillText(l,tx,y0+lh/2+i*lh)});}
      }else{const sz=opSize(op);x.font=(op.bold?'bold ':'')+sz+'px Arial,Helvetica,sans-serif';x.fillText(op.s,tx,op.y+op.h/2+1)}
    }
  }
  return cv;
}
/* v8.42.1 · vistas previas nítidas. Los ppp salen del ancho real del cuadro × la densidad de la pantalla (devicePixelRatio),
   con tope de lado y de área para no agotar la memoria del teléfono. renderPage dibuja con medidas lógicas (x.scale), así que
   subir la resolución no cambia el diseño de la hoja: solo hay más píxeles. */
const PV_MAXSIDE=4096,PV_MAXAREA=12e6;
function pvDensity(){return Math.min(3,Math.max(1,window.devicePixelRatio||1))}
function pvAvail(max){const w=(document.documentElement&&document.documentElement.clientWidth)||360;return Math.max(160,Math.min(max||w,w-32))}
function pvDpi(pg,cssW,mult,minPx){
  const px=Math.max(minPx||0,Math.max(1,cssW)*pvDensity()*(mult||1));
  let k=px/pg.w;
  k=Math.min(k,PV_MAXSIDE/pg.w,PV_MAXSIDE/pg.h,Math.sqrt(PV_MAXAREA/(pg.w*pg.h)));
  return Math.max(0.3,k)*DPI;
}
/* JPEG como URL de blob (mucho más ligera que un base64 en memoria); libera el canvas al terminar */
function pvUrl(cv,q){
  return new Promise(res=>{
    const done=u=>{try{cv.width=cv.height=0}catch(e){}res(u)};
    const fb=()=>{let u='';try{u=cv.toDataURL('image/jpeg',q)}catch(e){}done(u)};
    try{cv.toBlob(b=>{if(!b)return fb();done(URL.createObjectURL(b))},'image/jpeg',q)}catch(e){fb()}
  });
}
function pvRevoke(u){if(typeof u==='string'&&u.slice(0,5)==='blob:'){try{URL.revokeObjectURL(u)}catch(e){}}}
function pvFree(list){(list||[]).forEach(p=>pvRevoke(p&&p.src))}
function b64ToBytes(b64){const s=atob(b64),u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i);return u}
/* PDF mínimo: una imagen JPEG por página */
function pdfFromCanvases(items){
  const enc=new TextEncoder(),chunks=[],offs=[];let len=0;
  const push=b=>{const u=typeof b==='string'?enc.encode(b):b;chunks.push(u);len+=u.length};
  const obj=(n,fn)=>{offs[n]=len;push(n+' 0 obj\n');fn();push('\nendobj\n')};
  push('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n');
  const n=items.length,imgs=items.map(it=>b64ToBytes(it.cv.toDataURL('image/jpeg',0.92).split(',')[1]));
  obj(1,()=>push('<< /Type /Catalog /Pages 2 0 R >>'));
  obj(2,()=>push('<< /Type /Pages /Count '+n+' /Kids ['+items.map((_,i)=>(3+i*3)+' 0 R').join(' ')+'] >>'));
  items.forEach((it,i)=>{
    const p=3+i*3,c=p+1,im=p+2,w=it.wpt,h=it.hpt;
    obj(p,()=>push('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 '+w.toFixed(2)+' '+h.toFixed(2)+'] /Resources << /XObject << /Im0 '+im+' 0 R >> >> /Contents '+c+' 0 R >>'));
    const cs='q '+w.toFixed(2)+' 0 0 '+h.toFixed(2)+' 0 0 cm /Im0 Do Q';
    obj(c,()=>push('<< /Length '+cs.length+' >>\nstream\n'+cs+'\nendstream'));
    obj(im,()=>{push('<< /Type /XObject /Subtype /Image /Width '+it.cv.width+' /Height '+it.cv.height+' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+imgs[i].length+' >>\nstream\n');push(imgs[i]);push('\nendstream')});
  });
  const xr=len,tot=3+n*3;
  push('xref\n0 '+tot+'\n0000000000 65535 f \n');
  for(let i=1;i<tot;i++)push(String(offs[i]).padStart(10,'0')+' 00000 n \n');
  push('trailer\n<< /Size '+tot+' /Root 1 0 R >>\nstartxref\n'+xr+'\n%%EOF');
  return new Blob(chunks,{type:'application/pdf'});
}
/* v8.9.3: imagen JPG a partir de las mismas hojas del PDF, a la misma resolución (200 ppp) o más; varias hojas van una debajo de otra */
async function pagesToJpg(pages,dpi){
  dpi=dpi||200;const cvs=[];for(const pg of pages)cvs.push(await renderPage(pg,dpi));
  if(!cvs.length)throw new Error('sin hojas');
  const blobOf=c=>new Promise((res,rej)=>c.toBlob(b=>b?res(b):rej(new Error('jpg')),'image/jpeg',0.95));
  if(cvs.length===1)return blobOf(cvs[0]);
  const G=Math.round(dpi/6),W=Math.max(...cvs.map(c=>c.width)),H=cvs.reduce((s,c)=>s+c.height,0)+G*(cvs.length+1);
  /* límite de un lienzo del navegador: si no cabe, se reduce lo justo */
  const k=Math.min(1,16000/H,Math.sqrt(120e6/((W+2*G)*H)));
  const cv=document.createElement('canvas');cv.width=Math.round((W+2*G)*k);cv.height=Math.round(H*k);
  const x=cv.getContext('2d');x.fillStyle='#d9dde1';x.fillRect(0,0,cv.width,cv.height);x.imageSmoothingQuality='high';
  let y=G;cvs.forEach(c=>{x.drawImage(c,Math.round((G+(W-c.width)/2)*k),Math.round(y*k),Math.round(c.width*k),Math.round(c.height*k));y+=c.height+G});
  return blobOf(cv);
}
async function pagesToPdf(pages){
  const items=[];
  for(const pg of pages){const cv=await renderPage(pg,200);items.push({cv:cv,wpt:pg.w*72/DPI,hpt:pg.h*72/DPI})}
  return pdfFromCanvases(items);
}
/* PowerPoint editable: cada operación es una forma o un cuadro de texto que se puede corregir */
async function pagesToPptx(pages,title){
  if(typeof PptxGenJS==='undefined')throw new Error('pptx');
  const px=new PptxGenJS();px.defineLayout({name:'DOC',width:pages[0].w/DPI,height:pages[0].h/DPI});px.layout='DOC';
  px.author=APP_NAME;px.title=title||'Documento';
  const I=v=>v/DPI,hex=c=>String(c||'000000').replace('#','');
  for(const pg of pages){
    const s=px.addSlide();s.background={color:'FFFFFF'};
    for(const op of pg.ops){
      if(op.t==='r'){
        const o={x:I(op.x),y:I(op.y),w:I(op.w),h:I(op.h)};
        o.fill=op.fill?{color:hex(op.fill)}:{type:'none'};
        o.line=op.line?{color:hex(op.line),width:(op.lw||2)*72/DPI}:{type:'none'};
        if(op.rad){o.rectRadius=op.rad/DPI;s.addShape(px.ShapeType.roundRect,o)}else s.addShape(px.ShapeType.rect,o);
      }else if(op.t==='l'){
        s.addShape(px.ShapeType.line,{x:I(op.x),y:I(op.y),w:I(op.w),h:I(op.h),line:{color:hex(op.line),width:(op.lw||2)*72/DPI}});
      }else if(op.t==='i'){
        if(op.b64)s.addImage({data:'data:image/jpeg;base64,'+op.b64,x:I(op.x),y:I(op.y),w:I(op.w),h:I(op.h)});
      }else if(op.t==='t'&&op.s!==''){
        const sz=op.wrap?op.size:opSize(op);
        s.addText(String(op.s),{x:I(op.x),y:I(op.y),w:I(op.w),h:I(op.h),fontFace:'Arial',fontSize:Math.max(6,Math.round(sz*72/DPI*2)/2),bold:!!op.bold,color:hex(op.color||'#111111'),align:op.align||'left',valign:op.wrap?'top':'middle',margin:[0,3,0,3],wrap:!!op.wrap,fit:'none'});
      }
    }
  }
  try{return await px.write({outputType:'blob'})}catch(e){return await px.write('blob')}
}

/* ===== Manifiesto (formato Citrilar / JC Cítricos): una sola hoja; en Datos de la carga va una columna por calidad y tipo de empaque (hasta 8) ===== */
const Q_COL={'1':'1ERA','1.5':'1½'};
function manCols(m,v){
  const S=docSrc(m,'man',v),z=S.z,src=S.src;
  const tot=L=>CAL.reduce((a,c)=>a+((src[L]||{})[c.k]||0),0);
  const found=TIPO_K.filter(t=>tot(lineKey('1',t))||tot(lineKey('1.5',t))),ts=found.length?found:['RPC'],cols=[];
  ts.forEach(t=>['1','1.5'].forEach(q=>{const L=lineKey(q,t),n=tot(L);if(n)cols.push({t:t,q:q,v:src[L]||{},n:n})}));
  if(!cols.length)cols.push({t:ts[0],q:'1',v:{},n:0}); /* solo salen las calidades que llevan cajas */
  const rows=CAL_ASC.filter(k=>cols.some(c=>(c.v[k]||0)>0)),byT={};
  ts.forEach(t=>{byT[t]=cols.filter(c=>c.t===t).reduce((a,c)=>a+c.n,0)});
  const ta=cols.filter(c=>c.q==='1').reduce((a,c)=>a+c.n,0),tb=cols.filter(c=>c.q==='1.5').reduce((a,c)=>a+c.n,0);
  return {cols:cols,rows:rows,types:ts,byT:byT,ta:ta,tb:tb,t:ta+tb,fromPal:!!z.nPal,nPal:z.nPal,from:S.from};
}
function manCant(m,C,auto,v){
  const u=auto?'':String(dvv(m,'cantTxt',v)||'').trim();if(u)return u;
  const p=[];if(C.ta)p.push(fmt(C.ta)+' CALIDAD PRIMERA');if(C.tb)p.push(fmt(C.tb)+' CALIDAD UNO Y MEDIO');
  /* v8.35.10: el tipo de empaque ya se declara abajo (Datos de la carga y totales por tipo): no se repite aquí */
  return p.join(' Y ');
}
/* v8.44 · manifiesto interno: la cantidad con su calidad y su tipo de empaque, desglosada si van varios tipos («800 CALIDAD PRIMERA EN RPC, 100 CALIDAD PRIMERA EN CTN Y 177 CALIDAD UNO Y MEDIO EN RPC») */
function manCantInt(m,C){
  const u=String(dv(m,'cantTxt')||'').trim();if(u)return u;
  const QL={'1':'CALIDAD PRIMERA','1.5':'CALIDAD UNO Y MEDIO'},p=[];
  ['1','1.5'].forEach(q=>C.cols.filter(c=>c.q===q&&c.n).forEach(c=>p.push(fmt(c.n)+' '+QL[q]+' EN '+TIPO_L[c.t].toUpperCase())));
  return p.length>1?p.slice(0,-1).join(', ')+' Y '+p[p.length-1]:(p[0]||'');
}
function manTypesTxt(C){return C.types.filter(t=>C.byT[t]).map(t=>TIPO_L[t].toUpperCase()+': '+fmt(C.byT[t])).join('   ')}
