  const nr=Math.max(1,C.rows.length),r00=hy+(multi?92:60),avail=yTot-14-r00,step=Math.max(30,Math.min(175,Math.floor(avail/nr))),r0=r00+Math.max(0,Math.floor((avail-step*nr)/2)),fs=Math.max(18,Math.min(n>4?38:n>2?46:54,Math.round(step*0.42)));
