function openOutInt(){
  const o=cur();if(!o)return;const m=docMain(o),f={},E=EMPS[m.emp];
  f.pdf=async()=>pagesToPdf(await internoPages(o));
  f.pptx=async()=>pagesToPptx(await internoPages(o),'Manifiesto interno');
  openOut({pages:()=>internoPages(o),title:'Manifiesto interno '+E.name+' '+(dv(m,'poCli')||m.cod),base:'ManifiestoInterno_'+fileSafe(E.name)+'_'+fileSafe(dv(m,'poCli')||m.cod),fmts:f});
}

