/* ===== PDF del registro y de la trazabilidad (tablas completas y legibles) ===== */
function tablePages(sp){
  const land=sp.land,W=land?1754:1240,H=land?1240:1754,M=50,pages=[];
  let ops=[],y=M;
  const newPage=()=>{pages.push({w:W,h:H,ops:ops});ops=[];y=M};
  const TX=(s,x,yy,w,h,p)=>ops.push(Object.assign({t:'t',s:s==null?'':String(s),x,y:yy,w,h,size:24,color:'#111'},p));
  if(sp.logo){const k=Math.min(260/sp.logo.w,100/sp.logo.h);ops.push({t:'i',b64:sp.logo.b64,x:W-M-sp.logo.w*k,y:y,w:sp.logo.w*k,h:sp.logo.h*k})}
  TX(sp.title,M,y,W-M*2-280,52,{size:38,bold:true});y+=56;
  if(sp.sub){TX(sp.sub,M,y,W-M*2-280,36,{size:24,color:sp.subColor||'#444'});y+=40}
  y=Math.max(y,M+110);
  if(sp.pre)y=sp.pre(ops,y,W,M,TX);
  else if(sp.kv&&sp.kv.length){
    const cols=land?4:3,cw=(W-M*2)/cols;
    sp.kv.forEach((a,i)=>{const cx=M+(i%cols)*cw,cy=y+Math.floor(i/cols)*62;TX(a[0],cx,cy,cw-10,24,{size:18,color:'#666'});TX(a[1]||'—',cx,cy+22,cw-10,34,{size:24,bold:true})});
    y+=Math.ceil(sp.kv.length/cols)*62+16;
  }
  sp.tables.forEach(t=>{
    if(!t.rows.length)return;
    const tw=W-M*2,sum=t.w.reduce((a,b)=>a+b,0),xs=[];let ax=M;t.w.forEach(w=>{xs.push(ax);ax+=w/sum*tw});xs.push(M+tw);
    const rh=t.rh||44,fs=t.fs||22;
    const header=()=>{
      ops.push({t:'r',x:M,y:y,w:tw,h:rh+4,fill:'#1b2c46'});
      t.head.forEach((h,i)=>TX(h,xs[i],y,xs[i+1]-xs[i],rh+4,{size:fs-2,bold:true,color:'#ffffff',align:i===0?'left':'center',min:12}));y+=rh+4;
    };
    /* una tabla que cabe completa en una hoja no se parte: pasa entera a la siguiente */
    const need=(t.title?46:0)+rh+4+t.rows.length*rh;
    if(y+rh*3>H-M||(y+need>H-M&&need<=H-M*2-60&&y>M+200))newPage();
    if(t.title){TX(t.title,M,y,tw,40,{size:28,bold:true});y+=46}
    header();
    t.rows.forEach((r,ri)=>{
      if(y+rh>H-M){newPage();TX((t.title||sp.title)+' (continuación)',M,y,tw,36,{size:22,bold:true,color:'#555'});y+=42;header()}
      const bold=r.bold,cells=r.c||r;
      if(bold)ops.push({t:'r',x:M,y:y,w:tw,h:rh,fill:'#e9eef4'});
      else if(ri%2)ops.push({t:'r',x:M,y:y,w:tw,h:rh,fill:'#f6f8fa'});
      cells.forEach((c,i)=>TX(c,xs[i],y,xs[i+1]-xs[i],rh,{size:fs,bold:!!bold,align:i===0||(t.left&&t.left.indexOf(i)>=0)?'left':'center',min:12}));
      ops.push({t:'l',x:M,y:y+rh,w:tw,h:0,line:'#cfd6de',lw:1});y+=rh;
    });
    y+=34;
  });
  if(sp.foot)TX(sp.foot,M,Math.min(y,H-M-30),W-M*2,30,{size:20,color:'#666'});
  pages.push({w:W,h:H,ops:ops});
  return pages;
}
/* v8.8: el PDF del Registro de empaque es el mismo Excel impreso: cada hoja (primera, 1.5) completa en una página */
