/* ===== pantalla de documentos ===== */
/* campos de documentos que se llenan desde Control Logístico */
const DOC_LIST={cliente:'cliente',linea:'transporte',operador:'conductor',eco:'trailer',vend:'vendedor'};
function docLists(m){
  const h=ensureTraz(m).hdr;
  return Object.keys(DOC_LIST).map(k=>{const f=DOC_LIST[k];return `<datalist id="dg-${f}">${catList(f,dv(m,'linea')||h.transporte).map(v=>`<option value="${esc(v)}"></option>`).join('')}</datalist>`}).join('');
}
/* al elegir un dato del catálogo en el documento se completan los que dependen de él */
document.addEventListener('change',e=>{
  const el=e.target;if(!el||!el.dataset||!el.dataset.doc||ro||!cur())return;const m=docMain(cur());if(!m)return;
  const k=el.dataset.doc,v=String(el.value||'').trim();if(!v){docBlankWarn(m,k);return}let ch=false;
  const put=(kk,val)=>{val=String(val==null?'':val).trim();if(!val||String(dv(m,kk)||'')===val)return;const hk=DOC2HDR[kk];if(hk){ensureTraz(m).hdr[hk]=val;if(m.docs)delete m.docs[kk]}else{m.docs=m.docs||{};m.docs[kk]=val}ch=true};
  if(k==='linea'){const t=regFind('transportistas',v);if(t){put('caat',t.caat);put('alpha',t.alpha)}}
  if(k==='operador'){const x=regFind('conductores',v);if(x){if(!String(dv(m,'eco')||'').trim()||!regFind('trailers',dv(m,'eco')))put('placasT',x.placas);if(x.transporte&&!String(dv(m,'linea')||'').trim())put('linea',x.transporte)}}
  if(k==='eco'){const x=regFind('trailers',v);if(x){put('placasT',x.placas);if(x.transporte&&!String(dv(m,'linea')||'').trim())put('linea',x.transporte)}}
  if(k==='vend'){const x=regFind('vendedores',v);if(x)put('tel',x.tel)}
  /* el cliente del documento es el del pedido: Registro, Trazabilidad y las hojas 1 y 1.5 */
  if(k==='cliente'&&!docV(m)){setCliente(m,v);ch=true}
  /* v8.44: factura y P.O. también son las del pedido: lo que se cambia en un documento cambia en Registro y en las hojas 1 y 1.5 */
  if((k==='factura'||k==='poCli')&&!docV(m)){ordSync(m,k==='factura'?'factura':'po',v);ch=true}
  if(ch){touch(m);render()}
});
function docF(m,k,l,type,wide){
  const ls=DOC_LIST[k];return `<label class="fld${wide?' wide':''}" for="d-${k}"><span>${esc(l)}</span><input class="in txt" id="d-${k}" type="${type||'text'}" autocomplete="off" data-doc="${k}"${ls?` list="dg-${ls}"`:''} value="${esc(dvv(m,k,docV(m)))}"${ro?' readonly':''}></label>`;
}
function qtyTable(m,v){
  const C=manCols(m,v);if(!C.rows.length)return '<p class="note">Aún no hay cantidades. Captura el manifiesto en Resumen o las tarimas en Código de Trazabilidad y aquí aparecen solas.</p>';
  const gc=`grid-template-columns:64px repeat(${C.cols.length},minmax(0,1fr))`,multi=C.types.length>1;
  const th=C.cols.map(c=>`<span style="text-align:right">${multi?esc(TIPO_L[c.t])+'<br>':''}${Q_COL[c.q]}</span>`).join('');
  return `<div class="sumbox qtyb mtab"><div class="shead" style="${gc}"><span>Tamaño</span>${th}</div>${C.rows.map(k=>`<div class="srow" style="${gc}"><span class="cl">${esc(CAL_LAB[k])}</span>${C.cols.map(c=>`<span class="mono" style="text-align:right">${c.v[k]?fmt(c.v[k]):'–'}</span>`).join('')}</div>`).join('')}<div class="srow mtot" style="${gc}"><span class="k">Total</span>${C.cols.map(c=>`<span class="mono" style="text-align:right">${fmt(c.n)}</span>`).join('')}</div><div class="totline"><span class="k">Total de cajas</span><b>${fmt(C.t)}</b></div><p class="note" style="margin-top:6px">${esc(manTypesTxt(C))}</p></div>`;
}
function docsView(o){
  docLink(docMain(o));
  const m=docMain(o),v=docV(m),mv=multiV(m),q=docQty(m,null,v),C=manCols(m,v);
  const tabs=`<div class="tabs" role="tablist">${[['man','Manifiesto'],['pl','Packing List']].map(t=>`<button class="tab" role="tab" data-act="dx:tab:${t[0]}" aria-selected="${docTab===t[0]}">${t[1]}</button>`).join('')}</div>`;
  const head=`<section class="label"><div class="lrow"><div><div class="k">Pedido ${esc(m.emp)} · ${esc(m.emb)}</div><div class="big">${esc(m.cod)}</div></div><div style="text-align:right"><span class="chip">${q.fromPal?q.nPal+(q.nPal===1?' tarima':' tarimas'):'Sin tarimas'}</span></div></div></section>`;
  const note=C.from==='man'?`<div class="panel info"><p class="note">Las cantidades salen del manifiesto capturado en Resumen. Puedes ver y generar el manifiesto aunque todavía no esté el código de trazabilidad.</p></div>`:C.from==='pal'?'':`<div class="panel warn"><p class="note">Todavía no hay manifiesto capturado en Resumen ni tarimas. Las cantidades salen de lo empacado; captura el manifiesto en Resumen para que salga completo.</p></div>`;
  let body='';
  if(docTab==='man'){
    const ch=`<div class="panel info"><p class="note">El manifiesto sale en una sola hoja. Datos de la carga lleva una columna por cada calidad y tipo de empaque del embarque (hasta 8): ${esc(C.cols.map(c=>TIPO_L[c.t]+' '+Q_COL[c.q]).join(', '))}.</p></div>`;
    body=`<div class="dsk ddoc"><div class="dcol">${ch}<div class="sec">Datos de la carga${mv?' · manifiesto '+ventaN(m,v):''}</div><div class="panel">${qtyTable(m,v)}</div>${note}${liveHtml()}</div><div class="dcol">
<div class="sec">Encabezado</div><div class="panel"><div class="grid2 hdrgrid">${docF(m,'h1','Membrete: empresa',0,1)}${docF(m,'h2','Membrete: línea 2',0,1)}${docF(m,'h3','Membrete: línea 3',0,1)}${docF(m,'salida','Fecha de salida','date')}${docF(m,'llegada','Fecha de llegada','date')}${docF(m,'cliente','Compañía',0,1)}${docF(m,'factura','No. de factura')}${docF(m,'poCli','P.O. (recuadro)')}${docF(m,'poLinea','P.O. línea (cliente y número)')}${docF(m,'cantTxt','Cantidad de cajas (vacío = automático)',0,1)}</div><p class="note" style="margin-top:8px">Cantidad automática: ${esc(manCant(m,C,1)||'—')}</p></div>
<div class="sec">Datos del transporte</div><div class="panel"><div class="grid2 hdrgrid">${docF(m,'linea','Transportista',0,1)}${docF(m,'operador','Conductor',0,1)}${docF(m,'placasT','Placas del tractor')}${docF(m,'placasF','Placas del termo')}${docF(m,'coment','Comentarios',0,1)}</div></div>
<div class="sec">Varios</div><div class="panel"><div class="grid2 hdrgrid">${docF(m,'alpha','Código ALPHA')}${docF(m,'caat','Código CAAT')}${docF(m,'eco','Trailer (núm. económico)')}${docF(m,'cert','Certificado')}</div></div>
<div class="panel"><p class="note">Encabezado, transporte y varios se llenan solos con lo capturado en Código de Trazabilidad, que a su vez toma los datos de Control Logístico. Al elegir un transportista, conductor, trailer o vendedor del catálogo se completan sus teléfonos, placas y códigos. Aquí los puedes corregir y se guardan con el pedido.</p><div class="pact">${genMenu('man','Generar manifiesto')}</div></div>
${v?'':`<div class="sec">Manifiesto interno · ${esc(EMPS[m.emp].name)}</div><div class="panel"><p class="note">Formato interno de ${esc((DOC_MX[m.emp]||DOC_MX.VL).name)}, con su logotipo, R.F.C. y dirección en México. ${mv?'Es uno solo para todo el viaje: lleva la carga de todas las tarimas, aunque vayan en varios manifiestos.':'Lleva la misma carga y el mismo transporte que el manifiesto.'}</p><div class="grid2 hdrgrid" style="margin-top:8px">${docF(m,'viaje','No. de viaje')}${docF(m,'sello','Num. de sello')}</div><div class="pact">${genMenu('int','Generar manifiesto interno')}</div></div>`}</div></div>`;
  }else{
    TM=tipoMapFor(m);
    const sm=plSummary(plCtx(m,v).rows.filter(r=>!r.empty));
    body=`<div class="dsk ddoc"><div class="dcol"><div class="sec">Encabezado del packing list</div><div class="panel"><div class="grid2 hdrgrid">${docF(m,'salida','Fecha de salida','date')}${docF(m,'hora','Hora de salida','time')}${docF(m,'llegada','Fecha de llegada','date')}${docF(m,'poCli','PO# cliente')}${docF(m,'prov','Proveedor',0,1)}${docF(m,'cliente','Cliente',0,1)}${docF(m,'vend','Vendedor')}${docF(m,'pOrder','P. Order')}${docF(m,'tel','Teléfono del vendedor')}${docF(m,'sello','Num. de sello')}</div></div></div><div class="dcol">
<div class="sec">Tarimas por empaque y calidad</div><div class="panel">${sm.length?sm.map(g=>`<div class="kv"><span>${esc(g.l)}</span><b>${g.n} ${g.n===1?'tarima':'tarimas'} · ${fmt(g.cajas)} cajas</b></div>`).join(''):'<p class="note">Captura las tarimas en Código de Trazabilidad para que aparezcan aquí.</p>'}<div class="pact"><button class="btn" data-act="dx:pv:pl" ${q.nPal?'':'disabled'}>Vista previa</button><button class="btn primary" data-act="dx:outpl" ${q.nPal?'':'disabled'}>Generar packing list</button></div></div>${q.nPal?liveHtml():''}</div></div>`;
  }
  return topbar(m.cod+' · Documentos','docback')+`<main class="wrap">${lockBan(m)}${head}${ventasHtml(m)}${tabs}${body}</main>${docLists(m)}`;
}
/* botón Generar con sus opciones desplegadas: Vista previa, PDF y PowerPoint editable */
let genOpen=null;
function genMenu(k,label){
  const op=genOpen===k;
  return `<div class="gmenu"><button class="btn primary" data-act="dx:gm:${k}" aria-expanded="${op}" aria-haspopup="menu">${esc(label)} <span aria-hidden="true">${op?'▴':'▾'}</span></button>${op?`<div class="gmlist" role="menu"><button role="menuitem" data-act="dx:pv:${k}">Vista previa</button><button role="menuitem" data-act="dx:dl:${k}.pdf">PDF</button><button role="menuitem" data-act="dx:dl:${k}.pptx">PowerPoint editable</button></div>`:''}</div>`;
}
/* vista en vivo: el manifiesto se vuelve a dibujar mientras se llenan las casillas */
let liveK='man',liveSrc='',liveSrcK='',liveT=null,liveT2=null,liveN=0;
function liveClr(){pvRevoke(liveSrc);liveSrc=''}
function liveKind(){return docTab==='pl'?'pl':liveK}
function liveHtml(){
  const b=(k,l)=>`<button class="btn sm" data-act="dx:lv:${k}" aria-pressed="${liveK===k}">${l}</button>`,k=liveKind();
  const nm={man:'manifiesto',int:'manifiesto interno',pl:'packing list'}[k];
  return `<div class="sec">Vista en vivo</div><div class="panel lvbox">${k==='pl'?'':`<div class="lvsw" role="group" aria-label="Documento">${b('man','Manifiesto')}${b('int','Manifiesto interno')}</div>`}${pzBar('lvpg')}<div class="lvpg pz${(PZ.lvpg||1)>1.01?' pzin':''}" id="pz-lvpg" style="--pz:${PZ.lvpg||1}">${liveSrc&&liveSrcK===k?`<img id="lvimg" src="${liveSrc}" alt="Vista en vivo del ${nm}">`:'<img id="lvimg" alt="" hidden><p class="note" id="lvwait">Preparando la vista…</p>'}</div><p class="note">Se actualiza sola al escribir. Así sale el ${nm}${k==='pl'?' (primera hoja)':''}.</p></div>`;
}
function liveSched(ms){
  clearTimeout(liveT);clearTimeout(liveT2);
  liveT=setTimeout(async()=>{
    const o=cur();if(!o||view!=='docs')return;const n=++liveN,k=liveKind();
    try{const v=docV(docMain(o));const pg=await (k==='pl'?packingPages(o,v):k==='int'?internoPages(o):manifestPages(o,v));
      const box=document.querySelector('.lvpg'),cssW=Math.max(160,Math.min(520,box&&box.clientWidth?box.clientWidth-16:360));
      /* v8.42.1: primero una pasada rápida (mientras se escribe) y, ya quieto, otra nítida según la pantalla */
      const paint=async(mult,minPx,q)=>{
        const cv=await renderPage(pg[0],pvDpi(pg[0],cssW,mult,minPx));if(n!==liveN){cv.width=cv.height=0;return false}
        const u=await pvUrl(cv,q);if(n!==liveN){pvRevoke(u);return false}
        const old=liveSrc;liveSrc=u;liveSrcK=k;
        const im=document.getElementById('lvimg');if(im){im.src=u;im.hidden=false}
        const w=document.getElementById('lvwait');if(w)w.remove();
        if(old&&old!==u)pvRevoke(old);return true};
      if(await paint(.75,600,.8))liveT2=setTimeout(()=>{if(n===liveN)paint(1.5,1000,.92).catch(()=>{})},650);
    }catch(e){}
  },ms==null?350:ms);
}
function docAct(verb,arg){
  const o=cur();
  if(arg&&String(arg).indexOf('@')>=0){const q=String(arg).split('@'),m=o&&docMain(o);arg=q[0];if(m)setDocV(m,q[1]==='0'?'':q[1])}
  if(verb&&String(verb).indexOf('@')>=0){const q=String(verb).split('@'),m=o&&docMain(o);verb=q[0];if(m)setDocV(m,q[1]==='0'?'':q[1])}
  switch(verb){
    case 'vsel':{const m=o&&docMain(o);if(m){setDocV(m,arg==='0'?'':arg);liveClr();render();liveSched(0)}break}
    case 'vadd':{const m=o&&docMain(o);if(m){ventaAdd(m);liveClr();liveSched(0)}break}
    case 'vdel':{const m=o&&docMain(o);if(m){ventaDel(m);liveSched(0)}break}
    case 'vasg':{const m=o&&docMain(o);if(m){ventaAsg(m,arg);liveSched(0)}break}
    case 'vrng':{const m=o&&docMain(o);if(m){ventaRng(m);liveSched(0)}break}
    case 'vemp':{const m=o&&docMain(o);if(m){ventaEmpSet(m,arg);liveClr();liveSched(0)}break}
    case 'gm':genOpen=genOpen===arg?null:arg;render();break;
    case 'dl':{const q=String(arg||'').split('.'),F={man:openOutMan,int:openOutInt}[q[0]];genOpen=null;if(F&&(q[1]==='pdf'||q[1]==='pptx')){render();F();outDo('save',q[1])}else if(F&&q[1]==='print'){render();F();outDo('print','pdf')}break}
    case 'lv':liveK=arg==='int'?'int':'man';liveClr();render();break;
    case 'open':if(!o)return;liveClr();genOpen=null;docFrom=view==='trazo'?'trazo':view==='dvt'?'dvt':'order';view='docs';docTab=arg==='pl'?'pl':'man';sheet=null;renderSheet();render();window.scrollTo(0,0);break;
    case 'tab':docTab=arg==='pl'?'pl':'man';render();break;
    case 'mt':if(ro)return;setDocVal('manTipo',arg);render();break;
    case 'outman':openOutMan();break;
    case 'outint':openOutInt();break;
    case 'outpl':openOutPl();break;
    case 'outreg':openOutReg();break;
    case 'outtraz':openOutTraz(true);break;
    case 'wa':outDo('wa',arg);break;
    case 'prev':outPrev();break;
    case 'pv':{const F={reg:openOutReg,traz:()=>openOutTraz(true),man:openOutMan,int:openOutInt,pl:openOutPl}[arg];genOpen=null;if(F){F();outPrev()}break}
    case 'pvback':if(sheet&&sheet.kind==='out'){pvFree(sheet.prev);sheet.prev=null;renderSheet()}break;
    case 'save':outDo('save',arg);break;
    case 'print':outDo('print',arg);break;
    case 'pdfimg':prodImgPdf();break;
  }
}
