  const fm=new Map();
  V.slice().sort((a,b)=>String(a.fecha||'').localeCompare(String(b.fecha||''))||String(a.cod).localeCompare(String(b.cod),'es',{numeric:true})).forEach(o=>{
    const k=o.emp+'|'+o.cod;let r=fm.get(k);if(!r){r={emp:o.emp,cod:o.cod,po:'',emb:'',fecha:o.fecha||'',seg:0,llevo:0,cera:0,tor:0,des:0,c15:0,jug:0};fm.set(k,r)}
    if(o.variante!=='1.5'||!r.po){r.po=o.po||r.po;r.emb=o.emb||r.emb}
    const M=compute(o);
    M.rows.forEach(x=>{const p=x.p;if(isSob(p)||isSegRow(p))return;const ll=Math.min(n0(p.seg),Math.max(0,n0(p.segLlevo)));
      r.seg+=n0(p.seg)-ll;r.llevo+=ll;r.cera+=n0(p.cera);r.tor+=n0(p.tor);r.des+=n0(p.des);r.jug+=n0(p.jug);if(o.variante==='1.5')r.c15+=x.t});
  });
  const first=[...fm.values()].filter(r=>r.seg||r.llevo||r.cera||r.tor||r.des||r.c15);
