  const isC=x=>!!x.cera||/\.c$/.test(x.lot||'');
  const S={manS:0,manC:0,cieS:0,cieC:0,penS:0,penC:0};
  man.forEach(z=>{S[isC(z)?'manC':'manS']+=n0(z.n)});cie.forEach(x=>{S[isC(x)?'cieC':'cieS']+=n0(x.n)});
  if(!cl)jugCandidates(wk).forEach(l=>{S[l.cera?'penC':'penS']+=l.av});
  /* lista de envíos para la pantalla, con lo necesario para anular */
  const env=[];
  visible().forEach(o=>(o.productores||[]).forEach(p=>{const mm=p.jugEnv;if(!mm)return;Object.keys(mm).forEach(id=>{const z=mm[id];if(z&&z.wk===wk&&n0(z.n)>0)env.push(Object.assign({sid:id,src:'o',hid:p.id},z))})}));
  entradas().forEach(e=>{const mm=e.jugEnv;if(!mm)return;Object.keys(mm).forEach(id=>{const z=mm[id];if(z&&z.wk===wk&&n0(z.n)>0)env.push(Object.assign({sid:id,src:'e',hid:e.id},z))})});
  env.sort((a,b)=>(b.at||0)-(a.at||0));
  return {wk:wk,num:m?+m[2]:0,anio:m?+m[1]:0,yy:m?String(m[1]).slice(2):'',span:wkSpan(wk),closed:cl,T:T,lots:lots,first:first,maq:maq,S:S,env:env,cie:cie,
    noCorS:S.manS+S.cieS+S.penS,noCorC:S.manC+S.cieC+S.penC,pend:S.penS+S.penC};
