  const DV=desWk(wk),DS={casEmp:0,casMaq:0,recepKg:0,recepCj:0,vac:DV.vac+DV.auto,pend:DV.pend};D.first.forEach(r=>DS.casEmp+=r.des);maq.forEach(r=>DS.casMaq+=r.des);recep.forEach(r=>{DS.recepKg+=r.desKg;DS.recepCj+=r.desCj});
