  const Q={gen:lsum(l=>isO(l)&&!l.cera,'tot'),cera:lsum(l=>isO(l)&&l.cera,'tot'),recep:lsum(l=>l.src==='e'&&!l.rc,'tot'),rem:lsum(l=>l.rem,'tot'),alm:lsum(l=>l.alm,'tot'),rc:lsum(l=>l.rc,'tot'),
    maq:lsum(()=>true,'proc'),sinSrc:maq.reduce((s2,r)=>s2+(r.src.length?0:r.ent),0),prev:D.T.prev,jugB:lsum(()=>true,'jugM'),jugC:lsum(()=>true,'jugC'),mer:lsum(()=>true,'mer'),nac:lsum(()=>true,'nac'),tor:lsum(()=>true,'tor'),des:lsum(()=>true,'des'),av:D.T.av,vend:lsum(()=>true,'vend'),llevo:D.T.llevo};
  Q.ent=Q.gen+Q.cera+Q.recep+Q.rem+Q.alm+Q.rc;Q.sal=Q.maq+Q.jugB+Q.jugC+Q.mer+Q.nac+Q.tor+Q.des+Q.av+Q.vend;Q.otros=Math.round((Q.ent-Q.sal)*100)/100;
