    if(t.jugB||t.jugC)N.push('A Juguera sin maquilar: '+[t.jugB?fm(t.jugB)+' con el botón':'',t.jugC?fm(t.jugC)+' al cerrar la semana':''].filter(Boolean).join(' y ')+'.');
    if(t.alm||t.rc)N.push([t.alm?fm(t.alm)+' bajaron a segunda en el almacén':'',t.rc?fm(t.rc)+' de desecho se reclasificaron a segunda':''].filter(Boolean).join(' y ')+'.');
