  return Object.assign({},D,{emp:(mains[0]&&mains[0].emp)||emp,recep:recep,maq2:maq,proc:proc,trips:trips,J:J,TO:TO,DS:DS,Q:Q,VT:VT,lots2:lots,kg:{seg:SEG_KG,c15:PESOS.kg.RPC,ctn:PESOS.kg.CTN,tara:TARA_KG}});
