/* ---------- v8.28 · Vaciar desecho ----------
   El desecho (tercera calidad) se captura por renglón. «Vaciar desecho» registra que esas cajas salieron del empaque.
   Se guarda en el pedido (o.desVac) para sincronizarse con él; no cambia pagos ni la merma valorizada.
   Al cerrar la semana, lo que falte por vaciar se vacía solo (PER.list[k].des); al reabrirla, regresa. */
/* v8.42: también las segundas que pasaron a desecho en el almacén, menos lo que se reclasificó a segunda */
function desOrd(o){return (o.productores||[]).reduce((s,p)=>s+desRowNet(o,p),0)}
function desVacOf(o){const m=o.desVac||{};return Object.keys(m).map(id=>Object.assign({id:id,oid:o.id,cod:o.cod},m[id]))}
function desWk(wk){
  const V=visible().filter(o=>wkOf(o)===wk).sort((a,b)=>String(a.fecha||'').localeCompare(String(b.fecha||''))||String(a.cod).localeCompare(String(b.cod),'es',{numeric:true}));
  const P=PER.list[wk],cie=P&&P.closed&&P.des?(P.des.items||[]):[],cm=new Map();cie.forEach(x=>cm.set(x.oid,(cm.get(x.oid)||0)+n0(x.n)));
  let cap=0,vac=0,auto=0;const ords=[],env=[];
  V.forEach(o=>{const d=desOrd(o),L=desVacOf(o),v=L.filter(z=>!z.anul).reduce((s2,z)=>s2+n0(z.n),0),a=cm.get(o.id)||0;
    cap+=d;vac+=v;auto+=a;L.forEach(z=>env.push(z));if(d||v||a)ords.push({o:o,cod:o.cod,des:d,vac:v,auto:a,pend:Math.max(0,d-v-a)})});
  env.sort((a,b)=>(b.at||0)-(a.at||0));
  return {cap:cap,vac:vac,auto:auto,pend:ords.reduce((s2,x)=>s2+x.pend,0),ords:ords,env:env};
}
function desOpen(wk){
  if(ro||!canAlm()){toast('Solo el jefe de empaque o la administración vacían el desecho');return}
  if(wkClosed(wk)){toast(wkLab(wk)+' está cerrada');return}
  const D=desWk(wk);if(!D.pend){toast('No hay desecho por vaciar en '+wkLab(wk));return}
  sheet={kind:'desv',wk:wk,n:String(D.pend),kg:'',nota:''};renderSheet();
}
function desvHtml(){
  const D=desWk(sheet.wk),g=D.ords.filter(x=>x.pend>0);
  return `<h3>Vaciar desecho · ${esc(wkLab(sheet.wk))}</h3><p class="note">Registra que el desecho (tercera calidad) salió del empaque. Queda en el historial y en las estadísticas; no cambia pagos.</p>
<div class="panel">${g.map(x=>`<div class="kv"><span class="mono">${esc(x.cod)}</span><b>${fmt(x.pend)}</b></div>`).join('')}<div class="kv tot"><span>Por vaciar</span><b>${fmt(D.pend)}</b></div></div>
<div class="grid2" style="margin-top:10px"><label class="fld" for="dv-n"><span>Cajas que se vacían</span><input class="in" id="dv-n" inputmode="numeric" autocomplete="off" data-dvf="n" value="${esc(sheet.n)}"></label><label class="fld" for="dv-kg"><span>Kilos de báscula (opcional)</span><input class="in" id="dv-kg" inputmode="decimal" autocomplete="off" data-dvf="kg" value="${esc(sheet.kg)}"></label></div>
<label class="fld" for="dv-nota"><span>Nota (opcional)</span><input class="in txt" id="dv-nota" autocomplete="off" data-dvf="nota" value="${esc(sheet.nota)}" placeholder="Por ejemplo: se lo llevó el camión de composta"></label>
<p class="note">Si se vacía solo una parte, escribe cuántas cajas; se descuentan primero de los viajes más antiguos.</p>
<div class="srow2"><button class="btn" data-act="closesheet">Cancelar</button><button class="btn primary" data-act="dvgo">Vaciar</button></div>`;
}
function desGo(){
  if(!sheet||sheet.kind!=='desv'||ro||!canAlm())return;const wk=sheet.wk;
  if(wkClosed(wk)){toast(wkLab(wk)+' está cerrada');return}
  const D=desWk(wk);let n=Math.round(n0(sheet.n));if(n<=0){toast('Escribe cuántas cajas se vacían');return}
  if(n>D.pend){toast('Solo hay '+fmt(D.pend)+' cajas por vaciar');return}
  const kg=num(sheet.kg),tot=n,at=Date.now(),by=whoName(),nota=String(sheet.nota||'').trim();
  D.ords.forEach(x=>{if(n<=0||x.pend<=0)return;const k=Math.min(n,x.pend);n-=k;
    x.o.desVac=Object.assign({},x.o.desVac||{});x.o.desVac[uid()]={n:k,wk:wk,at:at,by:by,kg:kg!=null&&kg>0?Math.round(kg*k/tot*100)/100:undefined,nota:nota||undefined};touch(x.o)});
  logAdd({k:'note',where:'Recepción',ctx:{t:'w',id:wk,cod:wkLab(wk)},lab:'Vaciar desecho',o:'',n:fmt(tot)+' cajas'+(kg?' · '+fmt(kg)+' kg':'')+(nota?' · '+nota:'')});
  sheet=null;renderSheet();render();toast('Se vaciaron '+fmt(tot)+' '+(tot===1?'caja':'cajas')+' de desecho');if(canAuto())doSync(true);
}
function desAnular(oid,id){
  if(ro||!canAlm())return;const o=orders.find(x=>x.id===oid),z=o&&o.desVac&&o.desVac[id];if(!z||z.anul)return;
  if(wkClosed(z.wk)){toast(wkLab(z.wk)+' está cerrada; no se puede anular');return}
  const k='dvan:'+oid+':'+id;if(confirmKey!==k){armConfirm(k);render();return}confirmKey=null;
  o.desVac=Object.assign({},o.desVac);o.desVac[id]=Object.assign({},z,{anul:true,anulBy:whoName(),anulAt:Date.now()});touch(o);
  logAdd({k:'note',where:'Recepción',ctx:ctxOf(o),lab:'Vaciado de desecho anulado',o:fmt(z.n)+' cajas',n:'Anulado'});render();toast('Vaciado anulado: '+fmt(z.n)+' cajas regresan a desecho por vaciar');
}
/* índices de desecho y Juguera de una semana, por productor (cajas totales = primera + segundas + cera + Torreón + desecho + Juguera) */
function desIdx(wk){
  const V=visible().filter(o=>wkOf(o)===wk&&o.variante!=='1.5'),m=new Map(),L=[...seg2Lots().values()].filter(l=>l.wk===wk);
  V.forEach(o=>compute(o).rows.forEach(x=>{const p=x.p;if(isSob(p)||isSegRow(p))return;const k=pKey(p);let a=m.get(k);
    if(!a){const pc=pCode(p),li=pc?LISTA.find(y=>y.c===pc):null;a={k:k,nombre:(li&&li.n)||p.nombre||'Sin nombre',cod:pc,tot:0,des:0,jug:0,mw:0,mk:0};m.set(k,a)}
    const t=n0(x.t)+n0(p.seg)+n0(p.cera)+n0(p.tor)+n0(p.des)+n0(p.jug);a.tot+=t;a.des+=n0(p.des);a.jug+=n0(p.jug);
    const mu=muesOf(p);if(mu&&mu.des!=null&&t>0){a.mw+=t;a.mk+=mu.des*t}}));
  L.forEach(l=>{const a=[...m.values()].find(y=>y.k===l.key||(l.codigo&&y.cod===l.codigo));if(a)a.jug+=n0(l.jug)});
  const R=[...m.values()].filter(a=>a.tot>0).map(a=>Object.assign(a,{pd:a.des/a.tot*100,pj:a.jug/a.tot*100,pm:a.mw?a.mk/a.mw:null})).sort((a,b)=>b.pd-a.pd);
  const T=R.reduce((s2,a)=>({tot:s2.tot+a.tot,des:s2.des+a.des,jug:s2.jug+a.jug}),{tot:0,des:0,jug:0});
  return {R:R,T:T,pd:T.tot?T.des/T.tot*100:0,pj:T.tot?T.jug/T.tot*100:0};
}
$sh.addEventListener('input',e=>{const t=e.target;if(sheet&&sheet.kind==='desv'&&t.dataset&&t.dataset.dvf)sheet[t.dataset.dvf]=t.value});
const DES_LIM=8; /* % de desecho a partir del cual se avisa por productor */
function desIdxHtml(wk){
  const I=desIdx(wk);if(!I.R.length)return '<p class="note">Sin empaques esta semana.</p>';
  const pc=v=>v==null?'—':fmt(v,1)+'%';
  const ks=segSemKeys().filter(k=>k<=wk).slice(0,8),tr=ks.map(k=>{const J=desIdx(k),D=desWk(k);return {k:k,pd:J.pd,pj:J.pj,cap:D.cap,vac:D.vac+D.auto}});
  const alto=I.R.filter(a=>a.pd>=DES_LIM);
  return `<div class="ig tot tot4"><div><span>% de desecho</span><b>${pc(I.pd)}</b><small>${fmt(I.T.des)} de ${fmt(I.T.tot)} cajas</small></div><div><span>% a Juguera</span><b>${pc(I.pj)}</b><small>${fmt(I.T.jug)} cajas</small></div><div><span>Productores sobre ${DES_LIM}% de desecho</span><b class="${alto.length?'neg':''}">${fmt(alto.length)}</b></div><div><span>Productores</span><b>${fmt(I.R.length)}</b></div></div>
${alto.length?`<div class="warnbox" style="margin-top:8px"><strong>Desecho alto</strong><div>${alto.map(a=>esc(a.nombre)+' ('+pc(a.pd)+')').join(', ')}. Conviene revisar la fruta con el productor.</div></div>`:''}
<div class="tblx"><table class="stbl"><thead><tr><th>Productor</th><th class="r">Cajas</th><th class="r">Desecho</th><th class="r">% desecho</th><th class="r">Muestreo</th><th class="r">Juguera</th><th class="r">% Juguera</th></tr></thead><tbody>${I.R.map(a=>`<tr><th scope="row">${esc(a.nombre)}${a.cod?`<small class="mono"> · ${pad(a.cod,3)}</small>`:''}</th><td class="r">${fmt(a.tot)}</td><td class="r">${fmt(a.des)}</td><td class="r${a.pd>=DES_LIM?' neg':''}">${pc(a.pd)}</td><td class="r">${pc(a.pm)}</td><td class="r">${fmt(a.jug)}</td><td class="r">${pc(a.pj)}</td></tr>`).join('')}</tbody></table></div>
<p class="note">Muestreo = % de desecho del muestreo de recepción. Si se aleja mucho del real, el muestreo no está reflejando la fruta.</p>
${tr.length>1?`<div class="sec">Últimas semanas</div><div class="tblx"><table class="stbl"><thead><tr><th>Semana</th><th class="r">% desecho</th><th class="r">% Juguera</th><th class="r">Desecho capturado</th><th class="r">Desecho vaciado</th></tr></thead><tbody>${tr.map(x=>`<tr><th scope="row">${esc(wkLab(x.k))}</th><td class="r">${pc(x.pd)}</td><td class="r">${pc(x.pj)}</td><td class="r">${fmt(x.cap)}</td><td class="r${Math.abs(x.cap-x.vac)>0.01&&x.k<wk?' neg':''}">${fmt(x.vac)}</td></tr>`).join('')}</tbody></table></div>`:''}`;
}
let segWk=null;
