    Object.keys(t.byT).forEach(k=>CK.forEach(c=>{if(t.byT[k][c])t.byT[k][c]=Math.round(t.byT[k][c]*100)/100}));Object.keys(t.byT15).forEach(k=>t.byT15[k]=Math.round(t.byT15[k]*100)/100);
    t.tiposMan=TIPO_K.filter(k=>Object.values(t.byT[k]||{}).some(v=>v>0)||(t.byT15[k]||0)>0).map(k=>({k:k,l:TIPO_L[k]||k,cal:t.byT[k]||{},c15:t.byT15[k]||0}));
    const ts=[...t.tipos];t.pack=!ts.length||ts.every(x=>x==='RPC')?'PLASTICO':ts.every(x=>x==='CTN'||x==='CTN10')?'CARTON':'MIXTO';
    const ord={chico:0,grande:1,interno:2};
    t.prods=[...pm.values()].sort((x,y)=>ord[x.cls]-ord[y.cls]||x.nombre.localeCompare(y.nombre));
