/* hoja de movimientos: registrar, ver y anular cobros o pagos de una cuenta */
function movHtml(){
  const S=sheet.S,cob=S==='cob',St=cob?COB:PAG,x=accRow(sheet.ref),can=canMov()&&!ro;
  const L=St.list.filter(y=>y.ref===sheet.ref).sort((a,b)=>String(b.fecha).localeCompare(String(a.fecha))||b.at-a.at);
  if(!x&&!L.length)return `<h3>Cuenta no encontrada</h3><p class="note">El pedido de esta cuenta ya no existe o cambió de empresa.</p><div class="srow2"><button class="btn" data-act="closesheet">Cerrar</button></div>`;
  const div=x?x.div:(L[0]&&L[0].div)||(cob?'USD':'MXN'),wk=x&&x.wk,tcDef=x?+parsDe(x.emp,wk||curWk()).tc||'':'';
  const head=x?`<div class="ig tot wkg"><div><span>Total</span><b>${amt(x.monto,div)}</b></div><div><span>${cob?'Cobrado':'Pagado'}</span><b>${amt(x.hecho,div)}</b></div><div><span>Saldo</span><b class="${x.saldo<-0.005?'neg':''}">${amt(x.saldo,div)}</b></div><div><span>Vence</span><b>${x.venc?esc(fmtDate(x.venc)):'—'}</b></div></div>`:'';
  const tipos=cob?['cobro','nota']:['pago','ajuste'];
  const extra=x?(cob?(x.jug?liqFormHtml(x,can):factFormHtml(x,can)):x.tipo==='flete'?realFormHtml(x,can):''):'';
  const form=can&&x?`<div class="sec">${cob?'Registrar cobro':'Registrar pago'}</div><div class="grid2">
<label class="fld" for="mv-f"><span>Fecha</span><input class="in txt" id="mv-f" type="date" value="${esc(sheet.vf||todayISO())}"></label>
<label class="fld" for="mv-t"><span>Tipo</span><select class="in sel" id="mv-t">${tipos.map(k=>`<option value="${k}">${MOV_T[k]}</option>`).join('')}</select></label>
<label class="fld" for="mv-m"><span>Monto (${div})</span><input class="in" id="mv-m" inputmode="decimal" value="${x.saldo>0.005?esc(x.saldo):''}"></label>
${cob&&div==='USD'?`<label class="fld" for="mv-tc"><span>Tipo de cambio del cobro (MXN por 1 USD)</span><input class="in" id="mv-tc" inputmode="decimal" placeholder="${esc(tcDef)}"></label>`:''}
<label class="fld" for="mv-fo"><span>Forma</span><select class="in sel" id="mv-fo">${FORMAS.map(k=>`<option>${k}</option>`).join('')}</select></label>
<label class="fld" for="mv-r"><span>Referencia bancaria</span><input class="in txt" id="mv-r" type="text" autocomplete="off"></label></div>
<label class="fld" for="mv-n"><span>Nota</span><input class="in txt" id="mv-n" type="text" autocomplete="off"></label>${sheet.err?`<p class="note" style="color:var(--crit)" role="alert">${esc(sheet.err)}</p>`:''}
<div class="srow2"><button class="btn primary" data-act="movsave">Guardar ${cob?'cobro':'pago'}</button></div>`:'';
  const rows=L.map(y=>{
    const an=sheet.anul===y.id;
    return `<div class="mvr${y.anulado?' anu':''}"><div class="kv"><span><b>${esc(y.tipo==='fact'&&String(y.ref).indexOf('cxj|')===0?'Liquidación de '+cxjNm(y.ref):MOV_T[y.tipo]||y.tipo)}</b> · ${esc(fmtDate(y.fecha))}${y.forma?' · '+esc(y.forma):''}${y.num?' · núm. '+esc(y.num):''}${y.tipo==='fact'?' · '+esc(RECLAMO[y.reclamo||'']||''):''}${y.refb?' · ref '+esc(y.refb):''}<br><small class="note">${esc(y.by||'—')} · ${esc(fmtTs(y.at))}${y.tc?' · TC '+esc(y.tc)+' (= '+esc(money(y.monto*y.tc,2))+' MXN)':''}${y.nota?' · '+esc(y.nota):''}${St.dirty.indexOf(y.id)>=0&&cfgOK()?' · sin subir':''}</small>${y.anulado?`<br><small class="note">Anulado por ${esc(y.anulado.by)} (${esc(fmtTs(y.anulado.at))}): ${esc(y.anulado.motivo)}</small>`:''}</span><span class="kvb"><b>${amt(y.monto,y.div||div)}</b>${y.tipo==='fact'||y.tipo==='real'?'<small class="note">no es '+(cob?'cobro':'pago')+'</small>':''}${can&&!y.anulado&&!an?`<button class="btn sm danger" data-act="movanu:${y.id}">Anular</button>`:''}</span></div>${an?`<div class="warnbox"><label class="fld" for="mv-am"><span>Motivo para anular (obligatorio)</span><input class="in txt" id="mv-am" type="text" autocomplete="off"></label>${sheet.aErr?`<p class="note" style="color:var(--crit)" role="alert">${esc(sheet.aErr)}</p>`:''}<div class="pact"><button class="btn sm" data-act="movanuno">Cancelar</button><button class="btn sm danger" data-act="movanugo:${y.id}">Anular</button></div></div>`:''}</div>`;
  }).join('');
  return `<div class="shhead"><h3>${esc(x?x.nombre:'Movimientos')}</h3><button type="button" class="shx" data-act="closesheet" aria-label="Cerrar">✕</button></div><p class="note">${esc(x?(cob?x.lab+(x.po?' · PO '+x.po:''):x.det)+' · '+EMPS[x.emp].name:'')}</p>${head}${extra}${form}<div class="sec">Movimientos</div>${rows||'<p class="note">Aún no hay movimientos.</p>'}<p class="note" style="margin-top:8px">Los movimientos no se borran: si uno está mal, se anula con su motivo y se registra el correcto. Todo queda en la bitácora.</p><div class="srow2"><button class="btn" data-act="closesheet">Cerrar</button></div>`;
}
function movSave(){
  if(!sheet||sheet.kind!=='mov'||!canMov()||ro)return;
  const x=accRow(sheet.ref);if(!x)return;const cob=sheet.S==='cob',St=cob?COB:PAG;
  const g=id=>String((document.getElementById(id)||{}).value||'').trim(),fe=g('mv-f'),m=num(g('mv-m').replace(',','.')),tc=cob&&x.div==='USD'?num(g('mv-tc').replace(',','.')):null,tipo=g('mv-t')||(cob?'cobro':'pago');
  if(!/^\d{4}-\d{2}-\d{2}$/.test(fe)){sheet.err='Pon la fecha.';renderSheet();return}
  if(!(m>0)){sheet.err='Pon un monto mayor a cero.';renderSheet();return}
  const now=Date.now(),y={id:uid(),emp:x.emp,ref:x.ref,lab:x.lab,nombre:x.nombre,tipo:tipo,fecha:fe,monto:r2(m),div:x.div,tc:tc>0?tc:null,forma:g('mv-fo'),refb:g('mv-r'),nota:g('mv-n'),by:parBy(),uid:(authUser&&authUser.id)||'',at:now,ts:now,anulado:null};
  St.list.push(y);St.dirty.push(y.id);saveMov();
  logAdd({k:cob?'cobro':'pago',where:'Finanzas',ctx:{t:'c',id:x.ref,cod:x.nombre+' · '+x.lab},lab:MOV_T[tipo]+' registrado',o:amt(x.saldo,x.div),n:amt(y.monto,y.div)+' · '+fmtDate(fe)+' · '+y.forma+(y.refb?' · ref '+y.refb:'')+(y.tc?' · TC '+y.tc:'')});
  sheet.err='';const left=r2(x.saldo-y.monto);toast(left<-0.005?'Guardado. Queda un saldo a favor de '+amt(-left,x.div):'Guardado');renderSheet();render();
}
function movAnular(id){
  if(!sheet||sheet.kind!=='mov'||!canMov()||ro)return;
  const St=sheet.S==='cob'?COB:PAG,y=St.list.find(z=>z.id===id),mo=String((document.getElementById('mv-am')||{}).value||'').trim();if(!y||y.anulado)return;
  if(!mo){sheet.aErr='Escribe el motivo.';renderSheet();return}
  const now=Date.now();y.anulado={by:parBy(),at:now,motivo:mo};y.ts=now;if(St.dirty.indexOf(id)<0)St.dirty.push(id);saveMov();
  logAdd({k:sheet.S==='cob'?'cobro':'pago',where:'Finanzas',ctx:{t:'c',id:y.ref,cod:(y.nombre||'')+' · '+(y.lab||'')},lab:(MOV_T[y.tipo]||'Movimiento')+' anulado',o:amt(y.monto,y.div)+' · '+fmtDate(y.fecha),n:'Anulado · motivo: '+mo,motivo:mo});
  sheet.anul=null;sheet.aErr='';toast('Movimiento anulado');renderSheet();render();
}
/* sincronización: cada movimiento es una fila; gana la versión más reciente (solo cambia al anularse) */
async function syncMovTab(S,tb){
  try{
    if(canMov()&&S.dirty.length){
      const send=S.dirty.map(id=>S.list.find(x=>x.id===id)).filter(Boolean);
      for(let i=0;i<send.length;i+=100){const part=send.slice(i,i+100);await sb('/rest/v1/'+tb+'?on_conflict=id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:part.map(x=>({id:x.id,updated_at:x.ts,data:x}))});S.dirty=S.dirty.filter(id=>!part.some(x=>x.id===id&&x.ts===(S.list.find(z=>z.id===id)||{}).ts))}
    }
    const rows=await sbAll('/rest/v1/'+tb+'?select=id,updated_at,data&order=updated_at.asc');
    rows.forEach(r=>{if(!r.data||!okId(r.id))return;cleanRec(r.data);const i=S.list.findIndex(x=>x.id===r.id);if(i<0){S.list.push(r.data);remoteN++}else if((+r.data.ts||0)>(+S.list[i].ts||0)&&S.dirty.indexOf(r.id)<0){S.list[i]=r.data;remoteN++}});
    S.noTable=false;saveMov();
  }catch(e){if(e&&(e.status===404||e.status===400))S.noTable=true}
}
/* Excel para contabilidad: por cobrar, por pagar y todos los movimientos */
async function exportCuentas(){
  if(typeof ExcelJS==='undefined'){toast('La descarga en Excel no está disponible aquí');return}
  try{
    const A=accData(),wb=newWb(),stamp=todayISO(),hoy=fmtDate(stamp);
    const add=(name,cols,rows)=>{const ws=wb.addWorksheet(name,{views:[{state:'frozen',ySplit:1}]});ws.columns=cols.map(c=>({header:c[1],key:c[0],width:c[2]||14,style:c[3]?{numFmt:c[3]}:{}}));ws.getRow(1).font={bold:true};rows.forEach(r=>ws.addRow(r));ws.autoFilter={from:{row:1,column:1},to:{row:1,column:cols.length}};return ws};
    const M='#,##0.00';
    const tr=x=>x.b?(BUCKETS.find(b=>b[0]===x.b)||[])[1]:'Saldada',EST={ok:'Saldado',par:'Parcial',pen:'Pendiente'};
    add('Por cobrar',[['emp','Empresa',10],['cliente','Cliente',28],['doc','Factura o pedido',18],['po','PO',10],['fecha','Fecha pedido',12],['ffact','Fecha factura',12],['venc','Vence',12],['dias','Días de atraso',10],['calc','Calculado USD',14,M],['fact','Facturado USD',14,M],['total','Total a cobrar USD',14,M],['cob','Cobrado USD',14,M],['nc','Notas de crédito USD',14,M],['saldo','Saldo USD',14,M],['dif','Cobrado − calculado USD',14,M],['est','Conciliación',12],['rec','Reclamo',22],['tramo','Antigüedad',16]],
      A.cxc.map(x=>({emp:x.emp,cliente:x.nombre,doc:x.lab,po:x.po,fecha:x.fecha,ffact:x.fFact||'',venc:x.venc,dias:x.b?Math.max(0,x.atr):0,calc:x.calc,fact:x.fact==null?'':x.fact,total:x.monto,cob:x.cob,nc:x.nc,saldo:x.saldo,dif:x.dif,est:EST[x.est],rec:RECLAMO[x.reclamo]||'',tramo:tr(x)})));
    add('Por pagar',[['emp','Empresa',10],['tipo','Tipo',12],['nombre','Proveedor o productor',28],['det','Concepto',34],['venc','Vence',12],['dias','Días de atraso',10],['total','Calculado MXN',14,M],['pag','Pagado MXN',14,M],['saldo','Saldo MXN',14,M],['dif','Pagado − calculado MXN',14,M],['est','Conciliación',12],['tramo','Antigüedad',16]],
      A.cxp.map(x=>({emp:x.emp,tipo:x.tipo==='prod'?'Fruta':x.tipo==='jug'?'Juguera':'Flete',nombre:x.nombre,det:x.det,venc:x.venc,dias:x.b?Math.max(0,x.atr):0,total:x.monto,pag:x.hecho,saldo:x.saldo,dif:x.dif,est:EST[x.est],tramo:tr(x)})));
    if(A.cxj.length)add('Juguera por cobrar',[['emp','Empresa',10],['sem','Semana',16],['caj','Cajas',10,'#,##0.0'],['venc','Vence',12],['dias','Días de atraso',10],['calc','Estimado MXN',14,M],['liq','Liquidado MXN',14,M],['total','Total a cobrar MXN',14,M],['cob','Cobrado MXN',14,M],['saldo','Saldo MXN',14,M],['est','Conciliación',12],['tramo','Antigüedad',16]],
      A.cxj.map(x=>({emp:x.emp,sem:wkLab(x.wk),caj:x.caj,venc:x.venc,dias:x.b?Math.max(0,x.atr):0,calc:x.sinPrecio?'':x.calc,liq:x.fact==null?'':x.fact,total:x.monto,cob:x.hecho,saldo:x.saldo,est:EST[x.est],tramo:tr(x)})));
    const grpRows=L=>{const g=new Map();L.forEach(x=>{if(!x.b)return;const k=norm(x.nombre);let a=g.get(k);if(!a){a={nombre:x.nombre,n:0,tot:0};BUCKETS.forEach(b=>a[b[0]]=0);g.set(k,a)}a[x.b]+=x.saldo;a.tot+=x.saldo;a.n++});return [...g.values()].sort((a,b)=>b.tot-a.tot)};
    const gcols=(w,div)=>[['nombre',w,30],['n','Cuentas',9]].concat(BUCKETS.map(b=>[b[0],b[1]+' '+div,15,M]),[['tot','Total '+div,15,M]]);
    add('Antigüedad por cliente',gcols('Cliente','USD'),grpRows(A.cxc));
    add('Antigüedad por productor',gcols('Productor o proveedor','MXN'),grpRows(A.cxp));
    const K=cashKpi();add('Indicadores',[['k','Indicador',46],['v','Valor',18],['u','Unidad',10],['n','Cómo se calcula',70]],[
      {k:'DSO · días para cobrar',v:K.dso==null?'':Math.round(K.dso),u:'días',n:'Saldo por cobrar ÷ ventas de los últimos 90 días × 90'},
      {k:'DPO · días para pagar',v:K.dpo==null?'':Math.round(K.dpo),u:'días',n:'Saldo por pagar ÷ compras (fruta y flete) de los últimos 90 días × 90'},
      {k:'Ciclo de conversión de efectivo',v:K.cce==null?'':Math.round(K.cce),u:'días',n:'DSO − DPO; no incluye días de inventario'},
      {k:'Por cobrar convertido a pesos',v:r2(K.cxcMXN),u:'MXN',n:'Saldo en USD × tipo de cambio de la semana actual'},
      {k:'Por pagar',v:r2(K.cxp),u:'MXN',n:''},
      {k:'Hueco de capital de trabajo',v:r2(K.gap),u:'MXN',n:'Por cobrar en MXN − por pagar'},
      {k:'Umbral',v:K.umbral==null?'sin umbral':K.umbral,u:'MXN',n:'Se captura en Precios y costos'}]);
    const mv=[].concat(COB.list.map(y=>Object.assign({cl:'Cobro'},y)),PAG.list.map(y=>Object.assign({cl:'Pago'},y))).filter(y=>statsF.emp==='ALL'||!statsF.emp||y.emp===statsF.emp).sort((a,b)=>String(a.fecha).localeCompare(String(b.fecha)));
    add('Movimientos',[['fecha','Fecha',12],['emp','Empresa',10],['cl','Clase',8],['tipo','Tipo',22],['nombre','Cliente o proveedor',26],['lab','Cuenta',30],['monto','Monto',14,M],['div','Divisa',8],['tc','TC',8],['forma','Forma',14],['refb','Referencia',16],['nota','Nota',24],['by','Registró',18],['anu','Anulado',36]],
      mv.map(y=>({fecha:y.fecha,emp:y.emp,cl:y.cl,tipo:y.tipo==='fact'&&String(y.ref).indexOf('cxj|')===0?'Liquidación de '+cxjNm(y.ref):MOV_T[y.tipo]||y.tipo,nombre:y.nombre||'',lab:y.lab||'',monto:y.monto,div:y.div,tc:y.tc||'',forma:y.forma||'',refb:y.refb||'',nota:y.nota||'',by:y.by||'',anu:y.anulado?'Sí · '+y.anulado.motivo:''})));
    await saveFile('Cuentas_'+(statsF.emp||'ALL')+'_'+stamp+'.xlsx',await wbBlob(wb));
  }catch(e){toast('No se pudo generar el archivo')}
}

/* ---------- v8.2 · costos fijos por categoría ----------
   Cada categoría tiene monto y periodicidad; se lleva a semana: mensual × 12 ÷ 52, anual ÷ 52.
   Mientras no haya ninguna categoría se usa el número único de siempre (costos fijos por semana). */
const FIJO_CAT=[['luz','Luz'],['agua','Agua'],['renta','Renta'],['dep','Depreciación'],['adm','Administración'],['otros','Otros']];
const FIJO_PER=[['sem','Semanal',1],['mes','Mensual',12/52],['anio','Anual',1/52]];
function fijoCats(e,wk){
  const F=wk?parsDe(e,wk):FIN[e],c=F&&F.fijos;if(!c||typeof c!=='object')return null;const out=[];
  FIJO_CAT.forEach(k=>{const x=c[k[0]],m=x?num(x.m):null;if(m==null||!(m>0))return;const p=FIJO_PER.find(q=>q[0]===x.p)||FIJO_PER[1];out.push({k:k[0],l:k[1],m:m,p:p[0],pl:p[1],sem:m*p[2]})});
  return out.length?out:null;
}
function fijoSem(e,wk){const c=fijoCats(e,wk);return c?c.reduce((s,x)=>s+x.sem,0):biPar(e,'fijo',wk)}
/* costos fijos de un mes: las categorías llevadas a mes (semanal × 52 ÷ 12, anual ÷ 12) o el número único × 52 ÷ 12 */
function fijoMes(e,ym){const wk=wkOfDate(ym+'-15'),c=fijoCats(e,wk);return c?c.reduce((s,x)=>s+(x.p==='mes'?x.m:x.p==='sem'?x.m*52/12:x.m/12),0):biPar(e,'fijo',wk)*52/12}
function fijoPeriodo(wks,es){
  const cats={},X={tot:0,cats:cats,nW:wks.length,sep:false};
  es.forEach(e=>wks.forEach(w=>{const c=fijoCats(e,w);if(c){X.sep=true;c.forEach(x=>{cats[x.l]=(cats[x.l]||0)+x.sem;X.tot+=x.sem})}else{const v=biPar(e,'fijo',w),l='Sin separar por categoría';cats[l]=(cats[l]||0)+v;X.tot+=v}}));
  return X;
}
function fijosFormHtml(e,F,inp,ed){
  const c=F.fijos||{},cs=fijoCats(e,sheet&&sheet.desde||curWk());
  const sel=k=>{const v=(c[k]||{}).p||'mes',id='fin-fijos-'+k+'-p';return `<label class="fld" for="${id}"><span>Periodicidad ${esc(k)}</span><select class="in sel" id="${id}" data-fin="${e}.fijos.${k}.p" data-fstr="1"${ed?'':' disabled'}>${FIJO_PER.map(p=>`<option value="${p[0]}"${p[0]===v?' selected':''}>${p[1]}</option>`).join('')}</select></label>`};
  return `<div class="sec">Costos fijos por categoría (MXN)</div><div class="fingrid fijg"><span></span><span class="fh">Monto (MXN)</span><span class="fh">Cada</span>${FIJO_CAT.map(k=>`<span class="fl">${k[1]}</span>${inp('fijos.'+k[0]+'.m',(c[k[0]]||{}).m,k[1]+' (MXN)','—')}${sel(k[0])}`).join('')}</div>
<p class="note">${cs?'Equivalen a <b>'+money(cs.reduce((s,x)=>s+x.sem,0))+' MXN por semana</b> (mensual × 12 ÷ 52; anual ÷ 52). Se reparten entre las cajas para el costo absorbido y el punto de equilibrio.':'Vacías: se usa el número único de costos fijos por semana de abajo. En cuanto captures una categoría, mandan las categorías.'}</p>`;
}
/* costo directo contra costo absorbido (directo + fijos repartidos por caja) */
function absHtml(F,X){
  const fc=F.cajas>0?X.tot/F.cajas:null,ab=F.costoCaja!=null&&fc!=null?F.costoCaja+fc:null,ua=F.util-X.tot,ma=F.ing>0?ua/F.ing:null;
  const cats=Object.keys(X.cats).filter(k=>X.cats[k]>0.005).sort((a,b)=>X.cats[b]-X.cats[a]);
  return `<div class="ig tot wkg abs"><div><span>Costo directo por caja</span><b>${money(F.costoCaja,2)}</b><small>MXN</small></div><div><span>Fijos por caja</span><b>${money(fc,2)}</b><small>MXN</small></div><div><span>Costo absorbido por caja</span><b>${money(ab,2)}</b><small>MXN</small></div></div>
<div class="ig tot wkg abs"><div><span>Margen directo</span><b>${pctTxt(F.margen)}</b><small>antes de fijos</small></div><div><span>Margen absorbido</span><b class="${ma!=null&&ma<0?'neg':''}">${pctTxt(ma)}</b><small>después de fijos</small></div><div><span>Utilidad después de fijos</span><b class="${ua<0?'neg':''}">${money(ua)}</b><small>MXN</small></div></div>
${cats.length?`<div class="abcats">${cats.map(k=>`<div class="kv"><span>${esc(k)}</span><b>${mxn(X.cats[k])}</b></div>`).join('')}<div class="kv tot"><span>Costos fijos del periodo (${X.nW} ${X.nW===1?'semana':'semanas'})</span><b>${mxn(X.tot)}</b></div></div>`:''}
<p class="note">${X.sep?'Costos fijos por categoría de Precios y costos, llevados a semana.':'Aún no hay costos fijos por categoría: se usa el número único por semana de Precios y costos.'} Costo absorbido = costo directo + costos fijos del periodo ÷ cajas de exportación.</p>`;
}

/* ---------- v8.2 · merma valorizada ----------
   Desecho (cajas campo × kg por caja) al precio que se paga por kg, más el material usado en merma si se captura.
   v8.7.1: la Juguera no es merma (se vende); se muestra aparte como dato.
   Ya va dentro del costo de fruta: muestra cuánto de ese pago se fue a merma. */
function mermaData(list){
  const T={des:0,jug:0,kg:0,fruta:0,mat:0,campo:0,kilos:0,mDes:0,mCampo:0,consig:false},pm=new Map();
  list.forEach(o=>{const wk=wkOf(o),F=parsDe(o.emp,wk),M=compute(o),mm=num(F.matMerma)||0;
    M.rows.forEach(r=>{const p=r.p;if(isSob(p)||+p.codigo===SEG_COD||p.segLot)return;
      const d=n0(p.des),j=0,jv=n0(p.jug),key=p.codigo?'c'+p.codigo:'n'+norm(p.nombre||'sin nombre');
      let a=pm.get(key);if(!a){const li=p.codigo?LISTA.find(x=>x.c===p.codigo):null;a={key:key,nombre:(li&&li.n)||p.nombre||'Sin nombre',des:0,jug:0,kg:0,fruta:0,mat:0,campo:0,kilos:0,mDes:0,mCampo:0,consig:false};pm.set(key,a)}
      const ac=(F.acu&&p.codigo&&F.acu[p.codigo])||{},consig=(p.modal||ac.modal)==='consig',pk=pkgOf(F,o,p);
      const kg=(d+j)*M.kg,m=muesOf(p);
      [a,T].forEach(z=>{z.des+=d;z.jug+=j;z.jugV=(z.jugV||0)+jv;z.kg+=kg;z.fruta+=kg*pk;z.mat+=(d+j)*mm;z.kilos+=n0(p.kilos);if(r.campo){z.campo+=r.campo;if(m&&m.des!=null){z.mDes+=m.des/100*r.campo;z.mCampo+=r.campo}}if(consig)z.consig=true});
    })});
  const fin=z=>{z.tot=z.fruta+z.mat;z.desP=z.campo>0?z.des/z.campo:null;z.jugP=z.campo>0?z.jug/z.campo:null;z.mDesP=z.mCampo>0?z.mDes/z.mCampo:null;z.kgP=z.kilos>0?z.kg/z.kilos:null;return z};
  return {T:fin(T),rows:[...pm.values()].map(fin).filter(a=>a.des+a.jug>0).sort((a,b)=>b.tot-a.tot)};
}
function mermaHtml(list){
  const Mm=mermaData(list),T=Mm.T;
  if(!(T.des>0))return '<p class="note">Sin desecho capturado en el periodo.</p>';
  const tiles=tileHtml('Merma valorizada',money(T.tot)+'<em class="cur">MXN</em>','fruta '+mxn(T.fruta)+(T.mat>0?' · material '+mxn(T.mat):' · material sin capturar'))
   +tileHtml('Kilos en merma',fmt(T.kg)+' kg',pctTxt(T.kgP)+' de lo recibido · '+fmt(T.des)+' cajas de desecho')
   +tileHtml('Desecho real',pctTxt(T.desP),T.mDesP!=null?'el muestreo de recepción decía '+pctTxt(T.mDesP):'sin muestreo de recepción',null,T.mDesP!=null&&T.desP!=null&&T.desP>T.mDesP*1.2?'warnt':'');
  const rows=Mm.rows.slice(0,10).map(a=>`<tr><th scope="row">${esc(a.nombre)}${a.consig?'<small>consignación: con el pago general por kg</small>':''}</th><td>${fmt(a.des+a.jug)}</td><td>${fmt(a.kg)}</td><td>${money(a.tot)}</td><td>${pctTxt(a.desP)}</td><td class="${a.mDesP!=null&&a.desP!=null&&a.desP>a.mDesP*1.2?'bv':''}">${pctTxt(a.mDesP)}</td></tr>`).join('');
  return `<div class="tiles">${tiles}</div><div class="tblx" style="margin-top:10px"><table class="ctab"><thead><tr><th>Productor</th><th>Cajas de merma</th><th>Kilos</th><th>MXN</th><th>Desecho real</th><th>Muestreo</th></tr></thead><tbody>${rows}</tbody></table></div><p class="note" style="margin-top:6px">Merma = desecho, en cajas campo × kilos por caja del pedido, al precio por kilo que se paga a cada productor${T.mat>0?', más el material usado en merma':''}. Ya está dentro del costo de fruta: muestra cuánto de ese pago se fue a merma. Desecho real contra el muestreo de Entrada de Fruta; en rojo si pasa por más de 20 %.${T.jugV>0?' La Juguera ('+fmt(T.jugV)+' cajas) no es merma: se vende y la venta queda para el empaque.':''}${Mm.rows.length>10?' Se muestran los 10 con más merma.':''}</p>`;
}

/* ---------- v8.2 · capital de trabajo: DSO, DPO y ciclo de conversión de efectivo ---------- */
function cashKpi(e0){
  const E=e0||statsF.emp||'ALL',A=accData(E),hoy=todayISO(),d90=dayAdd(hoy,-90),inW=x=>x.fecha&&x.fecha>=d90&&x.fecha<=hoy,es=E==='ALL'?['VL','EC']:[E];
  const tcOf=e=>+parsDe(e,curWk()).tc||0;
  const ventas=A.cxc.filter(inW).reduce((s,x)=>s+x.monto,0),compras=A.cxp.filter(inW).reduce((s,x)=>s+x.monto,0);
  const dso=ventas>0?A.agc.tot/ventas*90:null,dpo=compras>0?A.agp.tot/compras*90:null,cce=dso!=null&&dpo!=null?dso-dpo:null;
  const cxcMXN=A.cxc.reduce((s,x)=>s+(x.b?x.saldo*tcOf(x.emp):0),0),gap=cxcMXN-A.agp.tot;
  const us=es.map(e=>num(parsDe(e,curWk()).umbralCT)).filter(v=>v!=null),umbral=us.length?us.reduce((s,v)=>s+v,0):null;
  return {dso:dso,dpo:dpo,cce:cce,cxcMXN:cxcMXN,cxp:A.agp.tot,gap:gap,umbral:umbral,over:umbral!=null&&gap>umbral,ventas:ventas,compras:compras,b60:A.agc.b60p,b60p:A.agp.b60p};
}
function cashTilesHtml(K){
  if(!K)return '';
  return `<div class="tiles">${tileHtml('DSO · días para cobrar',K.dso==null?'–':fmt(K.dso,0)+' días','saldo por cobrar ÷ ventas de 90 días × 90')}${tileHtml('DPO · días para pagar',K.dpo==null?'–':fmt(K.dpo,0)+' días','saldo por pagar ÷ compras de 90 días × 90')}${tileHtml('Ciclo de efectivo',K.cce==null?'–':fmt(K.cce,0)+(Math.abs(Math.round(K.cce))===1?' día':' días'),'DSO − DPO, sin días de inventario')}${tileHtml('Hueco de capital de trabajo',money(K.gap,0)+'<em class="cur">MXN</em>','por cobrar '+mxn(K.cxcMXN,0)+' − por pagar '+mxn(K.cxp,0)+(K.umbral!=null?' · umbral '+mxn(K.umbral,0):' · sin umbral'),K.over?'<span class="chip crit">Arriba del umbral</span>':'',K.over?'warnt':'')}</div>`;
}
/* antigüedad agrupada por cliente o por productor */
const BK_SH={cur:'Por vencer',b30:'0–30 días',b60:'31–60 días',b60p:'+60 días'};
function agingGroupHtml(L,div,who){
  const g=new Map();L.forEach(x=>{if(!x.b)return;const k=norm(x.nombre);let a=g.get(k);if(!a){a={n:x.nombre,c:0,tot:0};BUCKETS.forEach(b=>a[b[0]]=0);g.set(k,a)}a[x.b]+=x.saldo;a.tot+=x.saldo;a.c++});
  const R=[...g.values()].sort((a,b)=>b.tot-a.tot);if(!R.length)return '<p class="note" style="margin-top:8px">Nada pendiente.</p>';
  const T={tot:R.reduce((s,a)=>s+a.tot,0)};BUCKETS.forEach(b=>T[b[0]]=R.reduce((s,a)=>s+a[b[0]],0));
  return `<div class="tblx" style="margin-top:8px"><table class="ctab agt"><thead><tr><th>${who}</th>${BUCKETS.map(b=>`<th><i class="agd ${BK_CLS[b[0]]}" aria-hidden="true"></i>${b[1]}</th>`).join('')}<th>Total ${div}</th></tr></thead><tbody>${R.map(a=>`<tr><th scope="row">${esc(a.n)}<small>${a.c} ${a.c===1?'cuenta':'cuentas'}</small></th>${BUCKETS.map(b=>`<td data-l="${BK_SH[b[0]]}">${a[b[0]]>0.005?money(a[b[0]],0):'–'}</td>`).join('')}<td data-l="Total ${div}"><b>${money(a.tot,0)}</b></td></tr>`).join('')}<tr class="tot"><th scope="row">Total</th>${BUCKETS.map(b=>`<td data-l="${BK_SH[b[0]]}">${money(T[b[0]],0)}</td>`).join('')}<td data-l="Total ${div}"><b>${money(T.tot,0)}</b></td></tr></tbody></table></div>`;
}

/* ---------- v8.2 · factura del pedido y flete real del embarque ----------
   Son registros en cobros y pagos (no cuentan como cobro ni pago); manda el más reciente sin anular. */
function factFormHtml(x,can){
  const fa=lastMov(COB,x.ref,'fact');
  const cur=fa?`<p class="note">Factura vigente: ${esc(fmtDate(fa.fecha))}${fa.num?' · núm. '+esc(fa.num):''} · ${esc(amt(fa.monto,'USD'))} · ${esc(RECLAMO[fa.reclamo||''])}. Calculado con los precios de su semana: ${esc(amt(x.calc,'USD'))}${Math.abs(fa.monto-x.calc)>0.005?' (diferencia '+esc(sgnAmt(r2(fa.monto-x.calc),'USD'))+')':''}.</p>`:`<p class="note">Sin factura registrada: se cobra lo calculado (${esc(amt(x.calc,'USD'))}) y vence desde la fecha del pedido.</p>`;
  if(!can)return `<div class="sec">Factura</div>${cur}`;
  return `<details class="mvx"${sheet.fOpen||!fa?' open':''}><summary>${fa?'Factura y reclamo · actualizar':'Registrar factura'}</summary>${cur}<div class="grid2">
<label class="fld" for="fa-f"><span>Fecha de factura</span><input class="in txt" id="fa-f" type="date" value="${esc((fa&&fa.fecha)||todayISO())}"></label>
<label class="fld" for="fa-n"><span>Número de factura</span><input class="in txt" id="fa-n" type="text" autocomplete="off" value="${esc((fa&&fa.num)||x.factura||'')}"></label>
<label class="fld" for="fa-m"><span>Monto facturado (USD)</span><input class="in" id="fa-m" inputmode="decimal" value="${esc(fa?fa.monto:x.calc)}"></label>
<label class="fld" for="fa-r"><span>Reclamo o nota de crédito</span><select class="in sel" id="fa-r">${Object.keys(RECLAMO).map(k=>`<option value="${k}"${(fa&&fa.reclamo||'')===k?' selected':''}>${RECLAMO[k]}</option>`).join('')}</select></label></div>
<label class="fld" for="fa-o"><span>Nota</span><input class="in txt" id="fa-o" type="text" autocomplete="off"></label>${sheet.fErr?`<p class="note" style="color:var(--crit)" role="alert">${esc(sheet.fErr)}</p>`:''}
<div class="srow2"><button class="btn" data-act="factsave">${fa?'Guardar cambios de la factura':'Guardar factura'}</button></div><p class="note">La factura no es un cobro: fija el monto a cobrar y la fecha desde la que corren los días de pago. Los montos de nota de crédito se registran abajo como «Nota de crédito o descuento».</p></details>`;
}
function realFormHtml(x,can){
  const fr=lastMov(PAG,x.ref,'real'),F=parsDe(x.emp,wkOf({fecha:x.fecha})),par=(+F.flete||0)+(+F.cruce||0);
  const cur=`<p class="note">${fr?'Se usa el flete real: <b>'+esc(amt(fr.monto,'MXN'))+'</b> (parámetro '+esc(amt(par,'MXN'))+').':'Se usa el parámetro de Precios y costos: '+esc(amt(par,'MXN'))+' (flete más cruce).'}</p>`;
  if(!can)return `<div class="sec">Flete real</div>${cur}`;
  return `<details class="mvx"${sheet.fOpen?' open':''}><summary>${fr?'Flete real · cambiar':'Registrar flete real'}</summary>${cur}<div class="grid2">
<label class="fld" for="fr-f"><span>Fecha</span><input class="in txt" id="fr-f" type="date" value="${esc((fr&&fr.fecha)||x.fecha||todayISO())}"></label>
<label class="fld" for="fr-m"><span>Flete y cruce reales (MXN)</span><input class="in" id="fr-m" inputmode="decimal" value="${esc(fr?fr.monto:'')}" placeholder="${esc(par)}"></label></div>
<label class="fld" for="fr-o"><span>Nota (transportista, factura del flete…)</span><input class="in txt" id="fr-o" type="text" autocomplete="off"></label>${sheet.fErr?`<p class="note" style="color:var(--crit)" role="alert">${esc(sheet.fErr)}</p>`:''}
<div class="srow2"><button class="btn" data-act="realsave">Guardar flete real</button></div><p class="note">El flete real reemplaza al parámetro en la utilidad, el costeo por embarque y esta cuenta por pagar. No es un pago.</p></details>`;
}
function movRec(St,x,y,lab,o,n){
  const now=Date.now();Object.assign(y,{id:uid(),emp:x.emp,ref:x.ref,lab:x.lab,nombre:x.nombre,by:parBy(),uid:(authUser&&authUser.id)||'',at:now,ts:now,anulado:null});
  St.list.push(y);St.dirty.push(y.id);saveMov();
  logAdd({k:St===COB?'cobro':'pago',where:'Finanzas',ctx:{t:'c',id:x.ref,cod:x.nombre+' · '+x.lab},lab:lab,o:o,n:n});
  sheet.fErr='';sheet.fOpen=false;toast('Guardado');renderSheet();render();
}
function liqFormHtml(x,can){
  const lq=lastMov(COB,x.ref,'fact'),est=x.sinPrecio?'sin precio de venta capturado':'estimado '+amt(x.calc,'MXN')+' ('+fmt(x.caj,x.caj%1?1:0)+' cajas × precio de Precios y costos)';
  const cur=lq?`<p class="note">Liquidación vigente: ${esc(fmtDate(lq.fecha))}${lq.num?' · núm. '+esc(lq.num):''} · ${esc(amt(lq.monto,'MXN'))}. Sin ella: ${esc(est)}.</p>`:`<p class="note">Sin liquidación registrada: ${esc(est)}.</p>`;
  if(!can)return `<div class="sec">Liquidación de la Juguera</div>${cur}`;
  return `<details class="mvx"${sheet.fOpen||!lq?' open':''}><summary>${lq?'Liquidación de la Juguera · actualizar':'Registrar liquidación de la Juguera'}</summary>${cur}<div class="grid2">
<label class="fld" for="fa-f"><span>Fecha</span><input class="in txt" id="fa-f" type="date" value="${esc((lq&&lq.fecha)||todayISO())}"></label>
<label class="fld" for="fa-n"><span>Número o folio</span><input class="in txt" id="fa-n" type="text" autocomplete="off" value="${esc((lq&&lq.num)||'')}"></label>
<label class="fld" for="fa-m"><span>Monto que paga la Juguera (MXN)</span><input class="in" id="fa-m" inputmode="decimal" value="${esc(lq?lq.monto:(x.calc||''))}"></label></div>
<label class="fld" for="fa-o"><span>Nota</span><input class="in txt" id="fa-o" type="text" autocomplete="off"></label>${sheet.fErr?`<p class="note" style="color:var(--crit)" role="alert">${esc(sheet.fErr)}</p>`:''}
<div class="srow2"><button class="btn" data-act="factsave">${lq?'Guardar cambios de la liquidación':'Guardar liquidación'}</button></div><p class="note">La liquidación no es un cobro: fija lo que se cobra a la Juguera por la semana y, en pase íntegro, lo que se reparte a los productores.</p></details>`;
}
function factSave(){
  if(!sheet||sheet.kind!=='mov'||sheet.S!=='cob'||!canMov()||ro)return;const x=accRow(sheet.ref);if(!x)return;
  if(x.jug){const g=id=>String((document.getElementById(id)||{}).value||'').trim(),fe=g('fa-f'),m=num(g('fa-m').replace(',','.'));sheet.fOpen=true;
    if(!/^\d{4}-\d{2}-\d{2}$/.test(fe)){sheet.fErr='Pon la fecha.';renderSheet();return}
    if(m==null||!(m>=0)){sheet.fErr='Pon el monto que paga la Juguera.';renderSheet();return}
    const old=lastMov(COB,x.ref,'fact');
    movRec(COB,x,{tipo:'fact',fecha:fe,monto:r2(m),div:'MXN',num:g('fa-n'),reclamo:'',nota:g('fa-o'),tc:null},old?'Liquidación de Juguera cambiada':'Liquidación de Juguera registrada',old?amt(old.monto,'MXN')+' · '+fmtDate(old.fecha):(x.sinPrecio?'sin precio':'estimado '+amt(x.calc,'MXN')),amt(r2(m),'MXN')+' · '+fmtDate(fe)+(g('fa-n')?' · núm. '+g('fa-n'):''));
    return}
  const g=id=>String((document.getElementById(id)||{}).value||'').trim(),fe=g('fa-f'),m=num(g('fa-m').replace(',','.')),rc=g('fa-r');
  sheet.fOpen=true;
  if(!/^\d{4}-\d{2}-\d{2}$/.test(fe)){sheet.fErr='Pon la fecha de factura.';renderSheet();return}
  if(!(m>0)){sheet.fErr='Pon el monto facturado.';renderSheet();return}
  const old=lastMov(COB,x.ref,'fact');
  movRec(COB,x,{tipo:'fact',fecha:fe,monto:r2(m),div:'USD',num:g('fa-n'),reclamo:RECLAMO[rc]!=null?rc:'',nota:g('fa-o'),tc:null},old?'Factura cambiada':'Factura registrada',old?amt(old.monto,'USD')+' · '+fmtDate(old.fecha)+' · '+RECLAMO[old.reclamo||'']:'calculado '+amt(x.calc,'USD'),amt(r2(m),'USD')+' · '+fmtDate(fe)+(g('fa-n')?' · núm. '+g('fa-n'):'')+' · '+RECLAMO[rc||'']);
}
function realSave(){
  if(!sheet||sheet.kind!=='mov'||sheet.S!=='pag'||!canMov()||ro)return;const x=accRow(sheet.ref);if(!x||x.tipo!=='flete')return;
  const g=id=>String((document.getElementById(id)||{}).value||'').trim(),fe=g('fr-f'),m=num(g('fr-m').replace(',','.'));
  sheet.fOpen=true;
  if(!/^\d{4}-\d{2}-\d{2}$/.test(fe)){sheet.fErr='Pon la fecha.';renderSheet();return}
  if(m==null||m<0){sheet.fErr='Pon el monto real del flete y cruce.';renderSheet();return}
  movRec(PAG,x,{tipo:'real',fecha:fe,monto:r2(m),div:'MXN',nota:g('fr-o'),tc:null},'Flete real registrado',amt(x.calc,'MXN'),amt(r2(m),'MXN'));
}

/* ---------- v8.2 · costeo por embarque (cada pedido es un embarque: contenedor o viaje) ---------- */
function jobData(list){
  const g=new Map();list.forEach(o=>{const k=o.emp+'|'+o.cod;if(!g.has(k))g.set(k,[]);g.get(k).push(o)});
  const J=[];
  g.forEach((os,k)=>{const A=finAgg(os),T=A.T;if(!(T.ing>0||T.cost>0))return;
    const m=mainOf(os[0]),bi=m.bi||{},wk=wkOf(m),tc=+parsDe(m.emp,wk).tc||0,ref='cxc|'+k,fa=lastMov(COB,ref,'fact'),nc=movSum(COB,ref,'nota'),fr=fleteReal(m.emp,m.cod);
    const usd=fa&&+fa.monto>0?+fa.monto:T.ingUSD,ing=usd*tc+T.ingNac,notas=nc*tc,dem=n0(bi.demora),demM=dem*tc,cost=T.fruta+T.mat+T.mo+T.flete+demM,neto=ing-notas-cost;
    J.push({k:k,emp:m.emp,cod:m.cod,wk:wk,fecha:m.fecha||'',cli:String(m.customer||'').trim()||'Sin cliente',cont:bi.contenedor||'',nav:bi.naviera||'',tc:tc,usdCalc:T.ingUSD,usd:usd,fact:!!fa,nac:T.ingNac,jug:T.ingJug,fjug:T.frutaJug,ing:ing,nc:nc,notas:notas,fruta:T.fruta,mat:T.mat,mo:T.mo,flete:T.flete,fr:fr!=null,dem:dem,demM:demM,rech:n0(bi.rech),cajas:T.cajas,kilos:T.kilos,cost:cost,neto:neto,margen:ing>0?neto/ing:null,prods:A.rows.filter(a=>a.kilos>0||a.cajas>0).sort((a,b)=>b.kilos-a.kilos)});
  });
  return J;
}
function embView(D){
  const J=jobData(D.cur.list),f=statsF,s=f.esort||'fecha';
  if(!J.length)return '<p class="note" style="margin-top:8px">Sin embarques con venta en el periodo.</p>';
  J.sort(s==='neto'?(a,b)=>a.neto-b.neto:s==='margen'?(a,b)=>(a.margen==null?-9:a.margen)-(b.margen==null?-9:b.margen):(a,b)=>String(b.fecha).localeCompare(String(a.fecha))||String(b.cod).localeCompare(String(a.cod)));
  const ti=J.reduce((t,j)=>{t.ing+=j.ing;t.neto+=j.neto;t.fr+=j.fr?1:0;t.neg+=j.neto<0?1:0;return t},{ing:0,neto:0,fr:0,neg:0});
  const tiles=tileHtml('Embarques',fmt(J.length),ti.fr+' con flete real · '+(J.length-ti.fr)+' con el parámetro')+tileHtml('Resultado neto',money(ti.neto)+'<em class="cur">MXN</em>','margen neto '+pctTxt(ti.ing>0?ti.neto/ti.ing:null),null,ti.neto<0?'warnt':'')+tileHtml('Con pérdida',fmt(ti.neg),ti.neg===1?'embarque':'embarques',null,ti.neg?'warnt':'');
  const b=(k,t)=>`<button class="btn sm" data-act="esort:${k}" aria-pressed="${s===k}">${t}</button>`;
  const L=(l,v,sub,cls)=>`<div class="kv${cls?' '+cls:''}"><span>${l}${sub?`<br><small class="note">${sub}</small>`:''}</span><b class="${v<0?'negv':''}">${mxn(v)}</b></div>`;
  const card=j=>`<details class="prd job${j.neto<0?' late':''}"><summary><div class="r1"><div class="pnm">${esc(j.cli)}<small>Pedido ${esc(j.cod)} · ${esc(j.emp)} · ${j.fecha?esc(fmtDate(j.fecha)):'sin fecha'}${j.cont?' · '+esc(j.cont):''}</small></div><div class="rend${j.neto<0?' negv':''}">${money(j.neto)}<em class="cur">MXN</em><small>neto · margen ${pctTxt(j.margen)}</small></div></div>
<div class="r3"><span class="chip ${j.fr?'good':''}">${j.fr?'Flete real':'Flete del parámetro'}</span><span class="chip ${j.fact?'good':''}">${j.fact?'Facturado':'Venta calculada'}</span>${j.dem>0?`<span class="chip warn">Demoras ${esc(usd(j.dem))}</span>`:''}${j.rech>0&&!j.nc?`<span class="chip warn">${fmt(j.rech)} cajas en reclamo sin nota de crédito</span>`:''}</div></summary>
<div class="jobd">${L('Venta de exportación',j.usd*j.tc,usd(j.usd,2)+(j.fact?' facturado':' calculado')+' × '+money(j.tc,2)+' MXN/USD'+(j.fact&&Math.abs(j.usd-j.usdCalc)>0.005?' · calculado '+usd(j.usdCalc,2):''))}${j.nac?L('Venta nacional',j.nac,j.jug?'segundas, Torreón y Juguera ('+mxn(j.jug)+')':'segundas y Torreón'):''}${j.notas?L('Notas de crédito y rechazos',-j.notas,usd(j.nc,2)+' registrados en Por cobrar'):''}
${L('Fruta',-j.fruta,fmt(j.kilos)+' kg de '+j.prods.length+(j.prods.length===1?' productor':' productores')+(j.fjug?' · Juguera '+mxn(j.fjug):''))}${L('Material de empaque',-j.mat)}${L('Mano de obra',-j.mo)}${L('Flete y cruce',-j.flete,j.fr?'real, registrado en Por pagar':'parámetro de Precios y costos')}${j.dem?L('Demoras (demurrage)',-j.demM,usd(j.dem,2)+' × '+money(j.tc,2)+' MXN/USD'):''}
${L('Resultado neto del embarque',j.neto,'margen '+pctTxt(j.margen),'tot')}
${j.prods.length?`<div class="tblx"><table class="ctab"><thead><tr><th>Productor</th><th>Kilos</th><th>Cajas</th><th>Fruta MXN</th></tr></thead><tbody>${j.prods.map(a=>`<tr><th scope="row">${esc(a.nombre)}</th><td>${fmt(a.kilos)}</td><td>${fmt(a.cajas)}</td><td>${money(a.pago)}</td></tr>`).join('')}</tbody></table></div>`:''}</div></details>`;
  return `<div class="tiles">${tiles}</div><div class="srt">${b('fecha','Más recientes')}${b('neto','Peor resultado primero')}${b('margen','Menor margen primero')}<button class="btn sm" data-act="embx">Descargar Excel</button></div>
<div class="cgrid">${J.slice(0,f.eN||80).map(card).join('')}</div>
<p class="note" style="margin-top:8px">Cada pedido es un embarque. Resultado neto = venta (facturada si se registró la factura, si no la calculada) − notas de crédito − fruta − material − mano de obra − flete y cruce (real si se registró, si no el parámetro) − demoras convertidas a pesos con el tipo de cambio de su semana. Las cajas en reclamo se restan cuando se registra su nota de crédito.</p>`;
}
async function exportEmb(){
  if(typeof ExcelJS==='undefined'){toast('La descarga en Excel no está disponible aquí');return}
  try{
    const D=statsData(),J=jobData(D.cur.list),wb=newWb(),M='#,##0.00',add=(name,cols,rows)=>{const ws=wb.addWorksheet(name,{views:[{state:'frozen',ySplit:1}]});ws.columns=cols.map(c=>({header:c[1],key:c[0],width:c[2]||14,style:c[3]?{numFmt:c[3]}:{}}));ws.getRow(1).font={bold:true};rows.forEach(r=>ws.addRow(r));ws.autoFilter={from:{row:1,column:1},to:{row:1,column:cols.length}}};
    add('Embarques',[['emp','Empresa',9],['cod','Pedido',12],['fecha','Fecha',12],['cli','Cliente',26],['cont','Contenedor o caja',16],['cajas','Cajas',10],['kilos','Kilos',11],['usd','Venta USD',13,M],['vf','Venta',12],['tc','TC MXN/USD',10,M],['ing','Ingreso MXN',14,M],['notas','Notas de crédito MXN',14,M],['fruta','Fruta MXN',14,M],['mat','Material MXN',13,M],['mo','Mano de obra MXN',13,M],['flete','Flete y cruce MXN',14,M],['ft','Flete',10],['dem','Demoras USD',12,M],['demM','Demoras MXN',12,M],['neto','Resultado neto MXN',15,M],['margen','Margen neto',10,'0.0%']],
      J.map(j=>({emp:j.emp,cod:j.cod,fecha:j.fecha,cli:j.cli,cont:j.cont,cajas:j.cajas,kilos:j.kilos,usd:r2(j.usd),vf:j.fact?'Facturada':'Calculada',tc:j.tc,ing:r2(j.ing),notas:r2(j.notas),fruta:r2(j.fruta),mat:r2(j.mat),mo:r2(j.mo),flete:r2(j.flete),ft:j.fr?'Real':'Parámetro',dem:r2(j.dem),demM:r2(j.demM),neto:r2(j.neto),margen:j.margen==null?'':j.margen})));
    const P=[];J.forEach(j=>j.prods.forEach(a=>P.push({emp:j.emp,cod:j.cod,fecha:j.fecha,prod:a.nombre,codigo:a.codigo?pad(a.codigo,3):'',kilos:a.kilos,cajas:a.cajas,pago:r2(a.pago)})));
    add('Kilos por productor',[['emp','Empresa',9],['cod','Pedido',12],['fecha','Fecha',12],['prod','Productor',30],['codigo','Código',8],['kilos','Kilos',11],['cajas','Cajas',10],['pago','Fruta MXN',14,M]],P);
    await saveFile('Embarques_'+(statsF.emp||'ALL')+'_'+todayISO()+'.xlsx',await wbBlob(wb));
  }catch(e){toast('No se pudo generar el archivo')}
}

/* ---------- v8.2 · presupuesto contra real ----------
   Catálogo «presupuesto»: una entrada por empresa y periodo (semana o mes) con precio por caja (USD), cajas, flete y costos fijos (MXN).
   Solo el administrador lo captura; al sincronizar gana, periodo por periodo, la versión más reciente. */
const LS_PRES='empaque-presupuesto';
var PPTO={d:{},dirty:false};
(function(){try{const j=JSON.parse(localStorage.getItem(LS_PRES)||'null');if(j&&j.d&&typeof j.d==='object')PPTO={d:j.d,dirty:!!j.dirty}}catch(e){}})();
function savePres(){try{localStorage.setItem(LS_PRES,JSON.stringify(PPTO))}catch(e){}setSync()}
const PRES_F=[['precio','Precio por caja','USD',1,2],['cajas','Cajas de exportación','cajas',1,0],['flete','Flete y cruce','MXN',-1,0],['fijos','Costos fijos','MXN',-1,0]];
async function syncPres(){
  try{
    const r=await sb('/rest/v1/catalogos?select=updated_at,data&clave=eq.presupuesto'),rd=(r&&r[0]&&r[0].data&&r[0].data.d)||{};let ch=false;
    Object.keys(rd).forEach(k=>{const a=rd[k],b=PPTO.d[k];if(a&&(!b||(+a.ts||0)>(+b.ts||0))){PPTO.d[k]=a;ch=true;remoteN++}});
    const ahead=Object.keys(PPTO.d).some(k=>!rd[k]||(+PPTO.d[k].ts||0)>(+rd[k].ts||0));
    if(ahead&&isAdmin()){await sb('/rest/v1/catalogos?on_conflict=clave',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:[{clave:'presupuesto',updated_at:Date.now(),data:{d:PPTO.d}}]});PPTO.dirty=false}
    savePres();if(ch&&view==='fin')render();
  }catch(e){}
}
const presKey=(e,mode,pk)=>e+'|'+mode+':'+pk;
const presLab=(mode,pk)=>mode==='S'?wkLab(pk):(()=>{const p=String(pk).split('-');return p.length===2?MESES[+p[1]-1]+' '+p[0]:pk})();
function presOf(es,mode,pk){
  const R={precio:null,cajas:null,flete:null,fijos:null,any:false};let pc=0,pw=0,pn=0,ps=0;
  es.forEach(e=>{const x=PPTO.d[presKey(e,mode,pk)];if(!x)return;['cajas','flete','fijos'].forEach(k=>{if(num(x[k])!=null){R[k]=(R[k]||0)+num(x[k]);R.any=true}});if(num(x.precio)!=null){R.any=true;ps+=num(x.precio);pn++;if(num(x.cajas)>0){pc+=num(x.precio)*num(x.cajas);pw+=num(x.cajas)}}});
  R.precio=pw>0?pc/pw:pn?ps/pn:null;R.usd=R.precio!=null&&R.cajas!=null?R.precio*R.cajas:null;return R;
}
function presReal(es,mode,pk){
  const L=visible().filter(o=>es.indexOf(o.emp)>=0&&(mode==='S'?wkOf(o)===pk:String(o.fecha||'').slice(0,7)===pk)),T=finAgg(L).T;
  return {precio:T.precio,cajas:T.cajas,flete:T.flete,fijos:es.reduce((s,e)=>s+(mode==='S'?fijoSem(e,pk):fijoMes(e,pk)),0),usd:T.ingUSD,hojas:L.length};
}
function presPeriods(mode){
  const s=new Set(),cw=curWk(),cm=todayISO().slice(0,7);
  visible().forEach(o=>{const k=mode==='S'?wkOf(o):String(o.fecha||'').slice(0,7);if(k)s.add(k)});
  Object.keys(PPTO.d).forEach(k=>{const m=/\|([SM]):(.+)$/.exec(k);if(m&&m[1]===mode)s.add(m[2])});
  if(mode==='S'){let k=cw;s.add(k);for(let i=0;i<4;i++){k=wkNext(k);s.add(k)}}
  else{s.add(cm);let d=cm+'-01';for(let i=0;i<2;i++){d=dayAdd(d,32).slice(0,7)+'-01';s.add(d.slice(0,7))}}
  return [...s].filter(k=>mode==='S'?/^\d{4}-S\d{2}$/.test(k):/^\d{4}-\d{2}$/.test(k)).sort().reverse().slice(0,60);
}
function varOf(p,r,sg,dec){
  if(p==null||r==null)return {t:'–',c:'',chip:''};
  const v=r-p,pc=p?v/Math.abs(p):null,fav=Math.abs(v)<1e-9?0:(v*sg>0?1:-1);
  return {t:(v>0?'+':'')+(dec==null?money(v):fmt(v,dec))+(pc==null?'':'<br>'+(pc>0?'+':'')+fmt(pc*100,1)+'%'),c:fav>0?'gv':fav<0?'bv':'',chip:fav?`<span class="chip ${fav>0?'good':'crit'}">${fav>0?'Favorable':'Desfavorable'}</span>`:'<span class="chip">Igual</span>'};
}
function presView(){
  const f=statsF,E=f.emp||'ALL',mode=f.pmode==='M'?'M':'S',es=E==='ALL'?['VL','EC']:[E],ed=isAdmin()&&E!=='ALL',ops=presPeriods(mode);
  const pk=ops.indexOf(f.ppk)>=0?f.ppk:(mode==='S'?curWk():todayISO().slice(0,7));f.ppk=pk;
  const P=presOf(es,mode,pk),R=presReal(es,mode,pk),x=ed?(PPTO.d[presKey(E,mode,pk)]||{}):null;
  const fm=(k,v)=>v==null?'–':k==='cajas'?fmt(v):money(v,k==='precio'?2:0);
  const card=(lab,u,pres,real,vr,tot)=>`<div class="prw${tot?' sum':''}"><div class="prh"><strong>${lab}</strong><small>${u}</small>${vr.chip}</div><div class="prg"><div>${pres}</div><div><span>Real</span><b>${real}</b></div><div><span>Variación</span><b class="${vr.c}">${vr.t}</b></div></div></div>`;
  const pres=q=>{const k=q[0];if(!ed)return `<span>Presupuesto</span><b>${fm(k,P[k])}</b>`;const id='pre-'+k;return `<label for="${id}"><span>Presupuesto</span><input class="in" id="${id}" inputmode="decimal" data-pres="${esc(presKey(E,mode,pk))}|${k}" value="${x[k]==null?'':esc(x[k])}" placeholder="—"></label>`};
  const cards=PRES_F.map(q=>card(q[1],q[2],pres(q),fm(q[0],R[q[0]]),varOf(P[q[0]],R[q[0]],q[3],q[0]==='cajas'?0:q[0]==='precio'?2:null))).join('')
    +card('Venta de exportación','USD · precio × cajas',`<span>Presupuesto</span><b>${P.usd==null?'–':money(P.usd)}</b>`,money(R.usd),varOf(P.usd,R.usd,1),1);
  const sel=`<label class="fld" for="pre-pk"><span>${mode==='S'?'Semana':'Mes'}</span><select class="in sel" id="pre-pk" data-ppk="1">${ops.map(k=>`<option value="${k}"${k===pk?' selected':''}>${esc(presLab(mode,k))}${mode==='S'?' · '+esc(wkSpan(k)):''}</option>`).join('')}</select></label>`;
  const hist=ops.filter(k=>k<=(mode==='S'?curWk():todayISO().slice(0,7))&&presOf(es,mode,k).any).slice(0,8).map(k=>{const p=presOf(es,mode,k),r=presReal(es,mode,k),v=varOf(p.usd,r.usd,1);return `<tr><th scope="row">${esc(presLab(mode,k))}<small>cajas ${p.cajas==null?'–':fmt(p.cajas)} → ${fmt(r.cajas)}</small></th><td>${p.usd==null?'–':money(p.usd)}<br>${money(r.usd)}</td><td class="${v.c}">${v.t}<br>${v.chip}</td></tr>`}).join('');
  return `<div class="srt">${[['S','Por semana'],['M','Por mes']].map(o=>`<button class="btn sm" data-act="pmode:${o[0]}" aria-pressed="${mode===o[0]}">${o[1]}</button>`).join('')}</div><div class="presel">${sel}</div>
${E==='ALL'?`<p class="note">Vista de ambas empresas: suma de los dos presupuestos.${isAdmin()?' Para capturar, elige Vera Limes o Citrilar.':''}</p>`:!isAdmin()?'<p class="note">Solo el administrador captura el presupuesto.</p>':''}
<div class="prws">${cards}</div>
<p class="note" style="margin-top:6px">Real: ${R.hojas?fmt(R.hojas)+(R.hojas===1?' hoja':' hojas')+' de empaque del periodo con los precios y costos de su semana (flete real donde se registró)':'aún sin empaques en el periodo'}. Los costos fijos reales son los de Precios y costos (la app no captura el gasto pagado). Favorable: más precio, más cajas o más venta; menos flete o menos costos fijos.</p>
${hist?`<div class="sec">Periodos con presupuesto</div><div class="tblx"><table class="ctab phist"><thead><tr><th>Periodo</th><th>Venta USD<small>presupuesto / real</small></th><th>Variación</th></tr></thead><tbody>${hist}</tbody></table></div>`:''}`;
}
document.addEventListener('change',e=>{
  const t=e.target;if(!t||!t.dataset)return;
  if(t.dataset.ppk){statsF.ppk=t.value;render();return}
  if(!t.dataset.pres||!isAdmin())return;
  const q=t.dataset.pres.split('|'),fk=q.pop(),key=q.join('|'),e0=q[0],v=num(String(t.value).replace(',','.')),cur0=PPTO.d[key]||{},old=cur0[fk];
  if(sv(old)===sv(v))return;
  const nx=Object.assign({},cur0);if(v==null)delete nx[fk];else nx[fk]=v;nx.ts=Date.now();nx.by=parBy();PPTO.d[key]=nx;PPTO.dirty=true;savePres();
  const m=/^([SM]):(.+)$/.exec(q[1]||''),fl=PRES_F.find(x=>x[0]===fk);
  logAdd({k:'param',where:'Presupuesto',ctx:{t:'f',id:e0,cod:EMPS[e0].name+' · '+(m?presLab(m[1],m[2]):'')},path:'pres.'+key+'.'+fk,lab:'Presupuesto · '+(fl?fl[1]+' ('+fl[2]+')':fk),o:sv(old),n:sv(v)});
  render();
});

/* ---------- v8.3 · Fase 3: tipo de cambio, impuestos, pólizas y cierre mensual ----------
   Catálogo «contable» (tabla catalogos, solo lo escribe el administrador): cuentas contables por empresa, tasas de IVA en ventas,
   regímenes fiscales con IVA y retenciones, y el régimen de cada productor. Todo viene vacío: lo define el contador.
   Al sincronizar gana, entrada por entrada, el cambio más reciente. */
const LS_CTB='empaque-contable';
var CTB={d:{}};
(function(){try{const j=JSON.parse(localStorage.getItem(LS_CTB)||'null');if(j&&j.d&&typeof j.d==='object')CTB.d=j.d}catch(e){}})();
function saveCtb(){try{localStorage.setItem(LS_CTB,JSON.stringify(CTB))}catch(e){}invalidateStats();setSync()}
async function syncCtb(){
  try{
    const r=await sb('/rest/v1/catalogos?select=updated_at,data&clave=eq.contable'),rd=(r&&r[0]&&r[0].data&&r[0].data.d)||{};let ch=false;
    Object.keys(rd).forEach(k=>{const a=rd[k],b=CTB.d[k];if(a&&(!b||(+a.ts||0)>(+b.ts||0))){CTB.d[k]=a;ch=true;remoteN++}});
    const ahead=Object.keys(CTB.d).some(k=>!rd[k]||(+CTB.d[k].ts||0)>(+rd[k].ts||0));
    if(ahead&&isAdmin())await sb('/rest/v1/catalogos?on_conflict=clave',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:[{clave:'contable',updated_at:Date.now(),data:{d:CTB.d}}]});
    if(ch){saveCtb();if(view==='fin')render()}
  }catch(e){}
}
const CTAS=[['bancos','Bancos'],['clientes','Clientes'],['ventasExp','Ventas de exportación'],['ventasNac','Ventas nacionales'],['devVentas','Notas de crédito sobre ventas'],['costoFruta','Compra de fruta'],['proveedores','Proveedores de fruta'],['fletes','Fletes y cruce'],['acreedores','Acreedores de flete'],['descCompras','Descuentos sobre compras'],['ivaAcred','IVA acreditable'],['ivaTras','IVA trasladado'],['retIsr','Retenciones de ISR por pagar'],['retIva','Retenciones de IVA por pagar'],['utilCamb','Utilidad cambiaria'],['perdCamb','Pérdida cambiaria']];
const CTA_L={};CTAS.forEach(c=>CTA_L[c[0]]=c[1]);
const TASAS=[['ivaExp','IVA en ventas de exportación (%)'],['ivaNac','IVA en ventas nacionales (%)']];
const ctaOf=(e,k)=>{const x=CTB.d['cta|'+e+'|'+k];return x&&String(x.num||'').trim()?x:null};
const tasaOf=(e,k)=>{const x=CTB.d['tasa|'+e+'|'+k];return x?num(x.v):null};
function regList(){return Object.keys(CTB.d).filter(k=>k.indexOf('reg|')===0&&!CTB.d[k].borrado).map(k=>Object.assign({},CTB.d[k],{id:k.slice(4)})).sort((a,b)=>String(a.nombre||'').localeCompare(String(b.nombre||'')))}
function regOfProd(c){const x=c?CTB.d['pr|'+c]:null;if(!x||!x.reg)return null;const r=CTB.d['reg|'+x.reg];return r&&!r.borrado?Object.assign({},r,{id:x.reg}):null}
function ctbSet(k,f,v,lab){
  const cur=CTB.d[k]||{},old=cur[f];if(sv(old)===sv(v))return false;
  const nx=Object.assign({},cur);if(v==null||v==='')delete nx[f];else nx[f]=v;nx.ts=Date.now();nx.by=parBy();CTB.d[k]=nx;saveCtb();
  const e0=(/^(cta|tasa)\|(VL|EC)\|/.exec(k)||[])[2]||'VL';
  logAdd({k:'param',where:'Contabilidad',ctx:{t:'f',id:e0,cod:'Catálogo contable'},path:'ctb.'+k+'.'+f,lab:lab,o:sv(old),n:sv(v)});return true;
}
const ymOf=d=>String(d||'').slice(0,7);
const ymLab=ym=>{const p=String(ym).split('-');return p.length===2?MESES[+p[1]-1]+' '+p[0]:ym};
function ctbMonths(){const s=new Set([todayISO().slice(0,7)]);visible().forEach(o=>{if(o.fecha)s.add(ymOf(o.fecha))});COB.list.concat(PAG.list).forEach(x=>{if(x.fecha)s.add(ymOf(x.fecha))});return [...s].filter(k=>/^\d{4}-\d{2}$/.test(k)).sort().reverse()}
const ctbEs=E=>E==='ALL'||!E?['VL','EC']:[E];
const tcHoy=e=>+parsDe(e,curWk()).tc||0;
/* tipo de cambio con el que se registró la venta: el de la semana del pedido (el mismo de Utilidad) */
const tcReg=x=>+parsDe(x.emp,x.wk||wkOfDate(x.fecha)).tc||0;

/* pérdida o ganancia cambiaria: realizada en cada cobro (TC del cobro contra el de registro) y no realizada en lo pendiente (TC de hoy) */
function fxData(E,ym){
  const es=ctbEs(E),A=accData(E||'ALL'),reg=new Map();A.cxc.forEach(x=>reg.set(x.ref,x));
  const R=[],sin=[];
  COB.list.forEach(y=>{if(y.anulado||y.tipo!=='cobro'||es.indexOf(y.emp)<0||(ym&&ymOf(y.fecha)!==ym))return;const x=reg.get(y.ref);if(!x)return;const tr=tcReg(x);if(!(+y.tc>0)){sin.push({y:y,x:x});return}R.push({y:y,x:x,tcR:tr,tcC:+y.tc,usd:+y.monto,dif:(+y.monto)*(+y.tc-tr)})});
  const U=A.cxc.filter(x=>x.b).map(x=>{const tr=tcReg(x),th=tcHoy(x.emp);return {x:x,tcR:tr,tcH:th,usd:x.saldo,dif:x.saldo*(th-tr)}});
  return {R:R,U:U,sin:sin,real:R.reduce((s,a)=>s+a.dif,0),noReal:U.reduce((s,a)=>s+a.dif,0),usdAb:A.agc.tot};
}
/* descalce: lo que se tiene y se debe en dólares, y cuánto cambia con ±1 MXN por dólar */
function fxExpo(E,ym){
  const es=ctbEs(E),A=accData(E||'ALL'),L=visible().filter(o=>es.indexOf(o.emp)>=0&&ymOf(o.fecha)===ym),T=finAgg(L).T;
  let dem=0;const ps=new Set();L.forEach(o=>{const k=o.emp+'|'+o.cod;if(ps.has(k))return;ps.add(k);dem+=n0(biOf(o).demora)});
  const tc=es.reduce((s,e)=>s+tcHoy(e),0)/es.length;
  return {act:A.agc.tot,pas:0,net:A.agc.tot,ingUSD:T.ingUSD,demUSD:dem,flujo:T.ingUSD-dem,util:T.util,tc:tc,hojas:L.length};
}
/* impuestos estimados del mes: compras de fruta por productor con su régimen y ventas con las tasas de la empresa */
function taxData(E,ym){
  const es=ctbEs(E),pm=new Map();let sinReg=0;
  es.forEach(e=>accData(e).cxp.forEach(x=>{if((x.tipo!=='prod'&&x.tipo!=='jug')||ymOf(x.fecha)!==ym)return;const k=x.codigo?'c'+x.codigo:'n'+norm(x.nombre);let a=pm.get(k);if(!a){a={nombre:x.nombre,codigo:x.codigo,reg:regOfProd(x.codigo),base:0};pm.set(k,a)}a.base+=x.monto}));
  const P=[...pm.values()].map(a=>{const r=a.reg,t=f=>r&&num(r[f])!=null?num(r[f])/100:0;if(!r)sinReg++;const iva=a.base*t('iva'),isr=a.base*t('isr'),riva=a.base*t('ivaRet');return Object.assign(a,{iva:iva,isr:isr,riva:riva,neto:a.base+iva-isr-riva})}).sort((a,b)=>b.base-a.base);
  const V=es.map(e=>{const T=finAgg(visible().filter(o=>o.emp===e&&ymOf(o.fecha)===ym)).T,te=tasaOf(e,'ivaExp'),tn=tasaOf(e,'ivaNac');return {e:e,exp:T.ingExp,nac:T.ingNac,te:te,tn:tn,iva:T.ingExp*(te||0)/100+T.ingNac*(tn||0)/100}});
  const S=k=>P.reduce((s,a)=>s+a[k],0);
  return {P:P,V:V,sinReg:sinReg,base:S('base'),iva:S('iva'),isr:S('isr'),riva:S('riva'),ivaTras:V.reduce((s,v)=>s+v.iva,0),sinTasa:V.some(v=>v.te==null||v.tn==null)};
}
/* pólizas del mes: ventas, compras y notas (diario), cobros (ingreso) y pagos (egreso), en MXN */
function polizas(E,ym){
  const P=[],miss=new Set(),cnt={};
  for(const e of ctbEs(E)){
    const A=accData(e),cx=new Map();A.cxc.concat(A.cxj).forEach(x=>cx.set(x.ref,x));const cp=new Map();A.cxp.forEach(x=>cp.set(x.ref,x));
    const L=(k,c,a)=>{const ct=ctaOf(e,k);return {k:k,cta:ct?String(ct.num).trim():'',nom:ct&&ct.nombre?ct.nombre:CTA_L[k],c:r2(c||0),a:r2(a||0)}};
    const pol=(t,fecha,con,ref,lines)=>{lines=lines.filter(l=>Math.abs(l.c)>0.004||Math.abs(l.a)>0.004);if(!lines.length)return;lines.forEach(l=>{if(!l.cta)miss.add(e+'|'+l.k)});const ck=e+t;cnt[ck]=(cnt[ck]||0)+1;P.push({e:e,t:t,id:e+'-'+t+'-'+ym.replace('-','')+'-'+pad(cnt[ck],3),fecha:fecha,con:con,ref:ref,lines:lines})};
    const te=(tasaOf(e,'ivaExp')||0)/100,tn=(tasaOf(e,'ivaNac')||0)/100;
    A.cxc.forEach(x=>{const f=x.fFact||x.fecha;if(ymOf(f)!==ym)return;const m=x.monto*tcReg(x),iv=m*te;pol('D',f,'Venta '+x.lab+' · '+x.nombre+' · '+amt(x.monto,'USD')+' a '+money(tcReg(x),2)+' MXN/USD',x.ref,[L('clientes',m+iv,0),L('ventasExp',0,m),L('ivaTras',0,iv)])});
    const nac=finAgg(visible().filter(o=>o.emp===e&&ymOf(o.fecha)===ym)).T.ingNac;if(nac>0.005)pol('D',ym+'-'+pad(new Date(+ym.slice(0,4),+ym.slice(5,7),0).getDate(),2),'Ventas nacionales del mes (segundas, Torreón y Juguera)','',[L('clientes',nac*(1+tn),0),L('ventasNac',0,nac),L('ivaTras',0,nac*tn)]);
    A.cxp.forEach(x=>{if(ymOf(x.fecha)!==ym)return;
      if(x.tipo==='prod'||x.tipo==='jug'){const r=regOfProd(x.codigo),t=f=>r&&num(r[f])!=null?num(r[f])/100:0,iv=x.monto*t('iva'),is=x.monto*t('isr'),ri=x.monto*t('ivaRet');pol('D',x.fecha,(x.tipo==='jug'?'Fruta a Juguera · ':'Compra de fruta · ')+x.nombre+' · '+wkLab(x.wk)+(r?' · '+r.nombre:' · sin régimen'),x.ref,[L('costoFruta',x.monto,0),L('ivaAcred',iv,0),L('retIsr',0,is),L('retIva',0,ri),L('proveedores',0,x.monto+iv-is-ri)])}
      else pol('D',x.fecha,x.det+(x.real?' · flete real':''),x.ref,[L('fletes',x.monto,0),L('acreedores',0,x.monto)]);
    });
    COB.list.forEach(y=>{if(y.anulado||y.emp!==e||ymOf(y.fecha)!==ym||(y.tipo!=='cobro'&&y.tipo!=='nota'))return;
      if(String(y.ref).indexOf('cxj|')===0){const m=+y.monto;if(y.tipo==='nota')pol('D',y.fecha,'Descuento de '+cxjNm(y.ref)+' · '+(y.lab||'')+' · '+amt(m,'MXN'),y.ref,[L('devVentas',m,0),L('clientes',0,m)]);else pol('I',y.fecha,'Cobro de '+cxjNm(y.ref)+' · '+(y.lab||'')+' · '+amt(m,'MXN')+(y.refb?' · ref '+y.refb:''),y.ref,[L('bancos',m,0),L('clientes',0,m)]);return}
      const x=cx.get(y.ref),tr=x?tcReg(x):+parsDe(e,wkOfDate(y.fecha)).tc||0,base=(+y.monto)*tr;
      if(y.tipo==='nota'){pol('D',y.fecha,'Nota de crédito · '+(y.nombre||'')+' · '+(y.lab||'')+' · '+amt(+y.monto,'USD'),y.ref,[L('devVentas',base,0),L('clientes',0,base)]);return}
      const tc=+y.tc>0?+y.tc:tr,bk=(+y.monto)*tc,d=bk-base;pol('I',y.fecha,'Cobro · '+(y.nombre||'')+' · '+(y.lab||'')+' · '+amt(+y.monto,'USD')+' a '+money(tc,2)+(+y.tc>0?'':' (sin TC del cobro: se usa el de registro)'),y.ref,[L('bancos',bk,0),L('perdCamb',d<0?-d:0,0),L('clientes',0,base),L('utilCamb',0,d>0?d:0)])});
    PAG.list.forEach(y=>{if(y.anulado||y.emp!==e||ymOf(y.fecha)!==ym||(y.tipo!=='pago'&&y.tipo!=='ajuste'))return;const fl=String(y.ref).indexOf('cxp|flete|')===0,k=fl?'acreedores':'proveedores';
      if(y.tipo==='ajuste')pol('D',y.fecha,'Ajuste o descuento · '+(y.nombre||'')+' · '+(y.lab||''),y.ref,[L(k,+y.monto,0),L('descCompras',0,+y.monto)]);
      else pol('E',y.fecha,'Pago · '+(y.nombre||'')+' · '+(y.lab||'')+(y.refb?' · ref '+y.refb:''),y.ref,[L(k,+y.monto,0),L('bancos',0,+y.monto)]);
    });
  }
  P.sort((a,b)=>a.e.localeCompare(b.e)||String(a.fecha).localeCompare(String(b.fecha))||a.t.localeCompare(b.t));
  return {P:P,miss:[...miss],c:P.reduce((s,p)=>s+p.lines.reduce((t,l)=>t+l.c,0),0),a:P.reduce((s,p)=>s+p.lines.reduce((t,l)=>t+l.a,0),0)};
}
/* hoja de cierre mensual */
function cierreData(E,ym){
  const es=ctbEs(E),L=visible().filter(o=>es.indexOf(o.emp)>=0&&ymOf(o.fecha)===ym),T=finAgg(L).T,fijo=es.reduce((s,e)=>s+fijoMes(e,ym),0),fx=fxData(E,ym),tx=taxData(E,ym),po=polizas(E,ym);
  const inE=x=>es.indexOf(x.emp)>=0&&!x.anulado&&ymOf(x.fecha)===ym;
  const usdM=x=>String(x.ref).indexOf('cxj|')!==0,cobJ=COB.list.filter(x=>inE(x)&&x.tipo==='cobro'&&!usdM(x)).reduce((s,x)=>s+(+x.monto||0),0);
  const cobU=COB.list.filter(x=>inE(x)&&x.tipo==='cobro'&&usdM(x)).reduce((s,x)=>s+(+x.monto||0),0),notU=COB.list.filter(x=>inE(x)&&x.tipo==='nota'&&usdM(x)).reduce((s,x)=>s+(+x.monto||0),0),pag=PAG.list.filter(x=>inE(x)&&x.tipo==='pago').reduce((s,x)=>s+(+x.monto||0),0);
  const wks=[...new Set(L.map(wkOf).filter(Boolean))].sort(),abiertas=wks.filter(k=>!wkClosed(k));
  const A=accData(E||'ALL'),sinFact=A.cxc.filter(x=>ymOf(x.fecha)===ym&&x.fact==null).length;
  const chk=[[!abiertas.length,abiertas.length?'Semanas sin cerrar: '+abiertas.map(k=>wkLab(k,true)).join(', '):'Todas las semanas del mes están cerradas'],
    [!sinFact,sinFact?sinFact+(sinFact===1?' venta sin factura registrada':' ventas sin factura registrada'):'Todas las ventas del mes tienen factura'],
    [!fx.sin.length,fx.sin.length?fx.sin.length+(fx.sin.length===1?' cobro sin tipo de cambio':' cobros sin tipo de cambio'):'Todos los cobros tienen tipo de cambio'],
    [!tx.sinReg,tx.sinReg?tx.sinReg+(tx.sinReg===1?' productor sin régimen fiscal':' productores sin régimen fiscal'):'Todos los productores del mes tienen régimen'],
    [!po.miss.length,po.miss.length?po.miss.length+(po.miss.length===1?' cuenta contable sin capturar':' cuentas contables sin capturar'):'Catálogo de cuentas completo'],
    [!tx.sinTasa,tx.sinTasa?'Faltan tasas de IVA en ventas':'Tasas de IVA en ventas capturadas'],
    [!FIN.ejemplo,FIN.ejemplo?'Precios y costos de ejemplo':'Precios y costos reales']];
  return {ym:ym,T:T,fijo:fijo,util:T.util-fijo,fx:fx,tx:tx,po:po,cobU:cobU,cobJ:cobJ,notU:notU,pag:pag,wks:wks,chk:chk,hojas:L.length,cxc:A.agc.tot,cxj:A.agj.tot,cxp:A.agp.tot};
}

/* ----- vista: pestaña Contabilidad ----- */
const CSUB=[['cie','Cierre mensual'],['fx','Tipo de cambio'],['imp','Impuestos'],['pol','Pólizas'],['cat','Catálogos']];
const AVAL='<span class="chip warn">A validar con el contador</span>';
function ctbView(){
  const f=statsF,E=f.emp||'ALL',sub=CSUB.some(x=>x[0]===f.csub)?f.csub:'cie',ms=ctbMonths(),ym=ms.indexOf(f.cym)>=0?f.cym:ms[0];f.cym=ym;
  const subs=`<div class="srt csub">${CSUB.map(x=>`<button class="btn sm" data-act="csub:${x[0]}" aria-pressed="${sub===x[0]}">${x[1]}</button>`).join('')}</div>`;
  const msel=sub==='cat'?'':`<div class="presel"><label class="fld" for="ctb-ym"><span>Mes</span><select class="in sel" id="ctb-ym" data-cym="1">${ms.map(k=>`<option value="${k}"${k===ym?' selected':''}>${esc(ymLab(k))}</option>`).join('')}</select></label></div>`;
  const body=sub==='fx'?fxHtml(E,ym):sub==='imp'?impHtml(E,ym):sub==='pol'?polHtml(E,ym):sub==='cat'?catHtml(E):cieHtml(E,ym);
  return subs+msel+body;
}
function fxHtml(E,ym){
  const X=fxData(E,ym),Z=fxExpo(E,ym),sg=v=>(v>0.005?'+':'')+mxn(v);
  const tiles=tileHtml('Cambiaria realizada · '+ymLab(ym),sg(X.real),X.R.length+(X.R.length===1?' cobro':' cobros')+' con tipo de cambio'+(X.sin.length?' · '+X.sin.length+' sin TC':''),null,X.real<-0.005?'warnt':'')
   +tileHtml('Cambiaria no realizada · hoy',sg(X.noReal),'pendiente por cobrar '+amt(X.usdAb,'USD',0)+' al TC de hoy',null,X.noReal<-0.005?'warnt':'');
  const rr=X.R.slice().sort((a,b)=>String(b.y.fecha).localeCompare(String(a.y.fecha))).slice(0,30).map(a=>`<tr><th scope="row">${esc(a.x.nombre)}<small>${esc(a.x.lab)} · ${esc(fmtDate(a.y.fecha))}</small></th><td>${amt(a.usd,'USD',0)}</td><td>${money(a.tcR,2)} → ${money(a.tcC,2)}</td><td class="${a.dif>0.005?'gv':a.dif<-0.005?'bv':''}">${sg(a.dif)}</td></tr>`).join('');
  const sens=[-1,0,1].map(d=>{const tc=Z.tc+d;return `<tr${d===0?' class="tot"':''}><th scope="row">${money(tc,2)} MXN/USD${d?'':'<small>tipo de cambio de hoy</small>'}</th><td>${mxn(Z.net*tc,0)}</td><td>${mxn(Z.util+d*Z.flujo,0)}${d?'<small>'+(d>0?'+':'−')+mxn(Math.abs(Z.flujo),0)+'</small>':''}</td></tr>`}).join('');
  return `<div class="tiles">${tiles}</div>
<div class="sec">Cobros del mes</div>${rr?`<div class="tblx"><table class="ctab phist"><thead><tr><th>Cliente</th><th>Cobrado</th><th>TC registro → cobro</th><th>Diferencia MXN</th></tr></thead><tbody>${rr}</tbody></table></div>`:'<p class="note">Sin cobros con tipo de cambio en el mes.</p>'}
${X.sin.length?`<p class="note">${X.sin.length} ${X.sin.length===1?'cobro no tiene':'cobros no tienen'} tipo de cambio: no entran en la cambiaria. Captúralo al registrar el cobro.</p>`:''}
<div class="sec">Descalce de monedas y sensibilidad</div>
<div class="ig tot wkg abs"><div><span>En dólares a favor</span><b>${amt(Z.act,'USD',0)}</b><small>por cobrar a clientes</small></div><div><span>En dólares en contra</span><b>${amt(Z.pas,'USD',0)}</b><small>la app no registra deudas en USD</small></div><div><span>Posición neta</span><b>${amt(Z.net,'USD',0)}</b><small>larga en dólares</small></div></div>
<div class="tblx" style="margin-top:8px"><table class="ctab phist"><thead><tr><th>Tipo de cambio</th><th>Por cobrar<small>valuado en MXN</small></th><th>Utilidad<small>${esc(ymLab(ym))}</small></th></tr></thead><tbody>${sens}</tbody></table></div>
<p class="note" style="margin-top:6px">Por cada peso que sube el dólar, lo por cobrar vale ${mxn(Z.net,0)} más y la utilidad de ${esc(ymLab(ym))} sube ${mxn(Z.flujo,0)} (ventas de ${amt(Z.ingUSD,'USD',0)}${Z.demUSD?' menos demoras de '+amt(Z.demUSD,'USD',0):''}); si baja, es al revés. Los costos van en pesos. Es aproximado: no ajusta el pago de fruta en consignación. La cambiaria realizada compara el tipo de cambio del cobro contra el de la semana del pedido (el mismo con el que se calcula la utilidad); la no realizada usa el tipo de cambio de hoy de Precios y costos.</p>`;
}
function impHtml(E,ym){
  const X=taxData(E,ym),regs=regList();
  const rows=X.P.map(a=>`<tr><th scope="row">${esc(a.nombre)}<small>${a.reg?esc(a.reg.nombre||'Régimen'):'<b class="negv">sin régimen</b>'}</small></th><td>${money(a.base)}</td><td>${money(a.iva)}</td><td>${money(a.isr+a.riva)}</td><td><b>${money(a.neto)}</b></td></tr>`).join('')+(X.P.length>1?`<tr class="tot"><th scope="row">Total</th><td>${money(X.base)}</td><td>${money(X.iva)}</td><td>${money(X.isr+X.riva)}</td><td><b>${money(X.P.reduce((s,a)=>s+a.neto,0))}</b></td></tr>`:'');
  const ven=X.V.map(v=>`<div class="kv"><span>${esc(EMPS[v.e].name)}<br><small class="note">exportación ${mxn(v.exp)} a ${v.te==null?'sin tasa':fmt(v.te,2)+' %'} · nacional ${mxn(v.nac)} a ${v.tn==null?'sin tasa':fmt(v.tn,2)+' %'}</small></span><b>${mxn(v.iva)}</b></div>`).join('');
  return `<div class="warnbox" role="note"><strong>Estimado ${AVAL}</strong><div>Las tasas y regímenes los define el contador en Catálogos. Sin ellos, los impuestos salen en cero.${regs.length?'':' Todavía no hay regímenes capturados.'}</div></div>
<div class="tiles" style="margin-top:10px">${tileHtml('Compras de fruta',mxn(X.base),ymLab(ym)+' · '+X.P.length+(X.P.length===1?' productor':' productores'))}${tileHtml('IVA acreditable',mxn(X.iva),'de las compras de fruta')}${tileHtml('Retenciones',mxn(X.isr+X.riva),'ISR '+mxn(X.isr)+' · IVA '+mxn(X.riva))}${tileHtml('IVA trasladado',mxn(X.ivaTras),X.sinTasa?'faltan tasas de IVA en ventas':'en ventas del mes')}</div>
<div class="sec">Por productor</div>${rows?`<div class="tblx"><table class="ctab phist"><thead><tr><th>Productor</th><th>Compra MXN</th><th>IVA MXN</th><th>Retenciones MXN</th><th>Neto MXN</th></tr></thead><tbody>${rows}</tbody></table></div>`:'<p class="note">Sin compras de fruta en el mes.</p>'}
${X.sinReg?`<p class="note">${X.sinReg} ${X.sinReg===1?'productor no tiene':'productores no tienen'} régimen: se asigna en Catálogos.</p>`:''}
<div class="sec">IVA en ventas</div><div class="panel">${ven}</div>
<p class="note" style="margin-top:6px">Neto = compra + IVA − retenciones. Es una estimación para planear y para las pólizas; no cambia lo que se ve en Por pagar ni sustituye la declaración. La compra de cada semana cuenta en el mes en que termina la semana.</p>`;
}
function polHtml(E,ym){
  const X=polizas(E,ym),T={D:'Diario',I:'Ingreso',E:'Egreso'};
  const miss=X.miss.length?`<div class="warnbox" role="alert"><strong>Faltan ${X.miss.length} ${X.miss.length===1?'cuenta contable':'cuentas contables'}</strong><div>${esc(X.miss.map(k=>{const q=k.split('|');return EMPS[q[0]].name+': '+CTA_L[q[1]]}).join(' · '))}. La exportación las marca como «SIN CUENTA». ${isAdmin()?'Captúralas en Catálogos.':'El administrador las captura en Catálogos.'}</div></div>`:'';
  const cards=X.P.slice(0,statsF.polN||40).map(p=>`<details class="prd pol"><summary><div class="r1"><div class="pnm">${esc(T[p.t])} ${esc(p.id)}<small>${esc(fmtDate(p.fecha))} · ${esc(p.con)}</small></div><div class="rend">${money(p.lines.reduce((s,l)=>s+l.c,0),2)}<em class="cur">MXN</em></div></div></summary>
<div class="tblx"><table class="ctab phist"><thead><tr><th>Cuenta</th><th>Cargo MXN</th><th>Abono MXN</th></tr></thead><tbody>${p.lines.map(l=>`<tr><th scope="row">${l.cta?esc(l.cta):'<b class="negv">SIN CUENTA</b>'}<small>${esc(l.nom)}</small></th><td>${l.c?money(l.c,2):''}</td><td>${l.a?money(l.a,2):''}</td></tr>`).join('')}</tbody></table></div></details>`).join('');
  return `${miss}<div class="tiles" style="margin-top:10px">${tileHtml('Pólizas de '+ymLab(ym),fmt(X.P.length),['D','I','E'].map(t=>X.P.filter(p=>p.t===t).length+' de '+T[t].toLowerCase()).join(' · '))}${tileHtml('Cargos = abonos',money(X.c,2)+'<em class="cur">MXN</em>',Math.abs(X.c-X.a)<0.05?'cuadran':'diferencia '+money(X.c-X.a,2),null,Math.abs(X.c-X.a)<0.05?'':'warnt')}</div>
<div class="srt"><button class="btn sm primary" data-act="ctbx:pol">${X.miss.length?'Descargar pólizas de todos modos':'Descargar pólizas (Excel)'}</button></div>
${X.P.length?`<div class="cgrid">${cards}</div>${X.P.length>(statsF.polN||40)?'<button class="btn sm" data-act="polmore">Ver más</button>':''}`:'<p class="note">Sin movimientos en el mes.</p>'}
<p class="note" style="margin-top:8px">Diario: ventas (con la factura si existe, al tipo de cambio de la semana del pedido), ventas nacionales, compras de fruta con IVA y retenciones de su régimen, fletes, notas de crédito y ajustes. Ingreso: cada cobro a su tipo de cambio, con la diferencia a utilidad o pérdida cambiaria. Egreso: cada pago. Todo en MXN. ${AVAL}</p>`;
}
function catHtml(E){
  const ed=isAdmin(),e=E==='ALL'?(statsF.cate||'VL'):E,dis=ed?'':' readonly',sel=ed?'':' disabled';
  const ti=(k,v,lab,ph)=>`<input class="in txt" aria-label="${esc(lab)}" data-ctb="${esc(k)}" value="${v==null?'':esc(v)}"${ph?` placeholder="${esc(ph)}"`:''}${dis}>`;
  const ctas=CTAS.map(c=>{const x=CTB.d['cta|'+e+'|'+c[0]]||{};return `<span class="fl">${c[1]}</span>${ti('cta|'+e+'|'+c[0]+'|num',x.num,'Número de cuenta '+c[1],'—')}${ti('cta|'+e+'|'+c[0]+'|nombre',x.nombre,'Nombre en tu catálogo '+c[1],c[1])}`}).join('');
  const tasas=TASAS.map(t=>{const x=CTB.d['tasa|'+e+'|'+t[0]]||{};return `<label class="fld"><span>${t[1]}</span>${ti('tasa|'+e+'|'+t[0]+'|v',x.v,t[1],'sin capturar')}</label>`}).join('');
  const regs=regList();
  const regH=regs.map(r=>`<div class="prw"><div class="grid4">${['nombre','iva','isr','ivaRet'].map(f=>`<label class="fld"><span>${{nombre:'Régimen',iva:'IVA en compra (%)',isr:'Retención ISR (%)',ivaRet:'Retención IVA (%)'}[f]}</span>${ti('reg|'+r.id+'|'+f,r[f],f,f==='nombre'?'nombre':'—')}</label>`).join('')}</div>${ed?`<div class="pact"><button class="btn sm danger" data-act="ctbregx:${esc(r.id)}">Quitar</button></div>`:''}</div>`).join('');
  const A=accData('ALL'),seen=new Map();A.cxp.forEach(x=>{if(x.tipo==='prod'&&x.codigo&&!seen.has(x.codigo))seen.set(x.codigo,x.nombre)});
  Object.keys(CTB.d).forEach(k=>{if(k.indexOf('pr|')===0){const c=+k.slice(3),li=LISTA.find(y=>y.c===c);if(!seen.has(c))seen.set(c,li?li.n:'#'+c)}});
  if(statsF.prAll)LISTA.forEach(li=>{if(!seen.has(li.c))seen.set(li.c,li.n)});
  const prs=[...seen.entries()].sort((a,b)=>a[0]-b[0]).map(([c,n])=>{const cur=(CTB.d['pr|'+c]||{}).reg||'';return `<div class="kv"><span>#${pad(c,3)} ${esc(n)}</span><select class="in sel prsel" aria-label="Régimen de ${esc(n)}" data-ctb="pr|${c}|reg"${sel}><option value="">Sin régimen</option>${regs.map(r=>`<option value="${esc(r.id)}"${cur===r.id?' selected':''}>${esc(r.nombre||'Régimen sin nombre')}</option>`).join('')}</select></div>`}).join('');
  return `<div class="warnbox" role="note"><strong>Lo define tu contador ${AVAL}</strong><div>Nada viene capturado: la app no supone cuentas, tasas ni regímenes. ${ed?'Lo capturas como administrador; cada cambio queda en la bitácora contable.':'Solo el administrador lo captura.'}</div></div>
${E==='ALL'?`<div class="srt" style="margin-top:10px">${['VL','EC'].map(k=>`<button class="btn sm" data-act="cate:${k}" aria-pressed="${e===k}">${EMPS[k].name}</button>`).join('')}</div>`:''}
<div class="sec">Cuentas contables · ${esc(EMPS[e].name)}</div><div class="fingrid ctag"><span></span><span class="fh">Número</span><span class="fh">Nombre en tu catálogo</span>${ctas}</div>
<div class="sec">IVA en ventas · ${esc(EMPS[e].name)}</div><div class="grid2">${tasas}</div>
<div class="sec">Regímenes fiscales de productores</div>${regH||'<p class="note">Sin regímenes.</p>'}${ed?'<div class="pact"><button class="btn sm" data-act="ctbreg">Agregar régimen</button></div>':''}
<div class="sec">Régimen de cada productor</div><div class="panel">${prs||'<p class="note">Sin productores con compras.</p>'}</div><div class="srt"><button class="btn sm" data-act="prall" aria-pressed="${!!statsF.prAll}">${statsF.prAll?'Solo productores con compras':'Ver toda la lista de productores'}</button></div>`;
}
function cieHtml(E,ym){
  const C=cierreData(E,ym),T=C.T,ok=C.chk.filter(c=>c[0]).length;
  const row=(l,v,sub,cls)=>`<div class="kv${cls?' '+cls:''}"><span>${l}${sub?`<br><small class="note">${sub}</small>`:''}</span><b class="${v<0?'negv':''}">${mxn(v)}</b></div>`;
  return `<div class="tiles">${tileHtml('Utilidad después de fijos',money(C.util+C.fx.real)+'<em class="cur">MXN</em>','con cambiaria realizada · '+ymLab(ym),null,C.util+C.fx.real<0?'warnt':'')}${tileHtml('Lista de cierre',ok+' de '+C.chk.length,ok===C.chk.length?'todo listo':'revisa los pendientes',null,ok===C.chk.length?'':'warnt')}</div>
<div class="dsk fin2"><div class="dcol"><div class="sec">Resultado de ${esc(ymLab(ym))}</div><div class="panel">${row('Ingresos',T.ing,'exportación '+amt(T.ingUSD,'USD',0)+' · nacional '+mxn(T.ingNac)+(T.ingJug?' (Juguera '+mxn(T.ingJug)+')':''))}${row('Costos directos',-T.cost,'fruta, material, mano de obra y flete')}${row('Utilidad bruta',T.util,'margen '+pctTxt(T.margen),'tot')}${row('Costos fijos',-C.fijo,'de Precios y costos, llevados a mes')}${row('Cambiaria realizada',C.fx.real)}${row('Resultado del mes',C.util+C.fx.real,'',  'tot')}</div>
<div class="sec">Cuentas</div><div class="panel"><div class="kv"><span>Cobrado en el mes</span><b>${amt(C.cobU,'USD')}</b></div>${C.cobJ||C.cxj?`<div class="kv"><span>Cobrado a la Juguera en el mes</span><b>${amt(C.cobJ,'MXN')}</b></div>`:''}<div class="kv"><span>Notas de crédito del mes</span><b>${amt(C.notU,'USD')}</b></div><div class="kv"><span>Pagado en el mes</span><b>${amt(C.pag,'MXN')}</b></div><div class="kv"><span>Por cobrar hoy</span><b>${amt(C.cxc,'USD')}</b></div>${C.cxj?`<div class="kv"><span>Por cobrar a la Juguera hoy</span><b>${amt(C.cxj,'MXN')}</b></div>`:''}<div class="kv"><span>Por pagar hoy</span><b>${amt(C.cxp,'MXN')}</b></div></div></div>
<div class="dcol"><div class="sec">Lista de cierre</div><div class="panel">${C.chk.map(c=>`<div class="kv"><span>${esc(c[1])}</span><span class="chip ${c[0]?'good':'warn'}">${c[0]?'Listo':'Pendiente'}</span></div>`).join('')}</div>
<div class="sec">Impuestos estimados</div><div class="panel"><div class="kv"><span>IVA acreditable (compras de fruta)</span><b>${mxn(C.tx.iva)}</b></div><div class="kv"><span>IVA trasladado (ventas)</span><b>${mxn(C.tx.ivaTras)}</b></div><div class="kv"><span>Retenciones por enterar</span><b>${mxn(C.tx.isr+C.tx.riva)}</b></div><p class="note">${AVAL}</p></div>
<div class="sec">Pólizas</div><div class="panel"><div class="kv"><span>${fmt(C.po.P.length)} pólizas del mes</span><b>${money(C.po.c,2)} MXN</b></div>${C.po.miss.length?`<p class="note">Faltan ${C.po.miss.length} cuentas contables.</p>`:''}</div></div></div>
<div class="srt"><button class="btn primary" data-act="ctbx:cie">Descargar cierre mensual (Excel)</button></div>
<p class="note" style="margin-top:6px">El Excel trae las hojas Cierre mensual, Pólizas, Impuestos y Cambiaria. Las cifras salen de lo capturado en la app con los precios y costos de cada semana; no sustituyen la contabilidad oficial.</p>`;
}
async function exportCtb(kind){
  if(typeof ExcelJS==='undefined'){toast('La descarga en Excel no está disponible aquí');return}
  try{
    const f=statsF,E=f.emp||'ALL',ym=f.cym||todayISO().slice(0,7),wb=newWb(),M='#,##0.00';
    const add=(name,cols,rows)=>{const ws=wb.addWorksheet(name,{views:[{state:'frozen',ySplit:1}]});ws.columns=cols.map(c=>({header:c[1],key:c[0],width:c[2]||14,style:c[3]?{numFmt:c[3]}:{}}));ws.getRow(1).font={bold:true};rows.forEach(r=>ws.addRow(r));return ws};
    const X=polizas(E,ym),TT={D:'Diario',I:'Ingreso',E:'Egreso'};
    if(kind==='cie'){
      const C=cierreData(E,ym),T=C.T;
      add('Cierre mensual',[['k','Concepto',44],['v','Monto',18,M],['u','Divisa',8],['n','Nota',60]],[
        {k:'Mes',v:null,u:'',n:ymLab(ym)+' · '+(E==='ALL'?'ambas empresas':EMPS[E].name)},
        {k:'Ventas de exportación',v:r2(T.ingUSD),u:'USD',n:'a los tipos de cambio de cada semana'},{k:'Ingresos',v:r2(T.ing),u:'MXN'},{k:'Costos directos',v:r2(T.cost),u:'MXN'},{k:'Utilidad bruta',v:r2(T.util),u:'MXN'},
        {k:'Costos fijos',v:r2(C.fijo),u:'MXN',n:'de Precios y costos, llevados a mes'},{k:'Cambiaria realizada',v:r2(C.fx.real),u:'MXN'},{k:'Resultado del mes',v:r2(C.util+C.fx.real),u:'MXN'},
        {k:'Cambiaria no realizada (hoy)',v:r2(C.fx.noReal),u:'MXN',n:'informativa'},{k:'Cobrado en el mes',v:r2(C.cobU),u:'USD'},{k:'Notas de crédito del mes',v:r2(C.notU),u:'USD'},{k:'Pagado en el mes',v:r2(C.pag),u:'MXN'},
        {k:'Por cobrar hoy',v:r2(C.cxc),u:'USD'},{k:'Por pagar hoy',v:r2(C.cxp),u:'MXN'},{k:'IVA acreditable estimado',v:r2(C.tx.iva),u:'MXN',n:'a validar con el contador'},{k:'IVA trasladado estimado',v:r2(C.tx.ivaTras),u:'MXN',n:'a validar con el contador'},{k:'Retenciones estimadas',v:r2(C.tx.isr+C.tx.riva),u:'MXN',n:'a validar con el contador'}]
        .concat([{k:'',v:null,u:'',n:''},{k:'Lista de cierre',v:null,u:'',n:''}],C.chk.map(c=>({k:c[1],v:null,u:'',n:c[0]?'Listo':'Pendiente'}))));
      const tx=C.tx;add('Impuestos',[['p','Productor',30],['r','Régimen',24],['b','Compra MXN',14,M],['i','IVA MXN',12,M],['s','Ret. ISR MXN',12,M],['ri','Ret. IVA MXN',12,M],['n','Neto MXN',14,M]],tx.P.map(a=>({p:a.nombre,r:a.reg?a.reg.nombre||'':'SIN RÉGIMEN',b:r2(a.base),i:r2(a.iva),s:r2(a.isr),ri:r2(a.riva),n:r2(a.neto)})));
      add('Cambiaria',[['f','Fecha',12],['c','Cliente',26],['d','Cuenta',22],['u','Cobrado USD',13,M],['tr','TC registro',11,M],['tc','TC cobro',11,M],['dif','Diferencia MXN',14,M]],C.fx.R.map(a=>({f:a.y.fecha,c:a.x.nombre,d:a.x.lab,u:a.usd,tr:a.tcR,tc:a.tcC,dif:r2(a.dif)})));
    }
    const rows=[];X.P.forEach(p=>p.lines.forEach(l=>rows.push({e:p.e,id:p.id,t:TT[p.t],f:p.fecha,con:p.con,cta:l.cta||'SIN CUENTA',nom:l.nom,c:l.c||null,a:l.a||null,ref:p.ref||''})));
    add('Pólizas',[['e','Empresa',9],['id','Póliza',20],['t','Tipo',10],['f','Fecha',12],['con','Concepto',60],['cta','Cuenta',16],['nom','Nombre de la cuenta',30],['c','Cargo MXN',15,M],['a','Abono MXN',15,M],['ref','Referencia',34]],rows);
    if(X.miss.length){const w=add('Avisos',[['m','Aviso',100]],[{m:'Faltan cuentas contables: '+X.miss.map(k=>{const q=k.split('|');return EMPS[q[0]].name+': '+CTA_L[q[1]]}).join('; ')},{m:'Las líneas sin cuenta dicen «SIN CUENTA». Captura las cuentas en Finanzas › Contabilidad › Catálogos.'}]);w.getRow(2).font={bold:true,color:{argb:'FFB3261E'}}}
    if(X.miss.length)toast('Ojo: faltan '+X.miss.length+' cuentas contables; van como «SIN CUENTA»');
    await saveFile((kind==='cie'?'Cierre_':'Polizas_')+E+'_'+ym+'.xlsx',await wbBlob(wb));
  }catch(e){toast('No se pudo generar el archivo')}
}
document.addEventListener('change',e=>{
  const t=e.target;if(!t||!t.dataset)return;
  if(t.dataset.cym){statsF.cym=t.value;render();return}
  if(!t.dataset.ctb||!isAdmin())return;
  const q=t.dataset.ctb.split('|'),fk=q.pop(),key=q.join('|'),raw=String(t.value||'').trim();
  const isNum=q[0]==='tasa'||(q[0]==='reg'&&fk!=='nombre'),v=isNum?num(raw.replace(',','.')):(raw||null);
  if(isNum&&raw&&v==null){toast('Escribe un número');return}
  const lab=q[0]==='cta'?'Cuenta contable · '+EMPS[q[1]].name+' · '+CTA_L[q[2]]+' · '+(fk==='num'?'número':'nombre'):q[0]==='tasa'?((TASAS.find(x=>x[0]===q[2])||[])[1]||q[2])+' · '+EMPS[q[1]].name:q[0]==='reg'?'Régimen fiscal · '+((CTB.d[key]||{}).nombre||'nuevo')+' · '+fk:'Régimen del productor #'+pad(+q[1],3);
  if(ctbSet(key,fk,v,lab))render();
});


/* ---------- v8.4.1 · seguridad móvil: huella, gesto de regresar y cierre por inactividad ---------- */
/* ---------- v8.27 · Almacén: todas las cajas que no van en un thermo, de todos los viajes ----------
   Cada caja sigue siendo de su productor, de su empaque y de su viaje de origen; el almacén solo junta lo que no se embarcó.
   · Viaje que ya salió (manifiesto cerrado o registro completo): sus tarimas se fueron; lo que quedó en piso está en el almacén.
   · Viaje en proceso: lo que está en piso también cuenta en el almacén; lo que está en sus tarimas abiertas se muestra aparte.
   · Segundas sin empacar: los lotes por productor y entrega (incluye el remanente de las hojas 1.5 y lo que bajó a segunda).
   Los movimientos (a segunda, merma y ajuste) se guardan en el renglón de origen (almMov) y no se borran: se anulan. */
let ALM={e:'ALL',w:'',items:[],open:{}};
function canAlm(){return canManClose()&&!roRole}
function almSalio(m){return manClosed(m)||m.estado==='completo'}
function almTrips(){return visible().filter(o=>mainOf(o)===o)}
function almItems(f,w){
  const out=[],hoy=todayISO();
  almTrips().forEach(m=>{if(f&&f!=='ALL'&&m.emp!==f)return;
    /* v8.27.2: el almacén es semanal: lo que quedó en piso de una semana cerrada se vendió al cierre */
    if(wkClosed(wkOf(m)))return;
    /* v8.27.5: filtro por semana */
    if(w&&wkOf(m)!==w)return;
    const sal=almSalio(m),nt=((m.traz&&m.traz.tarimas)||[]).length;
    rmpPlace(m,rmpAvail(m,true)).forEach(x=>{const a=x.a,pal=x.pals.reduce((s,y)=>s+y.n,0);
      if(!(x.piso>0)&&!(pal>0&&!sal))return;
      const s=orders.find(y=>y.id===a.sid)||m,fe=s.fecha||m.fecha||'';
      out.push({id:a.id,m:m,sid:a.sid,pid:a.pid,q:a.q,tipo:a.tipo0,ck:a.ck0,key:a.key,nombre:a.nombre||a.key,codigo:a.codigo,kg0:a.kg0||KG_DEF,via:a.via||null,ori:a.ori||'',
        piso:x.piso,pal:sal?0:pal,sal:sal,nt:nt,fecha:fe,dias:fe?Math.max(0,dayDiff(fe,hoy)):null})})});
  return out;
}
function almLots(f,w){return seg2Groups().map(g=>Object.assign({},g,{lots:g.lots.filter(l=>l.av>0&&(!f||f==='ALL'||!l.emp||l.emp===f)&&(!w||(l.wk||(l.fecha?wkOfDate(l.fecha):''))===w))})).filter(g=>g.lots.length).map(g=>Object.assign(g,{av:g.lots.reduce((s,l)=>s+l.av,0)}))}
/* pedidos repetidos: misma empresa, P.O. y fecha, con los mismos productores y las mismas cajas de campo y segundas */
function almDups(){
  const sig=o=>(o.productores||[]).filter(p=>!p.sob&&!p.sob2&&!p.rmp&&!p.c23&&!p.segLot).map(p=>(p.codigo||p.nombre||'')+'@'+n0(p.k18)+'/'+n0(p.k24)+'/'+n0(p.seg)).sort().join(',');
  const G=new Map();almTrips().forEach(o=>{if(!o.po)return;const k=o.emp+'|'+o.po+'|'+o.fecha,sg=sig(o);if((o.productores||[]).length<3||!sg)return;const kk=k+'|'+sg;let a=G.get(kk);if(!a)G.set(kk,a=[]);a.push(o)});
  return [...G.values()].filter(a=>a.length>1);
}
function almMovAll(){
  const out=[];
  orders.filter(o=>!o.deleted).forEach(o=>(o.productores||[]).forEach(p=>almMovOf(p,true).forEach(z=>out.push(Object.assign({h:'o',hid:o.id,rid:p.id,cod:o.cod,emp:o.emp},z)))));
  entradas().forEach(e=>almMovOf(e,true).forEach(z=>out.push(Object.assign({h:'e',hid:e.id,rid:'',cod:'Entrada de fruta',emp:null},z))));
  return out.sort((a,b)=>(b.at||0)-(a.at||0));
}
const ALM_T={th:'Salió en el thermo',seg:'Pasó a segunda',merma:'Merma',aj:'Ajuste por conteo',nac:'Venta nacional',tor:'Venta Torreón',des:'Pasó a desecho'};
function almQL(q){return q==='1.5'?'1½':'1ª'}
function almView(){
  /* v8.27.5: semanas abiertas con algo en almacén (las cerradas ya se fueron a venta) */
  const f=ALM.e,wNow=wkOfDate(todayISO()),wAll=almItems(f),gAll=almLots(f),wS=new Set([wNow]);
  wAll.forEach(x=>{const k=wkOf(x.m);if(k)wS.add(k)});gAll.forEach(g=>g.lots.forEach(l=>{const k=l.wk||(l.fecha?wkOfDate(l.fecha):'');if(k)wS.add(k)}));
  const wks=[...wS].filter(k=>!wkClosed(k)).sort().reverse();if(ALM.w&&wks.indexOf(ALM.w)<0)ALM.w='';
  const w=ALM.w,I=w?wAll.filter(x=>wkOf(x.m)===w):wAll,G=w?almLots(f,w):gAll,D=almDups(),ed=canAlm()&&!ro;ALM.items=I;
  const oldW=wks.filter(k=>k<wNow);
  const kg=x=>x.piso*x.kg0,P1=I.filter(x=>x.q!=='1.5'),P15=I.filter(x=>x.q==='1.5');
  const sum=(L,fn)=>L.reduce((s,x)=>s+fn(x),0),segC=sum(G,g=>g.av),palAb=sum(I,x=>x.pal);
  const chips=`<div class="almf"><label class="fld" for="alm-e"><span>Empresa</span><select class="in sel" id="alm-e" data-almsel="e">${[['ALL','Ambas'],['VL','Vera Limes'],['EC','Citrilar']].map(([k,t])=>`<option value="${k}"${f===k?' selected':''}>${t}</option>`).join('')}</select></label><label class="fld" for="alm-w"><span>Semana</span><select class="in sel" id="alm-w" data-almsel="w"><option value=""${!w?' selected':''}>Semanas abiertas</option>${wks.map(k=>`<option value="${k}"${w===k?' selected':''}>${esc(wkLab(k,true)+' · '+wkSpan(k))}${k===wNow?' (actual)':''}</option>`).join('')}</select></label></div>`
    +(oldW.length&&!w?`<div class="warnbox"><strong>${oldW.map(k=>esc(wkLab(k,true))).join(', ')} ${oldW.length>1?'siguen abiertas':'sigue abierta'}</strong><p class="note">Lo de ${oldW.length>1?'esas semanas':'esa semana'} ya no pasa a viajes nuevos: dale destino aquí (venta nacional, Torreón, Juguera o desecho) o al cerrarla en Periodos, donde se elige el destino de lo que quede.</p></div>`:'');
  const dup=D.length?`<div class="warnbox" role="alert"><strong>Posible pedido repetido</strong>${D.map(a=>`<div>${a.map(o=>`<b class="mono">${esc(o.cod)}</b>`).join(' y ')} tienen la misma P.O. (${esc(a[0].po)}), la misma fecha y los mismos productores con las mismas cajas. Si uno está de más, sus cajas y sus segundas cuentan dos veces.</div>`).join('')}</div>`:'';
  const tiles=`<div class="ig almig"><div><span>Primera en almacén</span><b>${fmt(sum(P1,x=>x.piso))}</b><small>${fmt(sum(P1,kg),0)} kg</small></div><div><span>1½ empacada</span><b>${fmt(sum(P15,x=>x.piso))}</b><small>${fmt(sum(P15,kg),0)} kg</small></div><div><span>Segundas sin empacar</span><b>${fmt(segC)}</b><small>${fmt(segC*SEG_KG,0)} kg</small></div><div><span>En tarimas sin salir</span><b>${fmt(palAb)}</b><small>viajes en proceso</small></div></div>`;
  /* resumen por calidad, presentación y calibre */
  const R=new Map();I.forEach(x=>{if(!(x.piso>0))return;const k=x.q+'|'+x.tipo+'|'+x.ck;let r=R.get(k);if(!r)R.set(k,r={q:x.q,tipo:x.tipo,ck:x.ck,n:0,kg:0,v:new Set(),old:null});r.n+=x.piso;r.kg+=kg(x);r.v.add(x.m.cod);if(x.dias!=null)r.old=Math.max(r.old||0,x.dias)});
  const ord=(a,b)=>a.q.localeCompare(b.q)||String(a.tipo).localeCompare(String(b.tipo))||CAL.findIndex(c=>c.k===a.ck)-CAL.findIndex(c=>c.k===b.ck);
  const rs=[...R.values()].sort(ord);
  const res=rs.length?`<div class="ltw"><table class="ltab almtab"><thead><tr><th>Calidad · presentación · calibre</th><th class="num">Cajas</th><th class="num">Kilos</th><th class="num">Más vieja</th><th>Viajes</th></tr></thead><tbody>${rs.map(r=>`<tr><td><b>${almQL(r.q)}</b> ${esc(TIPO_L[r.tipo]||r.tipo)} ${esc(calLab(r.ck))}</td><td class="num">${fmt(r.n)}</td><td class="num">${fmt(r.kg,0)}</td><td class="num">${r.old!=null?fmt(r.old)+' d':'–'}</td><td><small>${esc([...r.v].join(', '))}</small></td></tr>`).join('')}</tbody><tfoot><tr><td><b>Total empacado</b></td><td class="num"><b>${fmt(sum(I,x=>x.piso))}</b></td><td class="num"><b>${fmt(sum(I,kg),0)}</b></td><td></td><td></td></tr></tfoot></table></div>`:'<p class="note">No hay cajas empacadas fuera de tarimas.</p>';
  /* por viaje de origen */
  const V=new Map();I.forEach((x,i)=>{if(!(x.piso>0))return;let v=V.get(x.m.id);if(!v)V.set(x.m.id,v={m:x.m,sal:x.sal,nt:x.nt,L:[],n:0});v.L.push(i);v.n+=x.piso});
  const vs=[...V.values()].sort((a,b)=>(a.m.fecha||'').localeCompare(b.m.fecha||'')||(a.m.cons||0)-(b.m.cons||0));
  const via=x=>x.via==='rmp'?' · reempaque'+(x.ori?' de '+esc(x.ori):''):x.via==='sob'?' · sobrante'+(x.ori?' de '+esc(x.ori):''):'';
  const trip=v=>{const m=v.m,d=m.fecha?Math.max(0,dayDiff(m.fecha,todayISO())):null,op=!!ALM.open[m.id];
    const warn=(v.sal&&!v.nt?`<p class="note almw"><b>Este viaje salió sin tarimas capturadas.</b> Todo su empaque aparece en piso. Si la fruta se fue en el thermo, regístralo con «Salió en el thermo»: sale del almacén y queda como embarcada en este viaje. No uses «Pasar a segunda»: eso deja la fruta otra vez en el almacén como segunda.</p>`:'')+(v.sal&&!v.nt&&ed?`<div class="pact"><button class="btn sm nextb" data-act="almth:${esc(m.id)}">Todo lo de este viaje salió en el thermo (${fmt(v.n)})</button></div>`:'');
    return `<details class="panel almv"${op?' open':''} data-almv="${esc(m.id)}"><summary><span><b class="mono">${esc(m.cod)}</b> <span class="chip${v.sal?' good':' warn'}">${v.sal?'Salió':'En proceso'}</span>${f==='ALL'?` <span class="chip info">${esc(empNm(m.emp))}</span>`:''}${v.sal&&!v.nt?' <span class="chip warn">Sin tarimas</span>':''}</span><small>${fmt(v.n)} cajas · ${fmtDate(m.fecha)}${d!=null?' · '+fmt(d)+' días':''}</small></summary>${warn}
${v.L.map(i=>{const x=I[i];return `<div class="kv almr"><span><b>${esc(x.nombre)}</b><small>${/^(VL|EC)-\d+$/.test(x.key)?esc(x.key)+' · ':''}${almQL(x.q)} ${esc(TIPO_L[x.tipo]||x.tipo)} ${esc(calLab(x.ck))}${via(x)} · ${fmt(kg(x),0)} kg</small></span><span class="almn"><b>${fmt(x.piso)}</b>${ed?`<button class="btn sm" data-act="almmv:c:${i}">Mover</button>`:''}</span></div>`}).join('')}</details>`};
  const trips=vs.length?vs.map(trip).join(''):'';
  /* v8.42: segundas sin empacar, por viaje de origen y productor, con sus destinos */
  const GT=segTripGroups(f,w),segC2=GT.reduce((s,t)=>s+t.av,0);
  const lotR=l=>{const d=l.fecha?Math.max(0,dayDiff(l.fecha,todayISO())):null;return `<div class="kv almr"><span><b>${esc(diaTxt(l.fecha))}${l.cera?' <span class="chip cera">Con cera</span>':''}${l.rem?' <span class="chip info">Remanente 1.5</span>':''}${l.alm?' <span class="chip">Bajó en almacén</span>':''}${l.rc?' <span class="chip">Desecho reclasificado</span>':''}</b><small>${esc(l.de)}${d!=null?' · '+fmt(d)+' días':''}${l.mer?' · merma '+fmt(l.mer):''}${l.nac?' · nacional '+fmt(l.nac):''}${l.tor?' · Torreón '+fmt(l.tor):''}${l.jug?' · Juguera '+fmt(l.jug):''}${l.des?' · a desecho '+fmt(l.des):''}</small></span><span class="almn"><b${d!=null&&d>7?' class="old"':''}>${fmt(l.av)}</b>${ed?`<button class="btn sm" data-act="almmv:l:${esc(l.id)}">Merma</button>`:''}</span></div>`};
  const segT=GT.length?GT.map(t=>`<details class="panel almv almg"${ALM.open['s:'+t.key]?' open':''} data-almv="s:${esc(t.key)}"><summary><span><b class="mono">${esc(t.cod)}</b>${t.emp&&f==='ALL'?` <span class="chip info">${esc(empNm(t.emp))}</span>`:''}${t.wk?` <span class="chip">${esc(wkLab(t.wk,true))}</span>`:''}</span><small>${fmt(t.av)} cajas · ${t.P.length} ${t.P.length===1?'productor':'productores'}</small></summary>${t.P.map(p=>`<div class="almgh"><strong>${esc(p.nombre)}</strong><small>${p.codigo?'Código '+pad(p.codigo,3)+' · ':''}${fmt(p.av)} cajas</small></div>${p.lots.map(lotR).join('')}`).join('')}</details>`).join(''):'<p class="note">No hay segundas sin empacar en almacén.</p>';
  const sdB=ed&&segC2?`<div class="pact sdbtns"><button class="btn sm" data-act="sdst:nac">Venta nacional</button><button class="btn sm" data-act="sdst:tor">Venta Torreón</button><button class="btn sm" data-act="sdst:jug">Enviar a Juguera</button><button class="btn sm" data-act="sdst:des">Pasar a desecho</button></div>`:'';
  /* v8.42: desecho (terceras) por viaje, con «Reclasificar a segunda» */
  const DT=desTrips(f,w),dsT=DT.T.map(t=>`<details class="panel almv"${ALM.open['d:'+t.m.id]?' open':''} data-almv="d:${esc(t.m.id)}"><summary><span><b class="mono">${esc(t.m.cod)}</b>${f==='ALL'?` <span class="chip info">${esc(empNm(t.m.emp))}</span>`:''}</span><small>${fmt(t.net)} cajas de desecho${t.vac?' · vaciadas '+fmt(t.vac):''}${t.rc?' · reclasificadas '+fmt(t.rc):''}</small></summary>${t.R.map(x=>`<div class="kv almr"><span><b>${esc(x.p.nombre||'Sin nombre')}</b><small>${x.s.variante==='1.5'?'Hoja 1.5 · ':''}desecho ${fmt(x.cap)}${x.rc?' · reclasificadas '+fmt(x.rc):''}</small></span><span class="almn"><b>${fmt(x.net)}</b></span></div>`).join('')}${desRcOf(t.m).concat(...sheetsOf(t.m).filter(s=>s!==t.m).map(s=>desRcOf(s).map(z=>Object.assign({sid:s.id},z)))).map(z=>{const hid=z.sid||t.m.id,k='rcan:o:'+hid+':'+z.id;return `<div class="kv almm"><span><b>Reclasificadas a segunda · ${fmt(n0(z.n))}</b><small>${esc(z.nombre||'')} · ${esc(z.by||'—')}, ${esc(fmtTs(z.at))}</small></span>${ed?`<button class="btn sm" data-act="${k}">${confirmKey===k?'Toca otra vez':'Anular'}</button>`:''}</div>`}).join('')}${ed&&t.net>t.vac?`<div class="pact"><button class="btn sm" data-act="desrc:${esc(t.m.id)}">Reclasificar a segunda</button></div>`:''}</details>`).join('');
  const dsE=DT.E.length?`<details class="panel almv"${ALM.open['d:E']?' open':''} data-almv="d:E"><summary><span><b>Recepción</b> <small>desecho al recibir</small></span><small>${fmt(DT.E.reduce((s,x)=>s+x.net,0))} cajas</small></summary>${DT.E.map(x=>`<div class="kv almr"><span><b>${esc(x.e.nombre||'Sin nombre')}</b><small>${esc(diaTxt(x.e.fecha))} · ${fmt(entDes(x.e),0)} kg${x.rc?' · reclasificadas '+fmt(x.rc):''}</small></span><span class="almn"><b>${fmt(x.net)}</b></span></div>${desRcOf(x.e).map(z=>{const k='rcan:e:'+x.e.id+':'+z.id;return `<div class="kv almm"><span><b>Reclasificadas a segunda · ${fmt(n0(z.n))}</b><small>${esc(z.by||'—')}, ${esc(fmtTs(z.at))}</small></span>${ed?`<button class="btn sm" data-act="${k}">${confirmKey===k?'Toca otra vez':'Anular'}</button>`:''}</div>`}).join('')}`).join('')}${ed&&DT.E.some(x=>x.net>0)?'<div class="pact"><button class="btn sm" data-act="desrc:E">Reclasificar a segunda</button></div>':''}</details>`:'';
  const desH=dsT||dsE?dsT+dsE:'<p class="note">Sin desecho en las semanas abiertas.</p>';
  const TF=perAdmin()?thFixList():[],tfH=TF.length?`<div class="warnbox" role="alert"><strong>${fmt(TF.reduce((s,x)=>s+n0(x.z.n),0))} cajas dadas de baja con motivo «thermo»</strong><div>${[...new Set(TF.map(x=>x.o.cod))].map(c=>`<b class="mono">${esc(c)}</b>`).join(', ')}: se registraron como ajuste o «a segunda», pero el motivo dice que salieron en el thermo. Así no cuentan como embarcadas y, si pasaron a segunda, se mandaron a Juguera.</div><div class="pact"><button class="btn sm primary" data-act="thfix">${confirmKey==='thfix'?'Toca otra vez para corregir':'Corregir a «Salió en el thermo»'}</button></div></div>`:'';
  const lot=l=>{const d=l.fecha?Math.max(0,dayDiff(l.fecha,todayISO())):null;return `<div class="kv almr"><span><b>${esc(diaTxt(l.fecha))}${l.cera?' <span class="chip cera">Con cera</span>':''}${l.rem?' <span class="chip info">Remanente 1.5</span>':''}${l.alm?' <span class="chip">Bajó en almacén</span>':''}</b><small>${esc(l.de)}${d!=null?' · '+fmt(d)+' días':''}${l.mer?' · merma '+fmt(l.mer):''}</small></span><span class="almn"><b${d!=null&&d>7?' class="old"':''}>${fmt(l.av)}</b>${ed?`<button class="btn sm" data-act="almmv:l:${esc(l.id)}">Mover</button>`:''}</span></div>`};
  const segs=G.length?G.map(g=>`<div class="panel almg"><div class="almgh"><strong>${esc(g.nombre)}</strong><small>${g.codigo?'Código '+pad(g.codigo,3)+' · ':''}${fmt(g.av)} cajas</small></div>${g.lots.map(lot).join('')}</div>`).join(''):'<p class="note">No hay segundas sin empacar en almacén.</p>';
  /* libro de movimientos */
  const M=almMovAll().filter(z=>(f==='ALL'||!z.emp||z.emp===f)&&(!w||!z.f||wkOfDate(z.f)===w)).slice(0,60);
  const mv=z=>{const k='alman:'+z.h+':'+z.hid+':'+(z.rid||'-')+':'+z.id;return `<div class="kv almm${z.anul?' anul':''}"><span><b>${esc(ALM_T[z.t]||z.t)} · ${fmt(n0(z.n))} ${z.lot?'cajas de segunda':(almQL(z.q)+' '+esc(TIPO_L[z.tipo]||z.tipo)+' '+esc(calLab(z.ck)))}</b><small>${esc(z.nombre||'')}${z.cod?' · '+esc(z.cod):''}${n0(z.kg)>0?' · '+fmt(n0(z.kg),1)+' kg':''}${z.t==='seg'&&!z.lot?' · '+fmt(almSegN(z))+' cajas de segunda':''} · «${esc(z.mot||'')}» · ${esc(z.by||'—')}, ${esc(fmtTs(z.at))}${z.anul?' · anulado por '+esc(z.anul.by||'—')+(z.anul.mot?' («'+esc(z.anul.mot)+'»)':''):''}</small></span>${ed&&!z.anul?`<button class="btn sm" data-act="${k}">${confirmKey===k?'Toca otra vez':'Anular'}</button>`:''}</div>`};
  const libro=M.length?M.map(mv).join(''):'<p class="note">Todavía no hay movimientos en el almacén.</p>';
  const gear=psgCan()?`<div class="pact"><button class="btn sm" data-act="psg" title="Precios de venta de segunda" aria-label="Precios de venta de segunda"><svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><circle cx="12" cy="12" r="3" fill="none" stroke="currentColor" stroke-width="2"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.8l.1.1a2 2 0 1 1-2.8 2.8l-.1-.1a1.7 1.7 0 0 0-1.8-.3 1.7 1.7 0 0 0-1 1.5V21a2 2 0 1 1-4 0v-.1a1.7 1.7 0 0 0-1.1-1.5 1.7 1.7 0 0 0-1.8.3l-.1.1a2 2 0 1 1-2.8-2.8l.1-.1a1.7 1.7 0 0 0 .3-1.8 1.7 1.7 0 0 0-1.5-1H3a2 2 0 1 1 0-4h.1a1.7 1.7 0 0 0 1.5-1.1 1.7 1.7 0 0 0-.3-1.8l-.1-.1a2 2 0 1 1 2.8-2.8l.1.1a1.7 1.7 0 0 0 1.8.3H9a1.7 1.7 0 0 0 1-1.5V3a2 2 0 1 1 4 0v.1a1.7 1.7 0 0 0 1 1.5 1.7 1.7 0 0 0 1.8-.3l.1-.1a2 2 0 1 1 2.8 2.8l-.1.1a1.7 1.7 0 0 0-.3 1.8V9a1.7 1.7 0 0 0 1.5 1H21a2 2 0 1 1 0 4h-.1a1.7 1.7 0 0 0-1.5 1z" fill="none" stroke="currentColor" stroke-width="1.6"/></svg> Precios de venta</button></div>`:'';
  return topbar('Almacén','menu')+`<main class="wrap almw0" data-nopf>${chips}${gear}${tfH}${dup}${tiles}
<p class="note">El almacén es semanal: aquí está lo que no va en un thermo de las semanas abiertas (lo que quedó en piso de los viajes que ya salieron, lo que está en piso de los viajes en proceso y las segundas sin empacar). Lo de una semana no pasa a la siguiente: al cerrarla se elige el destino de lo que quede (segundas a Juguera, venta nacional, Torreón o desecho; cajas empacadas a segunda o «salió en el thermo») y ya no aparece. Cada caja conserva su productor, su empaque y su viaje de origen. Lo que está en tarimas de viajes en proceso se cuenta aparte.</p>
<div class="sec">Por calidad, presentación y calibre</div>${res}
<div class="sec">Cajas empacadas por viaje de origen</div>${trips||'<p class="note">Sin cajas en piso.</p>'}
<div class="sec">Segundas sin empacar · por viaje y productor</div><p class="note">Cada salida se registra en la semana del viaje de origen y se cobra con el precio de esa semana. Para correrlas en una hoja 1.5, ábrelas desde la hoja 1.5 del viaje.</p>${sdB}${segT}
<div class="sec">Desecho (terceras) · por viaje y productor</div><p class="note">Lo que todavía sirve como segunda se reclasifica (solo con la semana abierta): sale del desecho y queda en segundas disponibles del mismo viaje y productor.</p>${desH}
<div class="sec">Movimientos del almacén</div><div class="panel">${libro}</div>
<p class="note">Los movimientos no se borran: al anular uno, las cajas regresan a donde estaban y el registro queda tachado. Cada movimiento también queda en el Registro de cambios.</p></main>`;
}
$app.addEventListener('change',e=>{const t=e.target;if(!t||!t.dataset||!t.dataset.almsel)return;ALM[t.dataset.almsel]=t.value;render()});
/* ---------- v8.42 · Almacén: destino de las segundas y del desecho, por viaje y productor ----------
   Las segundas disponibles se agrupan por viaje de origen y productor. Cada salida (venta nacional, Torreón, Juguera o desecho)
   se registra sobre su lote, en la semana del lote, y se cobra con el precio de esa semana (engrane «Precios de venta»).
   El desecho (terceras) de cada viaje se puede reclasificar a segunda mientras su semana siga abierta: las cajas salen del desecho
   y entran como segundas disponibles a nombre del mismo productor y viaje. */
const SDST={nac:{t:'Venta nacional',v:'Registrar venta nacional',d:'Segundas vendidas en el mercado nacional. Se cobran con el precio de venta nacional de la semana del lote.'},
  tor:{t:'Venta Torreón',v:'Registrar venta a Torreón',d:'Segundas vendidas a Torreón. Se cobran con el precio de Torreón de la semana del lote.'},
  jug:{t:'Enviar a Juguera',v:'Enviar a Juguera',d:'La Juguera paga por kilo. Si tienes el peso de la báscula escríbelo; si no, se calcula con cajas × kg por caja.'},
  des:{t:'Pasar a desecho',v:'Pasar a desecho',d:'Ya no sirven como segunda: pasan al desecho (terceras) del mismo viaje. No se cobran.'}};
function lotWk(l){return l.wk||(l.fecha?wkOfDate(l.fecha):'')}
function segTripGroups(f,w){
  const T=new Map();seg2Lots().forEach(l=>{if(!(l.av>0))return;if(f&&f!=='ALL'&&l.emp&&l.emp!==f)return;const lk=lotWk(l);if(w&&lk!==w)return;if(lk&&wkClosed(lk))return;
    const tk=(l.emp||'')+'|'+(l.cod||'Recepción');let t=T.get(tk);if(!t){t={key:tk,cod:l.cod||'Recepción',emp:l.emp||null,fecha:l.fEmp||l.fecha||'',wk:lk,av:0,P:new Map()};T.set(tk,t)}
    let p=t.P.get(l.key);if(!p){p={key:l.key,nombre:l.nombre,codigo:l.codigo,av:0,lots:[]};t.P.set(l.key,p)}p.lots.push(l);p.av+=l.av;t.av+=l.av;if(!t.fecha||(l.fEmp&&l.fEmp<t.fecha))t.fecha=l.fEmp||t.fecha});
  const out=[...T.values()].map(t=>Object.assign(t,{P:[...t.P.values()].sort((a,b)=>a.nombre.localeCompare(b.nombre))}));
  out.forEach(t=>t.P.forEach(p=>p.lots.sort((a,b)=>(a.fecha||'').localeCompare(b.fecha||'')||a.de.localeCompare(b.de))));
  return out.sort((a,b)=>a.cod==='Recepción'?1:b.cod==='Recepción'?-1:String(a.fecha).localeCompare(String(b.fecha))||String(a.cod).localeCompare(String(b.cod),'es',{numeric:true}));
}
function psgTxt(e,wk,t){const P=psgOf(e,wk);if(t==='jug')return P.jugKg!=null?money(P.jugKg,2)+' por kg':'sin precio';if(t==='des')return '';const v=P[t];return v!=null?money(v,2)+' por caja':'sin precio'}
function sdstOpen(t){
  if(!psgCan()||!SDST[t])return;const G=segTripGroups(ALM.e,ALM.w);if(!G.length){toast('No hay segundas disponibles');return}
  eviDraftClear();EVI_MENU='';sheet={kind:'sdst',t:t,q:{},kg:'',tk:'',mot:''};renderSheet();
}
function sdLot(l,q){return `<label class="s2r" for="sd-${esc(l.id)}"><span class="s2d"><b>${esc(diaTxt(l.fecha))}${l.cera?' <span class="chip cera">Con cera</span>':''}${l.rc?' <span class="chip">Reclasificada</span>':''}</b><small>${esc(l.de)}${l.wk?' · '+esc(wkLab(l.wk,true)):''}</small></span><span class="s2a"><b>${fmt(l.av)}</b><small>de ${fmt(l.tot)}</small></span><input class="in" id="sd-${esc(l.id)}" inputmode="numeric" autocomplete="off" data-sd="${esc(l.id)}" value="${q[l.id]?esc(q[l.id]):''}" placeholder="0" aria-label="Cajas de ${esc(l.nombre)} del ${esc(diaTxt(l.fecha))}"></label>`}
function sdTot(){let c=0;const q=(sheet&&sheet.q)||{};Object.keys(q).forEach(k=>c+=n0(q[k]));return 'Seleccionadas: '+fmt(c)+' cajas · '+fmt(c*SEG_KG)+' kg (estimado)'}
function sdstHtml(){
  const s=sheet,D=SDST[s.t],G=segTripGroups(ALM.e,ALM.w),q=s.q||{};
  const wks=[...new Set([].concat(...G.map(t=>t.P.map(p=>p.lots.map(l=>(l.emp||'VL')+'|'+lotWk(l))))).flat())].filter(x=>!/\|$/.test(x));
  const pr=s.t==='des'?'':`<p class="note">Precio: ${wks.map(x=>{const a=x.split('|');return esc(empNm(a[0])+' '+wkLab(a[1],true)+': '+psgTxt(a[0],a[1],s.t))}).join(' · ')||'—'}. Se cambia con el engrane «Precios de venta».</p>`;
  return `<h3>${esc(D.t)}</h3><p class="note">${esc(D.d)} Cada caja se registra en la semana del viaje donde salió.</p>${pr}
<div class="srow2"><button class="btn sm" data-act="sdall">Seleccionar todo</button><button class="btn sm" data-act="sdnone">Limpiar</button></div>
<div class="s2list">${G.map((t,i)=>`<div class="s2g"><div class="s2h"><div><strong class="mono">${esc(t.cod)}</strong><small>${t.emp?esc(empNm(t.emp))+' · ':''}${t.wk?esc(wkLab(t.wk,true))+' · ':''}${fmt(t.av)} cajas</small></div><button class="btn sm" data-act="sdp:${i}">Todo el viaje</button></div>${t.P.map(p=>`<div class="sdp"><b>${esc(p.nombre)}</b><small>${p.codigo?' · '+pad(p.codigo,3):''} · ${fmt(p.av)} cajas</small></div>${p.lots.map(l=>sdLot(l,q)).join('')}`).join('')}</div>`).join('')}</div>
<p class="s2tot" id="sdtot">${esc(sdTot())}</p>
${s.t==='jug'?`<label class="fld" for="sd-kg"><span>Kilos de báscula del envío (opcional)</span><input class="in" id="sd-kg" inputmode="decimal" autocomplete="off" data-sdf="kg" value="${esc(s.kg)}"></label>`:''}
${eviBox('sal','draft',{t:'Evidencia de la salida',sub:s.t==='des'?'foto de la fruta y ticket de la pesada':'foto de la fruta y ticket de la venta'})}
${s.t!=='des'?`<label class="fld" for="sd-tk"><span>Ticket o nota de venta (opcional)</span><input class="in txt" id="sd-tk" autocomplete="off" data-sdf="tk" value="${esc(s.tk)}" placeholder="Folio del ticket"></label>`:`<label class="fld" for="sd-mot"><span>Motivo (opcional)</span><input class="in txt" id="sd-mot" autocomplete="off" data-sdf="mot" value="${esc(s.mot)}" placeholder="Ej.: ya no dan para segunda"></label>`}
<div class="srow2"><button class="btn" data-act="closesheet">Cancelar</button><button class="btn primary" data-act="sdok">${esc(D.v)}</button></div>`;
}
function sdstOk(){
  const s=sheet;if(!s||s.kind!=='sdst'||!psgCan())return;const L=seg2Lots(),q=s.q||{},by=whoName(),at=Date.now(),f=todayISO(),D=SDST[s.t];
  const sel=[];let over=false,cl=false;
  Object.keys(q).forEach(id=>{const l=L.get(id);let k=Math.round(n0(q[id]));if(!l||k<=0)return;const wk=lotWk(l)||wkOfDate(f);if(wkClosed(wk)){cl=true;return}if(k>l.av){k=l.av;over=true}if(k>0)sel.push({l:l,k:k,wk:wk})});
  if(!sel.length){toast(cl?'Esa semana ya está cerrada':'Escribe cuántas cajas, o toca «Seleccionar todo»');return}
  const tot=sel.reduce((a,x)=>a+x.k,0),kgT=num(s.kg),tk=String(s.tk||'').trim(),mot=String(s.mot||'').trim(),tO=new Set(),tE=new Set(),g=uid(); /* v8.43: g liga los movimientos de esta salida con sus fotos */
  sel.forEach(x=>{const l=x.l,h=jugHost(l);if(!h)return;const kg=kgT!=null&&kgT>0?Math.round(kgT*x.k/tot*100)/100:undefined;
    if(s.t==='jug'){h.x.jugEnv=Object.assign({},h.x.jugEnv||{});h.x.jugEnv[uid()]={lot:l.id,n:x.k,wk:x.wk,f:f,by:by,at:at,nombre:l.nombre,codigo:l.codigo||null,cera:l.cera?true:undefined,kg:kg,tk:tk||undefined,g:g}}
    else{h.x.almMov=Object.assign({},h.x.almMov||{});h.x.almMov[uid()]={t:s.t,lot:l.id,n:x.k,kg:Math.round(x.k*SEG_KG*100)/100,wk:x.wk,nombre:l.nombre,codigo:l.codigo||null,mot:mot||D.t,tk:tk||undefined,f:f,by:by,at:at,deCod:l.cod||'',g:g}}
    if(h.o)tO.add(h.o);else tE.add(h.e)});
  tO.forEach(touch);tE.forEach(touchE);
  logAdd({k:'note',where:'Almacén',ctx:{t:'w',id:sel[0].wk,cod:wkLab(sel[0].wk)},lab:D.t+' · segundas',o:fmt(tot)+' cajas ('+sel.length+(sel.length===1?' lote':' lotes')+')',n:(kgT?fmt(kgT,1)+' kg · ':'')+(tk?'ticket '+tk:mot||'')});
  const nF=EVI_DRAFT.size;if(nF){const wkM=sel[0].wk,cods=[...new Set(sel.map(x=>x.l.cod||'Recepción'))],prods=[...new Set(sel.map(x=>x.l.nombre||''))].filter(Boolean),emps=[...new Set(sel.map(x=>x.l.emp).filter(Boolean))];
    eviDraftCommit(g,{t:s.t,wk:wkM,emp:emps.length===1?emps[0]:'',emps:emps,n:tot,kg:kgT||0,tk:tk,cods:cods,prods:prods,lab:D.t+(tk?' '+tk:'')})}
  sheet=null;renderSheet();render();toast(D.t+': '+fmt(tot)+' cajas'+(nF?' · '+nF+(nF===1?' foto':' fotos'):'')+(over?'. Algunas cantidades se ajustaron a lo disponible':''));if(canAuto())doSync(true);
}
$sh.addEventListener('input',e=>{const el=e.target;if(!sheet||sheet.kind!=='sdst'||!el.dataset)return;
  if(el.dataset.sd){const d=el.value.replace(/\D+/g,'');if(d!==el.value)el.value=d;if(d)sheet.q[el.dataset.sd]=d;else delete sheet.q[el.dataset.sd];const t=document.getElementById('sdtot');if(t)t.textContent=sdTot()}
  else if(el.dataset.sdf){sheet[el.dataset.sdf]=el.value}});
function sdSel(act,arg){if(!sheet||sheet.kind!=='sdst')return;const G=segTripGroups(ALM.e,ALM.w),gs=act==='sdp'?[G[+arg]].filter(Boolean):G;
  gs.forEach(t=>t.P.forEach(p=>p.lots.forEach(l=>{if(act==='sdnone')delete sheet.q[l.id];else sheet.q[l.id]=String(l.av)})));renderSheet()}
/* desecho de un renglón: casilla Desecho + segundas que pasaron a desecho − lo reclasificado a segunda */
function desLotN(x){return almMovOf(x).filter(z=>z.lot&&z.t==='des').reduce((s,z)=>s+n0(z.n),0)}
function desRowRc(o,p){return desRcOf(o).filter(z=>z.pid===p.id).reduce((s,z)=>s+n0(z.n),0)}
function desRowCap(o,p){return (isSob(p)?0:n0(p.des))+desLotN(p)}
function desRowNet(o,p){return Math.max(0,desRowCap(o,p)-desRowRc(o,p))}
/* desecho al recibir en cajas de segunda (kilos ÷ kg por caja de segunda), más lo que pasó a desecho de sus lotes, menos lo reclasificado */
function entDesCj(e){return Math.floor(entDes(e)/(SEG_KG||18))+desLotN(e)}
function entDesNet(e){return Math.max(0,entDesCj(e)-desRcOf(e).reduce((s,z)=>s+n0(z.n),0))}
function desTrips(f,w){
  const out=[];almTrips().forEach(m=>{if(f&&f!=='ALL'&&m.emp!==f)return;const k=wkOf(m);if(!k||wkClosed(k)||(w&&k!==w))return;
    const R=[];sheetsOf(m).forEach(s=>(s.productores||[]).forEach(p=>{const c=desRowCap(s,p),rc=desRowRc(s,p);if(!(c>0)&&!(rc>0))return;R.push({s:s,p:p,cap:c,rc:rc,net:Math.max(0,c-rc)})}));
    if(!R.length)return;const vac=sheetsOf(m).reduce((a,s)=>a+desVacOf(s).filter(z=>!z.anul).reduce((b,z)=>b+n0(z.n),0),0);
    out.push({m:m,wk:k,R:R,net:R.reduce((a,x)=>a+x.net,0),rc:R.reduce((a,x)=>a+x.rc,0),vac:vac})});
  const E=entradas().filter(e=>{const k=wkOfDate(e.fecha);return k&&!wkClosed(k)&&(!w||k===w)&&(entDesCj(e)>0||desRcOf(e).length)}).map(e=>({e:e,cap:entDesCj(e),rc:entDesCj(e)-entDesNet(e),net:entDesNet(e)}));
  return {T:out.sort((a,b)=>String(a.m.fecha||'').localeCompare(String(b.m.fecha||''))||(a.m.cons||0)-(b.m.cons||0)),E:E};
}
function desRcOpen(src){if(!psgCan())return;sheet={kind:'desrc',src:src,q:{}};renderSheet()}
function desRcRows(){
  const D=desTrips('ALL','');if(sheet.src==='E')return D.E.filter(x=>x.net>0).map(x=>({id:'e:'+x.e.id,nombre:x.e.nombre||'Sin nombre',codigo:x.e.codigo,sub:'Desecho al recibir · '+diaTxt(x.e.fecha)+' · '+fmt(entDes(x.e),0)+' kg',max:x.net,e:x.e}));
  const t=D.T.find(x=>x.m.id===sheet.src);if(!t)return [];const pend=Math.max(0,t.net-t.vac);
  return t.R.filter(x=>x.net>0).map(x=>({id:'o:'+x.s.id+':'+x.p.id,nombre:x.p.nombre||'Sin nombre',codigo:x.p.codigo,sub:(x.s.variante==='1.5'?'Hoja 1.5 · ':'')+'desecho '+fmt(x.cap)+(x.rc?' · ya reclasificadas '+fmt(x.rc):''),max:Math.min(x.net,pend),s:x.s,p:x.p}));
}
function desRcHtml(){
  const R=desRcRows(),q=sheet.q||{},m=sheet.src==='E'?null:orders.find(x=>x.id===sheet.src);
  return `<h3>Reclasificar desecho a segunda${m?' · '+esc(m.cod):' · Recepción'}</h3><p class="note">Las cajas que escribas salen del desecho (terceras) y quedan como segundas disponibles del mismo productor${m?' y viaje':''}. Solo mientras la semana siga abierta. Después eliges su destino: hoja 1.5, venta nacional, Torreón o Juguera.</p>
<div class="panel">${R.length?R.map(r=>`<label class="s2r" for="rc-${esc(r.id)}"><span class="s2d"><b>${esc(r.nombre)}</b><small>${r.codigo?pad(r.codigo,3)+' · ':''}${esc(r.sub)}</small></span><span class="s2a"><b>${fmt(r.max)}</b><small>se pueden</small></span><input class="in" id="rc-${esc(r.id)}" inputmode="numeric" autocomplete="off" data-rc="${esc(r.id)}" value="${q[r.id]?esc(q[r.id]):''}" placeholder="0"></label>`).join(''):'<p class="note">No hay desecho por reclasificar (o ya se vació).</p>'}</div>
<div class="srow2"><button class="btn" data-act="closesheet">Cancelar</button><button class="btn primary" data-act="rcok"${R.length?'':' disabled'}>Reclasificar a segunda</button></div>`;
}
function desRcOk(){
  const s=sheet;if(!s||s.kind!=='desrc'||!psgCan())return;const R=desRcRows(),q=s.q||{},by=whoName(),at=Date.now();let tot=0;const tO=new Set(),tE=new Set();
  R.forEach(r=>{const k=Math.min(r.max,Math.round(n0(q[r.id])));if(!(k>0))return;
    if(r.e){if(wkClosed(wkOfDate(r.e.fecha)))return;r.e.desRc=Object.assign({},r.e.desRc||{});r.e.desRc[uid()]={n:k,wk:wkOfDate(r.e.fecha),at:at,by:by};tE.add(r.e)}
    else{if(wkClosed(wkOf(r.s)))return;r.s.desRc=Object.assign({},r.s.desRc||{});r.s.desRc[uid()]={pid:r.p.id,n:k,wk:wkOf(r.s),at:at,by:by,nombre:r.p.nombre||'',codigo:r.p.codigo||null};tO.add(r.s)}
    tot+=k});
  if(!tot){toast('Escribe cuántas cajas se reclasifican');return}
  tO.forEach(touch);tE.forEach(touchE);
  const m=s.src==='E'?null:orders.find(x=>x.id===s.src);
  logAdd({k:'note',where:'Almacén',ctx:m?ctxOf(m):{t:'w',id:curWk(),cod:'Recepción'},lab:'Desecho reclasificado a segunda'+(m?' · '+m.cod:' · Recepción'),o:fmt(tot)+' cajas de desecho',n:'pasan a segundas disponibles'});
  sheet=null;renderSheet();render();toast(fmt(tot)+' cajas de desecho pasaron a segunda');if(canAuto())doSync(true);
}
/* anular una reclasificación: solo si de esas segundas no se ha usado nada */
function desRcAnular(h,hid,id){
  if(!psgCan())return;const host=h==='e'?INV.entradas.find(x=>x.id===hid):orders.find(x=>x.id===hid),z=host&&host.desRc&&host.desRc[id];if(!z||z.anul)return;
  if(wkClosed(z.wk)){toast(wkLab(z.wk)+' está cerrada');return}
  const lid=h==='e'?'q.'+hid+'.'+id:'r.'+hid+'.'+z.pid+'.'+id,l=seg2Lots().get(lid);if(l&&l.usado>0){toast('De esas segundas ya se usaron '+fmt(l.usado)+'. Primero regresa eso');return}
  const k='rcan:'+h+':'+hid+':'+id;if(confirmKey!==k){armConfirm(k);render();return}confirmKey=null;
  host.desRc=Object.assign({},host.desRc);host.desRc[id]=Object.assign({},z,{anul:{by:whoName(),at:Date.now()}});if(h==='e')touchE(host);else touch(host);
  logAdd({k:'note',where:'Almacén',ctx:h==='e'?{t:'e',id:hid,cod:host.nombre||''}:ctxOf(host),lab:'Reclasificación anulada',o:fmt(n0(z.n))+' cajas',n:'regresan a desecho'});render();toast(fmt(n0(z.n))+' cajas regresan a desecho');
}
$sh.addEventListener('input',e=>{const el=e.target;if(!sheet||sheet.kind!=='desrc'||!el.dataset||!el.dataset.rc)return;const d=el.value.replace(/\D+/g,'');if(d!==el.value)el.value=d;if(d)sheet.q[el.dataset.rc]=d;else delete sheet.q[el.dataset.rc]});
/* engrane · precios de venta de segunda por empresa y semana */
function psgOpen(){if(!psgCan())return;const e=ALM.e&&ALM.e!=='ALL'?ALM.e:'VL',wk=ALM.w||curWk();const P=psgOf(e,wk);sheet={kind:'psg',e:e,wk:wk,v:{nac:P.own.nac?String(P.nac):'',tor:P.own.tor?String(P.tor):'',jugKg:P.own.jugKg?String(P.jugKg):''}};renderSheet()}
function psgWks(){const s=new Set(weekKeys(true).filter(k=>!wkClosed(k)));s.add(curWk());return [...s].sort().reverse()}
function psgHtml(){
  const s=sheet,P=psgOf(s.e,s.wk),F=parsDe(s.e,s.wk),cl=wkClosed(s.wk),fb={nac:num(F.seg),tor:num(F.tor),jugKg:num(F.jug)!=null?Math.round(num(F.jug)/jugKgDe(F)*10000)/10000:null};
  const inp=(k,l,u)=>`<label class="fld" for="psg-${k}"><span>${l}</span><input class="in" id="psg-${k}" inputmode="decimal" autocomplete="off" data-psg="${k}" value="${esc(s.v[k])}" placeholder="${fb[k]!=null?esc(String(fb[k])):'sin precio'}"${cl?' readonly':''}><small class="note">${u}${fb[k]!=null?' · sin capturar usa '+money(fb[k],2)+' de Precios y costos':''}</small></label>`;
  return `<h3>Precios de venta de segunda</h3><p class="note">Lo que pagan por la segunda en cada semana. Con ellos se calcula la venta en Finanzas, en Por cobrar y en el informe de segundas. Los captura el responsable del área; quién y cuándo queda registrado.</p>
<div class="grid2"><label class="fld" for="psg-e"><span>Empresa</span><select class="in sel" id="psg-e" data-psgsel="e">${Object.keys(EMPS).map(k=>`<option value="${k}"${s.e===k?' selected':''}>${esc(EMPS[k].name)}</option>`).join('')}</select></label>
<label class="fld" for="psg-w"><span>Semana</span><select class="in sel" id="psg-w" data-psgsel="wk">${[...new Set(psgWks().concat([s.wk]))].sort().reverse().map(k=>`<option value="${k}"${s.wk===k?' selected':''}>${esc(wkLab(k,true)+' · '+wkSpan(k))}${wkClosed(k)?' (cerrada)':''}</option>`).join('')}</select></label></div>
${cl?'<p class="note"><b>Semana cerrada:</b> sus precios quedaron fijos.</p>':''}
<div class="grid2">${inp('nac','Venta nacional · MXN por caja','Caja de segunda de '+fmt(SEG_KG)+' kg')}${inp('tor','Torreón · MXN por caja','Caja de segunda')}${inp('jugKg','Juguera · MXN por kilo','La Juguera pesa y paga por kilo')}</div>
${P.at?`<p class="note">Último cambio: ${esc(P.by||'—')} · ${esc(fmtTs(P.at))}</p>`:''}
<div class="srow2"><button class="btn" data-act="closesheet">Cancelar</button><button class="btn primary" data-act="psgok"${cl?' disabled':''}>Guardar</button></div>`;
}
function psgOk(){
  const s=sheet;if(!s||s.kind!=='psg'||!psgCan())return;if(wkClosed(s.wk)){toast(wkLab(s.wk)+' está cerrada');return}
  const v={};let bad=false;['nac','tor','jugKg'].forEach(k=>{const t=String(s.v[k]||'').trim();if(t===''){v[k]=null;return}const n=num(t);if(n==null||n<0){bad=true;return}v[k]=n});
  if(bad){toast('Revisa los precios: solo números');return}
  const key=s.e+'|'+s.wk,old=PSG.m[key]||{},x={nac:v.nac,tor:v.tor,jugKg:v.jugKg,by:whoName(),at:Date.now()};
  const txt=z=>['nac','tor','jugKg'].map(k=>({nac:'nacional',tor:'Torreón',jugKg:'Juguera/kg'}[k])+' '+(z[k]!=null&&z[k]!==''?money(+z[k],2):'—')).join(' · ');
  PSG.m[key]=x;savePsg(true);
  logAdd({k:'param',where:'Precios de segunda',ctx:{t:'p',id:key,cod:EMPS[s.e].name+' · '+wkLab(s.wk)},path:'psg.'+key,lab:'Precios de venta de segunda',o:txt(old),n:txt(x)});
  sheet=null;renderSheet();render();toast('Precios guardados para '+EMPS[s.e].name+' · '+wkLab(s.wk,true));if(canAuto())doSync(true);
}
$sh.addEventListener('input',e=>{const el=e.target;if(sheet&&sheet.kind==='psg'&&el.dataset&&el.dataset.psg)sheet.v[el.dataset.psg]=el.value});
$sh.addEventListener('change',e=>{const el=e.target;if(!sheet||sheet.kind!=='psg'||!el.dataset||!el.dataset.psgsel)return;sheet[el.dataset.psgsel]=el.value;const P=psgOf(sheet.e,sheet.wk);sheet.v={nac:P.own.nac?String(P.nac):'',tor:P.own.tor?String(P.tor):'',jugKg:P.own.jugKg?String(P.jugKg):''};renderSheet()});
/* v8.42 · EC-2026-185: bajas registradas como ajuste o «a segunda» cuyo motivo dice que salieron en el thermo */
function thFixList(){const out=[];orders.filter(o=>!o.deleted).forEach(o=>(o.productores||[]).forEach(p=>almMovOf(p).forEach(z=>{if(z.lot||(z.t!=='aj'&&z.t!=='seg')||!/thermo/i.test(z.mot||''))return;out.push({o:o,p:p,z:z})})));return out}
function thFixGo(){
  if(!perAdmin()){toast('Solo la administración corrige esto');return}const L=thFixList();if(!L.length)return;
  const k='thfix';if(confirmKey!==k){armConfirm(k);render();return}confirmKey=null;
  const by=whoName(),at=Date.now(),T=new Set();let n=0,pj=0;
  L.forEach(x=>{const z=x.z,id=z.id;if(z.t==='seg'){const lid='a.'+x.o.id+'.'+x.p.id+'.'+id;
      Object.keys(PER.list).forEach(k2=>{const P=PER.list[k2];if(!P||!P.jug||!P.jug.lots)return;const b=P.jug.lots.filter(y=>y.lot===lid);if(!b.length)return;const c=b.reduce((a,y)=>a+n0(y.n),0);P.jug.lots=P.jug.lots.filter(y=>y.lot!==lid);P.jug.cajas=Math.max(0,n0(P.jug.cajas)-c);P.ts=at;pj+=c})}
    const m=Object.assign({},x.p.almMov[id]);delete m.id;x.p.almMov=Object.assign({},x.p.almMov);x.p.almMov[id]=Object.assign(m,{t:'th',t0:z.t,fix:{by:by,at:at}});n+=n0(z.n);T.add(x.o)});
  T.forEach(touch);if(pj)savePer(true);
  logAdd({k:'note',where:'Almacén',ctx:{t:'w',id:curWk(),cod:'Almacén'},lab:'Corrección: bajas que salieron en el thermo',o:fmt(n)+' cajas como ajuste o a segunda'+(pj?' ('+fmt(pj)+' de segunda que se habían mandado a Juguera)':''),n:'Salió en el thermo'});
  render();toast(fmt(n)+' cajas corregidas a «Salió en el thermo»');
}
/* ventana para mover cajas: c = cajas empacadas (índice en ALM.items), l = lote de segunda */
function almMvOpen(src,arg){
  if(!canAlm()||ro)return;
  /* el almacén no depende de la semana: se mueve aunque la semana del viaje de origen esté cerrada (no cambia pagos ni precios) */
  if(src==='c'){const x=ALM.items[+arg];if(!x)return;
    /* v8.27.1: de un viaje que ya salió, lo primero que se ofrece es «Salió en el thermo» */
    sheet={kind:'almmv',src:'c',id:x.id,x:x,t:x.sal?'th':'seg',n:String(x.piso),kg:'',mot:x.sal?'Salió en el thermo de '+x.m.cod:''}}
  else{const l=seg2Lots().get(arg);if(!l||!(l.av>0))return;sheet={kind:'almmv',src:'l',id:l.id,l:l,t:'merma',n:String(l.av),kg:'',mot:''}}
  renderSheet();
}
function almMvHtml(){
  const s=sheet,c=s.src==='c',x=s.x,l=s.l,max=c?x.piso:l.av,n=Math.max(0,Math.min(max,Math.floor(n0(s.n)))),kgA=c?n*x.kg0:n*SEG_KG;
  const T=c?(x.sal?[['th','Salió en el thermo','Se embarcó en el thermo de '+esc(x.m.cod)+' aunque no se capturó en tarimas. Sale del almacén y cuenta como embarcada en su viaje (no es segunda).']]:[]).concat([['seg','Pasar a segunda','Pierde la calidad de exportación: queda como segunda en almacén, a nombre de su productor, para hoja 1.5 o Juguera.'],['merma','Merma','Se echó a perder. Pésala en la báscula.'],['aj','Ajuste por conteo','No está en el almacén: se capturó de más o el conteo físico da menos.']])
    :[['merma','Merma','Se echó a perder. Pésala en la báscula.'],['aj','Ajuste por conteo','No está en el almacén o el conteo físico da menos.']];
  const head=c?`<b>${esc(x.nombre)}</b> · ${almQL(x.q)} ${esc(TIPO_L[x.tipo]||x.tipo)} ${esc(calLab(x.ck))} · viaje ${esc(x.m.cod)} · ${fmt(x.piso)} en piso`:`<b>${esc(l.nombre)}</b> · ${esc(l.de)} · ${fmt(l.av)} cajas de segunda`;
  const eq=c&&s.t==='seg'?`<p class="note" id="almeq">Son ${fmt(kgA,0)} kg: quedan como ${fmt(n>0?almSegN({n:n,kg:kgA}):0)} cajas de segunda (${fmt(SEG_KG)} kg por caja).</p>`:'<p class="note" id="almeq"></p>';
  return `<h3>Mover del almacén</h3><p class="note" style="margin-bottom:8px">${head}</p>
<div class="pnopts" role="radiogroup" aria-label="Movimiento">${T.map(([k,t,d])=>`<label class="pnopt"><input type="radio" name="almt" value="${k}" data-almt="1"${s.t===k?' checked':''}><span><b>${t}</b><small>${d}</small></span></label>`).join('')}</div>
<div class="grid2"><label class="fld" for="alm-n"><span>Cajas (máximo ${fmt(max)})</span><input class="in" id="alm-n" inputmode="numeric" autocomplete="off" data-almf="n" value="${esc(s.n)}"></label>${s.t==='merma'?`<label class="fld" for="alm-kg"><span>Kilos en báscula</span><input class="in" id="alm-kg" inputmode="decimal" autocomplete="off" data-almf="kg" value="${esc(s.kg)}"></label>`:''}</div>${eq}
<label class="fld" for="alm-mot"><span>Justificación (obligatoria)</span><input class="in txt" id="alm-mot" type="text" autocomplete="off" data-almf="mot" value="${esc(s.mot)}" placeholder="${s.t==='th'?'Ej.: salió en el thermo del viaje':s.t==='seg'?'Ej.: se manchó en piso, ya no da para exportación':s.t==='merma'?'Ej.: podrida, separada y pesada':'Ej.: se capturó de más'}"></label>
<p class="note">Quién y cuándo quedan registrados. Si te equivocas, en la lista de movimientos está «Anular».</p>
<div class="srow2"><button class="btn" data-act="closesheet">Cancelar</button><button class="btn primary" data-act="almok">Registrar</button></div>`;
}
/* v8.27.1: todo lo que quedó en piso de un viaje que ya salió se fue en su thermo (una sola justificación) */
function almThOpen(oid){if(!canAlm()||ro)return;const m=orders.find(x=>x.id===oid);if(!m)return;sheet={kind:'almth',oid:oid,mot:'Salió en el thermo de '+m.cod};renderSheet()}
function almThHtml(){
  const m=orders.find(x=>x.id===sheet.oid);if(!m)return '';const I=almItems('ALL').filter(x=>x.m===m&&x.piso>0),n=I.reduce((a,x)=>a+x.piso,0);
  return `<h3>Salió en el thermo · ${esc(m.cod)}</h3><p class="note" style="margin-bottom:8px">Estas ${fmt(n)} cajas salen del almacén y quedan como embarcadas en ${esc(m.cod)}, sin tarima capturada. Cada productor y calibre queda como un movimiento que se puede anular.</p>
<div class="panel">${I.map(x=>`<div class="kv"><span><b>${esc(x.nombre)}</b><small>${almQL(x.q)} ${esc(TIPO_L[x.tipo]||x.tipo)} ${esc(calLab(x.ck))}</small></span><b>${fmt(x.piso)}</b></div>`).join('')}</div>
<label class="fld" for="alm-thm"><span>Justificación (obligatoria)</span><input class="in txt" id="alm-thm" type="text" autocomplete="off" data-almth="mot" value="${esc(sheet.mot)}"></label>
<div class="srow2"><button class="btn" data-act="closesheet">Cancelar</button><button class="btn primary" data-act="almthok">Registrar ${fmt(n)} cajas</button></div>`;
}
function almThOk(){
  const s=sheet;if(!s||s.kind!=='almth'||!canAlm()||ro)return;const m=orders.find(x=>x.id===s.oid);if(!m)return;
  const mot=String(s.mot||'').trim();if(mot.length<4){toast('Escribe la justificación');return}
  const I=almItems('ALL').filter(x=>x.m===m&&x.piso>0);if(!I.length){sheet=null;renderSheet();render();return}
  const by=whoName(),at=Date.now(),f=todayISO();let n=0;const T=new Set();
  I.forEach(x=>{const S=orders.find(y=>y.id===x.sid),p=S&&(S.productores||[]).find(y=>y.id===x.pid);if(!p)return;
    p.almMov=Object.assign({},p.almMov||{});p.almMov[uid()]={t:'th',q:x.q,tipo:x.tipo,ck:x.ck,key:x.key,n:x.piso,kg:Math.round(x.piso*x.kg0*100)/100,kg0:x.kg0,nombre:x.nombre,codigo:x.codigo||null,pk:invKey(x.codigo,x.nombre),mot:mot,f:f,by:by,at:at,deCod:m.cod};
    n+=x.piso;T.add(S)});
  T.forEach(touch);
  logAdd({k:'note',ctx:ctxOf(m),where:'Almacén',lab:'Salió en el thermo · '+m.cod,o:fmt(n)+' cajas en piso',n:mot,motivo:mot});
  sheet=null;renderSheet();render();toast(fmt(n)+' cajas registradas como embarcadas en '+m.cod);
}
function almMvOk(){
  const s=sheet;if(!s||s.kind!=='almmv'||!canAlm()||ro)return;
  const mot=String(s.mot||'').trim();if(mot.length<4){toast('Escribe la justificación');return}
  /* v8.42: lo que salió en el thermo no es ajuste ni segunda */
  if((s.t==='aj'||s.t==='seg')&&/thermo/i.test(mot)){toast(s.src==='c'&&s.x&&s.x.sal?'Si salió en el thermo, elige «Salió en el thermo»':'Si salió en el thermo no es ajuste ni segunda: regístralo en el viaje que salió con «Salió en el thermo»');return}
  const by=whoName(),at=Date.now(),f=todayISO(),id=uid();
  if(s.src==='c'){
    const x=almItems('ALL').find(y=>y.id===s.id);if(!x){toast('Esas cajas ya no están en piso');sheet=null;renderSheet();render();return}
    const n=Math.floor(n0(s.n));if(!(n>0)){toast('Escribe cuántas cajas');return}if(n>x.piso){toast('Solo hay '+fmt(x.piso)+' en piso');return}
    const kg=s.t==='merma'?n0(s.kg):Math.round(n*x.kg0*100)/100;if(s.t==='merma'&&!(kg>0)){toast('Escribe los kilos de la báscula');return}
    const S=orders.find(y=>y.id===x.sid),p=S&&(S.productores||[]).find(y=>y.id===x.pid);if(!p)return;
    p.almMov=Object.assign({},p.almMov||{});
    p.almMov[id]={t:s.t,q:x.q,tipo:x.tipo,ck:x.ck,key:x.key,n:n,kg:kg,kg0:x.kg0,nombre:x.nombre,codigo:x.codigo||null,pk:invKey(x.codigo,x.nombre),mot:mot,f:f,by:by,at:at,deCod:x.m.cod};
    touch(S);
    logAdd({k:'note',ctx:ctxOf(x.m),where:'Almacén',lab:(ALM_T[s.t]||s.t)+' · '+x.nombre+' · '+almQL(x.q)+' '+(TIPO_L[x.tipo]||x.tipo)+' '+calLab(x.ck),o:fmt(n)+' cajas en piso',n:(s.t==='seg'?fmt(almSegN(p.almMov[id]))+' cajas de segunda':fmt(kg,1)+' kg')+' · '+mot,motivo:mot});
    sheet=null;renderSheet();render();toast(s.t==='seg'?fmt(n)+' cajas pasaron a segunda':fmt(n)+' cajas registradas como '+(ALM_T[s.t]||s.t).toLowerCase());return;
  }
  const l=seg2Lots().get(s.id);if(!l){sheet=null;renderSheet();render();return}
  const n=Math.floor(n0(s.n));if(!(n>0)){toast('Escribe cuántas cajas');return}if(n>l.av){toast('Solo quedan '+fmt(l.av));return}
  const kg=s.t==='merma'?n0(s.kg):Math.round(n*SEG_KG*100)/100;if(s.t==='merma'&&!(kg>0)){toast('Escribe los kilos de la báscula');return}
  const h=jugHost(l);if(!h){toast('No se encontró de dónde salió ese lote');return}
  h.x.almMov=Object.assign({},h.x.almMov||{});
  h.x.almMov[id]={t:s.t,lot:l.id,n:n,kg:kg,nombre:l.nombre,codigo:l.codigo||null,mot:mot,f:f,by:by,at:at,deCod:l.cod||''};
  if(h.o)touch(h.o);else touchE(h.e);
  logAdd({k:'note',ctx:h.o?ctxOf(h.o):{t:'e',id:h.e.id,cod:h.e.nombre||''},where:'Almacén',lab:(ALM_T[s.t]||s.t)+' · segundas de '+l.nombre,o:fmt(n)+' cajas',n:fmt(kg,1)+' kg · '+mot,motivo:mot});
  sheet=null;renderSheet();render();toast(fmt(n)+' cajas de segunda registradas como '+(ALM_T[s.t]||s.t).toLowerCase());
}
function almAnular(h,hid,rid,mid){
  if(!canAlm()||ro)return;
  const k='alman:'+h+':'+hid+':'+rid+':'+mid;if(confirmKey!==k){armConfirm(k);render();return}confirmKey=null;
  let host=null,o=null,e=null;
  if(h==='o'){o=orders.find(x=>x.id===hid);host=o&&(o.productores||[]).find(p=>p.id===rid)}else{e=INV.entradas.find(x=>x.id===hid);host=e}
  const z=host&&host.almMov&&host.almMov[mid];if(!z||z.anul)return;
  if((z.cie&&wkClosed(z.cie))||(z.wk&&z.lot&&wkClosed(z.wk))){toast(wkLab(z.cie||z.wk)+' está cerrada; para corregirlo un administrador la reabre');return}
  if(z.t==='seg'&&!z.lot){const l=seg2Lots().get('a.'+hid+'.'+rid+'.'+mid);if(l&&l.usado>0){toast('De esas segundas ya se usaron '+fmt(l.usado)+' (hoja 1.5, Juguera o merma). Primero regresa eso');return}}
  host.almMov=Object.assign({},host.almMov);host.almMov[mid]=Object.assign({},z,{anul:{by:whoName(),at:Date.now()}});
  if(o)touch(o);else touchE(e);
  logAdd({k:'note',ctx:o?ctxOf(o):{t:'e',id:e.id,cod:e.nombre||''},where:'Almacén',lab:'Movimiento anulado · '+(ALM_T[z.t]||z.t)+' · '+(z.nombre||''),o:fmt(n0(z.n))+' cajas',n:'Anulado'});
  render();toast('Movimiento anulado: las cajas regresaron');
}
$sh.addEventListener('input',e=>{const t=e.target;if(!sheet||sheet.kind!=='almmv'||!t.dataset||!t.dataset.almf)return;const k=t.dataset.almf;
  if(k==='n'){t.value=t.value.replace(/\D+/g,'')}else if(k==='kg'){t.value=t.value.replace(/[^\d.]/g,'')}sheet[k]=t.value;
  if(k==='n'&&sheet.src==='c'&&sheet.t==='seg'){const x=sheet.x,n=Math.max(0,Math.min(x.piso,Math.floor(n0(t.value)))),kg=n*x.kg0,q=document.getElementById('almeq');if(q)q.textContent='Son '+fmt(kg,0)+' kg: quedan como '+fmt(n>0?almSegN({n:n,kg:kg}):0)+' cajas de segunda ('+fmt(SEG_KG)+' kg por caja).'}});
$sh.addEventListener('change',e=>{const t=e.target;if(!sheet||sheet.kind!=='almmv'||!t.dataset||!t.dataset.almt)return;sheet.t=t.value;if(sheet.t!=='th'&&/^Salió en el thermo de /.test(sheet.mot||''))sheet.mot='';else if(sheet.t==='th'&&!String(sheet.mot||'').trim())sheet.mot='Salió en el thermo de '+sheet.x.m.cod;renderSheet()});
$sh.addEventListener('input',e=>{const t=e.target;if(sheet&&sheet.kind==='almth'&&t.dataset&&t.dataset.almth)sheet.mot=t.value});
document.addEventListener('toggle',e=>{const t=e.target;if(t&&t.dataset&&t.dataset.almv)ALM.open[t.dataset.almv]=t.open},true);
const APP_VER='8.47.0';
const BIO_SRV='mx.registro.empaque',LS_BIO='empaque-huella',LS_BIONO='empaque-huella-no',LS_ULT='empaque-ultimo-uso';
const SEG_MIN=30;      /* minutos fuera de la app antes de cerrar la sesión */
const SEG_DBL=800;     /* milisegundos entre dos gestos de regresar para salir de la app */
let segSkew=0,segBackT=0,segBackW=SEG_DBL,segWebOff=false,segHideT=null,segAutoBio=false;
const segNow=()=>Date.now()+segSkew;
/* los plugins nativos solo existen dentro del APK; en el navegador la huella no se ofrece */
/* v8.37 · SEC-008: los ganchos de prueba (EMP_FAKE, EMP_SEG, EMP_TEST) solo existen en el prototipo sin base de datos
   o si config.js trae DEV:true. En producción no se puede simular la huella ni adelantar el reloj del cierre de sesión. */
function empDev(){try{return !cfgOK()||CFG.DEV===true}catch(e){return false}}
const empFake=()=>empDev()?window.EMP_FAKE:null;
function segPlug(n){
  if(empFake()&&empFake()[n])return empFake()[n];
  const C=window.Capacitor;
  if(C&&C.isNativePlatform&&C.isNativePlatform()&&C.Plugins&&C.Plugins[n])return C.Plugins[n];
  return null;
}
function segMobile(){
  if(empFake())return true;
  const C=window.Capacitor;if(C&&C.isNativePlatform&&C.isNativePlatform())return true;
  try{return matchMedia('(pointer:coarse)').matches&&/Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent)}catch(e){return false}
}

/* ----- huella ----- */
const FP_ICO='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3.5 10a8.5 8.5 0 0 1 17 0"/><path d="M5.5 13a6.5 6.5 0 0 1 13 0c0 3-.5 5.4-1.8 7.6"/><path d="M8.5 15c.3-1 .5-2.2.5-3.5a3 3 0 0 1 6 0c0 2.4-.5 4.6-1.5 6.5"/><path d="M12 11.5v3c0 2-.6 3.8-1.6 5.3"/></svg>';
function bioMeta(){try{return JSON.parse(localStorage.getItem(LS_BIO)||'null')}catch(e){return null}}
function bioMode(){return cfgOK()?'sb':'loc'}
function bioLinked(){const m=bioMeta();return !!(m&&m.mode===bioMode()&&segPlug('NativeBiometric'))}
async function bioAvail(){
  const B=segPlug('NativeBiometric');if(!B)return false;
  try{const r=await B.isAvailable();return !!(r&&r.isAvailable)}catch(e){return false}
}
function bioErr(e,def){
  const m=String((e&&(e.message||e.code))||'').toLowerCase();
  if(/cancel|user_cancel|negative|10$|13$/.test(m))return 'Cancelaste la verificación de la huella.';
  if(/lock|too many|7$|9$/.test(m))return 'Demasiados intentos con la huella. Espera un momento o usa tu contraseña.';
  return def;
}
function bioBtn(){return bioLinked()?`<button class="btn bio" style="width:100%;margin-top:8px" data-act="lgbio"${lg.busy?' disabled':''}>${FP_ICO}<span>Entrar con huella</span></button>`:''}
async function bioLink(user,pw){
  const B=segPlug('NativeBiometric');
  await B.verifyIdentity({reason:'Vincular tu huella',title:'Vincular huella',subtitle:APP_NAME,description:'Toca el sensor para confirmar que eres tú',maxAttempts:3,useFallback:false});
  await B.setCredentials({username:user,password:pw,server:BIO_SRV});
  try{localStorage.setItem(LS_BIO,JSON.stringify({u:user,mode:bioMode(),t:Date.now()}));localStorage.removeItem(LS_BIONO)}catch(e){}
}
async function bioUnlink(){
  const B=segPlug('NativeBiometric');
  try{if(B)await B.deleteCredentials({server:BIO_SRV})}catch(e){}
  try{localStorage.removeItem(LS_BIO)}catch(e){}
}
async function bioSync(user,pw){
  const m=bioMeta(),B=segPlug('NativeBiometric');
  if(!B||!m||m.mode!=='loc'||unorm(m.u)!==unorm(user))return;
  try{await B.setCredentials({username:m.u,password:pw,server:BIO_SRV})}catch(e){}
}
/* después de entrar con contraseña, ofrece vincular la huella (una vez por usuario) */
async function bioOffer(user,pw){
  try{
    if(!segPlug('NativeBiometric'))return;
    const m=bioMeta();
    if(m&&m.mode===bioMode()&&unorm(m.u)===unorm(user))return;
    if(localStorage.getItem(LS_BIONO)===unorm(user))return;
    if(!await bioAvail())return;
    if(!authUser||sheet)return;
    sheet={kind:'bio',u:user,p:pw,err:''};renderSheet();
  }catch(e){}
}
function bioHtml(){
  const S=sheet,need=!!S.needPw;
  return `<h3>Entrar con huella</h3><p class="note" style="margin-bottom:10px">${need?'Escribe tu contraseña una sola vez y confirma con tu huella. Después entrarás con solo tocar el sensor.':'Vincula tu huella para entrar sin escribir la contraseña. Los datos se guardan cifrados en este teléfono y tu contraseña sigue funcionando.'}</p>
${need?`<label class="fld" for="bio-p"><span>Contraseña</span>${PWI(`<input class="in txt" id="bio-p" type="password" autocomplete="current-password">`)}</label>`:''}
${S.err?`<p class="note" style="color:var(--crit);margin-bottom:8px" role="alert">${esc(S.err)}</p>`:''}
<div class="srow2"><button class="btn" data-act="biono">${need?'Cancelar':'Ahora no'}</button><button class="btn primary" data-act="bioyes"${S.busy?' disabled':''}>${S.busy?'Esperando la huella…':'Vincular huella'}</button></div>`;
}
function bioAcctHtml(){
  if(!segPlug('NativeBiometric')||!authUser)return '';
  const m=bioMeta(),linked=!!(m&&m.mode===bioMode()&&unorm(m.u)===unorm(authUser.user));
  return `<div class="sec">Huella digital</div><p class="note" style="margin-bottom:8px">${linked?'Tu huella está vinculada: puedes entrar sin escribir la contraseña.':'Vincula tu huella para entrar sin escribir la contraseña.'}</p><div class="srow2">${linked?'<button class="btn" data-act="biodel">Quitar huella</button>':'<button class="btn" data-act="bioopen">Vincular huella</button>'}</div>`;
}
function bioOpen(){if(!authUser)return;sheet={kind:'bio',u:authUser.user,p:'',needPw:true,err:''};renderSheet()}
async function bioDel(){await bioUnlink();if(sheet&&sheet.kind==='acct')renderSheet();toast('Huella quitada')}
function bioNo(){
  if(sheet&&sheet.kind==='bio'&&!sheet.needPw){try{localStorage.setItem(LS_BIONO,unorm(sheet.u))}catch(e){}}
  sheet=null;renderSheet();
}
async function bioCheckPw(user,pw){
  if(cfgOK()){
    try{await sb('/auth/v1/token?grant_type=password',{method:'POST',body:{email:user,password:pw},auth:false});return true}
    catch(e){if(e&&e.status>=400&&e.status<500)return false;throw e}
  }
  const x=USERS.find(y=>authUser&&y.id===authUser.id);
  return !!(x&&await pwMatch(x,pw));
}
async function bioYes(){
  const S=sheet;if(!S||S.kind!=='bio'||S.busy)return;
  if(S.needPw){
    const pw=gv('bio-p');
    if(!pw){S.err='Escribe tu contraseña.';renderSheet();return}
    S.busy=true;S.err='';renderSheet();
    let ok=false;
    try{ok=await bioCheckPw(S.u,pw)}catch(e){if(sheet===S){S.busy=false;S.err='No se pudo conectar. Revisa tu internet e inténtalo otra vez.';renderSheet()}return}
    if(sheet!==S)return;
    if(!ok){S.busy=false;S.err='La contraseña no es correcta.';renderSheet();return}
    S.p=pw;S.needPw=false;
  }
  S.busy=true;S.err='';renderSheet();
  try{await bioLink(S.u,S.p);if(sheet===S){sheet=null;renderSheet()}render();toast('Huella vinculada')}
  catch(e){if(sheet===S){S.busy=false;S.err=bioErr(e,'No se pudo vincular la huella.');renderSheet()}}
}
async function bioLogin(){
  const B=segPlug('NativeBiometric');if(!B||!bioLinked()||lg.busy||authUser)return;
  try{await B.verifyIdentity({reason:'Entrar a '+APP_NAME,title:'Entrar con huella',subtitle:APP_NAME,description:'Toca el sensor para entrar',maxAttempts:3,useFallback:false})}
  catch(e){lg.err=bioErr(e,'No se reconoció la huella. Puedes entrar con tu contraseña.');lg.msg='';render();return}
  let c=null;
  try{c=await B.getCredentials({server:BIO_SRV})}catch(e){c=null}
  if(!c||!c.username||!c.password){await bioUnlink();lg.err='La huella guardada ya no es válida. Entra con tu contraseña y vuelve a vincularla.';render();return}
  await doLogin({username:c.username,password:c.password,bio:true});
}

/* ----- gesto de regresar del teléfono ----- */
/* un gesto = una pantalla atrás; dos gestos rápidos = salir de la app (la sesión sigue abierta) */
function segParent(){
  if(sheet)return 'sheet';
  if(!authUser)return lg.tab==='reg'?'lgin':null;
  switch(view){
    case 'menu':return null;
    case 'order':return 'orders';
    case 'trazo':return 'traz';
    case 'docs':return docFrom==='trazo'?'trazo':docFrom==='dvt'?'dvt':'order';
    case 'dvt':return 'dvback';
    case 'log':return LG.rt?'logmenu':'menu';
    case 'conteo':case 'segcnt':return isTarima()||isSegC()?'menu':'supback';
    default:return 'menu';
  }
}
function segGoBack(){
  try{const a=document.activeElement;if(a&&a!==document.body&&a.blur)a.blur()}catch(e){}
  const p=segParent();
  if(p===null)return false;
  if(p==='sheet'){closeSheet();return true}
  if(p==='lgin'){lg.tab='in';lg.err='';lg.msg='';render();return true}
  if(view==='docs'){view=p;render();window.scrollTo(0,0);return true}
  /* de un catálogo de logística, al menú de Control Logístico (igual que la flecha de arriba) */
  if(p==='supback'){supBack();return true}
  if(p==='logmenu'){LG.rt=null;LG.q='';LG.edit=null;LG.err='';render();window.scrollTo(0,0);return true}
  goto(p);return true;
}
function segOnBack(){
  const now=Date.now();
  if(segBackT&&now-segBackT<=segBackW){segBackT=0;segExit();return}
  const moved=segGoBack();
  segBackT=now;segBackW=moved?SEG_DBL:2000;
  if(!moved)toast('Haz otro gesto rápido para salir');
}
function segExit(){
  segStamp();
  const A=segPlug('App');
  if(A&&A.exitApp){try{A.exitApp();return}catch(e){}}
  segWebOff=true;try{history.back()}catch(e){}
}

/* ----- cierre automático a los 30 min fuera de la app (móviles) ----- */
function segStamp(){try{localStorage.setItem(LS_ULT,String(segNow()))}catch(e){}}
function segLast(){try{return +localStorage.getItem(LS_ULT)||0}catch(e){return 0}}
function segCheck(){
  if(!segMobile()||!authUser)return false;
  const last=segLast();
  if(last&&segNow()-last>=SEG_MIN*60000){segLogout();return true}
  return false;
}
function segLogout(){
  userAct('ulogout');
  lg.msg='Tu sesión se cerró porque pasaron más de '+SEG_MIN+' minutos fuera de la app. Entra de nuevo.';
  segAutoBio=true;render();
  if(bioLinked())setTimeout(()=>{if(segAutoBio&&!authUser)bioLogin()},500);
}
function segPause(){
  segStamp();clearTimeout(segHideT);
  if(authUser&&segMobile())segHideT=setTimeout(segCheck,SEG_MIN*60000+1000);
}
function segResume(){clearTimeout(segHideT);if(!segCheck())segStamp()}
function segBoot(){try{if(segMobile())document.documentElement.classList.add('gest');segCheck()}catch(e){}}
function segInit(){
  try{
    segStamp();
    document.addEventListener('visibilitychange',()=>{document.hidden?segPause():segResume()});
    window.addEventListener('pagehide',segPause);
    setInterval(()=>{if(!document.hidden&&authUser)segStamp()},15000);
    const A=segPlug('App');
    if(A&&A.addListener){
      A.addListener('backButton',()=>segOnBack());
      A.addListener('appStateChange',st=>{st&&st.isActive?segResume():segPause()});
    }else if(segMobile()&&window.self===window.top&&!empFake()){
      /* navegador o PWA en el teléfono: una entrada de historial de guardia para atrapar el gesto */
      history.replaceState({seg:0},'');history.pushState({seg:1},'');
      window.addEventListener('popstate',e=>{
        if(segWebOff)return;
        if(e.state&&e.state.seg===0){segOnBack();if(!segWebOff){try{history.pushState({seg:1},'')}catch(x){}}}
      });
    }
    if(!authUser&&bioLinked()){segAutoBio=true;setTimeout(()=>{if(segAutoBio&&!authUser)bioLogin()},700)}
  }catch(e){}
  if(empDev())window.EMP_SEG={back:segOnBack,pause:segPause,resume:segResume,check:segCheck,skew:ms=>{segSkew+=ms},now:segNow,linked:bioLinked,ver:APP_VER};
}

/* ---------- v8.25 · Documentos de viaje ----------
   Todos los documentos de cada viaje en un solo lugar, por empresa y semana. Los documentos se siguen generando
   con las mismas funciones de siempre; aquí solo se ordenan y se enlazan con Empaque, Trazabilidad y Productores. */
const DV={e:null,wk:null,ord:'desc'};
function dvTrips(e){return visible().filter(o=>isLeader(o)&&o.emp===e)}
function dvView(){
  const e=DV.e||emp,T=dvTrips(e),cw=wkOfDate(todayISO()),ks=[...new Set(T.map(wkOf).filter(Boolean).concat([cw]))].sort().reverse();
  const sw=DV.wk==='ALL'?'ALL':(ks.indexOf(DV.wk)>=0?DV.wk:(ks.find(k=>T.some(o=>wkOf(o)===k))||cw));
  const L=T.filter(o=>sw==='ALL'||wkOf(o)===sw).sort((a,b)=>{const d=(a.cons||0)-(b.cons||0)||(a.createdAt||0)-(b.createdAt||0);return DV.ord==='asc'?d:-d});
  const cnt=k=>T.filter(o=>wkOf(o)===k).length;
  const tabs=`<div class="dvwk" role="tablist" aria-label="Semana">${ks.slice(0,8).map(k=>`<button class="chipbtn" role="tab" aria-selected="${k===sw}" data-act="dvwk:${k}">${esc(wkLab(k,true))}${cnt(k)?' · '+cnt(k):''}${k===cw?' · vigente':''}</button>`).join('')}<button class="chipbtn" role="tab" aria-selected="${sw==='ALL'}" data-act="dvwk:ALL">Todas</button></div>`;
  const card=o=>{const z=trazCalc(o),cl=manClosed(o);
    return `<button class="dvcard" data-act="dvt:${o.id}"><div class="orow"><span class="oec"><img class="oico" src="${ICO[o.emp]}" alt="">${esc(o.cod)}${o.ejemplo?'<span class="badge">Ejemplo</span>':''}</span>${cl?'<span class="chip good">Manifiesto cerrado</span>':'<span class="chip warn">Manifiesto abierto</span>'}</div><div class="note"><span class="mono">${esc(o.emb||'—')}</span> · ${esc(o.customer||'sin cliente')} · PO ${esc(o.po||'—')} · ${fmtDate(o.fecha)}</div><div class="dvst">${dvDot(z.nPal>0,z.nPal+(z.nPal===1?' tarima':' tarimas'))}${dvDot(!z.borrador,z.borrador?'Código en borrador':'Código listo')}${dvDot(o.estado==='completo',o.estado==='completo'?'Registro completo':'Empaque en proceso')}</div></button>`};
  const XL=ventasX(e).filter(x=>sw==='ALL'||wkOf(x.m)===sw);
  const xcard=x=>{const m=x.m,V=x.V,n=palsOfV(m,V.id).length;return `<button class="dvcard" data-act="dvt:${m.id}@${V.id}"><div class="orow"><span class="oec"><img class="oico" src="${ICO[e]}" alt="">${esc(V.cod)}</span><span class="chip">Manifiesto de ${esc(m.cod)}</span></div><div class="note">${esc(V.cliente||'sin cliente')} · P.O. ${esc(V.poCli||'—')}${V.factura?' · factura '+esc(V.factura):''} · ${fmtDate(m.fecha)}</div><div class="dvst">${dvDot(n>0,n+(n===1?' tarima':' tarimas'))}${dvDot(manClosed(m),manClosed(m)?'Manifiesto cerrado':'Manifiesto abierto')}</div></button>`};
  const xs=XL.length?`<div class="sec">Manifiestos de ${esc(EMPS[e].name)} en viajes de ${esc(EMPS[e==='VL'?'EC':'VL'].name)} · ${XL.length}</div><div class="ogrid dvgrid">${XL.map(xcard).join('')}</div>`:'';
  const body=(L.length?`<div class="ogrid dvgrid">${L.map(card).join('')}</div>`:`<section class="empty"><h2>Sin viajes${sw!=='ALL'?' en '+esc(wkLab(sw)):''}</h2><p>Aquí aparece cada viaje de ${esc(EMPS[e].name)} al crearlo en Registro de Empaque.</p></section>`)+xs;
  return topbar('Documentos de viaje','menu')+`<main class="wrap">${empToggle(e,'dvemp','Empresa',1)}<div class="dvbar">${tabs}<div class="seg dvord" role="group" aria-label="Orden"><button data-act="dvord:desc" aria-pressed="${DV.ord!=='asc'}">Más reciente primero</button><button data-act="dvord:asc" aria-pressed="${DV.ord==='asc'}">Por consecutivo</button></div></div><div class="sec">${esc(EMPS[e].name)} · ${sw==='ALL'?'todas las semanas':esc(wkLab(sw))} · ${L.length} ${L.length===1?'viaje':'viajes'}</div>${body}</main>`;
}
function dvDot(ok,t){return `<span class="dvdot${ok?' ok':''}"><i aria-hidden="true"></i>${esc(t)}</span>`}
function dvtView(o){
  const m=mainOf(o),z=trazCalc(m),cl=manClosed(m),np=z.nPal,lab=etqList(m);
  const dc=(t,sub,st,btns)=>`<section class="panel dvdoc"><div class="dvh"><div><strong>${t}</strong><small>${sub}</small></div>${st}</div><div class="pact">${btns}</div></section>`;
  const b=(act,t,pri,dis)=>`<button class="btn sm${pri?' primary':''}" data-act="${act}"${dis?' disabled':''}>${t}</button>`;
  const sh=sheetsOf(m),s15=sh.find(x=>x.variante==='1.5'),mv=multiV(m),VS=[''].concat(ventas(m).map(x=>x.id));
  return topbar(m.cod+' · Documentos','dvback')+`<main class="wrap">${lockBan(m)}<section class="label"><div class="lrow"><div><div class="k">${esc(EMPS[m.emp].name)} · ${esc(m.emb||'—')} · ${esc(wkLab(wkOf(m)))}</div><div class="big">${esc(m.cod)}</div><div class="note">${esc(m.customer||'sin cliente')} · PO ${esc(m.po||'—')} · ${fmtDate(m.fecha)}</div></div><div style="text-align:right">${cl?'<span class="chip good">Manifiesto cerrado</span>':'<span class="chip warn">Manifiesto abierto</span>'}</div></div></section>
${manBanHtml(m)}
<div class="dsk dvcols"><div class="dcol"><div class="sec">Empaque</div>
${VS.map(id=>{const w='@'+(id||'0'),n=palsOfV(m,id).length;return dc(mv?esc(ventaLab(m,id)):'Manifiesto',mv?n+(n===1?' tarima':' tarimas')+(dvv(m,'poCli',id)?' · P.O. '+esc(dvv(m,'poCli',id)):'')+' · una venta':'Una hoja con la carga por calidad y tipo de empaque',cl?'<span class="chip good">Cerrado</span>':'',b('dx:pv:man'+w,'Vista previa',1)+b('dx:dl:man.pdf'+w,'PDF')+b('dx:dl:man.print'+w,'Imprimir')+b('dx:dl:man.pptx'+w,'PowerPoint')+b('dx:open:man'+w,'Editar datos')+(id?'':b('open:'+m.id,'Ir a Empaque ›')))}).join('')}
${dc('Manifiesto interno',esc((DOC_MX[m.emp]||DOC_MX.VL).name)+(mv?' · todo el viaje':''),'',b('dx:pv:int','Vista previa',1)+b('dx:dl:int.pdf','PDF')+b('dx:dl:int.print','Imprimir')+b('dx:dl:int.pptx','PowerPoint')+b('dx:open:man','Editar datos'))}
${dc('Registro de Empaque','Hoja 1'+(s15?' y hoja 1.5':'')+' con productores, calibres y rendimiento',m.estado==='completo'?'<span class="chip good">Completo</span>':'<span class="chip warn">En proceso</span>',b('dx:pv:reg','Vista previa',1)+b('dx:outreg','Generar')+b('open:'+m.id,'Ir a Empaque ›'))}
</div><div class="dcol"><div class="sec">Trazabilidad</div>
${VS.map(id=>{const w='@'+(id||'0'),n=mv?palsOfV(m,id).length:np;return dc(mv?'Packing List · manifiesto '+ventaN(m,id):'Packing List',n+(n===1?' tarima':' tarimas')+(mv?' sombreadas en el thermo, numeradas por lugar':' con su empaque y calidad'),'',b('dx:pv:pl'+w,'Vista previa',1,!n)+b('dx:outpl'+w,'Generar',0,!n)+b('dx:open:pl'+w,'Editar datos')+(id?'':b('totraz:'+m.id,'Ir a Trazabilidad ›')))}).join('')}
${(trazPorV(m)?VS:[null]).map(id=>{const w=id==null?'':'@'+(id||'0'),st=z.borrador?'Sale como BORRADOR: '+esc(z.motivos.slice(0,2).join('; ')):id==null?'Listo para imprimir':palsOfV(m,id).length+(palsOfV(m,id).length===1?' tarima':' tarimas')+' sombreadas en el thermo; las de los otros manifiestos en gris';return dc(id==null?'Código de Trazabilidad':'Código de Trazabilidad · '+esc(trazVName(m,id)),st,z.borrador?'<span class="chip warn">Borrador</span>':'<span class="chip good">Listo</span>',b('dx:pv:traz'+w,'Vista previa',1)+b('dx:outtraz'+w,'Generar')+(id?'':b('totraz:'+m.id,'Ir a Trazabilidad ›')))}).join('')}
${dc('Etiquetas con QR',lab.length+(lab.length===1?' etiqueta':' etiquetas')+' · una por productor, calidad y presentación','',b('etq:'+m.id,'Generar etiquetas',1,!lab.length)+b('prods','Ir a Productores ›'))}
</div></div></main>`;
}
function dvOpen(id){const q=String(id||'').split('@');id=q[0];const o=orders.find(x=>x.id===id);if(!o)return;if(q[1])setDocV(mainOf(o),q[1]);curId=mainOf(o).id;view='dvt';sheet=null;renderSheet();render();window.scrollTo(0,0)}

/* ---------- v8.25 · Etiquetas con QR por productor ----------
   Mismo contenido que la etiqueta de Publisher (razón social, domicilio, producto, peso, embarque, productor, P.O.,
   calidad, cliente y fecha de empaque) con un QR en lugar del código de barras. El QR lleva el lote:
   EMBARQUE-EMPRESA+CÓDIGO-CALIDAD-AAAAMMDD, por ejemplo JC263301-EC003-1.5-20260812. */
function etqLot(m,code,q){return [String(m.emb||m.cod||'').replace(/\s+/g,''),m.emp+pad(code,3),q==='1.5'?'1.5':'1',String(m.fecha||todayISO()).replace(/-/g,'')].join('-')}
function etqList(m){
  const X=exisData(m),out=[],seen=new Set();
  X.G.forEach(g=>{const code=g.codigo||rmpCodeOf(g.key);g.L.forEach(r=>{if(!(r.reg-r.rmp-r.sent>0))return;const k=g.key+'|'+r.q+'|'+r.tipo;if(seen.has(k))return;seen.add(k);
    out.push({id:k,key:g.key,code:code,nombre:g.nombre||g.key,q:r.q==='1.5'?'1.5':'1',tipo:r.tipo,lot:code?etqLot(m,code,r.q):''})})});
  return out.sort((a,b)=>String(a.key).localeCompare(String(b.key),'es',{numeric:true})||a.q.localeCompare(b.q)||a.tipo.localeCompare(b.tipo));
}
function etqLbs(tipo){return tipo==='CTN10'?10:40}
function qrJpgB64(text,px){
  const q=qrcode(0,'M');q.addData(text);q.make();const n=q.getModuleCount(),qz=2,u=Math.max(4,Math.floor((px||480)/(n+qz*2)));
  const cv=document.createElement('canvas');cv.width=cv.height=u*(n+qz*2);const x=cv.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,cv.width,cv.height);x.fillStyle='#000';
  for(let r=0;r<n;r++)for(let c=0;c<n;c++)if(q.isDark(r,c))x.fillRect((c+qz)*u,(r+qz)*u,u,u);
  return cv.toDataURL('image/jpeg',0.95).split(',')[1];
}
async function etqPages(m,L){
  let lg=null;try{lg=await asset(LOGO[m.emp])}catch(e){}
  const MX=DOC_MX[m.emp]||DOC_MX.VL,INK='#111111',pages=[];
  L.forEach(a=>{
    const ops=[],T=(s,x,y,w,h,p)=>ops.push(Object.assign({t:'t',s:s==null?'':String(s),x,y,w,h,size:16,color:INK},p));
    T(MX.name,10,6,580,34,{size:26,bold:true,align:'center'});ops.push({t:'r',x:12,y:42,w:576,h:5,fill:INK});
    if(lg){const k=Math.min(118/lg.w,74/lg.h);ops.push({t:'i',b64:lg.b64,x:14+(118-lg.w*k)/2,y:54+(74-lg.h*k)/2,w:lg.w*k,h:lg.h*k})}
    T('CARRETERA FEDERAL CÓRDOBA-VERACRUZ KM 56.6 S/N',140,52,300,16,{size:10});T('CUITLÁHUAC, VERACRUZ, MÉXICO.',140,68,300,16,{size:10});
    T('LIMÓN PERSA',140,88,300,22,{size:17,bold:true});T('NET WEIGHT '+etqLbs(a.tipo)+' LBS.',140,110,300,22,{size:17,bold:true});
    ops.push({t:'i',b64:qrJpgB64(a.lot,480),x:462,y:52,w:126,h:126});
    T(a.lot,440,178,150,14,{size:9,align:'center',min:7});
    T(m.emb||m.cod,10,150,180,40,{size:30,bold:true});T(m.emp+' - '+pad(a.code,3),196,150,150,40,{size:30,bold:true,align:'center'});
    T('P.O. '+(m.po||'—'),346,150,110,40,{size:22,bold:true});
    T('Distributed by:',10,198,180,22,{size:14,bold:true});T(m.customer||'',10,222,260,26,{size:16,bold:true});
    ops.push({t:'r',x:206,y:198,w:84,h:50,line:INK,lw:2,rad:6});T('HECHO EN',206,202,84,20,{size:12,bold:true,align:'center'});T('MÉXICO',206,224,84,20,{size:12,bold:true,align:'center'});
    T(a.q==='1.5'?'1½':'1ª',300,192,120,34,{size:30,bold:true,align:'center'});T(TIPO_L[a.tipo]||a.tipo,300,224,120,24,{size:15,align:'center'});
    T('EMP: '+fmtDate(m.fecha),300,252,290,30,{size:20,bold:true,align:'right'});
    T(a.nombre,10,256,286,26,{size:13,color:'#444444'});
    pages.push({w:600,h:300,ops:ops});
  });
  return pages;
}
async function etqPng(pages){
  const cvs=[];for(const pg of pages)cvs.push(await renderPage(pg,300));
  const G=24,W=cvs[0].width,H=cvs.reduce((s,c)=>s+c.height,0)+G*(cvs.length+1),k=Math.min(1,16000/H);
  const cv=document.createElement('canvas');cv.width=Math.round((W+2*G)*k);cv.height=Math.round(H*k);const x=cv.getContext('2d');x.fillStyle='#d9dde1';x.fillRect(0,0,cv.width,cv.height);
  let y=G;cvs.forEach(c=>{x.drawImage(c,G*k,y*k,c.width*k,c.height*k);y+=c.height+G});
  return new Promise((res,rej)=>cv.toBlob(b=>b?res(b):rej(new Error('png')),'image/png'));
}
async function etqWb(m,L){
  const wb=newWb(),ws=wb.addWorksheet('Etiquetas');
  ws.columns=[{header:'Lote (QR)',key:'lot',width:30},{header:'QR',key:'qr',width:14},{header:'Empresa',key:'emp',width:38},{header:'Código',key:'code',width:10},{header:'Productor',key:'nom',width:30},{header:'Calidad',key:'q',width:9},{header:'Presentación',key:'tipo',width:13},{header:'Peso neto',key:'peso',width:12},{header:'Embarque',key:'emb',width:13},{header:'P.O.',key:'po',width:10},{header:'Distributed by',key:'cli',width:26},{header:'Fecha de empaque',key:'fecha',width:15},{header:'Domicilio',key:'dom',width:52}];
  ws.getRow(1).font={bold:true};
  L.forEach((a,i)=>{const r=ws.addRow({lot:a.lot,emp:(DOC_MX[m.emp]||DOC_MX.VL).name,code:m.emp+'-'+pad(a.code,3),nom:a.nombre,q:a.q==='1.5'?'1½':'1',tipo:TIPO_L[a.tipo]||a.tipo,peso:etqLbs(a.tipo)+' LBS',emb:m.emb||m.cod,po:m.po||'',cli:m.customer||'',fecha:fmtDate(m.fecha),dom:'CARRETERA FEDERAL CÓRDOBA-VERACRUZ KM 56.6 S/N, CUITLÁHUAC, VERACRUZ, MÉXICO'});r.height=78;
    const id=wb.addImage({base64:qrJpgB64(a.lot,240),extension:'jpeg'});ws.addImage(id,{tl:{col:1.1,row:i+1.08},ext:{width:96,height:96}})});
  const n=wb.addWorksheet('Cómo usar');n.getCell('A1').value='Para Publisher: Correspondencia › Combinar correspondencia › Usar una lista existente y elige la hoja «Etiquetas». Cada renglón es una etiqueta; la columna «Lote (QR)» es el texto del QR.';n.getColumn(1).width=120;
  return wb;
}
function etqOpen(id){
  const o=orders.find(x=>x.id===id);if(!o)return;const m=mainOf(o),L=etqList(m);if(!L.length){toast('Este viaje todavía no tiene fruta registrada para etiquetar');return}
  const sel={};L.forEach(a=>{if(a.code)sel[a.id]=true});sheet={kind:'etq',oid:m.id,sel:sel};renderSheet();
}
function etqHtml(){
  const m=orders.find(x=>x.id===sheet.oid);if(!m)return '';const L=etqList(m),sel=sheet.sel,n=L.filter(a=>sel[a.id]).length,sin=L.filter(a=>!a.code).length;
  return `<h3>Etiquetas con QR · ${esc(m.cod)}</h3><p class="note">Una etiqueta de 4 × 2 pulgadas por productor, calidad y presentación, con la razón social de ${esc(EMPS[m.emp].name)}. El QR lleva el lote: embarque, productor, calidad y fecha de empaque.</p>
<div class="srow2"><button class="btn sm" data-act="etqall">Seleccionar todo</button><button class="btn sm" data-act="etqnone">Limpiar</button></div>
<div class="s2list">${L.map(a=>`<label class="s2r" for="eq-${esc(a.id)}"><input type="checkbox" id="eq-${esc(a.id)}" data-etqsel="${esc(a.id)}"${sel[a.id]?' checked':''}${a.code?'':' disabled'}><span class="s2d"><b>${esc(a.nombre)}</b><small>${a.code?esc(m.emp+'-'+pad(a.code,3))+' · ':'sin código, no se etiqueta · '}${a.q==='1.5'?'1½':'Primera'} · ${esc(TIPO_L[a.tipo]||a.tipo)}${a.lot?' · <span class="mono">'+esc(a.lot)+'</span>':''}</small></span></label>`).join('')}</div>
${sin?`<p class="note">${sin} sin código de productor: asígnalo en Productores para poder etiquetar.</p>`:''}
<div class="srow2"><button class="btn" data-act="prods">Ir a Productores</button><button class="btn primary" data-act="etqgo"${n?'':' disabled'}>Generar ${n} ${n===1?'etiqueta':'etiquetas'}</button></div>`;
}
function etqGo(){
  const m=orders.find(x=>x.id===(sheet&&sheet.oid));if(!m)return;const L=etqList(m).filter(a=>sheet.sel[a.id]&&a.code);if(!L.length)return;
  const P=()=>etqPages(m,L),f={png:async()=>etqPng(await P()),pdf:async()=>pagesToPdf(await P())};
  if(typeof ExcelJS!=='undefined')f.xlsx=async()=>wbBlob(await etqWb(m,L));
  f.pptx=async()=>pagesToPptx(await P(),'Etiquetas '+m.cod);
  openOut({pages:P,title:'Etiquetas '+m.cod+' · '+L.length,base:'Etiquetas_'+fileSafe(m.emb||m.cod),fmts:f,note:'Una hoja de 4 × 2 pulgadas por etiqueta. El Excel sirve para Combinar correspondencia en Publisher.'});
}

$app.addEventListener('change',e=>{const t=e.target;if(!t||!t.dataset)return;if(t.dataset.ctz){ctTurnoSet('prod',t.value);return}if(t.dataset.tdprod){TD.prod=t.value||null;return}if(t.dataset.tdord){tdOrdAsk(t.dataset.tdord,t.value);return}if(t.dataset.ctrip){CT.oid=t.dataset.ctrip;CT.pal='new';TD.open=null;TD.mv=null;render()}else if(t.dataset.cpal){CT.pal=t.dataset.cpal}});
$app.addEventListener('input',e=>{const t=e.target;if(!t||!t.dataset)return;if(t.dataset.ctprod!=null)CT.prod=t.value;else if(t.dataset.ctn){const d=t.value.replace(/\D+/g,'');if(d!==t.value)t.value=d;CT.n[t.dataset.ctn]=d;const o=document.getElementById('cttot');if(o)o.textContent='Total: '+fmt(calsOfTipo(CT.tipo).reduce((s,c)=>s+n0(CT.n[c.k]),0))+' cajas'}});
/* ---------- v8.25 · Conteo de tarimas (rol «tarima») ----------
   El personal de tarima solo cuenta: por productor, calidad, presentación y calibre, cuántas cajas se agregan a qué tarima.
   El conteo queda pendiente hasta que el jefe de empaque lo autoriza en Código de Trazabilidad; al autorizar, las cajas
   entran a la tarima. Se guarda en la tabla «conteos» (supabase-v8.25.sql); sin ella queda en el dispositivo. */
const LS_CONT='empaque-conteos';
let CONT={list:[],dirty:[],noTable:false};
(function(){try{const j=JSON.parse(localStorage.getItem(LS_CONT)||'null');if(j&&Array.isArray(j.list))CONT={list:j.list,dirty:Array.isArray(j.dirty)?j.dirty:[],noTable:false}}catch(e){}})();
function saveCont(){try{localStorage.setItem(LS_CONT,JSON.stringify({list:CONT.list,dirty:CONT.dirty}))}catch(e){lsFail(e)}}
function touchC(c){c.updatedAt=Date.now();if(CONT.dirty.indexOf(c.id)<0)CONT.dirty.push(c.id);saveCont();setSync()}
async function syncCont(){
  try{
    const since=Date.now()-60*864e5;let rows;
    if(LOCAL.on){ /* v8.46: en la HP solo lo recibido desde la última vez (10 teléfonos cada 3 s no aguantan bajar todo) */
      const c=LOCAL.ccur?'&recibido=gt.'+encodeURIComponent(new Date(Date.parse(LOCAL.ccur)-60000).toISOString()):'';
      rows=await sbAll('/rest/v1/conteos?select=id,updated_at,data,recibido'+c+'&order=recibido.asc');
      let mx=LOCAL.ccur?Date.parse(LOCAL.ccur):0;rows.forEach(r=>{const t=Date.parse(r.recibido||'');if(t>mx)mx=t});if(mx)LOCAL.ccur=new Date(mx).toISOString();
    }else rows=await sbAll('/rest/v1/conteos?select=id,updated_at,data&updated_at=gt.'+since+'&order=updated_at.desc');CONT.noTable=false;
    rows.forEach(r=>{if(!r.data||!okId(r.id))return;const d=cleanRec(Object.assign({},r.data,{id:r.id,updatedAt:Number(r.updated_at)||0})),k=CONT.list.findIndex(x=>x.id===r.id);
      if(k<0)CONT.list.push(d);else if(d.updatedAt>(CONT.list[k].updatedAt||0)&&CONT.dirty.indexOf(r.id)<0)CONT.list[k]=d});
    const send=CONT.dirty.map(id=>CONT.list.find(c=>c.id===id)).filter(Boolean);
    if(send.length){await sb('/rest/v1/conteos?on_conflict=id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:send.map(c=>({id:c.id,updated_at:c.updatedAt,data:c}))});CONT.dirty=[]}
    CONT.list=CONT.list.filter(c=>(c.updatedAt||0)>Date.now()-120*864e5||c.estado==='pendiente');saveCont();
  }catch(e){if(e&&(e.status===404||e.status===400))CONT.noTable=true}
}
function contOf(m){return CONT.list.filter(c=>c.oid===m.id&&c.kind!=='seg'&&c.kind!=='mov')}
function contPend(m){return contOf(m).filter(c=>c.estado==='pendiente')}
function calsOfTipo(tp){return tp==='CTN10'?CAL_MM:CAL_STD.filter(c=>c.k!=='ctn')}
const CT={oid:null,q:'1',tipo:'RPC',pal:'new',prod:'',n:{},edit:null};
function contTrips(){return visible().filter(o=>isLeader(o)&&!manClosed(o)&&!orderLocked(o)).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)).slice(0,10)}
function contProds(m){const out=[],seen=new Set();sheetsOf(m).forEach(s=>(s.productores||[]).forEach(p=>{if(p.sob2||p.sob)return;const k=prodKey(s,p);if(seen.has(k))return;seen.add(k);out.push({k:k,n:p.nombre||k})}));return out}
function conteoViewV831(){
  const T=contTrips(),m=T.find(o=>o.id===CT.oid)||null;
  const trips=T.length?`<div class="pnopts">${T.map(o=>`<label class="pnopt"><input type="radio" name="ctrip" data-ctrip="${o.id}"${m&&m.id===o.id?' checked':''}><span><b class="mono">${esc(o.cod)}</b><small>${esc(EMPS[o.emp].name)} · ${esc(o.emb||'—')} · ${fmtDate(o.fecha)}</small></span></label>`).join('')}</div>`:'<p class="note">No hay viajes abiertos para contar. Avisa al jefe de empaque.</p>';
  let form='';
  if(m){const P=contProds(m),t=ensureTraz(m),cals=calsOfTipo(CT.tipo),tot=cals.reduce((s,c)=>s+n0(CT.n[c.k]),0);
    const pals=t.tarimas.map((p,i)=>({p:p,i:i})).filter(x=>palArm(x.p)&&palTipo(x.p)===CT.tipo&&palTot(x.p)<palCap(palTipo(x.p)));
    const tz=m.ctTurno;if(tz){CT.prod=tz.prod;CT.q=tz.q;if(CT.tipo!==tz.tipo){CT.tipo=tz.tipo;CT.n={};CT.pal='new'}}
    if(!tz){form=`<div class="panel warn" style="margin-top:12px"><strong>Falta el productor en turno</strong><p class="note">El jefe de empaque indica en Código de Trazabilidad qué productor, calidad y presentación se están contando. En cuanto lo haga aparece aquí.</p></div>`}else{
    form=`<div class="sec">En turno</div><div class="panel ctturno"><div class="kv"><span>Productor</span><b>${esc(tz.prod)} · ${esc(tz.nombre||'')}</b></div><div class="kv"><span>Calidad</span><b>${tz.q==='1.5'?'1.5':'Primera'}</b></div><div class="kv" style="border-bottom:0"><span>Presentación</span><b>${esc(TIPO_L[tz.tipo]||tz.tipo)}</b></div><small class="note">Lo indicó ${esc(tz.by||'el jefe de empaque')}, ${esc(fmtTs(tz.at))}.</small></div>
<div class="sec">Tarima</div><div class="pnopts">${pals.map(x=>`<label class="pnopt"><input type="radio" name="cpal" data-cpal="${x.p.id}"${CT.pal===x.p.id?' checked':''}><span><b>Tarima ${x.i+1}</b><small>${esc(TIPO_L[palTipo(x.p)])} · ${fmt(palTot(x.p))} de ${fmt(palCap(palTipo(x.p)))} cajas</small></span></label>`).join('')}<label class="pnopt"><input type="radio" name="cpal" data-cpal="new"${CT.pal==='new'||!pals.some(x=>x.p.id===CT.pal)?' checked':''}><span><b>Tarima nueva</b><small>${esc(TIPO_L[CT.tipo])}</small></span></label></div>
<div class="sec">Cajas por calibre</div><div class="panel ctgrid">${cals.map(c=>`<label class="fld" for="ct-${c.k}"><span>${esc(c.l)}</span><input class="in" id="ct-${c.k}" inputmode="numeric" autocomplete="off" data-ctn="${c.k}" value="${CT.n[c.k]!=null?esc(CT.n[c.k]):''}"></label>`).join('')}</div>
<p class="s2tot" id="cttot">Total: ${fmt(tot)} cajas</p><div class="pact">${CT.edit?'<button class="btn" data-act="ctedit:">Cancelar corrección</button>':''}<button class="btn primary" style="flex:1" data-act="ctsend">${CT.edit?'Guardar corrección':'Enviar conteo al jefe de empaque'}</button></div>`}}
  const meU=authUser&&authUser.user,mine=(m?contOf(m):[]).slice().sort((a,b)=>(b.at||0)-(a.at||0));
  const st=c=>c.estado==='autorizado'?'<span class="chip good">Autorizado</span>':c.estado==='rechazado'?'<span class="chip crit">Rechazado</span>':'<span class="chip warn">Pendiente</span>';
  /* v8.31: productores que van pasando en este viaje; lo autorizado ya no se cambia, lo pendiente propio sí */
  const byP=new Map();mine.forEach(c=>{const a=byP.get(c.prod)||{k:c.prod,n:c.nombre||'',L:[],tot:0,ok:0};a.L.push(c);if(c.estado!=='rechazado')a.tot+=contTot(c);if(c.estado==='autorizado')a.ok+=contTot(c);byP.set(c.prod,a)});
  const hist=m&&byP.size?`<div class="sec">Productores en este viaje</div><div class="panel ctlist">${[...byP.values()].map(a=>`<div class="ctp"><div class="ctph"><b>${esc(a.k)} · ${esc(a.n)}</b><span>${fmt(a.ok)} autorizadas${a.tot>a.ok?' · '+fmt(a.tot-a.ok)+' por autorizar':''}</span></div>${a.L.map(c=>`<div class="kv"><span>${c.q==='1.5'?'1.5 · ':''}${esc(TIPO_L[c.tipo])} · ${c.palN?'tarima '+c.palN:'tarima nueva'} · ${esc(c.lines.map(l=>calLab(l.ck)+': '+fmt(l.n)).join(', '))} · <b>${fmt(contTot(c))} cajas</b>${c.jed?' · corregido por '+esc(c.jed):''}${c.nota?' · «'+esc(c.nota)+'»':''}</span><span class="ctst">${st(c)}${c.estado==='pendiente'&&c.byU===meU&&!CT.edit?`<button class="btn sm" data-act="ctedit:${c.id}">Corregir</button>`:''}</span></div>`).join('')}</div>`).join('')}</div>`:'';
  return topbar('Conteo de tarimas','menu')+`<main class="wrap"><div class="panel info"><p class="note">Cuenta las cajas del productor en turno y a qué tarima van. El jefe de empaque indica productor, calidad y presentación, y autoriza cada conteo; un conteo autorizado ya no se cambia.</p></div><div class="sec">Viaje</div>${trips}${form}${hist}${legalFoot()}</main>`;
}
function contTot(c){return (c.lines||[]).reduce((s,l)=>s+n0(l.n),0)}
function contSend(){
  const m=orders.find(x=>x.id===CT.oid);if(!m){toast('Elige el viaje');return}
  const pk=resolveProd(sheetsOf(m),CT.prod);if(!pk){toast('Escribe el código o el nombre del productor');return}
  const lines=calsOfTipo(CT.tipo).map(c=>({ck:c.k,n:Math.max(0,Math.floor(n0(CT.n[c.k])))})).filter(l=>l.n>0);if(!lines.length){toast('Escribe cuántas cajas de cada calibre');return}
  const t=ensureTraz(m),pi=t.tarimas.findIndex(p=>p.id===CT.pal);
  if(pi>=0){const P=t.tarimas[pi],room=palCap(palTipo(P))-palTot(P),tot=lines.reduce((x,l)=>x+l.n,0);if(tot>room){toast('A la tarima '+(pi+1)+' le caben '+fmt(Math.max(0,room))+' cajas. Manda el resto a una tarima nueva');return}}
  const nm=(contProds(m).find(x=>x.k===pk)||{}).n||pk;
  if(CT.edit){const c0=CONT.list.find(x=>x.id===CT.edit);CT.edit=null;if(!c0||c0.estado!=='pendiente'){toast('Ese conteo ya lo revisó el jefe de empaque: ya no se cambia');render();return}
    c0.lines=lines;c0.pal=pi>=0?CT.pal:'new';c0.palN=pi>=0?pi+1:null;c0.at=Date.now();touchC(c0);CT.n={};render();toast('Corrección guardada: '+fmt(contTot(c0))+' cajas de '+c0.prod);if(canAuto())doSync(true);return}
  if(!m.ctTurno){toast('Falta que el jefe de empaque indique el productor en turno');return}
  const c={id:uid(),oid:m.id,emp:m.emp,cod:m.cod,prod:pk,nombre:nm,q:CT.q,tipo:CT.tipo,pal:pi>=0?CT.pal:'new',palN:pi>=0?pi+1:null,lines:lines,estado:'pendiente',at:Date.now(),by:whoName(),byU:authUser&&authUser.user};
  CONT.list.push(c);touchC(c);CT.n={};CT.prod='';render();toast('Conteo enviado: '+fmt(contTot(c))+' cajas de '+pk+'. Falta que lo autorice el jefe de empaque');if(canAuto())doSync(true);
}
/* v8.31.1: el jefe revisa cada conteo: lo autoriza o lo rechaza; uno autorizado se puede rechazar (sus cajas salen de la tarima) o corregir */
const CTV={id:null,ed:null,done:false};
function ctHist(c,a,n){(c.hist=c.hist||[]).push({a:a,by:whoName(),at:Date.now(),n:n||''})}
function ctLinesTxt(L){return (L||[]).map(l=>calLab(l.ck)+': '+fmt(l.n)).join(', ')}
function contAuth(id,ok){
  const c=CONT.list.find(x=>x.id===id);if(!c||!canManClose()||roRole)return;const m=orders.find(x=>x.id===c.oid);if(!m)return;
  if(ok?c.estado==='autorizado':c.estado==='rechazado')return;
  if(manClosed(m)||orderLocked(m)){toast('El manifiesto o la semana de '+m.cod+' está cerrado');return}
  const nota=String((document.getElementById('ctr-'+id)||{}).value||'').trim(),was=c.estado;
  if(ok){const t=ensureTraz(m);let p=c.pal&&c.pal!=='new'?t.tarimas.find(x=>x.id===c.pal):null;
    if(p&&palTot(p)+contTot(c)>palCap(palTipo(p))){toast('Ya no caben en la tarima '+(t.tarimas.indexOf(p)+1)+': le quedan '+fmt(Math.max(0,palCap(palTipo(p))-palTot(p)))+' cajas. Corrige el conteo o recházalo para que lo manden a otra tarima');return}
    if(!p){p={id:uid(),marca:marcaOfQ(m.emp,c.q),empaque:c.tipo,lines:[]};t.tarimas.push(p);c.palNew=true}
    c.lines.forEach(l=>palPut(m,p,c.q,l.ck,c.prod,l.n));c.palN=t.tarimas.indexOf(p)+1;c.pal=p.id;c.nota='';touch(m);
    logAdd({k:'note',ctx:ctxOf(m),lab:'Conteo de tarima autorizado',o:c.by||'',n:'Tarima '+c.palN+' · '+c.prod+' · '+fmt(contTot(c))+' cajas'})}
  else{c.nota=nota;
    if(was==='autorizado'){const t=ensureTraz(m),p=t.tarimas.find(x=>x.id===c.pal);let miss=contTot(c);
      if(p){miss=c.lines.reduce((s2,l)=>s2+palSub(m,p,c.q,l.ck,c.prod,l.n),0);if(c.palNew&&!palTot(p)&&!(p.lines||[]).length){t.tarimas.splice(t.tarimas.indexOf(p),1);if(palOpen===p.id)palOpen=null;c.pal='new';c.palN=null;c.palNew=false}}
      touch(m);logAdd({k:'note',ctx:ctxOf(m),lab:'Conteo autorizado que se rechazó',o:c.by||'',n:(c.palN?'Tarima '+c.palN+' · ':'')+c.prod+' · '+fmt(contTot(c))+' cajas salieron de la tarima'+(nota?' · '+nota:'')});
      if(miss>0)toast('Ojo: '+fmt(miss)+' cajas ya no estaban en la tarima (la movieron a mano). Revisa la tarima')}}
  c.estado=ok?'autorizado':'rechazado';c.autBy=whoName();c.autAt=Date.now();ctHist(c,c.estado,ok?'':nota);CTV.ed=null;touchC(c);render();
  toast(ok?'Conteo autorizado: las cajas entraron a la tarima '+c.palN:was==='autorizado'?'Conteo rechazado: sus cajas salieron de la tarima':'Conteo rechazado');
}
function contJefeSave(id){
  const c=CONT.list.find(x=>x.id===id);if(!c||!canManClose()||roRole)return;const m=orders.find(x=>x.id===c.oid);if(!m)return;
  if(manClosed(m)||orderLocked(m)){toast('El manifiesto o la semana de '+m.cod+' está cerrado');return}
  const L=calsOfTipo(c.tipo).map(k=>({ck:k.k,n:Math.max(0,Math.floor(n0((document.getElementById('cte-'+id+'-'+k.k)||{}).value)))})).filter(l=>l.n>0);
  if(!L.length){toast('Sin cajas no queda conteo: mejor recházalo');return}
  const before=ctLinesTxt(c.lines),after=ctLinesTxt(L);if(before===after){CTV.ed=null;render();return}
  if(c.estado==='autorizado'){const t=ensureTraz(m),p=t.tarimas.find(x=>x.id===c.pal);if(!p){toast('La tarima de este conteo ya no existe. Recházalo y vuelve a autorizarlo');return}
    const old={},nw={};c.lines.forEach(l=>old[l.ck]=l.n);L.forEach(l=>nw[l.ck]=l.n);const ks=[...new Set(Object.keys(old).concat(Object.keys(nw)))];
    const dTot=ks.reduce((s2,k)=>s2+(n0(nw[k])-n0(old[k])),0);if(dTot>0&&palTot(p)+dTot>palCap(palTipo(p))){toast('No caben: a la tarima '+(t.tarimas.indexOf(p)+1)+' le quedan '+fmt(Math.max(0,palCap(palTipo(p))-palTot(p)))+' cajas');return}
    ks.forEach(k=>{const d=n0(nw[k])-n0(old[k]);if(d<0)palSub(m,p,c.q,k,c.prod,-d);else if(d>0)palPut(m,p,c.q,k,c.prod,d)});touch(m)}
  c.lines=L;c.jed=whoName();ctHist(c,'corregido','antes '+before+' · ahora '+after);
  logAdd({k:'note',ctx:ctxOf(m),lab:'Conteo de tarima corregido por el jefe',o:c.by||'',n:c.prod+' · antes '+before+' · ahora '+after+(c.estado==='autorizado'?' · tarima '+c.palN+' ajustada':'')});
  CTV.ed=null;touchC(c);render();toast('Conteo corregido: '+fmt(contTot(c))+' cajas'+(c.estado==='autorizado'?'. La tarima '+c.palN+' ya quedó ajustada':''));
}
function ctChip(c){return c.estado==='autorizado'?'<span class="chip good">Autorizado</span>':c.estado==='rechazado'?'<span class="chip crit">Rechazado</span>':'<span class="chip warn">Pendiente</span>'}
const CTH_L={autorizado:'Autorizó',rechazado:'Rechazó',corregido:'Corrigió'};
function ctDetail(m,c,can){
  const t=ensureTraz(m),pi=t.tarimas.findIndex(p=>p.id===c.pal),ed=can&&CTV.ed===c.id,n={};c.lines.forEach(l=>n[l.ck]=l.n);
  const cals=calsOfTipo(c.tipo).filter(k=>ed||n[k.k]);
  const grid=ed?`<div class="ctgrid ctedg">${cals.map(k=>`<label class="fld" for="cte-${c.id}-${k.k}"><span>${esc(k.l)}</span><input class="in" id="cte-${c.id}-${k.k}" inputmode="numeric" autocomplete="off" value="${n[k.k]||''}"></label>`).join('')}</div>`
    :`<table class="ctdt"><thead><tr><th>Calibre</th><th>Cajas</th></tr></thead><tbody>${cals.map(k=>`<tr><td>${esc(k.l)}</td><td>${fmt(n[k.k])}</td></tr>`).join('')}</tbody><tfoot><tr><td>Total</td><td>${fmt(contTot(c))}</td></tr></tfoot></table>`;
  const H=(c.hist||[]).map(h=>`<li>${esc(CTH_L[h.a]||h.a)} ${esc(h.by||'')}, ${esc(fmtTs(h.at))}${h.n?' · '+esc(h.n):''}</li>`).join('');
  const kv=`<div class="kv"><span>Calidad</span><b>${c.q==='1.5'?'1.5':'Primera'}</b></div><div class="kv"><span>Presentación</span><b>${esc(TIPO_L[c.tipo]||c.tipo)}</b></div><div class="kv"><span>Tarima</span><b>${pi>=0?'Tarima '+(pi+1):'Tarima nueva'}</b></div><div class="kv"><span>Contó</span><b>${esc(c.by||'—')}, ${esc(fmtTs(c.at))}</b></div>${c.nota?`<div class="kv"><span>Motivo del rechazo</span><b>${esc(c.nota)}</b></div>`:''}`;
  let act='';
  if(can){const mot=`<input class="in txt" id="ctr-${c.id}" placeholder="Motivo si se rechaza" aria-label="Motivo del rechazo">`;
    act=ed?`<button class="btn sm" data-act="ctjed:">Cancelar</button><button class="btn sm primary" data-act="ctjsave:${c.id}">Guardar corrección</button>`
      :c.estado==='pendiente'?`${mot}<button class="btn sm" data-act="ctjed:${c.id}">Corregir</button><button class="btn sm danger" data-act="ctno:${c.id}">Rechazar</button><button class="btn sm primary" data-act="ctok:${c.id}">Autorizar</button>`
      :c.estado==='autorizado'?`${mot}<button class="btn sm" data-act="ctjed:${c.id}">Corregir cajas</button><button class="btn sm danger" data-act="ctno:${c.id}">Rechazar y sacar de la tarima</button>`
      :`<button class="btn sm" data-act="ctjed:${c.id}">Corregir</button><button class="btn sm primary" data-act="ctok:${c.id}">Autorizar</button>`;
    act=`<div class="pact">${act}</div>`;
    if(c.estado==='autorizado'&&!ed)act=`<p class="note">Si lo rechazas, sus ${fmt(contTot(c))} cajas salen de la tarima${pi>=0?' '+(pi+1):''}. Si lo corriges, la tarima se ajusta sola.</p>`+act}
  return `<div class="ctdet">${kv}${grid}${H?`<ul class="cthist">${H}</ul>`:''}${act}</div>`;
}
/* v8.32.2 · Supervisión del equipo de piso: desde el Código de Trazabilidad de cada viaje, el jefe de empaque y la administración
   abren las pantallas de Asistencia en tarimas y Conteo de segundas con ese viaje elegido, para revisar o corregir.
   El personal de esos roles sigue sin acceso a las demás funciones. */
let SUP=null;
function supOK(){return !!authUser&&!roRole&&['jefe','inocuidad','admin','superadmin'].indexOf(rolReal())>=0}
function supPanel(m){
  if(!m||!supOK()||!isLeader(m))return '';
  const open=contTrips().some(o=>o.id===m.id),R=scRecs(m.id),tot=R.reduce((a,c)=>a+n0(c.seg)+n0(c.cera)+n0(c.des),0),nP=new Set(R.map(c=>c.prod)).size;
  const b=(act,t,s)=>`<button class="lrow" data-act="${act}:${m.id}"${open?'':' disabled'}><span><b>${t}</b><small>${s}</small></span><span aria-hidden="true">›</span></button>`;
  return `<details class="panel lpanel suppan"${SUP&&SUP.oid===m.id?' open':''}><summary><strong>Equipo de piso</strong><small>Supervisar o corregir tarimas y conteo de segundas de ${esc(m.cod)}</small></summary>${b('supct','Tarimas del viaje','Lo que ve Asistencia en tarimas')}${b('supsc','Conteo de segundas',R.length?`${fmt(R.length)} conteos · ${fmt(nP)} productores · ${fmt(tot)} cajas`:'Sin conteos todavía')}${open?'':'<p class="note" style="margin-top:6px">Con el manifiesto cerrado o la semana cerrada estas pantallas ya no muestran el viaje.</p>'}</details>`;
}
function supGo(v,id){
  if(!supOK())return;const o=orders.find(x=>x.id===id);if(!o)return;
  SUP={oid:id,from:curId||id};if(v==='conteo')CT.oid=id;else{SC.oid=id;SC.prod='';SC.in='';SC.p={seg:[],cera:[],des:[]};SC.f='seg'}
  view=v;sheet=null;renderSheet();render();window.scrollTo(0,0);
}
function supBack(){
  const id=SUP&&SUP.from;SUP=null;
  if(id&&orders.some(o=>o.id===id)){curId=id;view='trazo'}else{curId=null;view='traz'}
  showHdr=false;render();window.scrollTo(0,0);
}
function supBan(){
  if(isTarima()||isSegC()||!supOK())return '';
  const o=SUP&&orders.find(x=>x.id===SUP.oid);
  return `<div class="panel info supban"><div><strong>Supervisión${o?' · '+esc(o.cod):''}</strong><p class="note">Ves lo mismo que el equipo de piso y puedes corregirlo. Lo que guardes queda con tu nombre.</p></div><button class="btn sm" data-act="supback">‹ Volver a Código de Trazabilidad</button></div>`;
}
function supScList(m){
  if(!m||isSegC()||!supOK())return '';
  const L=CONT.list.filter(c=>c.kind==='seg'&&c.oid===m.id).sort((a,b)=>(b.at||0)-(a.at||0));if(!L.length)return '';
  return `<div class="sec">Conteos del viaje (supervisión)</div><div class="panel">${L.map(c=>{const k='scan:'+c.id;return `<div class="kv${c.estado==='anulado'?' anul':''}"><span><b>${esc(c.nombre||c.prod)}</b><small class="mono"> · ${esc(c.prod)}</small><small> · ${esc(c.by||c.byU||'')} · ${esc(fmtTs(c.at))} · ${fmt(n0(c.seg))} segundas · ${fmt(n0(c.cera))} con cera · ${fmt(n0(c.des))} terceras${c.estado==='anulado'?' · anulado'+(c.anulBy?' por '+esc(c.anulBy):''):''}</small></span>${c.estado==='anulado'?'':`<button class="btn sm" data-act="${k}">${confirmKey===k?'Toca otra vez':'Anular'}</button>`}</div>`}).join('')}</div>`;
}
function contPanel(m){
  const A=contOf(m).slice().sort((a,b)=>(b.at||0)-(a.at||0));if(!A.length)return ctTurnoHtml(m);const can=canManClose()&&!roRole&&!manClosed(m)&&!orderLocked(m);
  const P=A.filter(c=>c.estado==='pendiente'),D=A.filter(c=>c.estado!=='pendiente'),nOk=D.filter(c=>c.estado==='autorizado').length,nNo=D.length-nOk;
  const row=c=>{const op=CTV.id===c.id;return `<div class="ctrow${op?' open':''}"><button class="ctrb" data-act="ctview:${c.id}" aria-expanded="${op}"><span class="ctrt"><b>${esc(c.prod)} · ${esc(c.nombre||'')}</b><small>${c.q==='1.5'?'1.5 · ':''}${esc(TIPO_L[c.tipo])} · ${c.palN?'tarima '+c.palN:'tarima nueva'} · ${esc(ctLinesTxt(c.lines))} · <b>${fmt(contTot(c))} cajas</b> · ${esc(c.by||'—')}, ${esc(fmtTs(c.at))}${c.jed?' · corregido':''}</small></span><span class="ctrs">${ctChip(c)}<span class="ctvb">${op?'Cerrar':'Ver'}</span></span></button>${op?ctDetail(m,c,can):''}</div>`};
  const dOpen=CTV.done||D.some(c=>c.id===CTV.id);
  return ctTurnoHtml(m)+(P.length?`<div class="panel warn ctpend"><strong>Conteos por autorizar · ${P.length}</strong><p class="note">Toca un conteo para verlo completo, corregirlo, autorizarlo o rechazarlo.</p>${P.map(row).join('')}</div>`:'')
    +(D.length?`<div class="panel ctpend ctdone"><button class="ctdh" data-act="ctdone" aria-expanded="${dOpen}"><strong>Conteos revisados · ${nOk} autorizados${nNo?' · '+nNo+' rechazados':''}</strong><span>${dOpen?'Ocultar':'Ver'}</span></button>${dOpen?D.map(row).join(''):''}</div>`:'');
}
/* v8.31: el jefe de empaque indica qué productor, calidad y presentación se están contando; asistencia en tarimas solo cuenta */
function ctTurnoHtml(m){
  if(!canManClose()||roRole||manClosed(m)||orderLocked(m))return '';
  const tz=m.ctTurno||{},P=contProds(m);
  return `<div class="panel ctzp"><strong>En turno para asistencia en tarimas</strong><p class="note">Lo que elijas aquí es lo que cuenta el personal de tarimas.</p><label class="fld" for="ctz-prod"><span>Productor</span><select class="in sel" id="ctz-prod" data-ctz="${m.id}"><option value="">— Elige productor —</option>${P.map(x=>`<option value="${esc(x.k)}"${tz.prod===x.k?' selected':''}>${esc(x.k)} · ${esc(x.n)}</option>`).join('')}</select></label><div class="seg" role="group" aria-label="Calidad"><button data-act="ctz:q:1" aria-pressed="${(tz.q||'1')==='1'}">Primera</button><button data-act="ctz:q:1.5" aria-pressed="${tz.q==='1.5'}">1.5</button></div><div class="seg" role="group" aria-label="Presentación" style="margin-top:8px">${TIPO_K.map(k=>`<button data-act="ctz:tipo:${k}" aria-pressed="${(tz.tipo||'RPC')===k}">${esc(TIPO_L[k])}</button>`).join('')}</div></div>`;
}
function ctTurnoSet(f,v){
  const m=trazOrder?trazOrder():cur();if(!m||!canManClose()||roRole)return;const tz=Object.assign({q:'1',tipo:'RPC'},m.ctTurno||{});
  if(f==='prod'){tz.prod=v||'';tz.nombre=(contProds(m).find(x=>x.k===v)||{}).n||'';delete tz.rw}else if(f==='q')tz.q=v==='1.5'?'1.5':'1';else if(f==='tipo'&&TIPO_K.indexOf(v)>=0)tz.tipo=v;
  if(tz.prod&&!tz.rw){const sq=sheetsOf(m).find(x=>(x.variante==='1.5'?'1.5':'1')===(tz.q||'1')),D=sq?rwDups(sq,tz.prod):[];if(D.length>1)tz.rw=D[D.length-1].id}
  tz.at=Date.now();tz.by=whoName();m.ctTurno=tz.prod?tz:Object.assign(tz,{prod:''});if(!m.ctTurno.prod)delete m.ctTurno;touch(m);render();
  if(m.ctTurno)toast('En turno: '+m.ctTurno.prod+' · '+(m.ctTurno.q==='1.5'?'1.5':'Primera')+' · '+(TIPO_L[m.ctTurno.tipo]||m.ctTurno.tipo));
}

/* ---------- v8.32 · Tarimas dibujadas (asistencia en tarimas) ----------
   Asistencia ve las tarimas del viaje dibujadas por camas y les suma o quita cajas del productor en turno.
   Las tarimas son las mismas de Código de Trazabilidad: una presentación por tarima; calidad, calibre y productor se mezclan.
   Cada asistente suma en su propio renglón (l.by), así dos personas tocando a la vez no se borran cajas al juntar cambios.
   Cada cambio queda como movimiento (tabla conteos, kind:'mov'); el jefe los ve y puede deshacer uno.
   Se congela al cerrar el manifiesto (autorizar el packing list) o al cerrar la semana. */
const CAMA={RPC:[5,10],CTN:[6,10],CTN10:[14,15],PLT:[5,10]};
const CAL_COL={c250:'#e4572e',c230:'#f3a712',c200:'#3a86ff',c175:'#2a9d8f',c150:'#8338ec',c110:'#ff006e',ctn:'#8d99ae',m63:'#e4572e',m60:'#f3a712',m54:'#3a86ff',m48:'#2a9d8f',m42:'#8338ec',m36:'#ff006e',m28:'#6c757d'};
const TD={open:null,ck:null,q:null,prod:null,tipo:null,mv:null,rm:null};
function meU(){return (authUser&&authUser.user)||''}
function tdLock(m){return !m||manClosed(m)||orderLocked(m)}
function tdCan(m){return !tdLock(m)&&(isTarima()||(!ro&&canManClose()))}
/* el dibujo: camas de abajo hacia arriba; cada caja con el color de su calibre, la 1.5 más clara; lo que pasa del tope se marca */
function palDraw(p,big){
  const tp=palTipo(p),cm=CAMA[tp]||CAMA.RPC,base=cm[0],cap=palCap(tp),seq=[];
  (p.lines||[]).forEach(l=>{const n=Math.max(0,Math.floor(n0(l.cant))),ck=PCAL_KEY[l.cal]||'',q=lineQ(p,l);for(let i=0;i<n&&seq.length<600;i++)seq.push({ck:ck,q:q,de:!!l.de})});
  const rows=Math.max(Math.ceil(cap/base),Math.ceil(seq.length/base)),s=big?14:10,g=2,W=base*(s+g)+g,H=rows*(s+g)+g,capRows=Math.ceil(cap/base);
  let r='';for(let i=0;i<rows*base;i++){const row=Math.floor(i/base),col=i%base,x=g+col*(s+g),y=H-(row+1)*(s+g),b=seq[i],over=i>=cap;
    r+=b?`<rect x="${x}" y="${y}" width="${s}" height="${s}" rx="2" fill="${CAL_COL[b.ck]||'#999'}" fill-opacity="${b.q==='1.5'?0.45:1}"${over?' stroke="#f08c00" stroke-width="1.5"':''}${b.de?' stroke="currentColor" stroke-dasharray="2 1"':''}/>`
      :i<cap?`<rect x="${x}" y="${y}" width="${s}" height="${s}" rx="2" fill="none" stroke="currentColor" stroke-opacity=".25"/>`:''}
  const yc=H-capRows*(s+g);
  return `<svg class="tdsvg${big?' big':''}" viewBox="0 0 ${W} ${H}" role="img" aria-label="Tarima con ${fmt(seq.length)} de ${fmt(cap)} cajas">${r}${seq.length>cap?`<line x1="0" x2="${W}" y1="${yc}" y2="${yc}" stroke="#f08c00" stroke-width="1.5" stroke-dasharray="3 2"/>`:''}</svg>`;
}
function palCalSum(p){const g=new Map();(p.lines||[]).forEach(l=>{const ck=PCAL_KEY[l.cal];if(!ck||!(n0(l.cant)>0))return;const k=calLab(ck)+(lineQ(p,l)==='1.5'?' (1.5)':'');g.set(k,(g.get(k)||0)+n0(l.cant))});return [...g].map(([k,v])=>k+': '+fmt(v)).join(' · ')}
function tdLegend(tp){return `<div class="tdleg">${calsOfTipo(tp).map(c=>`<span><i style="background:${CAL_COL[c.k]}"></i>${esc(c.l)}</span>`).join('')}<span><i class="q15"></i>1.5 más claro</span></div>`}
function tdProdName(m,k){return (contProds(m).find(x=>x.k===k)||{}).n||k}
function conteoView(){
  const T=contTrips(),m=T.find(o=>o.id===CT.oid)||(T.length===1?T[0]:null);if(m)CT.oid=m.id;
  const trips=T.length?`<div class="pnopts">${T.map(o=>`<label class="pnopt"><input type="radio" name="ctrip" data-ctrip="${o.id}"${m&&m.id===o.id?' checked':''}><span><b class="mono">${esc(o.cod)}</b><small>${esc(EMPS[o.emp].name)} · ${esc(o.emb||'—')} · ${fmtDate(o.fecha)}</small></span></label>`).join('')}</div>`:'<p class="note">No hay viajes abiertos. Cuando el jefe de empaque abra uno, aparece aquí.</p>';
  let body='';
  if(m){const t=ensureTraz(m),tz=m.ctTurno||null,can=tdCan(m),tipo=TD.tipo||(tz&&tz.tipo)||'RPC';
    const all=t.tarimas.map((p,i)=>({p:p,i:i})),pals=all.filter(x=>palTipo(x.p)===tipo),cnt=k=>all.filter(x=>palTipo(x.p)===k).length;
    const turno=tz?`<div class="panel ctturno tdturno"><div><small>En turno</small><b>${esc(tz.prod)} · ${esc(tz.nombre||'')}</b></div><div><small>Calidad</small><b>${tz.q==='1.5'?'1.5':'Primera'}</b></div><div><small>Presentación</small><b>${esc(TIPO_L[tz.tipo]||tz.tipo)}</b></div></div>`
      :`<div class="panel warn"><strong>Falta el productor en turno</strong><p class="note">El jefe de empaque lo indica en Código de Trazabilidad. Mientras tanto puedes ver las tarimas.</p></div>`;
    const tabs=`<p class="note tdgn">Presentación de la tarima nueva:</p><div class="seg tdtabs" role="group" aria-label="Presentación de la tarima nueva">${TIPO_K.map(k=>`<button data-act="tdtipo:${k}" aria-pressed="${k===tipo}">${esc(TIPO_L[k])}${cnt(k)?' · '+cnt(k):''}</button>`).join('')}</div>`;
    /* v8.34: lugares fijos, de dos en dos; al quitar o mandar una al almacén su lugar queda libre y las demás no se recorren */
    const AL=armLayout(t),selA=SEL.k==='arm'&&SEL.pid?t.tarimas.find(x=>x.id===SEL.pid):null;
    const card=(p,s)=>{const tp_=palTipo(p),tot=palTot(p),cap=palCap(tp_),op=TD.open===p.id,mv=selA===p,act=selA&&!mv?'armput:'+s:'tdopen:'+p.id;return `<button class="tdcard${op?' on':''}${mv?' mv':''}${tp_!==tipo?' otro':''}" data-act="${act}" data-drop="arm:${s}"${can?` draggable="true" data-drag="${p.id}"`:''} aria-pressed="${op}" aria-label="${esc(palName(p))}, lugar ${s+1}, ${esc(TIPO_L[tp_])}, ${fmt(tot)} de ${fmt(cap)} cajas"><span class="tdh"><b>${esc(palName(p))}</b><small class="tdtp">${esc(TIPO_L[tp_])}</small><span class="chip${tot===cap?' good':tot>cap?' crit':tot?' warn':''}">${fmt(tot)}/${fmt(cap)}</span></span>${palDraw(p,false)}<small>Lugar ${s+1} · ${esc(palCalSum(p)||'Vacía')}</small></button>`};
    const slot=s=>selA?`<button class="tdcard tdslot tgt" data-act="armput:${s}" data-drop="arm:${s}"><b>Lugar ${s+1}</b><small>Poner aquí la ${esc(palName(selA))}</small></button>`:can?`<button class="tdcard tdslot" data-act="tdadd:${tipo}:${s}" data-drop="arm:${s}"><span class="tdplus">+</span><b>Lugar ${s+1} libre</b><small>Abrir tarima ${esc(TIPO_L[tipo])}</small></button>`:`<div class="tdcard tdslot" data-drop="arm:${s}"><b>Lugar ${s+1}</b><small>Libre</small></div>`;
    const grid=`<p class="note tdgn">Área de armado: cada tarima conserva su lugar. Cuando una se quita o se manda al almacén, su lugar queda libre.</p>${selA?`<div class="panel info selban" role="status"><span>Cambiando de lugar la <b>${esc(palName(selA))}</b>: toca un lugar libre, u otra tarima para intercambiarlas.</span><button class="btn sm" data-act="selx">Cancelar</button></div>`:''}<div class="tdgrid">${AL.map((p,s)=>p?card(p,s):slot(s)).join('')}</div>`;
    const cur_=all.find(x=>x.p.id===TD.open);
    const nAlm=almAll().length,tabU=TD.tab==='ubic';
    const ptabs=`<div class="seg tdptabs" role="tablist" aria-label="Área"><button role="tab" data-act="tdtab:arm" aria-selected="${!tabU}" aria-pressed="${!tabU}">Armado</button><button role="tab" data-act="tdtab:ubic" aria-selected="${tabU}" aria-pressed="${tabU}">Ubicación de tarimas${nAlm?' · '+nAlm:''}</button></div>`;
    body=`<div class="sec">Viaje ${esc(m.cod)}</div>${tdLock(m)?'<div class="panel warn"><strong>Manifiesto cerrado</strong><p class="note">Las tarimas ya no se pueden cambiar.</p></div>':''}${ptabs}${tabU?espHtml(m):`${turno}${tabs}${tdLegend(tipo)}${cur_&&palArm(cur_.p)?tdDetail(m,cur_.p,cur_.i,can):''}${grid}`}${tdMine(m)}`;
  }
  return topbar('Tarimas del viaje',isTarima()?'menu':'supback')+`<main class="wrap tdw">${supBan()}<div class="sec">Viaje</div>${trips}${body}${legalFoot()}</main>`;
}
function tdDetail(m,p,i,can){
  const tp=palTipo(p),tz=m.ctTurno||{},P=contProds(m),q=TD.q||tz.q||'1',pk=TD.prod||tz.prod||'',ck=TD.ck,cm=CAMA[tp]||CAMA.RPC,tot=palTot(p),cap=palCap(tp);
  const sh=sheetsOf(m),G=new Map();(p.lines||[]).forEach(l=>{if(!(n0(l.cant)>0))return;const k=(l.de?'de|':'')+lineQ(p,l)+'|'+(PCAL_KEY[l.cal]||l.cal)+'|'+resolveProd(sh,l.prod);let a=G.get(k);if(!a)G.set(k,a={k:k,q:lineQ(p,l),ck:PCAL_KEY[l.cal]||'',pk:resolveProd(sh,l.prod),de:!!l.de,n:0,by:new Set()});a.n+=n0(l.cant);if(l.by)a.by.add(l.by)});
  const others=ensureTraz(m).tarimas.map((x,j)=>({p:x,j:j})).filter(x=>x.p.id!==p.id&&palTipo(x.p)===tp);
  const rows=[...G.values()].map(a=>{const mv=TD.mv===a.k,rm=TD.rm===a.k;return `<div class="tdl"><span class="tdlc"><i style="background:${CAL_COL[a.ck]||'#999'}"></i></span><span class="tdlt"><b>${esc(calLab(a.ck))}${a.q==='1.5'?' · 1.5':''} · ${fmt(a.n)} cajas</b><small>${esc(a.pk)} · ${esc(tdProdName(m,a.pk))}${a.de?' · llegó de otro viaje':''}</small></span>${can&&!a.de?`<button class="btn sm" data-act="tdrm:${esc(a.k)}">${rm?'Cancelar':'Editar'}</button>`:''}${can&&others.length?`<button class="btn sm" data-act="tdmv:${esc(a.k)}">${mv?'Cancelar':'Mover'}</button>`:''}</div>${rm?`<div class="tdmv"><label class="fld"><span>Cajas correctas de este renglón</span><input class="in" id="tdrm-n" inputmode="numeric" value="${a.n}"></label><button class="btn sm primary" data-act="tdrmok:${esc(a.k)}">Guardar</button></div>`:''}${mv?`<div class="tdmv"><label class="fld"><span>A la tarima</span><select class="in sel" id="tdmv-to">${others.map(x=>`<option value="${x.p.id}">Tarima ${x.j+1} · ${fmt(palTot(x.p))}/${fmt(palCap(tp))}</option>`).join('')}</select></label><label class="fld"><span>Cajas</span><input class="in" id="tdmv-n" inputmode="numeric" value="${a.n}"></label><button class="btn sm primary" data-act="tdmvok:${esc(a.k)}">Mover cajas</button></div>`:''}`}).join('')||'<p class="note">Tarima vacía.</p>';
  const ctl=can?`<div class="tdctl"><label class="fld"><span>Productor</span><select class="in sel" data-tdprod="1"><option value="">— Elige productor —</option>${P.map(x=>`<option value="${esc(x.k)}"${x.k===pk?' selected':''}>${esc(x.k)} · ${esc(x.n)}${x.k===tz.prod?' (en turno)':''}</option>`).join('')}</select></label>
<div class="seg" role="group" aria-label="Calidad"><button data-act="tdq:1" aria-pressed="${q==='1'}">Primera</button><button data-act="tdq:1.5" aria-pressed="${q==='1.5'}">1.5</button></div>
<div class="tdcals" role="group" aria-label="Calibre">${calsOfTipo(tp).map(c=>`<button class="tdcal" data-act="tdck:${c.k}" aria-pressed="${c.k===ck}" style="--cc:${CAL_COL[c.k]}">${esc(c.l)}</button>`).join('')}</div>
<div class="tdbtns"><button class="btn" data-act="tdn:-1"${ck?'':' disabled'}>−1</button><button class="btn primary" data-act="tdn:1"${ck?'':' disabled'}>+1</button><button class="btn primary" data-act="tdn:${cm[0]}"${ck?'':' disabled'}>+ cama (${cm[0]})</button><span class="tdqty"><input class="in" id="td-n" inputmode="numeric" placeholder="Cajas" aria-label="Cajas a sumar"><button class="btn" data-act="tdn:x"${ck?'':' disabled'}>Sumar</button></span></div>${ck?'':'<p class="note">Elige el calibre de las cajas que vas a poner.</p>'}</div>`:'';
  const sl=armLayout(ensureTraz(m)).indexOf(p),acts=can?`<div class="pact tdacts"><button class="btn sm" data-act="armsel:${p.id}">${SEL.k==='arm'&&SEL.pid===p.id?'Cancelar cambio de lugar':'Cambiar de lugar'}</button>${tot>0?`<button class="btn sm primary" data-act="almsend:${p.id}">Mover a almacén</button>`:''}</div>`:'';
  return `<section class="panel tddet" id="tddet"><div class="tdh"><b>${esc(palName(p,i))} · ${esc(TIPO_L[tp])}${sl>=0?' · lugar '+(sl+1):''}</b><span class="chip${tot===cap?' good':tot>cap?' crit':tot?' warn':''}">${fmt(tot)} de ${fmt(cap)}</span><button class="btn sm" data-act="tdopen:">Cerrar</button></div>${acts}${tot>cap?`<p class="note warnt">Pasa ${fmt(tot-cap)} cajas del estándar de ${fmt(cap)}.</p>`:''}<div class="tdcols"><div class="tddraw">${palDraw(p,true)}</div><div class="tdright">${ctl}<div class="sec">Lo que lleva</div><div class="tdls">${rows}</div>${can&&!tot&&!(p.lines||[]).some(l=>l.de)?`<div class="pact"><button class="btn sm danger" data-act="tddel:${p.id}">Quitar tarima vacía</button></div>`:''}</div></div></section>`;
}
function tdMine(m){const L=CONT.list.filter(c=>c.kind==='mov'&&c.oid===m.id&&c.byU===meU()).sort((a,b)=>(b.at||0)-(a.at||0)).slice(0,8);if(!L.length)return '';
  return `<div class="sec">Tus últimos movimientos</div><div class="panel ctlist">${L.map(c=>`<div class="kv"><span>${esc(movTxt(c))}</span><span class="ctst">${c.undo?'<span class="chip crit">Deshecho por el jefe</span>':''}<small>${esc(fmtTs(c.at))}</small></span></div>`).join('')}</div>`}
function movTxt(c){const a=Math.abs(c.n||0),cal=c.ck?calLab(c.ck)+(c.q==='1.5'?' (1.5)':''):'',tn=c.fol?'Tarima '+c.fol:'la tarima '+(c.palN||'');
  if(c.k==='alm')return 'Flejó '+tn+' y la mandó al almacén ('+(c.lug||'')+')';if(c.k==='esp')return 'Movió '+tn+' en el almacén: '+(c.de||'')+' → '+(c.lug||'');if(c.k==='carg')return 'Cargó '+tn+' al thermo, lugar '+c.palN+' (salió de '+(c.de||'almacén')+')';if(c.k==='desf')return 'Desflejó '+tn+' y la regresó al área de armado';if(c.k==='arm')return 'Cambió '+tn+' del '+(c.de||'')+' al '+(c.lug||'');
  return c.k==='ord'?'Pasó la tarima '+c.palN+' al lugar '+c.toN:c.k==='new'?(c.fol?'Abrió la Tarima '+c.fol:'Abrió la tarima '+(c.palN||'')):c.k==='del'?'Quitó la tarima vacía '+(c.palN||''):c.k==='mov'?'Movió '+fmt(a)+' de '+cal+' de '+c.prod+' de la tarima '+c.palN+' a la '+c.toN:(c.n>0?'+':'−')+fmt(a)+' de '+cal+' de '+c.prod+' en la tarima '+c.palN}
/* un movimiento por toque; los toques seguidos del mismo renglón se juntan mientras no se hayan subido */
function movAdd(m,x){
  const last=CONT.list.filter(c=>c.kind==='mov'&&c.oid===m.id&&c.byU===meU()).sort((a,b)=>(b.at||0)-(a.at||0))[0];
  if(last&&x.k==='put'&&last.k==='put'&&last.pal===x.pal&&last.prod===x.prod&&last.q===x.q&&last.ck===x.ck&&Math.sign(last.n)===Math.sign(x.n)&&Date.now()-last.at<30000&&CONT.dirty.indexOf(last.id)>=0&&!last.undo){last.n+=x.n;last.at=Date.now();touchC(last);return}
  const c=Object.assign({id:uid(),kind:'mov',oid:m.id,emp:m.emp,cod:m.cod,at:Date.now(),by:whoName(),byU:meU(),estado:'mov'},x);CONT.list.push(c);touchC(c);
}
function tdM(){const m=orders.find(x=>x.id===CT.oid);return m&&tdCan(m)?m:null}
function tdAdd(tipo,s){
  const m=tdM();if(!m)return;const t=ensureTraz(m),tz=m.ctTurno||{},q=TD.q||tz.q||'1',L=armLayout(t);s=+s;if(!(s>=0&&s<L.length&&!L[s]))s=L.indexOf(null);
  const p={id:uid(),marca:marcaOfQ(m.emp,q),empaque:TIPO_L[tipo]?tipo:'RPC',lines:[],by:meU(),slot:s};t.tarimas.splice(t.tarimas.filter(x=>!x.alm).length,0,p);TD.open=p.id;TD.mv=null;touch(m);
  movAdd(m,{k:'new',pal:p.id,palN:t.tarimas.indexOf(p)+1,fol:palFol(p),tipo:p.empaque});render();toast(palName(p)+' abierta en el lugar '+(s+1));
}
function tdPut(v){
  const m=tdM();if(!m)return;const t=ensureTraz(m),p=t.tarimas.find(x=>x.id===TD.open);if(!p||lkStop(p))return;const tz=m.ctTurno||{};
  const pk=TD.prod||tz.prod,q=TD.q||tz.q||'1',ck=TD.ck;if(!pk){toast('Elige el productor');return}if(!ck){toast('Elige el calibre');return}
  let n=v==='x'?Math.floor(n0((document.getElementById('td-n')||{}).value)):+v;if(!n){toast('Escribe cuántas cajas');return}
  if(calsOfTipo(palTipo(p)).every(c=>c.k!==ck)){toast('Ese calibre no va en '+TIPO_L[palTipo(p)]);return}
  const sh=sheetsOf(m),me=meU(),rw=rwFor(m,pk,q),same=l=>!l.de&&lineQ(p,l)===q&&PCAL_KEY[l.cal]===ck&&resolveProd(sh,l.prod)===pk;
  p.lines=(p.lines||[]).filter(l=>l.cal||n0(l.cant)>0||String(l.prod||'').trim());
  if(n>0){const l=p.lines.find(x=>same(x)&&(x.by||'')===me&&(x.rw||'')===rw);if(l)l.cant=n0(l.cant)+n;else{const nl={id:uid(),q:q,cal:calLab(ck),cant:n,prod:pk,by:me};if(rw)nl.rw=rw;p.lines.push(nl)}}
  else{const L=p.lines.filter(same).sort((a,b)=>((b.rw||'')===rw)-((a.rw||'')===rw)||((b.by||'')===me)-((a.by||'')===me)),have=L.reduce((s,l)=>s+n0(l.cant),0);if(have<-n){toast(have?'Solo hay '+fmt(have)+' de esas cajas en la tarima':'No hay cajas de '+pk+' calibre '+calLab(ck)+' en esta tarima');return}
    let r=-n;L.forEach(l=>{const d=Math.min(r,n0(l.cant));l.cant=n0(l.cant)-d;r-=d});p.lines=p.lines.filter(l=>n0(l.cant)>0||(!l.cal&&String(l.prod||'').trim()))}
  syncMarca(m,p);touch(m);movAdd(m,{k:'put',pal:p.id,palN:t.tarimas.indexOf(p)+1,prod:pk,q:q,ck:ck,n:n});render();
  const tot=palTot(p),cap=palCap(palTipo(p));if(n>0&&tot>cap&&tot-n<=cap)toast('La tarima pasó el estándar de '+fmt(cap)+' cajas');
}
/* v8.35.7: editar un renglón de la tarima cuando se contó mal: se escriben las cajas correctas (más o menos) sin elegir productor y calibre arriba */
function tdRemove(k){
  const m=tdM();if(!m)return;const t=ensureTraz(m),p=t.tarimas.find(x=>x.id===TD.open);if(!p||!palArm(p))return;
  const [q,ck,pk]=k.split('|'),raw=String((document.getElementById('tdrm-n')||{}).value||'').trim(),want=Math.floor(+raw);if(raw===''||!(want>=0)||!isFinite(want)){toast('Escribe las cajas correctas (0 para quitarlas todas)');return}
  const sh=sheetsOf(m),me=meU(),L=(p.lines||[]).filter(l=>!l.de&&lineQ(p,l)===q&&PCAL_KEY[l.cal]===ck&&resolveProd(sh,l.prod)===pk),have=L.reduce((s,l)=>s+n0(l.cant),0),n=want-have;
  if(!n){TD.rm=null;render();return}
  if(n<0){let r=-n;L.sort((a,b)=>((b.by||'')===me)-((a.by||'')===me)).forEach(l=>{const d=Math.min(r,n0(l.cant));l.cant=n0(l.cant)-d;r-=d});p.lines=p.lines.filter(l=>n0(l.cant)>0||(!l.cal&&String(l.prod||'').trim()))}
  else{const rw=rwFor(m,pk,q),l=L.find(x=>(x.by||'')===me&&(x.rw||'')===rw)||L.find(x=>(x.rw||'')===rw)||L[0];if(l)l.cant=n0(l.cant)+n;else{const nl={id:uid(),q:q,cal:calLab(ck),cant:n,prod:pk,by:me};if(rw)nl.rw=rw;p.lines.push(nl)}}
  syncMarca(m,p);touch(m);movAdd(m,{k:'put',pal:p.id,palN:t.tarimas.indexOf(p)+1,fol:palFol(p),prod:pk,q:q,ck:ck,n:n});TD.rm=null;render();toast(calLab(ck)+' de '+pk+': '+fmt(have)+' → '+fmt(want)+' cajas en la '+palName(p));
}
/* v8.36.7: las cajas que llegaron de otro viaje también se mueven entre tarimas; siguen siendo de su viaje de origen (l.de) */
function tdMoveDe(m,t,p,to,k){
  if(lkStop(p)||lkStop(to))return;
  if(tdLock(m)){toast('El manifiesto de '+m.cod+' está cerrado');return}
  if(to.alm){toast('Esa tarima está en el almacén: desfléjala primero');return}
  const [q,ck,pk]=k.split('|'),n=Math.floor(n0((document.getElementById('tdmv-n')||{}).value));if(!(n>0)){toast('Escribe cuántas cajas');return}
  const sh=sheetsOf(m),L=(p.lines||[]).filter(l=>l.de&&n0(l.cant)>0&&lineQ(p,l)===q&&PCAL_KEY[l.cal]===ck&&resolveProd(sh,l.prod)===pk),have=L.reduce((s2,l)=>s2+n0(l.cant),0);if(n>have){toast('En la tarima hay '+fmt(have));return}
  sobUnimport(m,p);sobUnimport(m,to);to.lines=(to.lines||[]).filter(x=>x.cal||n0(x.cant)>0||String(x.prod||'').trim());
  let r=n;L.forEach(l=>{if(r<=0)return;const d=Math.min(r,n0(l.cant)),f=lineFrom(p,l);r-=d;l.cant=n0(l.cant)-d;
    const y=to.lines.find(z=>z.de===l.de&&z.prod===l.prod&&z.cal===l.cal&&lineQ(to,z)===q);
    if(y)y.cant=n0(y.cant)+d;else to.lines.push({id:uid(),q:q,cal:l.cal,cant:d,prod:l.prod,dn:l.dn||'',de:l.de,deCod:f.cod,dePn:f.n})});
  if(!to.from)to.from=Object.assign({},p.from||{oid:L[0].de,cod:lineFrom(p,L[0]).cod,n:lineFrom(p,L[0]).n});
  p.lines=p.lines.filter(l=>n0(l.cant)>0||(!l.de&&!l.cal&&String(l.prod||'').trim()));
  if(p.from&&!p.lines.some(l=>l.de&&n0(l.cant)>0)&&!palOwnLines(p).length)delete p.from;
  syncMarca(m,p);syncMarca(m,to);touch(m);sobImport(m,[p.id,to.id]);
  movAdd(m,{k:'mov',pal:p.id,palN:t.tarimas.indexOf(p)+1,to:to.id,toN:t.tarimas.indexOf(to)+1,prod:pk,q:q,ck:ck,n:n});
  logAdd({k:'note',ctx:ctxOf(m),lab:'Cajas de otro viaje cambiadas de tarima',o:palName(p,t.tarimas.indexOf(p)),n:palName(to,t.tarimas.indexOf(to))+' · '+fmt(n)+' cajas'});
  TD.mv=null;render();toast(fmt(n)+' cajas pasaron a la '+palName(to,t.tarimas.indexOf(to))+'; siguen siendo de su viaje de origen');
}
function tdMove(k){
  const m=tdM();if(!m)return;const t=ensureTraz(m),p=t.tarimas.find(x=>x.id===TD.open),to=t.tarimas.find(x=>x.id===(document.getElementById('tdmv-to')||{}).value);if(!p||!to)return;
  if(k.indexOf('de|')===0)return tdMoveDe(m,t,p,to,k.slice(3));
  const [q,ck,pk]=k.split('|'),n=Math.floor(n0((document.getElementById('tdmv-n')||{}).value));if(!(n>0)){toast('Escribe cuántas cajas');return}
  const sh=sheetsOf(m),L=(p.lines||[]).filter(l=>!l.de&&lineQ(p,l)===q&&PCAL_KEY[l.cal]===ck&&resolveProd(sh,l.prod)===pk),have=L.reduce((s,l)=>s+n0(l.cant),0);if(n>have){toast('En la tarima hay '+fmt(have));return}
  /* v8.36.10: cada caja conserva su renglón (l.rw) al cambiar de tarima */
  const me=meU();to.lines=(to.lines||[]).filter(x=>x.cal||n0(x.cant)>0||String(x.prod||'').trim());
  let r=n;L.forEach(l=>{if(r<=0)return;const d=Math.min(r,n0(l.cant));if(!d)return;l.cant=n0(l.cant)-d;r-=d;const rw=l.rw||'';
    const y=to.lines.find(x=>!x.de&&lineQ(to,x)===q&&PCAL_KEY[x.cal]===ck&&resolveProd(sh,x.prod)===pk&&(x.by||'')===me&&(x.rw||'')===rw);
    if(y)y.cant=n0(y.cant)+d;else{const nl={id:uid(),q:q,cal:calLab(ck),cant:d,prod:pk,by:me};if(rw)nl.rw=rw;to.lines.push(nl)}});
  p.lines=p.lines.filter(l=>n0(l.cant)>0||(!l.cal&&String(l.prod||'').trim()));
  syncMarca(m,p);syncMarca(m,to);touch(m);
  movAdd(m,{k:'mov',pal:p.id,palN:t.tarimas.indexOf(p)+1,to:to.id,toN:t.tarimas.indexOf(to)+1,prod:pk,q:q,ck:ck,n:n});TD.mv=null;render();toast(fmt(n)+' cajas pasaron a la tarima '+(t.tarimas.indexOf(to)+1));
}
/* v8.32: asistencia también cambia el orden del thermo, pero confirma antes (todos ven el orden nuevo) */
function tdOrdAsk(id,to){
  const m=tdM();if(!m)return;const t=ensureTraz(m),i=t.tarimas.findIndex(x=>x.id===id);to=Math.max(0,Math.min(t.tarimas.length-1,+to));if(i<0||to===i){render();return}if(lkStop(t.tarimas[i])||lkSnap(t.tarimas).some(f=>f[1]===to)&&(toast('Ese lugar es de una tarima bloqueada 🔒'),true)){render();return}
  TD.ord={id:id,to:to};sheet={kind:'confirm',title:'¿Estás seguro?',msg:'La tarima '+(i+1)+' pasa al lugar '+(to+1)+' del thermo y las demás se recorren.',extra:'Todos los asistentes y el jefe de empaque verán el orden nuevo.',ok:'Sí, cambiar el orden',act:'tdordok'};renderSheet();
}
function tdOrdDo(){
  const m=tdM(),o=TD.ord;TD.ord=null;sheet=null;renderSheet();if(!m||!o)return render();const t=ensureTraz(m),i=t.tarimas.findIndex(x=>x.id===o.id);if(i<0||o.to===i)return render();
  const x=t.tarimas[i];if(lkStop(x))return render();if(!lkMoveTo(t.tarimas,i,o.to)){toast('Ese lugar es de una tarima bloqueada 🔒');return render()}touch(m);movAdd(m,{k:'ord',pal:x.id,palN:i+1,toN:o.to+1});render();toast('Tarima '+(i+1)+' ahora en el lugar '+(o.to+1));
}
function tdDel(id){
  const m=tdM();if(!m)return;const t=ensureTraz(m),i=t.tarimas.findIndex(x=>x.id===id);if(i<0)return;const p=t.tarimas[i];if(lkStop(p))return;if(palTot(p)>0||(p.lines||[]).some(l=>l.de)){toast('Solo se quita una tarima vacía');return}
  t.tarimas.splice(i,1);TD.open=null;touch(m);movAdd(m,{k:'del',pal:id,palN:i+1,fol:palFol(p)});render();toast(palName(p,i)+' quitada: su lugar quedó libre');
}

/* ---------- v8.34 · Ubicación de tarimas ----------
   Cada tarima tiene un folio fijo (p.fol, «T07») y, mientras se arma, un lugar fijo en el área de armado (p.slot; 2 columnas × 6 filas):
   al quitar una tarima su lugar queda vacío y las demás no se recorren.
   «Mover a almacén» la fleja y la pone en un lugar de un espacio (p.alm={e,c,r}): ahí ya no se le cambian cajas, solo se arrastra.
   La tarima sigue siendo de su viaje (cuenta para sus productores), pero no sale en el packing list ni en el Código de Trazabilidad
   hasta que se carga al viaje (p.carg). En la lista del viaje las del almacén van siempre al final (palNorm, en touch). */
const ESP=[{e:1,c:3,r:8},{e:2,c:3,r:14},{e:3,c:3,r:10}];
const ARM_C=2,ARM_R=6;
const SEL={k:null,pid:null};
function palFol(p){return p&&+p.fol>0?'T'+pad(p.fol,2):''}
function palName(p,i){return p&&+p.fol>0?'Tarima '+palFol(p):'Tarima '+((i||0)+1)}
function palArm(p){return !!p&&!p.alm&&!p.carg}
/* v8.35.5: en un viaje contado en tarimas, al packing list (Código de Trazabilidad) solo van las tarimas cargadas desde el almacén
   (o las que llegaron de otro viaje). Las del área de armado y las del almacén siguen contando para sus productores. */
function palPL(m,p){return !!p&&!p.alm&&(!tdMode(m)||!!p.carg||!!p.from)}
function espLug(c,r){return (['A','B','C'][c]||'?')+(r+1)}
function palFind(pid){
  if(!pid)return null;
  for(const m of visible()){if(!isLeader(m)||!m.traz||!Array.isArray(m.traz.tarimas))continue;const i=m.traz.tarimas.findIndex(p=>p.id===pid);if(i>=0)return {m:m,p:m.traz.tarimas[i],i:i}}
  return null;
}
/* lugares del área de armado: cada tarima en su lugar; las que no tienen (o chocan) toman el primero libre. Siempre queda al menos un lugar libre */
function armLayout(t){
  const A=((t&&t.tarimas)||[]).filter(palArm),mx=A.reduce((a,p)=>Number.isInteger(p.slot)?Math.max(a,p.slot+1):a,0);
  const n=Math.max(ARM_C*ARM_R,Math.ceil(mx/ARM_C)*ARM_C,Math.ceil(A.length/ARM_C)*ARM_C),L=new Array(n).fill(null),rest=[];
  A.forEach(p=>{const s=p.slot;if(Number.isInteger(s)&&s>=0&&s<n&&!L[s])L[s]=p;else rest.push(p)});
  rest.forEach(p=>{let s=L.indexOf(null);if(s<0){s=L.length;for(let k=0;k<ARM_C;k++)L.push(null)}L[s]=p});
  if(L.indexOf(null)<0)for(let k=0;k<ARM_C;k++)L.push(null);
  return L;
}
/* folio a las que no tienen (una que llegó de otro viaje con un folio repetido toma uno nuevo), lugar a las de armado y las del almacén al final */
function palNorm(t,o){
  if(!t||!Array.isArray(t.tarimas)||!t.tarimas.length)return;const T=t.tarimas;
  let mx=T.reduce((a,p)=>Math.max(a,+p.fol||0),0);const seen=new Set();
  T.filter(p=>!p.from).concat(T.filter(p=>p.from)).forEach(p=>{if(!(+p.fol>0)||seen.has(+p.fol))p.fol=++mx;seen.add(+p.fol)});
  armLayout(t).forEach((p,s)=>{if(p&&p.slot!==s)p.slot=s});
  T.forEach(p=>{if(!palArm(p)&&p.slot!=null)delete p.slot});
  const N=T.filter(p=>palPL(o,p)).concat(T.filter(p=>!p.alm&&!palPL(o,p)),T.filter(p=>p.alm));if(N.some((p,i)=>p!==T[i]))t.tarimas=N;
}
function almAll(){const out=[];visible().forEach(m=>{if(!isLeader(m)||!m.traz||!Array.isArray(m.traz.tarimas))return;m.traz.tarimas.forEach(p=>{if(p.alm)out.push({m:m,p:p})})});return out}
/* mapa del almacén; si dos tarimas quedaron en el mismo lugar (dos teléfonos a la vez) se queda la que llegó primero y la otra sale «sin lugar» */
function espMap(){
  const A=almAll().sort((a,b)=>(a.p.alm.at||0)-(b.p.alm.at||0)),G={},sin=[];
  A.forEach(x=>{const a=x.p.alm,E=ESP.find(s=>s.e===+a.e),k=a.e+':'+a.c+':'+a.r;if(!E||!(a.c>=0&&a.c<E.c&&a.r>=0&&a.r<E.r)||G[k])sin.push(x);else G[k]=x});
  return {G:G,sin:sin,n:A.length};
}
/* quién mueve tarimas dentro del almacén: asistencia en tarimas, jefe de empaque, inocuidad y administración (no dirección) */
function espEd(m){if(!m||!authUser||orderLocked(m))return false;if(isTarima())return true;return !ro&&!roRole&&canManClose()}
/* lo que decide el jefe de empaque o la administración: desflejar y enviar a otro viaje */
function espAdm(m){return !!m&&!ro&&!roRole&&canManClose()&&!orderLocked(m)}
/* mandar al almacén o cargar al viaje: el viaje con su manifiesto abierto */
function almSendCan(m){return !!m&&!tdLock(m)&&(isTarima()||(!ro&&!roRole&&canManClose()))}
/* v8.35.6: el jefe de empaque (o la administración) decide qué tarimas suben al thermo / packing list; asistencia solo trabaja en armado y almacén */
function almLoadCan(m){return !!m&&!tdLock(m)&&!isTarima()&&!ro&&!roRole&&canManClose()}
function almOfTrip(m){return ((m&&m.traz&&m.traz.tarimas)||[]).filter(p=>p.alm)}

/* ---- mandar al almacén ---- */
function almSendOpen(pid){
  const f=palFind(pid);if(!f||!almSendCan(f.m)||lkStop(f.p))return;if(f.p.carg&&!almLoadCan(f.m)){toast('Solo el jefe de empaque regresa una tarima cargada al almacén');return}
  if(!(palTot(f.p)>0)){toast('La tarima está vacía: ponle cajas antes de mandarla al almacén');return}
  sheet={kind:'almsend',pid:pid,e:(sheet&&sheet.e)||1};renderSheet();
}
function espGridHtml(E,M,cell){
  let h=`<div class="espg" style="--er:${E.r}"><span></span>${Array.from({length:E.c},(_,c)=>`<span class="espch">${espLug(c,-1).slice(0,1)}</span>`).join('')}`;
  for(let r=0;r<E.r;r++){h+=`<span class="esprh">${r+1}</span>`;for(let c=0;c<E.c;c++)h+=cell(E,c,r,M.G[E.e+':'+c+':'+r])}
  return h+'</div>';
}
function almSendHtml(){
  const f=palFind(sheet.pid);if(!f)return '<p>La tarima ya no existe.</p><div class="srow2"><button class="btn" data-act="closesheet">Cerrar</button></div>';
  const p=f.p,tot=palTot(p),cap=palCap(palTipo(p)),M=espMap(),E=ESP.find(x=>x.e===+sheet.e)||ESP[0];
  const libre=s=>s.r*s.c-Object.keys(M.G).filter(k=>k.split(':')[0]===String(s.e)).length;
  const tabs=`<div class="seg" role="group" aria-label="Espacio">${ESP.map(s=>`<button data-act="almsp:${s.e}" aria-pressed="${s.e===E.e}">Espacio ${s.e} · ${fmt(libre(s))} libres</button>`).join('')}</div>`;
  const cell=(E,c,r,x)=>x?`<span class="espc occ" title="${esc(palName(x.p))} · ${esc(x.m.cod)}"><b>${esc(palFol(x.p))}</b><small>${esc(x.m.emp)}</small></span>`:`<button class="espc free" data-act="almput:${E.e}:${c}:${r}" aria-label="Lugar ${espLug(c,r)} del espacio ${E.e}">${espLug(c,r)}</button>`;
  return `<h3>Mover a almacén · ${esc(palName(p,f.i))}</h3><p class="note">${esc(f.m.cod)} · ${esc(TIPO_L[palTipo(p)]||'')} · ${fmt(tot)} cajas. Queda <b>flejada</b>: ya no se le cambian cajas, solo se acomoda. Para corregirla, el jefe de empaque la desfleja.</p>${tot<cap?`<div class="warnbox" role="note"><strong>Va incompleta</strong><div>Lleva ${fmt(tot)} de ${fmt(cap)} cajas.</div></div>`:''}${tabs}<p class="note" style="margin:8px 0">Toca el lugar donde la vas a dejar (columnas A, B y C).</p>${espGridHtml(E,M,cell)}<div class="srow2"><button class="btn" data-act="closesheet">Cancelar</button></div>`;
}
function almPut(e,c,r){
  const f=palFind(sheet&&sheet.pid);sheet=null;renderSheet();if(!f||!almSendCan(f.m))return render();
  e=+e;c=+c;r=+r;if(espMap().G[e+':'+c+':'+r]){toast('Ese lugar ya se ocupó. Elige otro');return render()}
  const p=f.p,m=f.m;p.alm={e:e,c:c,r:r,at:Date.now(),by:whoName()};p.flej={at:Date.now(),by:whoName()};delete p.carg;delete p.slot;
  touch(m);movAdd(m,{k:'alm',pal:p.id,palN:f.i+1,fol:palFol(p),lug:'espacio '+e+' · '+espLug(c,r)});
  logAdd({k:'note',ctx:ctxOf(m),lab:palName(p,f.i)+' al almacén',o:'',n:'Espacio '+e+' · '+espLug(c,r)+' · '+fmt(palTot(p))+' cajas'});
  if(TD.open===p.id)TD.open=null;if(palOpen===p.id)palOpen=null;SEL.k=SEL.pid=null;render();toast(palName(p)+' flejada en el espacio '+e+', lugar '+espLug(c,r));
}

/* ---- moverse dentro del almacén: tocar una tarima y luego un lugar (o arrastrar en computadora) ---- */
function espTap(pid){
  const f=palFind(pid);if(!f)return;
  if(SEL.k==='esp'&&SEL.pid&&SEL.pid!==pid){const a=f.p.alm;if(a)return espTo(SEL.pid,a.e,a.c,a.r)}
  SEL.k=SEL.pid===pid?null:'esp';SEL.pid=SEL.pid===pid?null:pid;render();
  if(SEL.pid){const d=document.getElementById('espdet');if(d)d.scrollIntoView({block:'nearest',behavior:'smooth'})}
}
function espTo(pid,e,c,r){
  e=+e;c=+c;r=+r;const f=palFind(pid);if(!f||!f.p.alm)return;if(!espEd(f.m)){toast('No puedes mover esta tarima');return}
  const a=f.p.alm;if(+a.e===e&&+a.c===c&&+a.r===r){SEL.k=SEL.pid=null;render();return}
  const x=espMap().G[e+':'+c+':'+r];
  if(x&&x.p!==f.p){sheet={kind:'almswap',pid:pid,oth:x.p.id,e:e,c:c,r:r};renderSheet();return}
  espSet(f,e,c,r);SEL.k=SEL.pid=null;render();toast(palName(f.p)+' al espacio '+e+', lugar '+espLug(c,r));
}
function espSet(f,e,c,r){
  const a=f.p.alm||{},de='espacio '+a.e+' · '+espLug(+a.c,+a.r);
  f.p.alm=Object.assign({},a,{e:e,c:c,r:r,at:Date.now(),by:whoName()});touch(f.m);
  movAdd(f.m,{k:'esp',pal:f.p.id,palN:f.i+1,fol:palFol(f.p),de:de,lug:'espacio '+e+' · '+espLug(c,r)});
}
function almSwapHtml(){
  const f=palFind(sheet.pid),x=palFind(sheet.oth);if(!f||!x)return '<p>Ya cambió el almacén.</p><div class="srow2"><button class="btn" data-act="closesheet">Cerrar</button></div>';
  return `<h3>El lugar ${espLug(sheet.c,sheet.r)} está ocupado</h3><p class="note">Ahí está la ${esc(palName(x.p))} de ${esc(x.m.cod)}. ¿Qué hacemos con la ${esc(palName(f.p))}?</p><div class="pnopts"><button class="btn primary" data-act="almhole">Abrir hueco aquí</button><small class="note">Las tarimas de la columna ${espLug(sheet.c,0).slice(0,1)} se recorren un lugar hacia donde haya espacio.</small><button class="btn" data-act="almswapok">Intercambiar</button><small class="note">La ${esc(palName(x.p))} pasa al lugar de la ${esc(palName(f.p))}.</small></div><div class="srow2"><button class="btn" data-act="closesheet">Cancelar</button></div>`;
}
function almSwapDo(){
  const s=sheet;sheet=null;renderSheet();const f=palFind(s&&s.pid),x=palFind(s&&s.oth);if(!f||!x||!f.p.alm||!x.p.alm)return render();
  if(!espEd(f.m)||!espEd(x.m)){toast('No puedes mover esas tarimas');return render()}
  const a=f.p.alm;espSet(x,+a.e,+a.c,+a.r);espSet(f,+s.e,+s.c,+s.r);SEL.k=SEL.pid=null;render();toast('Intercambiadas: '+palName(f.p)+' y '+palName(x.p));
}
/* abrir hueco: en esa columna se recorren las tarimas un lugar hacia el hueco libre más cercano (primero hacia abajo) */
function almHoleDo(){
  const s=sheet;sheet=null;renderSheet();const f=palFind(s&&s.pid);if(!f||!f.p.alm)return render();
  const e=+s.e,c=+s.c,r=+s.r,E=ESP.find(x=>x.e===e),M=espMap(),at=k=>{const x=M.G[e+':'+c+':'+k];return x&&x.p!==f.p?x:null};
  let fr=-1,dir=0;for(let k=r+1;k<E.r;k++)if(!at(k)){fr=k;dir=1;break}
  if(fr<0)for(let k=r-1;k>=0;k--)if(!at(k)){fr=k;dir=-1;break}
  if(fr<0){toast('La columna '+espLug(c,0).slice(0,1)+' está llena. Usa Intercambiar o elige otro lugar');return render()}
  const mv=[];for(let k=r;k!==fr;k+=dir){const x=at(k);if(x)mv.push({x:x,to:k+dir})}
  if(mv.some(y=>!espEd(y.x.m))||!espEd(f.m)){toast('No puedes mover esas tarimas');return render()}
  mv.reverse().forEach(y=>espSet(y.x,e,c,y.to));espSet(f,e,c,r);SEL.k=SEL.pid=null;render();
  toast(palName(f.p)+' en '+espLug(c,r)+'; se recorrieron '+mv.length+(mv.length===1?' tarima':' tarimas'));
}

/* ---- salir del almacén ---- */
function almLoad(pid){
  const f=palFind(pid);if(!f||!f.p.alm)return;const m=f.m;
  if(tdLock(m)){toast(manClosed(m)?'El manifiesto de '+m.cod+' ya se cerró: el jefe de empaque la puede enviar a otro viaje':wkLab(wkOf(m))+' está cerrada');return}
  if(!almLoadCan(m)){toast('Solo el jefe de empaque carga tarimas al viaje');return}
  const t=ensureTraz(m),p=f.p;t.tarimas.splice(f.i,1);const at=t.tarimas.filter(x=>palPL(m,x)).length,a=p.alm;
  delete p.alm;p.carg={at:Date.now(),by:whoName()};lkIns(t.tarimas,at,p);touch(m);
  movAdd(m,{k:'carg',pal:p.id,palN:at+1,fol:palFol(p),de:'espacio '+a.e+' · '+espLug(+a.c,+a.r)});
  logAdd({k:'note',ctx:ctxOf(m),lab:palName(p)+' cargada al viaje',o:'Espacio '+a.e+' · '+espLug(+a.c,+a.r),n:'Lugar '+(at+1)+' del thermo'});
  SEL.k=SEL.pid=null;render();toast(palName(p)+' cargada a '+m.cod+': lugar '+(at+1)+' del thermo');
}
function almNext(pid){
  const f=palFind(pid);if(!f||!f.p.alm||!espAdm(f.m))return;const p=f.p;
  if(p.from?!palFwdOk(p):!palNextOk(p)){toast('La tarima necesita cajas con calibre para pasar a otro viaje');return}
  curId=f.m.id;palNextSheet(pid);
}
function almUnflej(pid){
  const f=palFind(pid);if(!f||!espAdm(f.m))return;const m=f.m,p=f.p;
  if(tdLock(m)){toast('El manifiesto de '+m.cod+' está cerrado: reábrelo para corregir la tarima');return}
  const k='almdf:'+pid;if(confirmKey!==k){armConfirm(k);render();return}confirmKey=null;
  const de=p.alm?'Espacio '+p.alm.e+' · '+espLug(+p.alm.c,+p.alm.r):p.carg?'Cargada al thermo':'';
  delete p.alm;delete p.flej;delete p.carg;delete p.slot;const s=armLayout(ensureTraz(m)).indexOf(p);if(s>=0)p.slot=s;touch(m);
  movAdd(m,{k:'desf',pal:p.id,palN:f.i+1,fol:palFol(p)});logAdd({k:'note',ctx:ctxOf(m),lab:palName(p)+' desflejada',o:de,n:'Área de armado'});
  SEL.k=SEL.pid=null;render();toast(palName(p)+' regresó al área de armado: ya se le pueden cambiar cajas');
}

/* ---- área de armado: lugares fijos ---- */
function armSel(pid){const m=tdM();if(!m)return;SEL.k=SEL.pid===pid&&SEL.k==='arm'?null:'arm';SEL.pid=SEL.k?pid:null;render()}
function armPut(s){
  const m=tdM(),pid=SEL.pid;SEL.k=SEL.pid=null;if(!m)return render();const t=ensureTraz(m),p=t.tarimas.find(x=>x.id===pid);if(!p||!palArm(p))return render();
  s=+s;const L=armLayout(t),from=L.indexOf(p),o=L[s];if(from===s||!(s>=0))return render();if(lkStop(p)||lkStop(o))return render();
  if(o)o.slot=from;p.slot=s;touch(m);movAdd(m,{k:'arm',pal:p.id,palN:t.tarimas.indexOf(p)+1,fol:palFol(p),de:'lugar '+(from+1),lug:'lugar '+(s+1)});
  render();toast(palName(p)+' al lugar '+(s+1)+(o?'; '+palName(o)+' pasó al lugar '+(from+1):''));
}

/* ---- pantallas ---- */
function espCellHtml(E,c,r,x,M){
  const S=SEL.k==='esp'&&SEL.pid,lug=`espacio ${E.e}, lugar ${espLug(c,r)}`;
  if(!x)return S?`<button class="espc free tgt" data-act="espto:${E.e}:${c}:${r}" data-drop="esp:${E.e}:${c}:${r}" aria-label="Mover aquí: ${lug}">${espLug(c,r)}</button>`:`<span class="espc free" data-drop="esp:${E.e}:${c}:${r}" aria-label="Libre: ${lug}">${espLug(c,r)}</span>`;
  const p=x.p,on=SEL.pid===p.id,tot=palTot(p),cap=palCap(palTipo(p)),ed=espEd(x.m);
  return `<button class="espc occ${on?' on':''}${tot<cap?' inc':''}${x.m.emp==='EC'?' ec':''}" data-act="esptap:${p.id}" data-drop="esp:${E.e}:${c}:${r}"${ed?` draggable="true" data-drag="${p.id}"`:''} aria-pressed="${on}" aria-label="${esc(palName(p))}, ${esc(x.m.cod)}, ${esc(TIPO_L[palTipo(p)]||'')}, ${fmt(tot)} cajas, ${lug}"><b>${esc(palFol(p))}</b><small>${esc(x.m.emp)} ${esc(String(x.m.cod).split('-').pop())}</small><small>${esc(TIPO_L[palTipo(p)]||'')} ${fmt(tot)}</small></button>`;
}
function espDetHtml(){
  const f=SEL.k==='esp'&&palFind(SEL.pid);if(!f||!f.p.alm)return '';const p=f.p,m=f.m,a=p.alm,tot=palTot(p),cap=palCap(palTipo(p));
  const prods=[...new Set((p.lines||[]).filter(l=>n0(l.cant)>0).map(l=>{const k=resolveProd(sheetsOf(m),l.prod)||l.prod||'';return k+(l.dn||prodNameOf(sheetsOf(m),k)?' · '+(l.dn||prodNameOf(sheetsOf(m),k)):'')}))];
  const adm=espAdm(m),acts=[almLoadCan(m)?`<button class="btn sm primary" data-act="almload:${p.id}">Cargar a ${esc(m.cod)}</button>`:'',adm?`<button class="btn sm nextb" data-act="almnext:${p.id}">Enviar a otro viaje →</button>`:'',adm&&!tdLock(m)?`<button class="btn sm" data-act="almdf:${p.id}">${confirmKey==='almdf:'+p.id?'Toca otra vez para desflejar':'Desflejar para corregir'}</button>`:'',`<button class="btn sm" data-act="esptap:${p.id}">Listo</button>`].join('');
  return `<section class="panel espdet" id="espdet"><div class="tdh"><b>${esc(palName(p))} · ${esc(m.cod)}</b><span class="chip${tot===cap?' good':tot>cap?' crit':' warn'}">${fmt(tot)} de ${fmt(cap)}</span></div><div class="tdcols"><div class="tddraw">${palDraw(p,false)}</div><div><p class="note">${esc(EMPS[m.emp].name)} · ${esc(TIPO_L[palTipo(p)]||'')} · espacio ${a.e}, lugar ${espLug(+a.c,+a.r)}${p.flej?' · flejada por '+esc(p.flej.by||'—')+', '+esc(fmtTs(p.flej.at)):''}${manClosed(m)?' · <b>manifiesto cerrado</b>':''}</p><p class="note">${esc(palCalSum(p)||'')}</p><p class="note">${prods.map(esc).join('<br>')}</p>${espEd(m)?'<p class="note">Toca un lugar libre para moverla, u otra tarima para intercambiar o abrir hueco.</p>':''}<div class="pact">${acts}</div></div></div></section>`;
}
/* Ubicación de tarimas: los 3 espacios. m = el viaje de la pantalla (para la lista de cargadas), o null */
function espHtml(m){
  const M=espMap(),cnt=e=>Object.keys(M.G).filter(k=>k.split(':')[0]===String(e)).length,sel=SEL.k==='esp'&&SEL.pid?palFind(SEL.pid):null;
  const spaces=ESP.map(E=>`<section class="panel espw"><div class="tdh"><b>Espacio ${E.e}</b><small class="note">${E.c} columnas × ${E.r} · ${fmt(cnt(E.e))} de ${fmt(E.c*E.r)} ocupados</small></div>${espGridHtml(E,M,(E,c,r,x)=>espCellHtml(E,c,r,x,M))}</section>`).join('');
  const sin=M.sin.length?`<div class="warnbox" role="alert"><strong>Tarimas sin lugar · ${M.sin.length}</strong><p class="note">Dos tarimas quedaron en el mismo lugar. Tócala y elige un lugar libre.</p><div class="pact">${M.sin.map(x=>`<button class="btn sm${SEL.pid===x.p.id?' primary':''}" data-act="esptap:${x.p.id}">${esc(palName(x.p))} · ${esc(x.m.cod)}</button>`).join('')}</div></div>`:'';
  const ban=sel?`<div class="panel info selban" role="status"><span>Moviendo <b>${esc(palName(sel.p))}</b> de ${esc(sel.m.cod)}: toca un lugar libre, u otra tarima.</span><button class="btn sm" data-act="selx">Cancelar</button></div>`:`<p class="note tdgn">Toca una tarima para ver qué lleva y moverla. En computadora también se arrastra. Las tarimas del almacén ya están flejadas.</p>`;
  const car=m?ensureTraz(m).tarimas.map((p,i)=>({p:p,i:i})).filter(x=>x.p.carg&&!x.p.alm):[];
  const carH=m?`<div class="sec">Cargadas al thermo de ${esc(m.cod)}</div><div class="panel">${car.length?car.map(x=>`<div class="kv"><span><b>Lugar ${x.i+1}</b> · ${esc(palName(x.p))} · ${esc(TIPO_L[palTipo(x.p)]||'')} · ${fmt(palTot(x.p))} cajas</span>${almLoadCan(m)?`<button class="btn sm" data-act="almsend:${x.p.id}">Regresar al almacén</button>`:''}</div>`).join(''):'<p class="note">Todavía no se carga ninguna tarima desde el almacén.</p>'}</div>`:'';
  return `${ban}${sin}${espDetHtml()}<div class="espall">${spaces}</div>${carH}`;
}
let ESPF={from:null};
function espGo(id){ESPF.from=id||null;SEL.k=SEL.pid=null;view='esp';curId=null;sheet=null;renderSheet();render();window.scrollTo(0,0)}
function espBack(){const id=ESPF.from;ESPF.from=null;SEL.k=SEL.pid=null;if(id&&orders.some(o=>o.id===id)){curId=id;view='trazo'}else{curId=null;view='menu'}render();window.scrollTo(0,0)}
function espView(){
  const L=almAll(),nE=new Set(L.map(x=>x.m.emp)).size;
  return topbar('Ubicación de tarimas','espback')+`<main class="wrap tdw espv"><div class="panel info"><p class="note">Almacén de producto terminado de Vera Limes y Citrilar: ${fmt(L.length)} ${L.length===1?'tarima':'tarimas'}${nE>1?' de las dos empresas':''}. Cada tarima sigue siendo de su viaje y conserva a sus productores. ${espAdm(L[0]&&L[0].m)||(!ro&&canManClose())?'Desde aquí se cargan al thermo, se envían a otro viaje o se desflejan para corregir.':'Solo consulta.'}</p></div>${espHtml(null)}${legalFoot()}</main>`+navHtml();
}
/* en Código de Trazabilidad: lo que el viaje tiene en el almacén */
function espTrazHtml(m){
  const A=almOfTrip(m),tot=almAll().length;
  return `<div class="panel espz"><div class="espzh"><div><strong>Espacios de almacén</strong><p class="note">${A.length?fmt(A.length)+(A.length===1?' tarima de este viaje está':' tarimas de este viaje están')+' en el almacén (flejadas, no salen en el packing list hasta cargarlas)':'Ninguna tarima de este viaje en el almacén'} · ${fmt(tot)} en total.</p></div><button class="btn sm${A.length?' primary':''}" data-act="espgo:${m.id}">Espacios de almacén ›</button></div>${A.length?`<div class="espzl">${A.map(p=>`<span class="chip">${esc(palFol(p))} · E${p.alm.e} ${espLug(+p.alm.c,+p.alm.r)} · ${fmt(palTot(p))}</span>`).join('')}</div>`:''}</div>`;
}
/* arrastrar en computadora: una tarima a otro lugar del almacén o del área de armado */
(function(){
  let drag=null;
  $app.addEventListener('dragstart',e=>{const el=e.target.closest&&e.target.closest('[data-drag]');if(!el)return;drag=el.dataset.drag;try{e.dataTransfer.setData('text/plain',drag);e.dataTransfer.effectAllowed='move'}catch(x){}});
  $app.addEventListener('dragover',e=>{if(!drag)return;const el=e.target.closest&&e.target.closest('[data-drop]');if(el){e.preventDefault();try{e.dataTransfer.dropEffect='move'}catch(x){}}});
  $app.addEventListener('drop',e=>{const el=e.target.closest&&e.target.closest('[data-drop]');const pid=drag;drag=null;if(!el||!pid)return;e.preventDefault();const q=el.dataset.drop.split(':');
    if(q[0]==='esp')espTo(pid,q[1],q[2],q[3]);else if(q[0]==='arm'){SEL.k='arm';SEL.pid=pid;armPut(q[1])}});
  $app.addEventListener('dragend',()=>{drag=null});
})();
/* el jefe ve los movimientos de asistencia y puede deshacer uno (solo sumas, restas y movimientos de cajas) */
function movPanel(m){
  const L=CONT.list.filter(c=>c.kind==='mov'&&c.oid===m.id).sort((a,b)=>(b.at||0)-(a.at||0));if(!L.length)return '';
  const can=canManClose()&&!roRole&&!tdLock(m),show=TD.allMov?L:L.slice(0,6);
  return `<details class="panel ctpend tdmovp"${TD.movOpen?' open':''}><summary><strong>Movimientos de asistencia en tarimas · ${L.length}</strong><small>El último: ${esc(L[0].by||'—')}, ${esc(fmtTs(L[0].at))}</small></summary>${show.map(c=>`<div class="kv"><span>${esc(movTxt(c))}<small>${esc(c.by||'—')} · ${esc(fmtTs(c.at))}</small></span><span class="ctst">${c.undo?`<span class="chip crit">Deshecho</span>`:can&&(c.k==='put'||c.k==='mov')?`<button class="btn sm" data-act="movundo:${c.id}">Deshacer</button>`:''}</span></div>`).join('')}${L.length>6&&!TD.allMov?'<button class="btn sm" data-act="movall">Ver todos</button>':''}</details>`;
}
function movUndo(id){
  const c=CONT.list.find(x=>x.id===id);if(!c||c.undo||!canManClose()||roRole)return;const m=orders.find(x=>x.id===c.oid);if(!m||tdLock(m))return;
  const t=ensureTraz(m),sh=sheetsOf(m),p=t.tarimas.find(x=>x.id===c.pal);if(!p){toast('Esa tarima ya no existe');return}
  const take=(P,n)=>{const L=(P.lines||[]).filter(l=>!l.de&&lineQ(P,l)===c.q&&PCAL_KEY[l.cal]===c.ck&&resolveProd(sh,l.prod)===c.prod),have=L.reduce((s,l)=>s+n0(l.cant),0);if(have<n)return false;let r=n;L.forEach(l=>{const d=Math.min(r,n0(l.cant));l.cant=n0(l.cant)-d;r-=d});P.lines=P.lines.filter(l=>n0(l.cant)>0||(!l.cal&&String(l.prod||'').trim()));return true};
  if(c.k==='put'){if(c.n>0){if(!take(p,c.n)){toast('Esas cajas ya no están en la tarima');return}}else palPut(m,p,c.q,c.ck,c.prod,-c.n)}
  else if(c.k==='mov'){const to=t.tarimas.find(x=>x.id===c.to);if(!to||!take(to,c.n)){toast('Esas cajas ya no están en la tarima '+c.toN);return}palPut(m,p,c.q,c.ck,c.prod,c.n)}
  else return;
  syncMarca(m,p);touch(m);c.undo={by:whoName(),at:Date.now()};touchC(c);
  logAdd({k:'note',ctx:ctxOf(m),lab:'Movimiento de asistencia deshecho',o:c.by||'',n:movTxt(c)});render();toast('Movimiento deshecho');
}

/* ---------- v8.32 · viaje «contado en tarimas»: el jefe valida productor por productor ----------
   En ese modo las cajas de cada productor salen de las tarimas (sin las que llegaron de otro viaje).
   Al validar se guardan en p.tdc {tipo:{calibre:n}} y las casillas del contador se rehacen solas como acumulado,
   para que Excel, manifiesto y pagos sigan igual. Lo no validado vale cero. */
function tdMode(o){const m=o&&mainOf(o);return !!(m&&m.cntTar)}
function tdRowOk(p){return !(p.rmp||p.sob||p.sob2||p.segLot||p.c23||+p.codigo===SEG_COD)}
/* v8.36.10: el mismo productor puede venir en dos renglones (una entrega ayer y otra hoy). Cada caja que asistencia acomoda
   guarda el renglón en turno (l.rw); las que no lo tienen (las de antes) son del primer renglón de ese productor */
function rwDups(s,k){return (s.productores||[]).filter(x=>tdRowOk(x)&&prodKey(s,x)===k)}
function rwOwns(s,p,D,l){if(D.length<2)return true;const ids=D.map(x=>x.id);return l.rw&&ids.indexOf(l.rw)>=0?l.rw===p.id:D[0]===p}
function rwFor(m,pk,q){const tz=m.ctTurno||{},s=sheetsOf(m).find(x=>(x.variante==='1.5'?'1.5':'1')===q),D=s?rwDups(s,pk):[];if(D.length<2)return '';if(tz.rw&&tz.prod===pk&&(tz.q||'1')===q&&D.some(x=>x.id===tz.rw))return tz.rw;return D[D.length-1].id}
/* el renglón que recibe las cajas de asistencia: el guardado en el turno o, si no hay, el último de ese productor (igual que rwFor) */
function rwTurnoIs(o,tz,p){const D=rwDups(o,tz.prod);if(D.length<2)return true;const ids=D.map(x=>x.id);return (tz.rw&&ids.indexOf(tz.rw)>=0?tz.rw:D[D.length-1].id)===p.id}
function tdFromPal(s,p){
  const m=mainOf(s),sh=sheetsOf(m),k=prodKey(s,p),q=s.variante==='1.5'?'1.5':'1',out={},D=rwDups(s,k);let tot=0;
  const add=(P,l)=>{const n=n0(l.cant),ck=PCAL_KEY[l.cal];if(!(n>0)||!ck||lineQ(P,l)!==q||!rwOwns(s,p,D,l))return;const tp=lineType(palTipo(P),ck);(out[tp]=out[tp]||{})[ck]=(out[tp][ck]||0)+n;tot+=n};
  ensureTraz(m).tarimas.forEach(P=>(P.lines||[]).forEach(l=>{if(!l.de&&resolveProd(sh,l.prod)===k)add(P,l)}));
  /* v8.35.1: las cajas que este viaje mandó a otro siguen siendo de su hoja de procedencia (su primer empaque) */
  (deOut(m.id)).forEach(x=>{if(x.l.prod===k||resolveProd(sh,x.l.prod)===k)add(x.P,x.l)});
  return {by:out,t:tot};
}
/* cajas con hoja de procedencia en otro viaje (l.de), agrupadas por el viaje de origen; se rehace cuando cambian los datos */
const DEO={v:-1,map:null};
function deOut(oid){
  if(DEO.v!==DATAV||!DEO.map){const M=new Map();visible().forEach(o=>{const t=o.traz;if(!t||!Array.isArray(t.tarimas))return;t.tarimas.forEach(P=>(P.lines||[]).forEach(l=>{if(!l.de||l.de===o.id)return;let a=M.get(l.de);if(!a)M.set(l.de,a=[]);a.push({P:P,l:l})}))});DEO.map=M;DEO.v=DATAV}
  return DEO.map.get(oid)||[];
}
function tdcTxt(by){const a=[];TIPO_K.forEach(tp=>{const x=by&&by[tp];if(!x)return;const s=CAL.filter(c=>x[c.k]).map(c=>c.l+': '+fmt(x[c.k])).join(', ');if(s)a.push(TIPO_L[tp]+' '+s)});return a.join(' · ')||'sin cajas'}
function tdSame(a,b){const k=x=>JSON.stringify(TIPO_K.map(tp=>CAL.map(c=>(x&&x[tp]&&x[tp][c.k])||0)));return k(a)===k(b)}
/* v8.36.8: el acumulado también lleva lo de los renglones que no salen de las tarimas (SOBRANTES, segundas…).
   Antes se los saltaba: un productor validado debajo de SOBRANTES quedaba con un acumulado menor al de arriba y salía en negativo. */
function accRebuild(s){
  if(!tdMode(s))return;const run={},rows=s.productores||[];
  const keep=new Map();rows.forEach(p=>{if(!p.rmp&&!tdRowOk(p))keep.set(p,rowDeltas(s,p))});
  rows.forEach(p=>{if(p.rmp)return;
    if(!tdRowOk(p)){const D=keep.get(p)||{},was=JSON.stringify([p.acc||{},p.accX||{}]);
      tiposOf(p).forEach(tp=>{const d=D[tp]||{},r=run[tp]=run[tp]||{},a=accOf(p,tp,true);CAL.forEach(c=>{const n=n0(d[c.k]);if(n){r[c.k]=(r[c.k]||0)+n;a[c.k]=r[c.k]}else if(a[c.k]!=null)a[c.k]=r[c.k]||0})});
      if(JSON.stringify([p.acc||{},p.accX||{}])!==was)delete p.accx;return}
    const by=p.tdc||{},ts=TIPO_K.filter(tp=>by[tp]&&CAL.some(c=>by[tp][c.k]>0));
    if(ts.length)p.tipos=ts;p.acc={};p.accX={};delete p.accx;
    ts.forEach(tp=>{const r=run[tp]=run[tp]||{},a=accOf(p,tp,true);CAL.forEach(c=>{const n=n0(by[tp][c.k]);if(n>0){r[c.k]=(r[c.k]||0)+n;a[c.k]=r[c.k]}})})});
}
/* v8.36.8: al abrir, los viajes «contados en tarimas» donde un productor validado no cuadra con lo validado se rehacen solos */
/* ---------- v8.37.1 · cajas de un renglón de ESTE viaje marcadas como «de otro viaje» ----------
   Pasó el 1-nov: asistencia acomodó cajas de NOE BIELMA (entrega del domingo) en tarimas de EC-190 que luego se mandaron a EC-191,
   y después el renglón del productor se movió a EC-191. Esas cajas llevan la marca de su renglón (l.rw), así que si el renglón
   está en el viaje que tiene la tarima, son de ese viaje: se les quita el «viene de» y salen de SOBRANTES. */
function rwOwnFix(m){
  if(!m||m.deleted||mainOf(m)!==m||orderLocked(m))return 0;const t=m.traz;if(!t||!Array.isArray(t.tarimas))return 0;
  const ids=new Set();sheetsOf(m).forEach(s=>(s.productores||[]).forEach(p=>ids.add(p.id)));let n=0;const P=[];
  t.tarimas.forEach(p=>{const L=(p.lines||[]).filter(l=>l.de&&l.de!==m.id&&l.rw&&ids.has(l.rw));if(!L.length)return;
    sobUnimport(m,p);L.forEach(l=>{delete l.de;delete l.deCod;delete l.dePn;delete l.dn;n+=n0(l.cant)});
    if(p.from&&!(p.lines||[]).some(l=>l.de&&n0(l.cant)>0))delete p.from;P.push(p.id)});
  if(!n)return 0;sobImport(m,P);touch(m);
  logAdd({k:'note',ctx:ctxOf(m),lab:'Cajas de este viaje que estaban marcadas como de otro viaje',o:'',n:fmt(n)+' cajas en '+P.length+(P.length===1?' tarima':' tarimas')+'; salen de SOBRANTES'});
  return n;
}
/* ---------- v8.37.1 · corrección de los viajes EC-2026-189 a 191 (internet caído el 1-nov) ----------
   Se aplica una sola vez, desde el Código de Trazabilidad de EC-2026-191, por el jefe de empaque o administración.
   Cada paso revisa que el dato siga como estaba en el respaldo del 3-nov; si ya cambió, ese paso no hace nada. */
const FIX1101={b:'mvy6jzo3s6h2g',a:'mvwpuow3yx38l',s9:'mvwgq0fshrjzq',r9:'mvwi0s57wom8v',m9:'mvvkm84kxeh99',
  saul:[['mvy7lpu7lxred','mvy7m8a25innd',19,'150'],['mvy6yuku5gdst','mvy7ov1pgsfkl',12,'110']],
  noe:[['mvy7s3ftstzy2','mvy7sb7rgshuz',13,'250'],['mvy7pv06kxkix','mvy7pv06ua9n4',6,'150']],
  load:['mvy7tzmc4kii9','mvy7tn6xrgmmg','mvy7t9guvzb5a','mvy7t0pg3x2hb','mvy7s3ftstzy2','mvy7pv06kxkix','mvy7qyslo4x3n','mvy7lpu7lxred','mvy6yuku5gdst','mvy7ucziqv8h6']};
function fix1101On(m){return !!m&&m.id===FIX1101.b&&!m.fix1101&&!m.deleted&&canManClose()&&!ro}
function fix1101Html(m){
  if(!fix1101On(m))return '';
  return `<div class="panel warn"><strong>Corrección pendiente · viajes EC-2026-189, 190 y 191</strong><p class="note">El 1 de noviembre se cayó el internet y quedaron cajas con el viaje o el productor equivocado. Las cajas que salieron cuadran con los manifiestos; esto solo corrige a quién y a qué viaje pertenecen:</p>
<div class="kv"><span>143 cajas de NOE BIELMA (entrega del domingo) que decían «de EC-2026-190»</span><b>pasan a EC-2026-191</b></div>
<div class="kv"><span>31 cajas de SAUL QUIÑONES (150: 19, 110: 12) capturadas como de este viaje</span><b>son de EC-2026-190</b></div>
<div class="kv"><span>19 cajas marcadas NOE BIELMA (250: 13, 150: 6) que son de SAUL QUIÑONES</span><b>SAUL · de EC-2026-190</b></div>
<div class="kv"><span>10 tarimas (folios 31, 40 a 48) que salieron en el thermo</span><b>de almacén a thermo</b></div>
<div class="kv"><span>CITRILAR SEGUNDAS capturado a mano en la hoja 1.5 de EC-2026-189 (274 cajas, repetidas de EC-2026-188)</span><b>se quita y entran sus SOBRANTES (272)</b></div>
<p class="note">Queda anotado en el registro de cambios. Se aplica una sola vez.</p><div class="pact"><button class="btn primary" data-act="fix1101" data-edit>Aplicar corrección</button></div></div>`;
}
function fix1101Do(){
  const B=orders.find(x=>x.id===FIX1101.b),A=orders.find(x=>x.id===FIX1101.a);if(!B||!A||!fix1101On(B))return;
  const t=ensureTraz(B),now=Date.now(),by=whoName(),log=[];let ch=false;
  const pal=id=>t.tarimas.find(x=>x.id===id);
  /* 1. NOE del domingo: por su marca de renglón */
  const n1=rwOwnFix(B);if(n1)log.push(fmt(n1)+' cajas NOE BIELMA a EC-2026-191');
  /* 2. y 3. cajas de SAUL QUIÑONES (EC-013) de EC-190 */
  const deA=(p,l)=>{l.prod='EC-013';l.dn='SAUL QUIÑONES';l.de=A.id;l.deCod=A.cod;l.dePn=null;delete l.rw;if(!p.from)p.from={oid:A.id,cod:A.cod,n:null,at:now}};
  const P=[];
  FIX1101.saul.forEach(([pid,lid,n,cal])=>{const p=pal(pid),l=p&&(p.lines||[]).find(x=>x.id===lid);if(!l||l.de||l.prod!=='EC-013'||n0(l.cant)!==n||l.cal!==cal)return;sobUnimport(B,p);deA(p,l);P.push(p.id);ch=true});
  let s2=0;FIX1101.noe.forEach(([pid,lid,n,cal])=>{const p=pal(pid),l=p&&(p.lines||[]).find(x=>x.id===lid);if(!l||l.de||l.prod!=='EC-020'||l.cal!==cal||n0(l.cant)<n)return;sobUnimport(B,p);
    if(n0(l.cant)===n)deA(p,l);else{l.cant=n0(l.cant)-n;const nl={id:uid(),q:'1',cal:cal,cant:n};p.lines.push(nl);deA(p,nl)}if(P.indexOf(p.id)<0)P.push(p.id);s2+=n;ch=true});
  if(P.length){sobImport(B,P);log.push('50 cajas de SAUL QUIÑONES como sobrante de EC-2026-190')}
  /* 4. las tarimas que salieron en el thermo */
  let nl=0;FIX1101.load.forEach(id=>{const p=pal(id);if(!p||!p.alm)return;delete p.alm;delete p.slot;p.carg={at:now,by:by};nl++;ch=true});
  if(nl)log.push(nl+' tarimas cargadas al thermo');
  /* 5. segunda duplicada en EC-189 */
  const S9=orders.find(x=>x.id===FIX1101.s9),M9=orders.find(x=>x.id===FIX1101.m9);
  if(S9&&M9&&!orderLocked(M9)){const i=(S9.productores||[]).findIndex(p=>p.id===FIX1101.r9&&!p.sob2&&n0(p.k18)===274);
    if(i>=0){logAdd({k:'del',what:'p',ctx:ctxOf(S9),snap:clone(S9.productores[i]),lab:'Productor CITRILAR SEGUNDAS (repetido de EC-2026-188)'});rowOut(S9,S9.productores[i],rowDeltas(S9,S9.productores[i]));touch(S9);
      const c=sobImport(M9);log.push('EC-2026-189: CITRILAR SEGUNDAS repetido quitado; '+fmt(c)+' cajas a SOBRANTES 1.5');ch=true}}
  B.fix1101={at:now,by:by};touch(B);touch(A);
  logAdd({k:'note',ctx:ctxOf(B),lab:'Corrección de viajes EC-2026-189 a 191 (internet caído el 1-nov)',o:'',n:log.join(' · ')||'sin cambios'});
  render();toast('Corrección aplicada'+(log.length?': '+log.join(' · '):''));
}
function accRepairAll(){
  try{orders.forEach(m=>{try{if(!m.deleted&&mainOf(m)===m&&!manClosed(m))rwOwnFix(m)}catch(e){}})}catch(e){}
  try{orders.forEach(s=>{if(s.deleted||!tdMode(s)||orderLocked(s)||manClosed(mainOf(s)))return;
    const M=compute(s),bad=M.rows.some(r=>{const p=r.p;if(!tdRowOk(p)||!p.tdv)return false;const by=p.tdc||{};return r.tipos.some(tp=>CAL.some(c=>n0(r.byT[tp].delta[c.k])!==n0(by[tp]&&by[tp][c.k])))});
    if(bad){accRebuild(s);touch(s);logAdd({k:'note',ctx:ctxOf(s),lab:'Registro de Empaque: acumulado rehecho',o:'',n:'Productores validados debajo de SOBRANTES'})}})}catch(e){}
}
/* v8.33 · Turno para asistencia en tarimas desde el Registro de Empaque.
   Al agregar un productor queda en turno si todavía no hay nadie; el tipo de empaque que elige el jefe pasa al turno;
   y cada ficha tiene «Poner en turno». Las cajas que acomoda asistencia son las tarimas del Código de Trazabilidad. */
function turnoCan(o){const m=o&&mainOf(o);return !!m&&!ro&&!roRole&&canManClose()&&!manClosed(m)&&!orderLocked(o)}
function turnoSet(o,p,tipo,force){
  if(!p||!turnoCan(o)||!tdRowOk(p))return false;const m=mainOf(o);if(!force&&m.ctTurno&&m.ctTurno.prod)return false;
  const ts=tiposOf(p),tp=TIPO_L[tipo]?tipo:(ts.indexOf(m.ctTurno&&m.ctTurno.tipo)>=0?m.ctTurno.tipo:ts[0]||'RPC');
  const old=m.ctTurno?m.ctTurno.prod+(m.ctTurno.rw?'#'+m.ctTurno.rw:'')+' · '+(TIPO_L[m.ctTurno.tipo]||m.ctTurno.tipo):'';
  m.ctTurno={q:o.variante==='1.5'?'1.5':'1',tipo:tp,prod:prodKey(o,p),rw:p.id,nombre:p.nombre||'',at:Date.now(),by:whoName()};touch(m);
  const nw=m.ctTurno.prod+'#'+p.id+' · '+TIPO_L[tp];if(old!==nw)logAdd({k:'note',ctx:ctxOf(m),lab:'En turno para asistencia en tarimas',o:old,n:nw});
  return true;
}
function turnoRowHtml(o,p){
  if(!tdRowOk(p)||!isLeader(mainOf(o)))return '';const m=mainOf(o),tz=m.ctTurno,on=!!(tz&&tz.prod===prodKey(o,p)&&(tz.q||'1')===(o.variante==='1.5'?'1.5':'1')&&rwTurnoIs(o,tz,p));
  if(on)return `<div class="scrow trow on"><div><b>En turno para asistencia en tarimas</b><small>${esc(tz.q==='1.5'?'1.5':'Primera')} · ${esc(TIPO_L[tz.tipo]||tz.tipo)}. Asistencia acomoda sus cajas en las tarimas del Código de Trazabilidad.</small></div><span class="chip good">En turno</span></div>`;
  if(!turnoCan(o))return '';
  return `<div class="scrow trow"><div><b>Asistencia en tarimas</b><small>${tz&&tz.prod?'En turno ahora: '+esc(tz.nombre||tz.prod):'Nadie en turno'}</small></div><button class="btn sm" data-act="turnop:${o.id}:${p.id}">Poner en turno</button></div>`;
}
function tdRowHtml(o,p){
  if(!tdMode(o)||!tdRowOk(p))return '';
  const P=tdFromPal(o,p),v=p.tdv,same=v&&tdSame(p.tdc,P.by),can=!ro&&!orderLocked(o)&&canManClose();
  const r=compute(o).rows.find(x=>x.p===p),kg=num(p.kilos),rend=r&&r.rend;
  const rTxt=kg==null?'Sin kilos de báscula todavía: puedes validar y el rendimiento sale cuando los captures.':rend==null?'':'Rendimiento de primeras: '+fmt(rend*100,1)+'%'+(rend>1?' · pasa de 100%, revisa kilos o cajas':'');
  const aj=v&&v.aj&&!same,ak=o.id+':'+p.id,op=can&&TDA.open===ak;
  return `<div class="scrow tdrow${same?' ok':''}"><div><b>Cajas en tarimas</b><small>${fmt(P.t)} cajas · ${esc(tdcTxt(P.by))}</small>${v?(same?`<span class="chip good">Validado por ${esc(v.by||'—')}, ${esc(fmtTs(v.at))}</span>${v.up?`<small>Actualizado desde las tarimas por ${esc(v.up.by||'—')}, ${esc(fmtTs(v.up.at))}</small>`:''}`:aj?`<span class="chip info">Ajustado por ${esc(v.aj.by||'—')}, ${esc(fmtTs(v.aj.at))}: ${esc(tdcTxt(p.tdc))}</span>`:`<span class="chip warn">Cambió en tarimas desde que lo validaste (${esc(tdcTxt(p.tdc))})</span>`):'<span class="chip warn">Sin validar: en el registro vale cero</span>'}${rTxt?`<small class="${rend>1?'warnt':''}">${esc(rTxt)}</small>`:''}</div>${can?`<div class="pact"><button class="btn sm primary" data-act="tdval:${o.id}:${p.id}">${v&&!same?'Usar lo de tarimas':v?'Validar otra vez':'Validar y pasar al siguiente'}</button><button class="btn sm" data-act="tdaj:${ak}" aria-expanded="${op}">${op?'Cancelar ajuste':'Ajustar cifras'}</button></div>`:''}${op?tdAjHtml(o,p,P):''}</div>`;
}
function tdValidate(oid,pid){
  const o=orders.find(x=>x.id===oid),p=o&&(o.productores||[]).find(x=>x.id===pid);if(!p||ro||orderLocked(o)||!canManClose()||!tdMode(o))return;
  const P=tdFromPal(o,p),old=p.tdv?tdcTxt(p.tdc):'sin validar',first=!p.tdv;p.tdc=P.by;p.tdv={at:Date.now(),by:whoName()};accRebuild(o);touch(o);
  logAdd({k:'note',ctx:ctxOf(o),lab:'Productor validado con tarimas · '+(p.nombre||''),o:old,n:tdcTxt(P.by)});
  /* pasa al siguiente productor sin validar de la misma hoja */
  const m=mainOf(o),L=(o.productores||[]).filter(tdRowOk),nx=L.slice(L.indexOf(p)+1).find(x=>!x.tdv);
  if(first&&nx){const tz=Object.assign({q:o.variante==='1.5'?'1.5':'1',tipo:(m.ctTurno&&m.ctTurno.tipo)||tiposOf(nx)[0]||'RPC'},{prod:prodKey(o,nx),nombre:nx.nombre||'',at:Date.now(),by:whoName()});m.ctTurno=tz;touch(m)}
  render();toast(first&&nx?'Validado. En turno: '+(nx.nombre||prodKey(o,nx)):'Validado: '+fmt(P.t)+' cajas de tarimas');
}
/* v8.34: el jefe de empaque y la administración corrigen las cifras de un productor aunque ya estén validadas (cuando faltan cajas, etc.).
   El ajuste se guarda como lo validado (p.tdc) con quién y cuándo; las casillas del contador se rehacen solas. */
const TDA={open:null};
function tdAjHtml(o,p,P){
  const by=p.tdv?(p.tdc||{}):P.by,ts=TIPO_K.filter(tp=>(by[tp]&&CAL.some(c=>by[tp][c.k]>0))||(P.by[tp]&&CAL.some(c=>P.by[tp][c.k]>0))||tiposOf(p).indexOf(tp)>=0);
  const blk=tp=>`<div class="tdaj"><b>${esc(TIPO_L[tp])}</b><div class="tdajg">${calsOfTipo(tp).map(c=>{const v=(by[tp]&&by[tp][c.k])||0,t0=(P.by[tp]&&P.by[tp][c.k])||0;return `<label class="fld"><span>${esc(c.l)}${t0!==v?` <small>(tarimas ${fmt(t0)})</small>`:''}</span><input class="in" inputmode="numeric" data-tdaj="${tp}:${c.k}" value="${v||''}" placeholder="0" aria-label="${esc(TIPO_L[tp])} ${esc(c.l)}"></label>`}).join('')}</div></div>`;
  return `<div class="tdajw" id="tdaj-${p.id}"><p class="note">Escribe las cajas correctas de este productor. Queda como validado con tu nombre; las tarimas no cambian.</p>${ts.map(blk).join('')}<div class="pact"><button class="btn sm primary" data-act="tdajok:${o.id}:${p.id}">Guardar ajuste</button></div></div>`;
}
function tdAdjust(oid,pid){
  const o=orders.find(x=>x.id===oid),p=o&&(o.productores||[]).find(x=>x.id===pid);if(!p||ro||orderLocked(o)||!canManClose()||!tdMode(o))return;
  const w=document.getElementById('tdaj-'+p.id);if(!w)return;const by={};let bad=false;
  w.querySelectorAll('[data-tdaj]').forEach(i=>{const q=i.dataset.tdaj.split(':'),raw=String(i.value||'').trim();if(raw===''){return}const n=Math.floor(+raw);if(!(n>=0)||!isFinite(n)){bad=true;return}if(n>0)(by[q[0]]=by[q[0]]||{})[q[1]]=n});
  if(bad){toast('Escribe solo números enteros');return}
  const old=p.tdv?tdcTxt(p.tdc):'sin validar',now={at:Date.now(),by:whoName()};p.tdc=by;p.tdv=Object.assign({},p.tdv||now,{aj:now});accRebuild(o);touch(o);
  logAdd({k:'note',ctx:ctxOf(o),lab:'Cifras ajustadas a mano · '+(p.nombre||''),o:old,n:tdcTxt(by)});TDA.open=null;render();toast('Ajuste guardado: '+tdcTxt(by));
}
/* v8.35 · lo que el jefe de empaque o la administración cambian en las tarimas (Código de Trazabilidad o Ubicación de tarimas)
   pasa solo al Registro de Empaque de los productores ya validados. Se toma una foto de las cajas en tarimas por productor
   al dibujar la pantalla y al bajar cambios de otros; al guardar, la diferencia contra esa foto se suma a lo validado (p.tdc).
   Así lo que movió asistencia después de validar sigue avisándose, y un ajuste a mano se conserva más la diferencia. */
const TDS={snap:{},busy:false,hold:0,edit:false};
/* v8.35.2: solo cuando el jefe o la administración escriben cajas, calibre o productor de una línea (o quitan una línea) en Código de Trazabilidad.
   «Acomodar en tarimas», ordenar, agregar o quitar tarimas, el almacén y asistencia nunca cambian lo registrado. */
/* v8.35.4: el jefe también ARMA tarimas en Código de Trazabilidad con cajas que ya están en el registro, así que sumar sus ediciones las duplicaba.
   Lo registrado ya no cambia por nada de las tarimas: solo con «Validar», «Usar lo de tarimas» o «Ajustar cifras» (jefe y administración). */
function tdsOn(){return false}
function tdsSnapAll(){
  TDS.snap={};TDS.edit=false;if(!(view==='trazo'&&canManClose()))return;
  visible().filter(o=>isLeader(o)&&tdMode(o)&&!manClosed(o)).forEach(m=>sheetsOf(m).forEach(s=>{if(orderLocked(s))return;(s.productores||[]).forEach(p=>{if(p.tdv&&tdRowOk(p))TDS.snap[s.id+':'+p.id]=tdFromPal(s,p).by})}));
}
function tdsApply(o){
  if(TDS.busy)return;const on=tdsOn();TDS.edit=false;if(!on||!tdMode(o))return;const m=mainOf(o);TDS.busy=true;
  try{sheetsOf(m).forEach(s=>{if(orderLocked(s))return;const ch=[];
    (s.productores||[]).forEach(p=>{const k=s.id+':'+p.id,b=TDS.snap[k];if(!p.tdv||!tdRowOk(p)||!b)return;const P=tdFromPal(s,p).by;TDS.snap[k]=P;if(tdSame(b,P))return;
      const nw={};TIPO_K.forEach(tp=>CAL.forEach(c=>{const v=n0(p.tdc&&p.tdc[tp]&&p.tdc[tp][c.k])+n0(P[tp]&&P[tp][c.k])-n0(b[tp]&&b[tp][c.k]);if(v>0)(nw[tp]=nw[tp]||{})[c.k]=v}));
      ch.push({p:p,o:tdcTxt(p.tdc)});p.tdc=nw;p.tdv=Object.assign({},p.tdv,{up:{at:Date.now(),by:whoName()}})});
    if(!ch.length)return;accRebuild(s);if(s!==m)touch(s);
    ch.forEach(x=>logAdd({k:'note',ctx:ctxOf(s),lab:'Registro de Empaque actualizado desde las tarimas · '+(x.p.nombre||''),o:x.o,n:tdcTxt(x.p.tdc)}))})}
  finally{TDS.busy=false}
}
/* v8.35.1: los espacios de almacén son lugares físicos para ordenar tarimas antes del packing list, y mandar una tarima a otro viaje
   no cambia de quién son sus cajas: nada de esto altera lo registrado en la hoja de empaque */
function tdsHold(f){return function(){TDS.hold++;try{return f.apply(this,arguments)}finally{TDS.hold--;tdsSnapAll()}}}
autoPal=tdsHold(autoPal);ordenarTarimas=tdsHold(ordenarTarimas);almPut=tdsHold(almPut);espSet=tdsHold(espSet);almSwapDo=tdsHold(almSwapDo);almHoleDo=tdsHold(almHoleDo);almLoad=tdsHold(almLoad);almUnflej=tdsHold(almUnflej);armPut=tdsHold(armPut);palNextDo=tdsHold(palNextDo);palFwdDo=tdsHold(palFwdDo);
/* v8.43: el botón es pequeño y pide confirmación: al encenderlo, las cajas de cada productor salen de las tarimas
   y lo capturado con el contador de la línea se reemplaza (le pasó a un jefe con todo el empaque ya capturado) */
function tdModeCnt(m){let P=0,C=0;sheetsOf(m).forEach(s=>{const M=compute(s);M.rows.forEach(r=>{if(r.p.rmp||r.p.sob2)return;const c=n0(r.t);if(c>0){P++;C+=c}})});return {P:P,C:C}}
function tdModeAsk(on){
  const o=cur();if(!o||ro||orderLocked(o)||!canManClose())return;const m=mainOf(o),K=tdModeCnt(m);
  if(on)sheet={kind:'confirm',title:'¿Contar este viaje en tarimas?',danger:K.C>0,
    msg:K.C>0?'Ya hay '+fmt(K.C)+' cajas capturadas con el contador de la línea en '+fmt(K.P)+(K.P===1?' productor':' productores')+'. Al contar en tarimas, esas cifras se reemplazan por lo que asistencia ponga en las tarimas.':'Las cajas de cada productor saldrán de lo que asistencia ponga en las tarimas, y tú validas productor por productor.',
    extra:K.C>0?'Si ya terminaste de contar en la línea, toca Cancelar.':'',ok:K.C>0?'Sí, reemplazar y contar en tarimas':'Sí, contar en tarimas',act:'tdmode:1'};
  else sheet={kind:'confirm',title:'¿Volver al contador de la línea?',msg:'Las cajas dejarán de salir de las tarimas. Las cifras que ya tiene cada productor se quedan y desde ahora se capturan con el contador de la línea.',ok:'Sí, volver al contador',act:'tdmode:0'};
  renderSheet();
}
function tdModeSet(on){
  if(sheet&&sheet.kind==='confirm'){sheet=null;renderSheet()}
  const o=cur();if(!o||ro||orderLocked(o)||!canManClose())return;const m=mainOf(o);
  m.cntTar=!!on;touch(m);if(on)sheetsOf(m).forEach(s=>{accRebuild(s);touch(s)});
  logAdd({k:'note',ctx:ctxOf(m),lab:'Viaje contado en tarimas',o:on?'No':'Sí',n:on?'Sí':'No'});render();toast(on?'Este viaje se cuenta en tarimas: valida cada productor':'Este viaje vuelve a contarse con el contador de la línea');
}
function tdModeHtml(o){
  if(!isLeader(o)&&!tdMode(o))return '';const on=tdMode(o),can=!ro&&!orderLocked(o)&&canManClose()&&isLeader(o);
  const nv=sheetsOf(o).reduce((s,x)=>s+(x.productores||[]).filter(p=>tdRowOk(p)&&!p.tdv).length,0);
  return `<div class="panel ${on?'info':''} tdmode"><strong>${on?'Viaje contado en tarimas':'¿Contar este viaje en tarimas?'}</strong><p class="note">${on?'Las cajas de cada productor salen de lo que asistencia pone en las tarimas. Revisa kilos y rendimiento y toca Validar en cada productor. Las casillas del contador se llenan solas.'+(nv?' Faltan '+nv+(nv===1?' productor':' productores')+' por validar.':' Todos los productores están validados.'):'Asistencia en tarimas pone las cajas de cada productor en las tarimas dibujadas y tú validas productor por productor. Si ya capturaste lecturas del contador, se reemplazan por lo validado.'}</p>${can?`<div class="pact"><button class="btn sm tdsm" data-act="tdmodeask:${on?0:1}">${on?'Volver al contador de la línea':'Contar en tarimas'}</button></div>`:''}</div>`;
}

/* ---------- v8.32 · Aviso «Empaque procesado» ----------
   El jefe lo enciende junto a Completar registro; se manda una vez y se apaga. Lo ven superadmin, admin, inocuidad y solo lectura (dirección).
   Vive solo la semana en curso. Con base de datos va a la tabla «avisos» y la función enviar-aviso lo manda por Firebase a los teléfonos. */
const LS_AV='empaque-avisos',AV_ROLES=['superadmin','admin','inocuidad','lector'];
let AV={list:[],dirty:[],seen:[]};
(function(){try{const j=JSON.parse(localStorage.getItem(LS_AV)||'null');if(j&&Array.isArray(j.list))AV=Object.assign(AV,j)}catch(e){}})();
function saveAv(){try{localStorage.setItem(LS_AV,JSON.stringify(AV))}catch(e){}}
function avWeek(){return AV.list.filter(a=>a.wk===curWk())}
function avFor(){return !!authUser&&AV_ROLES.indexOf(rolReal())>=0}
function avOfOrder(m){return avWeek().filter(a=>a.oid===m.id).sort((a,b)=>b.at-a.at)}
function avHtml(o){
  if(!isLeader(o))return '';const m=mainOf(o),L=avOfOrder(m),cw=wkOf(m)===curWk(),can=!ro&&canManClose()&&!orderLocked(o)&&cw,arm=confirmKey==='avsend:'+m.id;
  return `<div class="panel avp"><div class="avrow"><div><strong>Notificar: empaque procesado</strong><p class="note">${cw?'Avisa a administración, dirección e inocuidad que el empaque '+esc(m.cod)+' quedó procesado. Enciéndelo cuando ya revisaste conteo y manifiesto.':'Solo se avisa en la semana en curso.'}${L.length?' Último aviso: '+esc(L[0].by)+', '+esc(fmtTs(L[0].at))+'.':''}</p></div><button class="sw${arm?' on':''}" role="switch" aria-checked="${arm}" data-act="avsend:${m.id}"${can?'':' disabled'} aria-label="Notificar empaque procesado"><i></i></button></div>${arm?`<p class="note warnt">${L.length?'Ya se avisó esta semana. ':''}Toca otra vez para mandar «Empaque ${esc(m.cod)} procesado».</p>`:''}</div>`;
}
function avSend(oid){
  const m=orders.find(x=>x.id===oid);if(!m||ro||!canManClose()||wkOf(m)!==curWk())return;const k='avsend:'+m.id;
  if(confirmKey!==k){armConfirm(k);render();return}confirmKey=null;
  const a={id:uid(),oid:m.id,cod:m.cod,emp:m.emp,wk:curWk(),at:Date.now(),by:whoName(),byU:meU(),t:'Empaque '+m.cod+' procesado'};AV.list.push(a);AV.dirty.push(a.id);AV.seen.push(a.id);saveAv();
  logAdd({k:'note',ctx:ctxOf(m),lab:'Aviso enviado',o:'',n:a.t});render();toast('Aviso enviado: '+a.t);if(canAuto())avSync();
}
async function avSync(){
  if(!cfgOK()||!session)return;
  try{const send=AV.dirty.map(id=>AV.list.find(a=>a.id===id)).filter(Boolean);
    for(const a of send){await sb('/rest/v1/avisos?on_conflict=id',{method:'POST',headers:{Prefer:'resolution=ignore-duplicates,return=minimal'},body:[{id:a.id,semana:a.wk,oid:a.oid,data:a}]});
      try{await sb('/functions/v1/enviar-aviso',{method:'POST',body:{id:a.id}})}catch(e){}}
    AV.dirty=[];
    if(avFor()){const rows=(await sb('/rest/v1/avisos?select=id,data&semana=eq.'+encodeURIComponent(curWk())))||[];rows.forEach(r=>{if(r.data&&okId(r.id)&&!AV.list.some(a=>a.id===r.id))AV.list.push(cleanRec(Object.assign({},r.data,{id:r.id})))})}
    AV.list=AV.list.filter(a=>a.wk===curWk()||AV.dirty.indexOf(a.id)>=0);saveAv();avShow();
  }catch(e){}
}
/* con la app abierta: aviso del sistema (si lo permitió) y mensaje dentro de la app; con la APK cerrada lo manda Firebase */
function avShow(){
  if(!avFor())return;const nu=avWeek().filter(a=>AV.seen.indexOf(a.id)<0);if(!nu.length)return;
  nu.forEach(a=>{AV.seen.push(a.id);try{if(window.Notification&&Notification.permission==='granted')new Notification(a.t,{body:'Lo avisó '+a.by+' · '+fmtTs(a.at),icon:ICO[a.emp]||undefined})}catch(e){}});
  saveAv();toast(nu.length===1?'🔔 '+nu[0].t+' · '+nu[0].by:'🔔 '+nu.length+' empaques procesados esta semana');if(view==='menu')render();
}
function avMenuHtml(){if(!avFor())return '';const L=avWeek().sort((a,b)=>b.at-a.at);if(!L.length)return '';
  return `<div class="panel avlist"><strong>Avisos de esta semana</strong>${L.map(a=>`<div class="kv"><span><b>${esc(a.t)}</b><small>${esc(a.by)} · ${esc(fmtTs(a.at))}</small></span><button class="btn sm" data-act="avgo:${a.oid}">Ver</button></div>`).join('')}${window.Notification&&Notification.permission==='default'?'<button class="btn sm" data-act="avperm">Recibir avisos en este equipo</button>':''}</div>`}
/* APK: registra el teléfono en Firebase (complemento @capacitor/push-notifications) y guarda su token.
   Solo si la APK se compiló con firebase/google-services.json (el workflow pone FIREBASE: true en config.js); sin eso el registro cerraría la app */
async function avPushInit(){
  try{const C=window.Capacitor,PN=C&&C.Plugins&&C.Plugins.PushNotifications;if(!PN||!CFG.FIREBASE||!avFor()||!cfgOK()||!session||avPushInit.done)return;avPushInit.done=1;
    let st=await PN.checkPermissions();if(st.receive==='prompt')st=await PN.requestPermissions();if(st.receive!=='granted')return;
    PN.addListener('registration',async t=>{try{await sb('/rest/v1/dispositivos?on_conflict=token',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:[{token:t.value,plataforma:'android'}]})}catch(e){}});
    PN.addListener('pushNotificationReceived',()=>{avSync()});
    await PN.register();
  }catch(e){}
}

/* ---------- v8.28 · Conteo de segundas por productor ----------
   Rol «segundas»: solo entra a esta pantalla. Cuenta segundas, con cera y terceras (desecho) de cada productor en un viaje abierto,
   sumando parte por parte. Cada conteo se guarda en la tabla «conteos» (kind:'seg') y se suma con los demás del mismo productor.
   El jefe ve el total junto a la casilla Segundas del productor y lo usa con un botón, lo compara o lo corrige: su casilla manda. */
const SC_F=[['seg','Segundas'],['cera','Con cera'],['des','Terceras (desecho)']];
const SC={oid:null,prod:'',f:'seg',p:{seg:[],cera:[],des:[]},in:''};
function isSegC(){return !!authUser&&authUser.rol==='segundas'}
function scProds(m){const out=[],seen=new Set();sheetsOf(m).filter(s=>s.variante!=='1.5').forEach(s=>(s.productores||[]).forEach(p=>{if(p.sob2||p.sob||isSegRow(p))return;const k=prodKey(s,p);if(seen.has(k))return;seen.add(k);out.push({k:k,n:p.nombre||k})}));return out}
function scVal(x){const t=String(x==null?'':x).replace(/\s+/g,'');if(!t)return null;if(!/^[+-]?\d+([+-]\d+)*$/.test(t))return NaN;return t.match(/[+-]?\d+/g).reduce((a,b)=>a+(+b),0)}
function scSum(a){return (a||[]).reduce((s2,x)=>s2+n0(x),0)}
function scRecs(oid,pk){return CONT.list.filter(c=>c.kind==='seg'&&c.estado!=='anulado'&&c.oid===oid&&(pk==null||c.prod===pk))}
function scTot(L){const t={seg:0,cera:0,des:0,cnt:L.length,last:null};L.forEach(c=>{t.seg+=n0(c.seg);t.cera+=n0(c.cera);t.des+=n0(c.des);if(!t.last||(c.at||0)>(t.last.at||0))t.last=c});return t}
function scView(){
  const T=contTrips(),m=T.find(o=>o.id===SC.oid)||null;
  const trips=T.length?`<div class="pnopts">${T.map(o=>`<label class="pnopt"><input type="radio" name="sctrip" data-sctrip="${o.id}"${m&&m.id===o.id?' checked':''}><span><b class="mono">${esc(o.cod)}</b><small>${esc(EMPS[o.emp].name)} · ${esc(o.emb||'—')} · ${fmtDate(o.fecha)}</small></span></label>`).join('')}</div>`:'<p class="note">No hay viajes abiertos para contar. Avisa al jefe de empaque.</p>';
  let form='',tv='';
  if(m){const P=scProds(m),cur=SC.p[SC.f]||[],lab=(SC_F.find(x=>x[0]===SC.f)||SC_F[0])[1];
    form=`<div class="sec">Productor</div><div class="panel"><label class="fld" for="sc-prod"><span>Código o nombre</span><input class="in txt" id="sc-prod" list="sc-plist" autocomplete="off" autocapitalize="characters" data-scprod="1" value="${esc(SC.prod)}" placeholder="VL-156 o nombre"></label><datalist id="sc-plist">${P.map(x=>`<option value="${esc(x.k)}">${esc(x.n)}</option>`).join('')}</datalist></div>
<div class="sec">Qué cuentas</div><div class="seg seg3" role="group" aria-label="Qué cuentas">${SC_F.map(x=>`<button data-act="scf:${x[0]}" aria-pressed="${SC.f===x[0]}">${esc(x[1])}<small class="scbt">${fmt(scSum(SC.p[x[0]]))}</small></button>`).join('')}</div>
<div class="panel scpad"><label class="fld" for="sc-in"><span>Cajas de ${esc(lab.toLowerCase())}. Puedes escribir 20+15+12</span><input class="in scin" id="sc-in" inputmode="tel" enterkeyhint="done" autocomplete="off" data-scin="1" value="${esc(SC.in)}"></label><button class="btn primary" data-act="scadd">Sumar</button>
<div class="scparts" aria-live="polite">${cur.length?cur.map((v,i)=>`<button class="chip scp" data-act="scdel:${SC.f}:${i}" aria-label="Quitar ${fmt(v)}">${fmt(v)} <span aria-hidden="true">×</span></button>`).join('<span class="scplus" aria-hidden="true">+</span>')+`<span class="sceq">= <b>${fmt(scSum(cur))}</b></span>`:'<span class="note">Cada número que sumes queda aquí; tócalo para quitarlo.</span>'}</div></div>
<div class="ig tot"><div><span>Segundas</span><b>${fmt(scSum(SC.p.seg))}</b></div><div><span>Con cera</span><b>${fmt(scSum(SC.p.cera))}</b></div><div><span>Terceras</span><b>${fmt(scSum(SC.p.des))}</b></div></div>
<div class="srow2"><button class="btn" data-act="scclr">Empezar de nuevo</button><button class="btn primary" data-act="scsend">Guardar conteo</button></div>`;
    const G=new Map();scRecs(m.id).forEach(c=>{let a=G.get(c.prod);if(!a)G.set(c.prod,a={k:c.prod,n:c.nombre||c.prod,L:[]});a.L.push(c)});
    const R=[...G.values()].map(a=>Object.assign(a,scTot(a.L))).sort((a,b)=>String(a.n).localeCompare(String(b.n)));
    tv=R.length?`<div class="sec">Total contado en ${esc(m.cod)}</div><div class="tblx"><table class="stbl"><thead><tr><th>Productor</th><th class="r">Segundas</th><th class="r">Con cera</th><th class="r">Terceras</th><th class="r">Conteos</th></tr></thead><tbody>${R.map(a=>`<tr><th scope="row">${esc(a.n)}<small class="mono"> · ${esc(a.k)}</small></th><td class="r">${fmt(a.seg)}</td><td class="r">${fmt(a.cera)}</td><td class="r">${fmt(a.des)}</td><td class="r">${fmt(a.L.length)}</td></tr>`).join('')}</tbody><tfoot><tr><th scope="row">Total</th><td class="r"><b>${fmt(R.reduce((x,a)=>x+a.seg,0))}</b></td><td class="r"><b>${fmt(R.reduce((x,a)=>x+a.cera,0))}</b></td><td class="r"><b>${fmt(R.reduce((x,a)=>x+a.des,0))}</b></td><td></td></tr></tfoot></table></div>`:'';
  }
  const mine=CONT.list.filter(c=>c.kind==='seg'&&c.byU===(authUser&&authUser.user)).sort((a,b)=>(b.at||0)-(a.at||0)).slice(0,15);
  const hist=mine.length?`<div class="sec">Mis conteos</div><div class="panel">${mine.map(c=>{const k='scan:'+c.id;return `<div class="kv${c.estado==='anulado'?' anul':''}"><span><b class="mono">${esc(c.cod)}</b> · ${esc(c.nombre||c.prod)}<small> · ${esc(fmtTs(c.at))} · ${fmt(n0(c.seg))} segundas · ${fmt(n0(c.cera))} con cera · ${fmt(n0(c.des))} terceras${c.estado==='anulado'?' · anulado':''}</small></span>${c.estado==='anulado'?'':`<button class="btn sm" data-act="${k}">${confirmKey===k?'Toca otra vez':'Anular'}</button>`}</div>`}).join('')}</div>`:'';
  return topbar('Conteo de segundas',isSegC()?null:'supback')+`<main class="wrap">${supBan()}<div class="panel info"><p class="note">Cuenta por productor las segundas, las de cera y las terceras (desecho) de un viaje. Suma parte por parte y guarda. El jefe de empaque ve tu total en el Registro de Empaque y lo compara con el suyo.</p></div><div class="sec">Viaje</div>${trips}${form}${tv}${supScList(m)}${hist}<div class="pact" style="margin-top:16px"><button class="btn sm" data-act="sync">Sincronizar</button>${isSegC()?'<button class="btn sm" data-act="acctopen">Mi cuenta</button><button class="btn sm" data-act="ulogout">Cerrar sesión</button>':'<button class="btn sm" data-act="supback">Volver a Código de Trazabilidad</button>'}</div>${legalFoot()}</main>`;
}
function scAdd(){
  const v=scVal(SC.in);if(v==null){toast('Escribe cuántas cajas');return}if(isNaN(v)){toast('Solo números, + y -. Por ejemplo 20+15');return}
  if(v===0){toast('La suma da cero');return}
  const a=SC.p[SC.f]||(SC.p[SC.f]=[]);if(scSum(a)+v<0){toast('El total no puede quedar abajo de cero');return}
  a.push(v);SC.in='';focusId='sc-in';render();
}
function scSend(){
  const m=orders.find(x=>x.id===SC.oid);if(!m){toast('Elige el viaje');return}
  if(manClosed(m)||orderLocked(m)){toast('El viaje '+m.cod+' ya está cerrado');return}
  const pk=resolveProd(sheetsOf(m),SC.prod);if(!pk){toast('Escribe el código o el nombre del productor');return}
  if(scVal(SC.in)){scAdd();if(scVal(SC.in))return}
  const t={seg:scSum(SC.p.seg),cera:scSum(SC.p.cera),des:scSum(SC.p.des)};if(!t.seg&&!t.cera&&!t.des){toast('Suma al menos una cantidad');return}
  const nm=(scProds(m).find(x=>x.k===pk)||{}).n||pk;
  const c={id:uid(),kind:'seg',oid:m.id,emp:m.emp,cod:m.cod,prod:pk,nombre:nm,partes:{seg:SC.p.seg.slice(),cera:SC.p.cera.slice(),des:SC.p.des.slice()},seg:t.seg,cera:t.cera,des:t.des,estado:'enviado',at:Date.now(),by:whoName(),byU:authUser&&authUser.user};
  CONT.list.push(c);touchC(c);SC.p={seg:[],cera:[],des:[]};SC.in='';SC.prod='';SC.f='seg';render();
  toast('Conteo guardado: '+fmt(t.seg)+' segundas, '+fmt(t.cera)+' con cera y '+fmt(t.des)+' terceras de '+nm);if(canAuto())doSync(true);
}
function scAnular(id){
  const c=CONT.list.find(x=>x.id===id&&x.kind==='seg');if(!c||c.estado==='anulado')return;
  if(!(isSegC()&&c.byU===(authUser&&authUser.user))&&!(canManClose()&&!roRole))return;
  const k='scan:'+id;if(confirmKey!==k){armConfirm(k);render();return}confirmKey=null;
  c.estado='anulado';c.anulBy=whoName();c.anulAt=Date.now();touchC(c);render();toast('Conteo anulado');
}
/* lo que ve el jefe en el renglón del productor, junto a Segundas, Cera y Desecho */
function scRowHtml(o,p){
  if(isSegRow(p)||p.sob||p.sob2||o.variante==='1.5')return '';
  const m=mainOf(o),L=scRecs(m.id,prodKey(o,p));if(!L.length)return '';const t=scTot(L);
  const dif=[['seg',t.seg,p.seg,'segundas'],['cera',t.cera,p.cera,'con cera'],['des',t.des,p.des,'terceras']].filter(x=>(x[1]||x[2]!=null&&x[2]!=='')&&Math.abs(n0(x[1])-n0(x[2]))>0.001);
  const igual=!dif.length,can=!ro&&!orderLocked(o);
  return `<div class="scrow${igual?' ok':''}"><div><b>Conteo de segundas</b><small>${fmt(t.seg)} segundas · ${fmt(t.cera)} con cera · ${fmt(t.des)} terceras · ${L.length} ${L.length===1?'conteo':'conteos'}, el último de ${esc(t.last.by||'—')} (${esc(fmtTs(t.last.at))})</small>${igual?'<span class="chip good">Coincide con la hoja</span>':`<span class="chip warn">Diferente: ${dif.map(x=>esc(x[3])+' '+fmt(n0(x[2]))+' en la hoja').join(', ')}</span>`}</div>${can&&!igual?`<button class="btn sm primary" data-act="scuse:${o.id}:${p.id}" data-edit>Usar conteo</button>`:''}</div>`;
}
function scUse(oid,pid){
  const o=orders.find(x=>x.id===oid),p=o&&(o.productores||[]).find(x=>x.id===pid);if(!p||ro||orderLocked(o))return;
  const t=scTot(scRecs(mainOf(o).id,prodKey(o,p))),old=[p.seg,p.cera,p.des].map(v=>v==null||v===''?'—':v).join(' / ');
  p.seg=t.seg?String(t.seg):p.seg&&!t.seg?'0':p.seg;p.cera=t.cera?String(t.cera):p.cera?'0':p.cera;p.des=t.des?String(t.des):p.des?'0':p.des;touch(o);
  logAdd({k:'note',ctx:ctxOf(o),lab:'Conteo de segundas usado · '+(p.nombre||''),o:old,n:[t.seg,t.cera,t.des].join(' / ')});
  render();toast('Se llenaron Segundas, Cera y Desecho con el conteo');
}
$app.addEventListener('change',e=>{const t=e.target;if(t&&t.dataset&&t.dataset.sctrip){SC.oid=t.dataset.sctrip;render()}});
$app.addEventListener('input',e=>{const t=e.target;if(!t||!t.dataset)return;if(t.dataset.scprod!=null)SC.prod=t.value;else if(t.dataset.scin!=null)SC.in=t.value});
$app.addEventListener('keydown',e=>{const t=e.target;if(t&&t.dataset&&t.dataset.scin!=null&&e.key==='Enter'){e.preventDefault();scAdd()}});

/* ---------- v8.25 · Usuarios y roles (con base de datos) ----------
   Solo administradores y superadministradores entran. Los dos ven las cuentas, las agregan y las bloquean o habilitan;
   solo el superadministrador cambia roles. Todo pasa por funciones de Supabase (supabase-v8.25.sql) que revisan el rol
   en el servidor, así que la app nunca necesita la clave secreta. */
const ROL_ORD=['superadmin','admin','jefe','inocuidad','tarima','segundas','lector','contador',''];
const ROL_L={superadmin:'Superadministrador',admin:'Administrador',jefe:'Jefe de empaque',inocuidad:'Jefe de inocuidad',tarima:'Asistencia en tarimas',segundas:'Conteo de segundas',lector:'Dirección (solo lectura)',contador:'Contador','':'Sin rol (sin acceso)'};
const ROL_D={superadmin:'Todo, y además cambia roles',admin:'Todo, menos cambiar roles',jefe:'Empaque, trazabilidad y documentos; autoriza conteos e indica productor, calidad y presentación en turno',inocuidad:'Lo mismo que el jefe de empaque, y además productores y logística; no borra pedidos',tarima:'Cuenta las cajas del productor en turno que van a cada tarima',segundas:'Solo el conteo de segundas y terceras por productor',lector:'Ve todo, no cambia nada',contador:'Finanzas',' ':''};
function usrOpen(){
  if(!(isAdmin()||perAdmin())){toast('Solo la administración entra a Usuarios');return}
  if(!cfgOK()){userAct('usersopen');return}
  sheet={kind:'usr',list:null,err:'',busy:false,add:false};renderSheet();usrLoad();
}
async function usrLoad(){
  try{await ensureSession();const r=await sb('/rest/v1/rpc/admin_usuarios',{method:'POST',body:{}});if(sheet&&sheet.kind==='usr'){sheet.list=r||[];sheet.err='';renderSheet()}}
  catch(e){if(sheet&&sheet.kind==='usr'){sheet.list=[];sheet.err=e&&e.status===404?'Falta correr supabase-v8.25.sql en Supabase.':e&&e.status===403?'Tu cuenta no tiene permiso para ver usuarios.':'No se pudo cargar la lista. Revisa tu internet.';renderSheet()}}
}
function usrHtml(){
  const S=sheet,sup=isSuper(),me=session&&session.email;
  const rows=(S.list||[]).slice().sort((a,b)=>ROL_ORD.indexOf(a.rol||'')-ROL_ORD.indexOf(b.rol||'')||String(a.email).localeCompare(String(b.email))).map(u=>{
    const r=u.rol||'',self=u.email===me,blk=!!u.bloqueado,top=r==='admin'||r==='superadmin';
    const sel=sup&&!self?`<select class="in sel" data-usrol="${esc(u.id)}" aria-label="Rol de ${esc(u.email)}">${ROL_ORD.map(k=>`<option value="${k}"${k===r?' selected':''}>${esc(ROL_L[k])}</option>`).join('')}</select>`:`<span class="chip${r?'':' warn'}">${esc(ROL_L[r]||r)}</span>`;
    const blkB=self||(top&&!sup)?'':`<button class="btn sm" data-act="${blk?'usrok':'usrblk'}:${esc(u.id)}">${blk?'Habilitar':'Bloquear'}</button><button class="btn sm danger" data-act="usrdel:${esc(u.id)}">${confirmKey==='usrdel:'+u.id?'Toca otra vez para eliminar':'Eliminar'}</button>`;
    return `<div class="urow"><div class="rtx"><strong>${esc(u.nombre||u.email)}${self?' (tú)':''}</strong><small>${esc(u.email)} · ${blk?'<b class="neg">bloqueada</b>':'activa'} · último acceso ${u.ultimo?esc(fmtTs(Date.parse(u.ultimo))):'nunca'}</small></div><div class="ubt">${sel}${blkB}</div></div>`}).join('');
  const add=S.add?`<div class="panel"><label class="fld" for="ua-n"><span>Nombre</span><input class="in txt" id="ua-n" autocomplete="off"></label><label class="fld" for="ua-e"><span>Correo</span><input class="in txt" id="ua-e" type="email" autocapitalize="none" autocomplete="off"></label><label class="fld" for="ua-p"><span>Contraseña temporal (mínimo 10)</span><input class="in txt" id="ua-p" type="text" autocomplete="off"></label>${sup?`<label class="fld" for="ua-r"><span>Rol</span><select class="in sel" id="ua-r">${ROL_ORD.filter(k=>k).map(k=>`<option value="${k}"${k==='jefe'?' selected':''}>${esc(ROL_L[k])}</option>`).join('')}</select></label>`:'<p class="note">La cuenta queda sin rol (sin acceso) hasta que el superadministrador le asigne uno.</p>'}<div class="srow2"><button class="btn" data-act="usradd:0">Cancelar</button><button class="btn primary" data-act="usrnew"${S.busy?' disabled':''}>${S.busy?'Creando…':'Crear cuenta'}</button></div></div>`:`<div class="pact"><button class="btn primary sm" data-act="usradd:1">+ Agregar usuario</button><button class="btn sm" data-act="usrload">Actualizar</button></div>`;
  return `<h3>Usuarios y roles</h3><p class="note">${sup?'Como superadministrador cambias roles; el cambio aplica la próxima vez que la persona entre.':'Puedes agregar, bloquear, habilitar y eliminar cuentas. Los roles los cambia el superadministrador.'}</p>
<details class="panel"><summary>Qué hace cada rol</summary>${ROL_ORD.filter(k=>k).map(k=>`<div class="kv"><span><b>${esc(ROL_L[k])}</b></span><small>${esc(ROL_D[k])}</small></div>`).join('')}</details>
${add}${S.err?`<p class="note" style="color:var(--crit)" role="alert">${esc(S.err)}</p>`:''}${S.list==null?'<p class="note">Cargando…</p>':`<div class="panel">${rows||'<p class="note">Sin cuentas.</p>'}</div>`}<div class="srow2"><button class="btn primary" data-act="closesheet">Cerrar</button></div>`;
}
async function usrRol(uid,rol){
  if(!isSuper()){toast('Solo el superadministrador cambia roles');return}
  try{await ensureSession();await sb('/rest/v1/rpc/asignar_rol',{method:'POST',body:{p_uid:uid,p_rol:rol}});const u=(sheet.list||[]).find(x=>x.id===uid);if(u)u.rol=rol;logAdd({k:'note',ctx:{t:'u'},lab:'Rol cambiado',o:u?u.email:uid,n:ROL_L[rol]||rol});toast('Rol asignado: '+(ROL_L[rol]||rol)+'. Aplica al volver a entrar');renderSheet()}
  catch(e){toast(e&&e.status===403?'Tu cuenta no puede cambiar roles':'No se pudo cambiar el rol');usrLoad()}
}
/* v8.45 · eliminar cuentas: pasa por la función «crear-usuario» (acción «borrar»), que corre con la clave secreta y revisa
   en el servidor que quien borra sea administración; a un administrador solo lo borra el superadministrador; nadie se borra a sí mismo.
   Es definitivo. Lo que la persona capturó se queda (los registros guardan su nombre y correo). Bloquear sigue siendo lo recomendado. */
async function usrDel(uid){
  const u=(sheet.list||[]).find(x=>x.id===uid);if(!u)return;
  if(confirmKey!=='usrdel:'+uid){confirmKey='usrdel:'+uid;renderSheet();return}
  confirmKey=null;
  if(!window.confirm('¿Eliminar para siempre la cuenta '+u.email+'? No se puede deshacer. Lo que capturó se conserva. Si solo quieres quitarle el acceso, usa Bloquear.')){renderSheet();return}
  try{await ensureSession();await sb('/functions/v1/crear-usuario',{method:'POST',body:{accion:'borrar',id:uid}});
    logAdd({k:'note',ctx:{t:'u'},lab:'Cuenta eliminada',o:u.email,n:''});toast('Cuenta eliminada: '+u.email);usrLoad()}
  catch(e){toast(e&&(e.status===404||e.code==='invalid_email')?'Falta publicar en Supabase la función crear-usuario nueva (v8.45)':e&&e.status===403?(e.msg||'No tienes permiso para eliminar esa cuenta'):'No se pudo eliminar'+(e&&e.msg?': '+e.msg:''));usrLoad()}
}
async function usrBlk(uid,on){
  try{await ensureSession();await sb('/rest/v1/rpc/habilitar_usuario',{method:'POST',body:{p_uid:uid,p_activo:on}});const u=(sheet.list||[]).find(x=>x.id===uid);if(u)u.bloqueado=!on;toast(on?'Cuenta habilitada':'Cuenta bloqueada');renderSheet()}
  catch(e){toast(e&&e.status===403?'No tienes permiso para esa cuenta':'No se pudo cambiar');usrLoad()}
}
/* el registro de Supabase responde 400/422/429 por varias causas; se muestra la causa real */
function usrErr(x){
  const c=String(x&&x.code||''),m=String(x&&x.msg||''),t=(c+' '+m).toLowerCase();
  if(/not.?authorized/.test(t))return 'Supabase no puede mandar el correo de confirmación a esa dirección (su correo de prueba solo envía al equipo del proyecto). Desactiva Authentication › Sign In / Providers › Confirm email y toca Save changes; la cuenta queda lista con la contraseña temporal.';
  if(/signup.?disabled|signups not allowed/.test(t))return 'Supabase no permite registrar cuentas: activa Authentication › Sign In / Providers › Allow new users to sign up.';
  if(/already|exists|registered/.test(t))return 'Ese correo ya tiene cuenta.';
  if(/weak|password/.test(t))return 'Supabase no aceptó la contraseña temporal: usa una más larga o con letras y números.';
  if(/rate|limit/.test(t)||(x&&x.status===429))return 'Supabase limita los correos por hora. Espera un rato o desactiva Confirm email.';
  if(/invalid/.test(t)&&/email/.test(t))return 'Supabase no aceptó ese correo: revisa que esté bien escrito.';
  return 'No se pudo crear la cuenta'+(m?': '+m:x&&x.status?' (error '+x.status+')':'')+'.';
}
async function usrNew(){
  const S=sheet,n=gv('ua-n').trim(),e=gv('ua-e').trim().toLowerCase(),p=gv('ua-p'),r=isSuper()?gv('ua-r'):'';
  if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e)){toast('Escribe un correo válido');return}if(p.length<10){toast('La contraseña lleva al menos 10 caracteres');return}
  S.busy=true;renderSheet();
  try{
    /* v8.30.1: primero se intenta la función segura «crear-usuario» (corre en Supabase con la clave secreta y revisa que quien crea sea administración).
       Si todavía no está publicada, se usa el registro público como antes. Con la función publicada se puede apagar «Allow new users to sign up». */
    let id=null,conRol=false,fn=false;
    try{await ensureSession();const j=await sb('/functions/v1/crear-usuario',{method:'POST',body:{email:e,password:p,nombre:n,rol:r}});id=j&&j.id;conRol=!!(j&&j.rol);fn=true}
    catch(x){if(x&&x.code==='login')throw x;if(x&&x.status&&x.status!==404)throw x}
    if(!fn){const j=await sb('/auth/v1/signup',{method:'POST',auth:false,body:{email:e,password:p,data:{nombre:n}}});id=(j&&(j.user&&j.user.id))||(j&&j.id)}
    if(r&&id&&!conRol){await ensureSession();await sb('/rest/v1/rpc/asignar_rol',{method:'POST',body:{p_uid:id,p_rol:r}})}
    S.busy=false;S.add=false;toast('Cuenta creada para '+e+(r?' como '+ROL_L[r]:'')+'. Entrégale su contraseña temporal');usrLoad()}
  catch(x){S.busy=false;S.err=usrErr(x);renderSheet()}
}

/* ---------- v8.24 · buscador de productores en todas las listas ----------
   Después de cada dibujo busca tablas y listas con 5 o más renglones de productor (código VL-/EC- o nombre del
   catálogo) y les pone encima «Buscar productor». Solo oculta renglones en pantalla: no cambia datos, totales ni
   documentos. Las listas que ya tienen su propio buscador se dejan como están. */
const PF={q:{},raf:0,focus:null};
const PF_SKIP='select,.bnav,.pfind,#pvgrid,#plist,#rlist,#tfout,#rexprods,#results,.pdd,[data-nopf]';
const PF_CODE=/\b(?:VL|EC)-\d{1,4}\b(?!-)/;
function pfNames(){const m=lisNameMap();if(PF.nsrc!==m){PF.nsrc=m;PF.names=[...m.keys()].filter(k=>k.length>=5)}return PF.names}
function pfText(el){const w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let t='',x;while((x=w.nextNode()))t+=' '+x.nodeValue;return t}
function pfIsProd(el){const t=pfText(el);if(PF_CODE.test(t))return true;const n=norm(t).replace(/\s+/g,' ');return pfNames().some(k=>n.indexOf(k)>=0)}
/* dentro de una lista de productores, cuenta todo renglón salvo encabezados, totales y títulos (también los productores sin código) */
function pfData(r){if(r.tagName==='TR'&&r.querySelector('th')&&!r.querySelector('td'))return false;if(/(^|\s)(sec|tot|total|thead|hdr|head)(\s|$)/.test(r.className||''))return false;return !/^\s*(total|totales|suma)\b/i.test(pfText(r))}
function pfRowsOf(c){return c.tagName==='TBODY'||c.tagName==='TABLE'?[...c.children].filter(r=>r.tagName==='TR'):[...c.children].filter(r=>!r.classList.contains('pfind'))}
function pfCands(root){
  const out=[];
  root.querySelectorAll('tbody,table,div,ul,ol,section').forEach(c=>{
    if(c.closest(PF_SKIP)||c.children.length<5||c.children.length>3000)return;
    if(c.tagName==='TABLE'&&[...c.children].some(x=>x.tagName==='TBODY'))return;
    const rows=pfRowsOf(c);if(rows.length<5)return;
    let n=0;for(const r of rows){if((r.textContent||'').length<1500&&pfIsProd(r))n++}
    if(n>=5&&n>=rows.length*0.5)out.push(c)});
  return out.filter(c=>!out.some(d=>d!==c&&c.contains(d)))}
function pfAnchor(c){let a=c.tagName==='TBODY'?c.closest('table'):c;while(a.parentElement&&a.parentElement.children.length===1&&a.parentElement!==$app&&a.parentElement!==$sh&&!a.parentElement.classList.contains('panel')&&!a.parentElement.classList.contains('sheet'))a=a.parentElement;return a}
function pfApply(box){
  const c=box._pfc;if(!c)return;const q=norm(box.querySelector('input').value||'').replace(/\s+/g,' ').trim();
  let tot=0,vis=0;
  pfRowsOf(c).forEach(r=>{if(!pfData(r)){r.hidden=false;return}tot++;const ok=!q||norm(pfText(r)).replace(/\s+/g,' ').indexOf(q)>=0;r.hidden=!ok;if(ok)vis++});
  const s=box.querySelector('.pfn');if(s)s.textContent=q?`${vis} de ${tot}`:`${tot} en la lista`}
function pfScan(){
  PF.raf=0;if(!authUser)return;
  const vk=view+'|'+(sheet&&sheet.kind||'');
  const used=new Set();
  [[$app,'a'],[$sh,'s']].forEach(([root,pre])=>{
    pfCands(root).forEach((c,i)=>{
      const key=vk+'|'+pre+i,a=pfAnchor(c);if(used.has(a))return;used.add(a);let box=a.previousElementSibling;
      /* v8.27.5: un solo buscador por lista (antes se apilaban cuando varias listas compartían el mismo contenedor) */
      while(box&&box.classList.contains('pfind')&&box.dataset.pfk!==key){const pv=box.previousElementSibling;box.remove();box=pv}
      if(!(box&&box.classList.contains('pfind')&&box.dataset.pfk===key)){
        a.insertAdjacentHTML('beforebegin',`<div class="pfind" data-pfk="${esc(key)}"><span class="tfin"><svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5" fill="none" stroke="currentColor" stroke-width="2"/><path d="M15.5 15.5L21 21" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg><input class="in txt pfq" type="search" autocomplete="off" enterkeyhint="search" placeholder="Buscar productor" aria-label="Buscar productor en esta lista"></span><span class="pfn" aria-live="polite"></span></div>`);
        box=a.previousElementSibling;const inp=box.querySelector('input');inp.value=PF.q[key]||'';inp.readOnly=false;
        if(PF.focus&&PF.focus.k===key&&(!document.activeElement||document.activeElement===document.body)){inp.focus();try{inp.setSelectionRange(PF.focus.p,PF.focus.p)}catch(e){}}}
      box._pfc=c;pfApply(box)})})}
function pfSched(){if(!PF.raf)PF.raf=requestAnimationFrame(pfScan)}
document.addEventListener('input',e=>{const t=e.target;if(!t||!t.classList||!t.classList.contains('pfq'))return;e.stopPropagation();const box=t.closest('.pfind');PF.q[box.dataset.pfk]=t.value;PF.focus={k:box.dataset.pfk,p:t.selectionStart||t.value.length};pfApply(box)},true);
document.addEventListener('focusout',e=>{const t=e.target;if(t&&t.classList&&t.classList.contains('pfq'))setTimeout(()=>{if(!document.activeElement||!document.activeElement.classList||!document.activeElement.classList.contains('pfq'))PF.focus=null},0)});
document.addEventListener('keydown',e=>{const t=e.target;if(t&&t.classList&&t.classList.contains('pfq')&&e.key==='Enter'){e.preventDefault();e.stopPropagation();t.blur()}},true);
if(typeof MutationObserver!=='undefined'){const mo=new MutationObserver(pfSched);mo.observe($app,{childList:true,subtree:true});mo.observe($sh,{childList:true,subtree:true})}

/* ---------- v8.40 · contingencia sin internet ----------
   La franja de color de arriba dice siempre en qué modo está el teléfono: verde Nube (al día o subiendo),
   rojo Solo este teléfono (con cuántos cambios tiene sin subir). El amarillo queda para el modo local de la siguiente versión.
   Sin nube: el guardado que falle avisa en rojo; los viajes nuevos nacen con código provisional; «Pasar mis cambios»
   genera un archivo que otro teléfono junta sin duplicar (Quick Share o AirDrop funcionan sin internet);
   Conciliación marca códigos repetidos y tarimas que parecen la misma. */
function lsFail(e){try{errNote('guardar en el teléfono',e)}catch(x){}
  const t=Date.now(),first=!NET.saveErr;NET.saveErr=t;
  if(first||t-(NET.saveToast||0)>30000){NET.saveToast=t;try{toast('No se pudo guardar en este teléfono (memoria llena). Sincroniza o usa «Pasar mis cambios» ya.',7000)}catch(x){}}
  try{netUpd()}catch(x){}
}
function netOff(){return cfgOK()&&(navigator.onLine===false||NET.ok===false)}
function pendN(){
  let n=dirty.size+listaOps().length;
  try{if(!INV.noTable)n+=INV.dirty.length}catch(e){}
  try{if(!LOG.noTable)n+=LOG.dirty.length}catch(e){}
  try{if(typeof CONT!=='undefined'&&!CONT.noTable)n+=CONT.dirty.length}catch(e){}
  try{n+=(REG.dirty?1:0)+(FIN.dirty?1:0)+(PESOS.dirty?1:0)+(DEC.dirty?1:0)+(PER.dirty?1:0)}catch(e){}
  return n;
}
function netState(){if(!cfgOK())return 'na';if(!session)return 'login';return netOff()?'off':'ok'}
const hhmm=ts=>{try{return new Date(ts).toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'})}catch(e){return ''}};
function netText(){
  const st=netState(),p=pendN(),cam=n=>fmt(n)+(n===1?' cambio':' cambios');let t='';
  if(st==='login')t='Sin sesión · toca para entrar y sincronizar';
  else if(st==='off')t='Solo este teléfono · sin nube'+(NET.down?' desde '+hhmm(NET.down):'')+' · '+(p?cam(p)+' por subir':'nada pendiente');
  else if(st==='ok'){const o=typeof RT!=='undefined'&&RT.st==='on'?rtNames():[];t='Nube · '+(p?'subiendo '+cam(p):'al día')+(o.length?' · en vivo con '+o.join(', '):'')}
  if(NET.saveErr)t='No se pudo guardar en este teléfono · '+t;
  return t;
}
function netbarHtml(){const st=netState();if(st==='na')return '';return `<button class="netbar" id="netbar" data-act="netopen" data-n="${st}"${NET.saveErr?' data-err="1"':''} aria-live="polite"><i aria-hidden="true"></i><span>${esc(netText())}</span></button>`}
function netUpd(){
  const el=document.getElementById('netbar');if(!el)return;const st=netState();el.dataset.n=st;if(NET.saveErr)el.dataset.err='1';else delete el.dataset.err;
  const s=el.querySelector('span'),t=netText();if(s&&s.textContent!==t)s.textContent=t;
  if(sheet&&sheet.kind==='net'){const b=document.getElementById('net-state');if(b)b.textContent=t}
}
window.addEventListener('offline',()=>{if(!NET.down)NET.down=Date.now();NET.ok=false;setSync()});

/* ---- viajes creados sin nube: código provisional hasta confirmarlo en la nube ---- */
{const nO=newOrder;newOrder=function(f){const o=nO(f);if(!(f&&f.ejemplo)&&netOff())o.prov={at:Date.now(),by:whoName(),dev:RT.dev};return o}}
/* dos viajes con la misma empresa, año, consecutivo y hoja: lo crearon dos teléfonos sin verse */
function codeDups(){
  const G={};visible().forEach(o=>{if(o.cons==null||o.cons==='')return;const k=o.emp+'|'+o.anio+'|'+o.cons+'|'+(o.variante||'1');(G[k]=G[k]||[]).push(o)});
  return Object.keys(G).filter(k=>G[k].length>1).map(k=>G[k].sort((a,b)=>(a.createdAt||0)-(b.createdAt||0)));
}
function isDup(o){return !!o&&codeDups().some(g=>g.indexOf(o)>=0)}
/* después de sincronizar bien: el que no choca con nadie queda confirmado */
function provCheck(){
  const D=codeDups();let n=0;
  orders.forEach(o=>{if(!o.prov||dirty.has(o.id)||D.some(g=>g.indexOf(o)>=0))return;delete o.prov;touch(o);n++});
  return n;
}
function provBanner(o){
  if(!o)return '';const m=mainOf(o);
  if(isDup(o)||isDup(m))return `<div class="netnote" data-n="err"><span><b>Código repetido:</b> ${esc(o.cod)} lo tiene más de un viaje. Pasó porque se crearon en dos teléfonos sin internet.</span>${canManClose()?'<button class="btn sm" data-act="concopen">Conciliación</button>':''}</div>`;
  if(o.prov||m.prov)return `<div class="netnote" data-n="off"><span><b>Código provisional:</b> ${esc(o.cod)} se creó sin internet. Se confirma al sincronizar; no imprimas documentos definitivos hasta entonces.</span></div>`;
  if(netOff()&&(dirty.has(o.id)||dirty.has(m.id)))return `<div class="netnote" data-n="off"><span><b>Pendiente de nube:</b> los cambios de este viaje están solo en este teléfono. Si otro teléfono los necesita, usa «Pasar mis cambios».</span><button class="btn sm" data-act="netopen">Opciones</button></div>`;
  return '';
}

/* ---- ventana «Estado de la conexión» ---- */
function canJunt(){return !!authUser&&!roRole&&canManClose()}
/* v8.46 · A-16: diario de errores. Las fallas que la app atrapa (o que se le escapan) quedan anotadas en este teléfono
   (las últimas 100) y se ven en Estado de la conexión › Errores recientes, con botón para copiarlas y mandarlas a soporte. */
const LS_ERR='empaque-errores';let ERRS=[];try{const j=JSON.parse(localStorage.getItem(LS_ERR)||'[]');if(Array.isArray(j))ERRS=j.slice(-100)}catch(e){}
function errNote(where,e){try{
  const m=String(e&&(e.message||e.msg||e.reason)||e||'').slice(0,300),st=e&&e.status?' ['+e.status+']':'';
  const last=ERRS[ERRS.length-1];if(last&&last.w===where&&last.m===m+st&&Date.now()-last.t<60000){last.n=(last.n||1)+1;last.t=Date.now()}
  else ERRS.push({t:Date.now(),w:String(where||'').slice(0,60),m:m+st,v:APP_VER});
  if(ERRS.length>100)ERRS=ERRS.slice(-100);localStorage.setItem(LS_ERR,JSON.stringify(ERRS));
}catch(x){}}
window.addEventListener('error',ev=>{errNote('script',ev&&(ev.error||ev.message))});
window.addEventListener('unhandledrejection',ev=>{errNote('promesa',ev&&ev.reason)});
function errHtml(){
  if(!ERRS.length)return '';
  const L=ERRS.slice(-15).reverse().map(x=>`<div class="kv"><span>${esc(fmtTs(x.t))}${x.n>1?' ×'+x.n:''} · ${esc(x.w)}</span><small>${esc(x.m)}</small></div>`).join('');
  return `<details class="panel"><summary>Errores recientes (${fmt(ERRS.length)})</summary>${L}<div class="pact"><button class="btn sm" data-act="errcopy">Copiar para soporte</button> <button class="btn sm" data-act="errclear">Borrar lista</button></div></details>`;
}
function netHtml(){
  const st=netState(),p=pendN(),last=meta.lastSync?fmtTs(meta.lastSync):'nunca';
  const lab={ok:'Nube',off:'Solo este teléfono',login:'Sin sesión',na:'Sin base de datos'}[st];
  return `<h3>Estado de la conexión</h3><div class="netbar" data-n="${st}"${NET.saveErr?' data-err="1"':''} style="margin:0 0 10px;border-radius:10px"><i aria-hidden="true"></i><span id="net-state">${esc(netText())}</span></div>`
   +`<div class="panel"><div class="kv"><span>Modo</span><b>${lab}</b></div><div class="kv"><span>Última sincronización</span><b>${esc(last)}</b></div><div class="kv" style="border-bottom:0"><span>Cambios en este teléfono sin subir</span><b>${fmt(p)}</b></div></div>`
   +(NET.saveErr?'<p class="warnbox">El último guardado en este teléfono falló (memoria llena o bloqueada). Lo que captures puede perderse si cierras la app: sincroniza o usa «Pasar mis cambios» ahora.</p>':'')
   +`<p class="note" style="margin:10px 0">${st==='off'?'Sin internet sigue capturando: todo queda en este teléfono y sube solo cuando vuelva la red. Para que el jefe vea lo tuyo ahora, toca «Pasar mis cambios» y mándale el archivo por Quick Share o AirDrop (funcionan sin internet). No vuelvan a capturar a mano lo que ya está en otro teléfono.':'Si un teléfono se queda sin internet, sus cambios se pueden pasar a otro con un archivo y se juntan sin duplicar.'}</p>`
   +`<div class="pact">${st==='login'?'<button class="btn sm primary" data-act="sync">Entrar y sincronizar</button>':'<button class="btn sm primary" data-act="sync">Sincronizar ahora</button>'}<button class="btn sm" data-act="juntexp">Pasar mis cambios</button>${canJunt()?'<button class="btn sm" data-act="juntimp">Juntar cambios de otro teléfono</button>':''}${canManClose()?'<button class="btn sm" data-act="concopen">Conciliación</button>':''}</div><input type="file" id="juntfile" accept=".json,application/json" hidden>`
   +errHtml()
   +'<div class="srow2"><button class="btn" data-act="closesheet">Cerrar</button></div>';
}

/* ---- pasar y juntar cambios entre teléfonos ---- */
async function juntExport(){
  const os=[...dirty].map(id=>orders.find(o=>o.id===id)).filter(Boolean);
  const es=(INV.dirty||[]).map(id=>INV.entradas.find(x=>x.id===id)).filter(Boolean);
  const cs=(typeof CONT!=='undefined'?CONT.dirty:[]).map(id=>CONT.list.find(x=>x.id===id)).filter(Boolean);
  if(!os.length&&!es.length&&!cs.length){toast('No tienes cambios sin subir: no hay nada que pasar');return}
  const d={app:'registro-empaque',kind:'cambios',v:1,de:whoName(),user:meU(),dev:RT.dev,version:APP_VER,at:Date.now(),
    orders:os.map(o=>({d:o,so:SYNCB.so[o.id]==null?null:SYNCB.so[o.id],b:SYNCB.o[o.id]||null})),
    entradas:es.map(e=>({d:e,so:SYNCB.se[e.id]==null?null:SYNCB.se[e.id],b:SYNCB.e[e.id]||null})),cont:cs};
  const nm=String(whoName()).replace(/[^A-Za-z0-9]+/g,'_').slice(0,24)||'telefono',t=new Date(),hh=pad(t.getHours(),2)+pad(t.getMinutes(),2);
  await saveFile('Cambios_'+nm+'_'+todayISO()+'_'+hh+'.json',new Blob([JSON.stringify(d)],{type:'application/json'}),'Pasar mis cambios');
  logAdd({k:'note',where:'Conexión',ctx:{t:'r',id:'junt',cod:'Cambios'},lab:'Pasó sus cambios a otro teléfono',o:'',n:os.length+' viajes, '+es.length+' entradas'});
}
/* la base común: la versión de la nube que vieron los dos; si este teléfono vio otra, la del que manda */
function juntBase(x,g,id){const so=g==='o'?SYNCB.so[id]:SYNCB.se[id],B=g==='o'?SYNCB.o[id]:SYNCB.e[id];if(x.so!=null&&so===x.so&&B)return B;if(x.b&&impOk(x.b))return cleanRec(clone(x.b));return undefined}
function juntPlan(j){
  const out={o:[],e:[],c:[],bad:0,same:0};
  (Array.isArray(j.orders)?j.orders:[]).forEach(x=>{
    const r=x&&x.d?cleanRec(clone(x.d)):null;if(!impOrder(r)){out.bad++;return}
    const i=orders.findIndex(o=>o.id===r.id);
    if(i<0){out.o.push({nuevo:true,m:r});return}
    const L=orders[i],m=merge3(juntBase(x,'o',r.id),L,r);m.id=r.id;
    const a=Object.assign({},L,{updatedAt:0}),b=Object.assign({},m,{updatedAt:0});
    if(jeq(a,b)){out.same++;return}
    out.o.push({nuevo:false,m:m,i:i});
  });
  (Array.isArray(j.entradas)?j.entradas:[]).forEach(x=>{
    const r=x&&x.d?cleanRec(clone(x.d)):null;if(!impEntrada(r)){out.bad++;return}
    const i=INV.entradas.findIndex(e=>e.id===r.id);
    if(i<0){out.e.push({nuevo:true,m:r});return}
    const L=INV.entradas[i],m=merge3(juntBase(x,'e',r.id),L,r);m.id=r.id;
    if(jeq(Object.assign({},L,{updatedAt:0}),Object.assign({},m,{updatedAt:0}))){out.same++;return}
    out.e.push({nuevo:false,m:m,i:i});
  });
  if(typeof CONT!=='undefined')(Array.isArray(j.cont)?j.cont:[]).forEach(c=>{if(c&&okId(c.id)&&impOk(c)&&!CONT.list.some(y=>y.id===c.id))out.c.push(cleanRec(clone(c)))});
  return out;
}
function juntImport(inp){
  const f=inp.files&&inp.files[0];if(!f)return;
  if(!canJunt()){toast('Solo el jefe de empaque o la administración juntan cambios de otro teléfono');inp.value='';return}
  if(f.size>IMP_MAX*4){toast('El archivo es demasiado grande');inp.value='';return}
  const rd=new FileReader();
  rd.onload=function(){
    try{
      const j=JSON.parse(rd.result);if(!j||j.app!=='registro-empaque'||j.kind!=='cambios')throw new Error('formato');
      if(j.dev&&j.dev===RT.dev){toast('Ese archivo salió de este mismo teléfono');inp.value='';return}
      const P=juntPlan(j),no=P.o.filter(x=>x.nuevo).length,uo=P.o.length-no,ne=P.e.filter(x=>x.nuevo).length,ue=P.e.length-ne;
      if(!P.o.length&&!P.e.length&&!P.c.length){toast(P.bad?'El archivo no trae cambios válidos ('+P.bad+' descartados)':'Ya tienes todo lo que trae ese archivo');inp.value='';return}
      const de=String(j.de||'otro teléfono').slice(0,60),ver=j.version&&j.version!==APP_VER?'\n\nOjo: ese teléfono tiene la versión '+String(j.version).slice(0,12)+' y este la '+APP_VER+'. Lo ideal es que todos tengan la misma.':'';
      const msg='Juntar los cambios de '+de+':\n· '+no+' viajes nuevos y '+uo+' viajes que se juntan con los tuyos\n· '+ne+' entradas nuevas y '+ue+' que se juntan'+(P.c.length?'\n· '+P.c.length+' movimientos de tarimas':'')+(P.bad?'\n· '+P.bad+' registros no válidos se descartan':'')+'\n\nSe junta campo por campo y tarima por tarima: no se duplica lo que ya tienes. Si los dos cambiaron lo mismo, queda lo de este teléfono.'+ver+'\n\n¿Continuar?';
      if(!window.confirm(msg)){toast('Cancelado');inp.value='';return}
      const now=Date.now();
      P.o.forEach(x=>{x.m.updatedAt=now;if(x.nuevo)orders.push(x.m);else orders[x.i]=x.m;dirty.add(x.m.id)});
      P.e.forEach(x=>{x.m.updatedAt=now;if(x.nuevo)INV.entradas.push(x.m);else INV.entradas[x.i]=x.m;if(INV.dirty.indexOf(x.m.id)<0)INV.dirty.push(x.m.id)});
      if(P.c.length){P.c.forEach(c=>CONT.list.push(c));saveCont()}
      if(P.e.length)saveInv();
      logAdd({k:'note',where:'Conexión',ctx:{t:'r',id:'junt',cod:'Cambios'},lab:'Juntó cambios de '+de,o:'',n:P.o.length+' viajes, '+P.e.length+' entradas'+(P.c.length?', '+P.c.length+' movimientos':'')});
      normOrders();invalidateStats();saveLocal();setSync();sheet=null;renderSheet();render();
      toast('Listo: se juntaron '+P.o.length+' viajes'+(P.e.length?' y '+P.e.length+' entradas':'')+' de '+de);
      if(codeDups().length)setTimeout(()=>toast('Hay códigos repetidos: revísalos en Conciliación',5000),2600);
    }catch(e){toast('El archivo no es de «Pasar mis cambios»')}
    inp.value='';
  };
  rd.readAsText(f);
}
document.addEventListener('change',e=>{if(e.target&&e.target.id==='juntfile')juntImport(e.target)});

/* ---- Conciliación: códigos repetidos y tarimas que parecen la misma ---- */
function palSig(sh,p){const M={};(p.lines||[]).forEach(l=>{const c=n0(l.cant);if(!(c>0))return;const k=resolveProd(sh,l.prod)+'|'+(PCAL_KEY[l.cal]||l.cal)+'|'+lineQ(p,l);M[k]=(M[k]||0)+c});return M}
function palSim(A,B){const ta=Object.values(A).reduce((a,x)=>a+x,0),tb=Object.values(B).reduce((a,x)=>a+x,0);if(!ta||!tb)return 0;let c=0;Object.keys(A).forEach(k=>{if(B[k])c+=Math.min(A[k],B[k])});return c/Math.max(ta,tb)}
function palWho(p){const s=new Set();if(p.by)s.add(p.by);(p.lines||[]).forEach(l=>{if(l.by)s.add(l.by)});return [...s]}
function palWhere(p){return p.carg?'cargada al thermo':p.alm?'almacén '+(p.alm.e?'E'+p.alm.e+' ':'')+espLug(p.alm.c,p.alm.r):'armado'}
function palDups(){
  const out=[];
  visible().forEach(m=>{if(!isLeader(m)||!m.traz||!Array.isArray(m.traz.tarimas))return;const T=m.traz.tarimas,sh=sheetsOf(m),ok=(m.conc&&m.conc.ok)||{};
    const S=T.map(p=>palSig(sh,p));
    for(let i=0;i<T.length;i++)for(let j=i+1;j<T.length;j++){
      const a=T[i],b=T[j];if(palTipo(a)!==palTipo(b))continue;const ta=palTot(a),tb=palTot(b);if(ta<5||tb<5)continue;
      const k=[a.id,b.id].sort().join('~');if(ok[k])continue;
      const s=palSim(S[i],S[j]);if(s<0.9)continue;
      const wa=palWho(a),wb=palWho(b);if(wa.length&&wb.length&&wa.join()===wb.join())continue; /* la misma persona armó dos tarimas iguales: es normal */
      out.push({m:m,a:a,b:b,ia:i,ib:j,s:s,k:k});
    }
  });
  return out;
}
function concHtml(){
  const D=codeDups(),P=palDups(),ed=canManClose()&&!roRole;
  const trip=o=>`<b class="mono">${esc(o.cod)}</b>${o.variante==='1.5'?' · hoja 1.5':''} · ${esc(o.fecha||'')}${o.customer?' · '+esc(o.customer):''} · ${fmt((o.productores||[]).length)} productores${o.prov?' · creado sin internet por '+esc(o.prov.by||'—')+' a las '+esc(hhmm(o.prov.at)):''}`;
  let h='<h3>Conciliación</h3><p class="note" style="margin-bottom:10px">Lo que quedó raro después de trabajar sin internet. Nada se cambia solo: tú decides, y todo queda en el Registro de cambios.</p>';
  h+='<div class="sec">Códigos repetidos</div>';
  if(!D.length)h+='<div class="panel"><p class="note">Ninguno.</p></div>';
  D.forEach(g=>{h+='<div class="panel">'+g.map((o,i)=>{const nx=codOf(o.emp,o.anio,nextCons(o.emp,o.anio));return `<div class="kv" style="display:block"><div>${trip(o)}</div>${ed&&i>0?`<div class="pact" style="margin-top:6px"><button class="btn sm" data-act="concrec:${esc(o.id)}">Darle el código ${esc(nx)}</button><button class="btn sm" data-act="concgo:${esc(o.id)}">Abrir</button></div>`:`<div class="pact" style="margin-top:6px"><button class="btn sm" data-act="concgo:${esc(o.id)}">Abrir</button></div>`}</div>`}).join('')+'<p class="note" style="margin-top:6px">Se queda con el código el que se creó primero. Si el otro es el mismo viaje capturado dos veces, ábrelo y pasa lo que falte antes de eliminarlo.</p></div>'});
  h+='<div class="sec">Tarimas que parecen la misma</div>';
  if(!P.length)h+='<div class="panel"><p class="note">Ninguna.</p></div>';
  P.slice(0,40).forEach(x=>{const side=(p,i)=>`<div><b>${esc(palName(p,i))}</b> · ${fmt(palTot(p))} cajas · ${esc(palWhere(p))}${palWho(p).length?' · '+esc(palWho(p).join(', ')):''}</div>`;
    const canDel=p=>ed&&!p.carg&&!p.alm&&!manClosed(x.m);
    h+=`<div class="panel"><div class="kv" style="display:block"><div><b class="mono">${esc(x.m.cod)}</b> · ${Math.round(x.s*100)}% iguales</div>${side(x.a,x.ia)}${side(x.b,x.ib)}</div>${ed?`<div class="pact">${canDel(x.b)?`<button class="btn sm" data-act="concdel:${esc(x.m.id)}:${esc(x.b.id)}">Quitar ${esc(palName(x.b,x.ib))}</button>`:''}${canDel(x.a)?`<button class="btn sm" data-act="concdel:${esc(x.m.id)}:${esc(x.a.id)}">Quitar ${esc(palName(x.a,x.ia))}</button>`:''}<button class="btn sm" data-act="concok:${esc(x.m.id)}:${esc(x.k)}">No es la misma</button></div>`:''}</div>`});
  if(P.length>40)h+=`<p class="note">Y ${fmt(P.length-40)} más.</p>`;
  h+=`<p class="note" style="margin-top:8px">Una tarima quitada se puede restaurar desde el Registro de cambios. Las del almacén o cargadas no se quitan aquí: primero se desflejan o se regresan.</p><div class="srow2"><button class="btn" data-act="closesheet">Cerrar</button></div>`;
  return h;
}
function concAct(act,parts){
  if(!canManClose()||roRole)return;
  if(act==='concrec'){const o=orders.find(x=>x.id===parts[1]);if(!o||!isDup(o))return;const old=o.cod,c=nextCons(o.emp,o.anio);
    if(!window.confirm('¿Cambiar '+old+' a '+codOf(o.emp,o.anio,c)+'? Revisa después su hoja 1.5 y sus documentos.'))return;
    o.cons=c;o.cod=codOf(o.emp,o.anio,c);delete o.prov;touch(o);logAdd({k:'note',ctx:ctxOf(o),lab:'Código repetido corregido',o:old,n:o.cod});renderSheet();render();toast(old+' ahora es '+o.cod);return}
  if(act==='concgo'){const o=orders.find(x=>x.id===parts[1]);if(!o)return;sheet=null;renderSheet();curId=o.id;view='order';tab='captura';render();window.scrollTo(0,0);return}
  if(act==='concdel'){const m=orders.find(x=>x.id===parts[1]);if(!m||!m.traz)return;const t=ensureTraz(m),i=t.tarimas.findIndex(p=>p.id===parts[2]);if(i<0)return;const p=t.tarimas[i];
    if(p.carg||p.alm||manClosed(m)){toast('Esa tarima no se quita aquí');return}
    if(!window.confirm('¿Quitar la '+palName(p,i)+' ('+fmt(palTot(p))+' cajas) de '+m.cod+'? Se puede restaurar desde el Registro de cambios.'))return;
    logAdd({k:'del',what:'t',ctx:ctxOf(m),snap:clone(p),idx:i,lab:'Tarima '+(i+1)+' (duplicada, Conciliación)'});t.tarimas.splice(i,1);touch(m);renderSheet();render();toast(palName(p,i)+' quitada');return}
  if(act==='concok'){const m=orders.find(x=>x.id===parts[1]);if(!m)return;m.conc=m.conc||{};m.conc.ok=m.conc.ok||{};m.conc.ok[parts.slice(2).join(':')]=1;touch(m);renderSheet();return}
}

/* ---------- v8.41 · Modo local con la HP de la oficina ----------
   Cuando se cae el internet, la HP corre el «Servidor de planta» y cada teléfono (app de Android) prende el interruptor
   «Modo local» en la franja de arriba. Entonces los viajes se sincronizan con la HP por CITRILAR WIFI con las mismas reglas
   de siempre (unión campo por campo y control de versión), y los teléfonos se ven entre sí cada pocos segundos.
   La franja queda amarilla (Red local). Al volver el internet se apaga el interruptor y el teléfono sube a la nube todo lo
   que cambió en modo local, contra la última versión de la nube que conocía (así no pisa lo de nadie).
   En esta versión por la HP pasan los viajes (manifiesto, empaques, tarimas y trazabilidad). Entradas, bitácora y
   movimientos de tarimas se guardan en cada teléfono y suben a la nube al volver el internet. */
const LS_LOCAL='empaque-local',LS_LOCALB='empaque-local-base';
const LOCAL={on:false,ip:'',port:8787,key:'',hubId:'',name:'',since:0,chg:[],mine:{inv:{},cont:{},log:{},evi:{}},ccur:'',ok:0,fail:0,devs:[],avail:0,cloud:0,busy:false,err:'',edit:false,lastHola:0,lastPoll:0,lastProbe:0,lastCloud:0,B:null};
(function(){try{const j=JSON.parse(localStorage.getItem(LS_LOCAL)||'null');if(j&&typeof j==='object')['on','ip','port','key','hubId','name','since','chg','mine','ccur'].forEach(k=>{if(j[k]!=null)LOCAL[k]=j[k]})}catch(e){}
  if(!Array.isArray(LOCAL.chg))LOCAL.chg=[];
  if(!LOCAL.mine||typeof LOCAL.mine!=='object')LOCAL.mine={};['inv','cont','log','evi'].forEach(k=>{const v=LOCAL.mine[k];if(!v||typeof v!=='object'||Array.isArray(v))LOCAL.mine[k]={}});
  if(LOCAL.on){try{LOCAL.B=JSON.parse(localStorage.getItem(LS_LOCALB)||'null')}catch(e){LOCAL.B=null}LOCAL.ok=Date.now()}})();
function saveLocalCfg(){try{localStorage.setItem(LS_LOCAL,JSON.stringify({on:LOCAL.on,ip:LOCAL.ip,port:LOCAL.port,key:LOCAL.key,hubId:LOCAL.hubId,name:LOCAL.name,since:LOCAL.since,chg:LOCAL.chg,mine:LOCAL.mine,ccur:LOCAL.ccur||''}))}catch(e){lsFail(e)}}
/* v8.46 · por la HP pasan también entradas, conteos, registro de cambios y fotos. Antes de mandarlas a la HP se anota
   qué cambió ESTE teléfono (LOCAL.mine); solo eso sube a la nube al apagar el modo local (igual que los viajes). */
/* Se guarda la versión (hora) que dejó este teléfono: si después llega por la HP una versión más nueva de otro, esa la sube
   su autor y este teléfono no la vuelve a mandar con su permiso (p. ej. un conteo que el jefe ya validó). */
const LAN_K={inv:['updatedAt',()=>INV.dirty,()=>INV.entradas],cont:['updatedAt',()=>CONT.dirty,()=>CONT.list],log:['ts',()=>LOG.dirty,()=>LOG.list],evi:['ts',()=>EVI.dirty,()=>EVI.list]};
function lanMark(){const M=LOCAL.mine;Object.keys(LAN_K).forEach(k=>{try{const [f,D,L]=LAN_K[k],list=L();(D()||[]).forEach(id=>{const r=list.find(x=>x&&x.id===id);if(r)M[k][id]=+r[f]||0})}catch(e){}});saveLocalCfg()}
function lanMine(k){const M=(LOCAL.mine||{})[k]||{},[f,,L]=LAN_K[k],list=L();return Object.keys(M).filter(id=>{const r=list.find(x=>x&&x.id===id);return r&&(+r[f]||0)===M[id]})}
function mineN(){return Object.keys(LAN_K).reduce((n,k)=>{try{return n+lanMine(k).length}catch(e){return n}},0)}
/* cambios hechos o recibidos en modo local: son los que subirán a la nube al salir */
function lchg(id){if(!LOCAL.on||!id||LOCAL.chg.indexOf(id)>=0)return;LOCAL.chg.push(id);saveLocalCfg()}
/* el modo local necesita la app de Android (la versión web no puede hablar con la HP por seguridad del navegador) */
/* v8.47 · el modo local funciona en la APK (http, por el propio Android) y en iPhone y la versión web (https con el sello de la
   planta instalado en el equipo; la HP escucha cifrado en el puerto siguiente: 8788). */
function hubNative(){const C=window.Capacitor;return !!(C&&C.Plugins&&C.Plugins.CapacitorHttp)}
function hubWeb(){return !hubNative()&&location.protocol==='https:'&&typeof fetch==='function'}
function hubCan(){return hubNative()||hubWeb()}
function hubSelloUrl(ip){return 'http://'+(ip||LOCAL.ip||'IP-de-la-HP')+':'+(LOCAL.port||8787)+'/planta/sello'}
const hubPaired=()=>!!(LOCAL.ip&&LOCAL.key);
function hubIp(s){s=String(s||'').trim().replace(/^https?:\/\//i,'').replace(/\/.*$/,'');const m=/^(\d{1,3}(?:\.\d{1,3}){3})(?::(\d{2,5}))?$/.exec(s);if(!m)return null;if(m[1].split('.').some(n=>+n>255))return null;return {ip:m[1],port:m[2]?+m[2]:8787}}
async function hubReq(path,opts,ip,key,port){
  opts=opts||{};const web=hubWeb(),pp=port||LOCAL.port||8787,url=(web?'https://':'http://')+(ip||LOCAL.ip)+':'+(web?pp+1:pp)+path,tmo=opts.timeout||8000;
  const h={'Content-Type':'application/json','x-planta-key':key||LOCAL.key,'x-planta-dev':RT.dev,'x-planta-user':encodeURIComponent(whoName()||'')};
  const oh=opts.headers||{};Object.keys(oh).forEach(k=>{if(k!=='Authorization'&&k!=='apikey')h[k]=oh[k]});
  const CH=hubNative()?window.Capacitor.Plugins.CapacitorHttp:null;let st=0,data=null;
  if(CH){
    const r=await CH.request({url:url,method:opts.method||'GET',headers:h,data:opts.body,connectTimeout:Math.min(tmo,4000),readTimeout:tmo});
    st=+r.status||0;data=r.data;
  }else{
    const ac=typeof AbortController!=='undefined'?new AbortController():null,t=ac?setTimeout(()=>{try{ac.abort()}catch(x){}},tmo):0;
    try{const r=await fetch(url,{method:opts.method||'GET',headers:h,body:opts.body?JSON.stringify(opts.body):undefined,signal:ac?ac.signal:undefined,mode:'cors',cache:'no-store'});st=r.status;data=await r.text()}
    catch(e){if(web&&!(e&&e.name==='AbortError')){const x=new Error('sin conexión cifrada');x.hub=true;x.sello=true;throw x}throw e}
    finally{clearTimeout(t)}
  }
  if(typeof data==='string'){try{data=data?JSON.parse(data):null}catch(e){data=null}}
  if(st<200||st>=300){const err=new Error('HTTP '+st);err.status=st;err.hub=true;err.code=(data&&data.error)||'';throw err}
  return data;
}
function hubHola(ip,key,port,tmo){return hubReq('/planta/hola',{timeout:tmo||4000},ip,key,port)}
/* si la HP cambió de dirección (el router le dio otra), se busca en la misma red por su identificador */
async function hubFind(){
  if(hubWeb())return null;
  const p=String(LOCAL.ip||'').split('.');if(p.length!==4||!LOCAL.hubId)return null;const pre=p.slice(0,3).join('.')+'.';
  for(let a=1;a<255;a+=32){
    const tries=[];for(let i=a;i<Math.min(a+32,255);i++){const ip=pre+i;tries.push(hubHola(ip,LOCAL.key,LOCAL.port,900).then(h=>h&&h.hubId===LOCAL.hubId?ip:null,()=>null))}
    const f=(await Promise.all(tries)).find(Boolean);if(f){LOCAL.ip=f;saveLocalCfg();return f}
  }
  return null;
}
function hubSeen(h){if(!h)return;LOCAL.ok=Date.now();LOCAL.fail=0;LOCAL.err='';if(h.nombre)LOCAL.name=String(h.nombre).slice(0,40);LOCAL.devs=Array.isArray(h.devs)?h.devs.filter(d=>d&&d.dev!==RT.dev).map(d=>String(d.u||'—').slice(0,40)):[]}
function hubErr(e){if(e&&e.sello)return 'No se pudo conectar cifrado con la HP. Revisa que la HP esté prendida y en CITRILAR WIFI, y que este equipo tenga instalado el sello de la planta ('+hubSelloUrl()+').';return e&&e.status===401?'La clave no coincide con la de la HP. Revísala en la ventana del servidor.':'No encuentro la HP. Revisa que esté prendida, conectada a CITRILAR WIFI y con la ventana del servidor abierta.'}
const waitSync=async()=>{for(let i=0;i<80&&syncing;i++)await new Promise(r=>setTimeout(r,250))};
const ordSame=(a,b)=>{try{const x=Object.assign({},a),y=Object.assign({},b);delete x.updatedAt;delete y.updatedAt;return JSON.stringify(x)===JSON.stringify(y)}catch(e){return false}};

/* entrar: se guarda la última versión de la nube que conocía este teléfono y se le pasan a la HP los viajes recientes */
async function localOn(){
  if(LOCAL.on||LOCAL.busy)return;
  if(!hubCan()){LOCAL.err='El modo local necesita la app de Android o la versión web desde https (dominio de la empresa). En este equipo usa «Pasar mis cambios».';renderSheet();return}
  if(!hubPaired()){LOCAL.edit=true;renderSheet();return}
  if(!session){LOCAL.err='Primero entra con tu usuario (se necesita internet una vez por teléfono).';renderSheet();return}
  LOCAL.busy=true;LOCAL.err='';renderSheet();
  try{
    let h=null;try{h=await hubHola()}catch(e){if(e&&e.status===401)throw e;if(await hubFind())h=await hubHola();else throw e}
    await waitSync();
    LOCAL.B={so:Object.assign({},SYNCB.so),o:Object.assign({},SYNCB.o),se:Object.assign({},SYNCB.se),e:Object.assign({},SYNCB.e),
      log:{cur:LOG.cur||'',inc:LOG.inc},evi:{cur:EVI.cur||'',inc:EVI.inc,since:EVI.since||0}};
    try{localStorage.setItem(LS_LOCALB,JSON.stringify(LOCAL.B))}catch(e){/* sin memoria: se queda en la memoria de la app */}
    LOCAL.chg=[...dirty];SYNCB.so={};SYNCB.se={};LOCAL.mine={inv:{},cont:{},log:{},evi:{}};LOCAL.ccur='';lanMark();
    LOG.cur='';LOG.inc=null;EVI.cur='';EVI.inc=null;EVI.since=0; /* la HP lleva su propia hora de recibido */
    const lim=Date.now()-45*86400000;orders.forEach(o=>{if(!o.ejemplo&&(o.updatedAt||0)>=lim)dirty.add(o.id)});
    rtStop();LOCAL.on=true;LOCAL.since=Date.now();hubSeen(h);LOCAL.avail=0;LOCAL.cloud=0;
    saveLocalCfg();saveSyncB();saveLocal();setSync();
    toast('Modo local: conectado a '+(LOCAL.name||'la HP'));
    doSync(true);
  }catch(e){LOCAL.err=hubErr(e)}
  finally{LOCAL.busy=false;netUpd();if(sheet&&sheet.kind==='net')renderSheet();softRender()}
}
/* salir: vuelve la base de la nube y queda pendiente todo lo que cambió en modo local */
async function localOff(){
  if(!LOCAL.on||LOCAL.busy)return;
  LOCAL.busy=true;
  try{
    await waitSync();
    const B=LOCAL.B||{};SYNCB.so=Object.assign({},B.so||{});SYNCB.o=Object.assign({},B.o||{});
    /* si el modo local empezó con una versión anterior (sin referencia de entradas), no se sabe qué tiene la nube: se sube lo propio y la nube lo junta */
    SYNCB.se=Object.assign({},B.se||{});SYNCB.e=Object.assign({},B.e||{});
    if(B.log){LOG.cur=B.log.cur||'';LOG.inc=B.log.inc}if(B.evi){EVI.cur=B.evi.cur||'';EVI.inc=B.evi.inc;EVI.since=B.evi.since||0}
    lanMark();const uni=(a,b)=>[...new Set((a||[]).concat(b||[]))];
    INV.dirty=uni(INV.dirty,lanMine('inv').filter(id=>{const e=INV.entradas.find(x=>x.id===id),b=SYNCB.e[id];return !(b&&SYNCB.se[id]!=null&&ordSame(e,b))}));
    CONT.dirty=uni(CONT.dirty,lanMine('cont'));
    LOG.dirty=uni(LOG.dirty,lanMine('log'));
    EVI.dirty=uni(EVI.dirty,lanMine('evi').filter(id=>EVI.list.some(r=>r.id===id&&!r.hpOnly)));
    saveInv();saveCont();saveLog();saveEvi();
    /* v8.43.2 · A-04: solo lo que cambió este teléfono (antes también lo recibido de otros por la HP, que subía con el permiso de quien apagaba) */
    const ids=new Set(LOCAL.chg);dirty.clear();
    ids.forEach(id=>{const o=orders.find(x=>x.id===id);if(!o)return;const b=SYNCB.o[id];if(b&&SYNCB.so[id]!=null&&ordSame(o,b))return;dirty.add(id)});
    const nOtros=INV.dirty.length+CONT.dirty.length+LOG.dirty.length+EVI.dirty.length;LOCAL.on=false;LOCAL.chg=[];LOCAL.mine={inv:{},cont:{},log:{},evi:{}};LOCAL.ccur='';LOCAL.B=null;LOCAL.devs=[];LOCAL.since=0;LOCAL.cloud=0;
    try{localStorage.removeItem(LS_LOCALB)}catch(e){}
    NET.ok=null;saveLocalCfg();saveSyncB();saveLocal();setSync();
    toast(dirty.size||nOtros?'Modo local apagado: subiendo a la nube '+(dirty.size?fmt(dirty.size)+(dirty.size===1?' viaje':' viajes'):'')+(dirty.size&&nOtros?' y ':'')+(nOtros?fmt(nOtros)+(nOtros===1?' registro más':' registros más'):''):'Modo local apagado');
    doSync(true);rtStart();setTimeout(eviPump,1500);
  }finally{LOCAL.busy=false;netUpd();if(sheet&&sheet.kind==='net')renderSheet();softRender()}
}
async function localPair(){
  const s=sheet||{},lc=s.lc||{},x=hubIp(lc.ip),k=String(lc.key||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
  if(!x){LOCAL.err='Escribe la dirección tal como sale en la ventana de la HP, por ejemplo 192.168.1.50';renderSheet();return}
  if(k.length<6){LOCAL.err='Escribe la clave que sale en la ventana de la HP.';renderSheet();return}
  if(!hubCan()){LOCAL.err='El modo local necesita la app de Android o la versión web desde https (dominio de la empresa). En este equipo usa «Pasar mis cambios».';renderSheet();return}
  LOCAL.busy=true;LOCAL.err='';renderSheet();
  try{
    const h=await hubHola(x.ip,k,x.port);if(!h||!h.hubId)throw new Error('no es la HP');
    Object.assign(LOCAL,{ip:x.ip,port:x.port,key:k,hubId:String(h.hubId).slice(0,40),edit:false});hubSeen(h);saveLocalCfg();
  }catch(e){LOCAL.err=hubErr(e);LOCAL.busy=false;renderSheet();return}
  LOCAL.busy=false;await localOn();
}

