{const t0=touch;touch=function(o){t0(o);if(LOCAL.on&&o&&o.id)lchg(o.id)}}
{const c0=canAuto;canAuto=function(){if(LOCAL.on)return cfgOK()&&!!session&&!syncing&&!LOCAL.busy;return c0()}}
{const a0=autoKick;autoKick=function(ms){
  if(!LOCAL.on)return a0(ms);
  try{if(autoT||!canAuto())return;if(ms==null&&!dirty.size)return;
    const d=ms!=null?ms:Math.min(800*Math.pow(2,autoFail),30000);autoT=setTimeout(()=>{autoT=null;if(canAuto())doSync(true)},d)}catch(e){}}}
{const r0=rtStart;rtStart=function(){if(LOCAL.on)return;return r0()}}
setInterval(()=>{
  const t=Date.now();
  if(LOCAL.on){
    if(!document.hidden&&canAuto()&&t-LOCAL.lastPoll>=2800){LOCAL.lastPoll=t;doSync(true)}
    if(t-LOCAL.lastHola>=6000){LOCAL.lastHola=t;hubHola().then(h=>{hubSeen(h);netUpd()},()=>{LOCAL.fail++;netUpd()})}
    /* ¿volvió el internet? se avisa para apagar el modo local (no se apaga solo) */
    if(cfgOK()&&t-LOCAL.lastCloud>=30000&&navigator.onLine!==false){LOCAL.lastCloud=t;
      const ac=typeof AbortController!=='undefined'?new AbortController():null,tm=ac?setTimeout(()=>{try{ac.abort()}catch(x){}},5000):0;
      fetch(String(CFG.SUPABASE_URL).replace(/\/$/,'')+'/auth/v1/health',{headers:{apikey:CFG.SUPABASE_KEY},signal:ac?ac.signal:undefined}).then(r=>{LOCAL.cloud=r.ok?t:0},()=>{LOCAL.cloud=0}).finally(()=>{clearTimeout(tm);netUpd()})}
    netUpd();
  }else if(hubCan()&&hubPaired()&&netOff()&&t-LOCAL.lastProbe>=20000){
    /* sin nube: se ve si la HP está prendida para sugerir el modo local */
    LOCAL.lastProbe=t;hubHola(null,null,null,2500).then(h=>{LOCAL.avail=h&&h.hubId===LOCAL.hubId?t:0;if(h)LOCAL.name=String(h.nombre||LOCAL.name).slice(0,40);netUpd()},()=>{LOCAL.avail=0;netUpd()});
  }
},1000);

/* ---- franja y ventana de estado ---- */
{const n0=netState;netState=function(){if(LOCAL.on&&cfgOK())return Date.now()-(LOCAL.ok||0)<20000&&LOCAL.fail<3?'local':'lost';return n0()}}
