document.addEventListener('input',e=>{const el=e.target;if(!el||!el.dataset||!el.dataset.lc||!sheet||sheet.kind!=='net')return;sheet.lc=sheet.lc||{ip:LOCAL.ip,key:''};sheet.lc[el.dataset.lc]=el.value});
function localAct(act,parts){
  if(act==='localsw'){if(LOCAL.on)localOff();else localOn();return}
  if(act==='localpair'){localPair();return}
  if(act==='localedit'){LOCAL.edit=parts[1]==='1';LOCAL.err='';if(sheet)sheet.lc={ip:LOCAL.ip,key:''};renderSheet();return}
}

/* ---------- v8.43 · Evidencias: fotos de fruta y tickets ----------
   Entrada de Fruta (cada productor) y destinos de segunda del Almacén (venta nacional, Torreón, Juguera, desecho).
   La foto se reduce y se guarda en WebP (fruta a color; ticket en escala de grises, que pesa menos) en Supabase Storage
   (bucket privado «evidencias»). Los datos de cada foto van en la tabla «evidencias» (todos los de la app las ven).
   Sin internet la foto se queda en el teléfono (IndexedDB) como «pendiente de subir» y se sube sola al volver la señal.
   Vista previa en WebP; la descarga se convierte a JPG. Borrar pide justificación: quien la subió (el mismo día) o administración. */
const EVI_BUCKET='evidencias',EVI_MAX=5,LS_EVI='empaque-evidencias';
const EVI_K={fr:'Foto de fruta',tk:'Ticket'};
const EVI_T={nac:'Venta nacional',tor:'Venta Torreón',jug:'Juguera',des:'Desecho'};
let EVI={list:[],dirty:[],noTable:false,since:0};
(function(){try{const j=JSON.parse(localStorage.getItem(LS_EVI)||'null');if(j&&Array.isArray(j.list))EVI={list:j.list,dirty:Array.isArray(j.dirty)?j.dirty:[],noTable:false,since:+j.since||0,cur:typeof j.cur==='string'?j.cur:'',inc:j.inc===true?true:null}}catch(e){}})();
function saveEvi(){try{localStorage.setItem(LS_EVI,JSON.stringify({list:EVI.list,dirty:EVI.dirty,since:EVI.since,cur:EVI.cur||'',inc:EVI.inc===true}))}catch(e){lsFail(e)}}
/* suben fotos: superadmin, admin, jefe de inocuidad y jefe de empaque (los mismos que dan destino en el Almacén) */
function eviCan(){return canManClose()&&!roRole}
function eviSameDay(ts){const a=new Date(ts),b=new Date();return a.getFullYear()===b.getFullYear()&&a.getMonth()===b.getMonth()&&a.getDate()===b.getDate()}
function eviDelCan(r){if(!r||r.del||roRole||r.hpOnly)return false;if(isAdmin())return true;return eviCan()&&!!authUser&&r.uid===authUser.id&&eviSameDay(r.at)}
function eviOf(ctx,ref,all){return EVI.list.filter(r=>r.ctx===ctx&&r.ref===ref&&(all||!r.del)).sort((a,b)=>a.at-b.at)}
function eviPend(){return EVI.list.filter(r=>r.pend&&!r.del).length}

/* ---- almacén local de las fotos pendientes (IndexedDB) ---- */
let EVI_DB=null;
function eviDb(){
  if(EVI_DB)return EVI_DB;
  EVI_DB=new Promise((res,rej)=>{try{const q=indexedDB.open('empaque-fotos',1);q.onupgradeneeded=()=>{q.result.createObjectStore('b')};q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)}catch(e){rej(e)}});
  EVI_DB.catch(()=>{EVI_DB=null});return EVI_DB;
}
async function eviIdb(mode,fn){const db=await eviDb();return new Promise((res,rej)=>{const tx=db.transaction('b',mode),st=tx.objectStore('b');let out;const r=fn(st);if(r)r.onsuccess=()=>{out=r.result};tx.oncomplete=()=>res(out);tx.onerror=()=>rej(tx.error);tx.onabort=()=>rej(tx.error)})}
const eviBlobPut=(id,b)=>eviIdb('readwrite',st=>st.put(b,id));
const eviBlobGet=id=>eviIdb('readonly',st=>st.get(id));
const eviBlobDel=id=>eviIdb('readwrite',st=>st.delete(id));

/* ---- compresión: lado mayor 1600 px (fruta) o 2000 px (ticket, para que se lean los números) ---- */
function eviLoadImg(file){return new Promise((res,rej)=>{const u=URL.createObjectURL(file),im=new Image();im.onload=()=>res({im:im,u:u});im.onerror=()=>{URL.revokeObjectURL(u);rej(new Error('img'))};im.src=u})}
function eviGray(ctx,w,h){
  const d=ctx.getImageData(0,0,w,h),a=d.data,H=new Uint32Array(256),n=w*h;
  for(let i=0;i<a.length;i+=4){const y=(a[i]*77+a[i+1]*150+a[i+2]*29)>>8;a[i]=y;H[y]++}
  /* contraste: se estira del 1 % más oscuro al 1 % más claro, para que el papel quede blanco y la tinta negra */
  /* el papel (lo más claro, ~10 % de arriba) pasa a blanco y la tinta (1 % más oscuro) a negro */
  let lo=0,hi=255,c=0;while(lo<255&&(c+=H[lo])<n*0.01)lo++;c=0;while(hi>0&&(c+=H[hi])<n*0.10)hi--;if(hi-lo<60)lo=Math.max(0,hi-200);if(hi<=lo){lo=0;hi=255}
  const k=255/(hi-lo);for(let i=0;i<a.length;i+=4){let y=Math.round((a[i]-lo)*k);y=y<0?0:y>255?255:y;a[i]=a[i+1]=a[i+2]=y;a[i+3]=255}
  ctx.putImageData(d,0,0);
}
let EVI_WASM=null;
async function eviWasmEnc(ctx,w,h,q){
  /* Safari (iPhone) no genera WebP con el canvas: se usa el codificador WebP de la app (WebAssembly, vendor/webp) */
  if(!EVI_WASM)EVI_WASM=import('./vendor/webp/webp_enc.js').then(m=>m.default({noInitialRun:true})).catch(e=>{EVI_WASM=null;throw e});
  const M=await EVI_WASM,d=ctx.getImageData(0,0,w,h);
  const o={quality:Math.round(q*100),target_size:0,target_PSNR:0,method:4,sns_strength:50,filter_strength:60,filter_sharpness:0,filter_type:1,partitions:0,segments:4,pass:1,show_compressed:0,preprocessing:0,autofilter:0,partition_limit:0,alpha_compression:1,alpha_filtering:1,alpha_quality:100,lossless:0,exact:0,image_hint:0,emulate_jpeg_size:0,thread_level:0,low_memory:0,near_lossless:100,use_delta_palette:0,use_sharp_yuv:0};
  const r=M.encode(d.data,w,h,o);if(!r)throw new Error('webp');return new Blob([r],{type:'image/webp'});
}
async function eviCompress(file,gray,forceWasm){
  const L=await eviLoadImg(file);
  try{
    const W0=L.im.naturalWidth,H0=L.im.naturalHeight,MX=gray?2000:1600,s=Math.min(1,MX/Math.max(W0,H0)),w=Math.max(1,Math.round(W0*s)),h=Math.max(1,Math.round(H0*s));
    const cv=document.createElement('canvas');cv.width=w;cv.height=h;const ctx=cv.getContext('2d',{willReadFrequently:!!gray});
    ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);ctx.imageSmoothingQuality='high';ctx.drawImage(L.im,0,0,w,h);
    if(gray)eviGray(ctx,w,h);
    const q=gray?0.72:0.8;let b=null;
    if(!forceWasm)b=await new Promise(r=>{try{cv.toBlob(x=>r(x),'image/webp',q)}catch(e){r(null)}});
    if(!b||b.type!=='image/webp')b=await eviWasmEnc(ctx,w,h,q);
    try{cv.width=cv.height=0}catch(e){}
    return {blob:b,w:w,h:h};
  }finally{URL.revokeObjectURL(L.u)}
}

/* ---- captura ---- */
let EVI_IN=null; /* {ctx,ref,k,meta} de la captura en curso */
let EVI_MENU=''; /* 'ctx|ref|k': muestra Cámara / Galería en lugar del botón */
const EVI_DRAFT=new Map(); /* fotos tomadas en la ventana de destino antes de registrar (solo en memoria) */
function eviFileInput(cam){
  let el=document.getElementById(cam?'evi-cam':'evi-gal');
  if(!el){el=document.createElement('input');el.type='file';el.accept='image/*';el.id=cam?'evi-cam':'evi-gal';if(cam)el.setAttribute('capture','environment');el.style.display='none';el.tabIndex=-1;el.setAttribute('aria-hidden','true');
    el.addEventListener('change',()=>{const f=el.files&&el.files[0];el.value='';if(f)eviGot(f)});document.body.appendChild(el)}
  return el;
}
const EVI_OPT=new Map();
function eviBoxRefresh(){let n=0;document.querySelectorAll('.evbox[data-evk]').forEach(el=>{const k=el.dataset.evk,i=k.indexOf('|'),h=eviBox(k.slice(0,i),k.slice(i+1),EVI_OPT.get(k));if(h){el.outerHTML=h;n++}});if(!n&&!sheet)softRender()}
async function eviGot(file){
  const c=EVI_IN;EVI_IN=null;if(!c)return;
  if(!/^image\//.test(file.type||'image/')){toast('Ese archivo no es una imagen');return}
  const n=c.ctx==='sal'?sdDraftN():eviOf(c.ctx,c.ref).length;if(n>=EVI_MAX){toast('Máximo '+EVI_MAX+' fotos aquí');return}
  toast('Comprimiendo la foto…');
  let z;try{z=await eviCompress(file,c.k==='tk')}catch(e){toast('No se pudo leer la foto. Intenta otra vez.');return}
  const id=uid(),now=Date.now(),r={id:id,ctx:c.ctx,ref:c.ref,k:c.k,at:now,ts:now,by:whoName(),uid:(authUser&&authUser.id)||'',w:z.w,h:z.h,sz:z.blob.size,orig:file.size};
  Object.assign(r,c.meta||{});
  if(c.ctx==='sal'){EVI_DRAFT.set(id,{r:r,blob:z.blob});eviUrlSet(id,URL.createObjectURL(z.blob));eviBoxRefresh();toast(EVI_K[c.k]+' lista · '+eviKb(z.blob.size)+'. Se sube al registrar.');return}
  r.path=eviPath(r);r.pend=1;
  try{await eviBlobPut(id,z.blob)}catch(e){toast('No se pudo guardar la foto en este teléfono');return}
  eviUrlSet(id,URL.createObjectURL(z.blob));
  EVI.list.push(r);saveEvi();logAdd({k:'note',where:'Evidencias',ctx:{t:'e',id:c.ref,cod:c.lab||''},lab:EVI_K[c.k]+' agregada',o:'',n:eviKb(z.blob.size)});
  eviBoxRefresh();toast(EVI_K[c.k]+' guardada · '+eviKb(z.blob.size)+(navigator.onLine===false?'. Se sube al volver la señal.':''));eviPump();
}
function eviKb(b){return b>=1048576?fmt(b/1048576,1)+' MB':fmt(Math.max(1,Math.round(b/1024)))+' KB'}
function eviPath(r){const s=x=>String(x||'x').replace(/[^A-Za-z0-9_-]/g,'_');return s(r.emp||'gen')+'/'+s(r.wk||'sin-semana')+'/'+s(r.ctx)+'/'+s(r.ref)+'/'+s(r.id)+'.webp'}

/* ---- subida (cola): una por una; si falla se reintenta después ---- */
let EVI_BUSY=false,EVI_T0=null;
/* v8.46 · fotos por la HP: el teléfono que la tomó manda el archivo a la HP (máx. 3 por vuelta) para que los demás la vean
   sin internet. A la nube la sube él mismo al volver la señal (eviPump), como siempre. */
function blobB64(b){return new Promise((ok,mal)=>{const fr=new FileReader();fr.onload=()=>ok(String(fr.result).replace(/^data:[^,]*,/,''));fr.onerror=()=>mal(fr.error);fr.readAsDataURL(b)})}
function b64Blob(s,t){const bin=atob(s),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);return new Blob([u],{type:t})}
async function lanFotosUp(){
  if(!LOCAL.on)return;let n=0;
  for(const r of EVI.list.filter(x=>x.pend&&!x.del&&!x.hp)){
    if(n>=3)break;const b=await eviBlobGet(r.id).catch(()=>null);if(!b)continue; /* sin archivo no se marca nada: lo resuelve eviPump con internet */
    await hubReq('/planta/foto/'+encodeURIComponent(r.id),{method:'PUT',body:{b64:await blobB64(b)},timeout:30000});
    r.hp=1;if(EVI.dirty.indexOf(r.id)<0)EVI.dirty.push(r.id);n++;
  }
  if(n)saveEvi();
}
async function eviPump(){
  if(EVI_BUSY||!cfgOK()||!session||LOCAL.on)return;
  const P=EVI.list.filter(r=>r.pend&&!r.del);if(!P.length){return}
  EVI_BUSY=true;let ok=0,fail=false;
  try{
    await ensureSession();
    for(const r of P){
      const b=await eviBlobGet(r.id).catch(()=>null);
      if(!b){r.pend=0;r.del={by:'app',at:Date.now(),why:'La foto ya no estaba en el teléfono'};continue}
      const h={apikey:CFG.SUPABASE_KEY,Authorization:'Bearer '+session.access_token,'Content-Type':'image/webp','x-upsert':'false','cache-control':'31536000'};
      let st=0;try{const x=await fetch(String(CFG.SUPABASE_URL).replace(/\/$/,'')+'/storage/v1/object/'+EVI_BUCKET+'/'+r.path,{method:'POST',headers:h,body:b});st=x.status;if(!x.ok&&st!==409){let t='';try{t=await x.text()}catch(e){}if(st===400&&/Duplicate|already exists/i.test(t))st=409}}catch(e){fail=true;break}
      if(st===200||st===201||st===409){r.pend=0;r.ts=Date.now();if(EVI.dirty.indexOf(r.id)<0)EVI.dirty.push(r.id);ok++;eviBlobDel(r.id).catch(()=>{})}
      else{fail=true;r.err=st;break}
    }
  }catch(e){fail=true}
  finally{EVI_BUSY=false;saveEvi();setSync()}
  if(ok){await syncEvi().catch(()=>{});softRender()}
  if(fail){clearTimeout(EVI_T0);EVI_T0=setTimeout(eviPump,60000)}
}
window.addEventListener('online',()=>setTimeout(eviPump,1500));

/* ---- datos de las fotos (tabla evidencias) ---- */
function eviMerge(d){
  if(!d||!d.id||!okId(d.id))return false;const k=EVI.list.findIndex(x=>x.id===d.id);
  if(k<0){EVI.list.push(d);return true}
  const l=EVI.list[k];if(EVI.dirty.indexOf(d.id)>=0||l.pend)return false;
  if(l.hpOnly&&!d.hpOnly){EVI.list[k]=d;return true} /* ya la subió a la nube quien la tomó */
  if((+d.ts||0)>(+l.ts||0)){EVI.list[k]=d;return true}return false;
}
async function syncEvi(){
  if(EVI.noTable)return;
  try{
    const send=EVI.dirty.map(id=>EVI.list.find(r=>r.id===id)).filter(r=>r&&!r.hpOnly&&(!r.pend||(LOCAL.on&&r.hp)));
    for(let i=0;i<send.length;i+=50){
      const part=send.slice(i,i+50),up=b=>sb('/rest/v1/evidencias?on_conflict=id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:b.map(r=>({id:r.id,ts:r.ts,data:LOCAL.on?Object.assign({},r,{err:undefined,hpOnly:undefined}):Object.assign({},r,{pend:undefined,err:undefined,hp:undefined,hpOnly:undefined})}))});
      try{await up(part)}catch(er){if(!er||er.status!==403)throw er;for(const r of part){try{await up([r])}catch(x){if(!x||x.status!==403)throw x}}}
      EVI.dirty=EVI.dirty.filter(id=>!part.some(r=>r.id===id));
    }
    /* v8.45 · A-25: antes bajaba por la hora de la foto (la pone el teléfono): una foto tomada sin señal y subida horas
       después, o de un teléfono con la hora mal puesta, quedaba atrás del corte y los demás nunca la veían. Ahora baja por
       la hora en que la nube la recibió (columna «recibido», supabase-v8.45.sql), por páginas. Sin la columna, sigue como antes. */
    let rows=null;
    if(EVI.inc!==false){
      try{const d=EVI.cur?'&recibido=gt.'+encodeURIComponent(new Date(Date.parse(EVI.cur)-60000).toISOString()):'';
        rows=await sbAll('/rest/v1/evidencias?select=id,ts,data,recibido'+d+'&order=recibido.asc');EVI.inc=true}
      catch(er){if(er&&er.status===400&&EVI.inc!==true&&/recibido/.test(er.msg||'')){EVI.inc=false;rows=null}else throw er}
    }
    const since=Math.max(0,(EVI.since||0)-120000);
    if(!rows)rows=await sbAll('/rest/v1/evidencias?select=id,ts,data&ts=gt.'+since+'&order=ts.asc');
    let mx=EVI.since||0,mr=EVI.cur?Date.parse(EVI.cur):0;rows.forEach(x=>{if(x.data){cleanRec(x.data);if(x.data.pend){if(!LOCAL.on)x.data=null;else{x.data.pend=0;x.data.hpOnly=1;delete x.data.hp}}if(x.data)eviMerge(x.data)}mx=Math.max(mx,+x.ts||0);if(x.recibido){const t=Date.parse(x.recibido);if(t>mr)mr=t}});EVI.since=mx;if(EVI.inc===true&&mr)EVI.cur=new Date(mr).toISOString();
    saveEvi();
  }catch(e){if(e&&(e.status===404||(e.status===400&&/evidencias/.test(e.msg||''))))EVI.noTable=true;else if(e&&e.status!==400)throw e}
}

/* ---- imágenes: URL de blob por foto (la pendiente sale del teléfono; la subida, de Storage con la sesión) ---- */
const EVI_URL=new Map(),EVI_LOADING=new Set();
function eviUrlSet(id,u){const o=EVI_URL.get(id);if(o&&o!==u)try{URL.revokeObjectURL(o)}catch(e){}EVI_URL.set(id,u)}
async function eviFetchBlob(r){
  const dr=EVI_DRAFT.get(r.id);if(dr)return dr.blob;
  if(r.pend){const b=await eviBlobGet(r.id);if(!b)throw new Error('none');return b}
  if(r.hpOnly){if(!LOCAL.on)throw new Error('en la HP');const j=await hubReq('/planta/foto/'+encodeURIComponent(r.id),{timeout:20000});if(!j||!j.b64)throw new Error('none');return b64Blob(j.b64,'image/webp')}
  await ensureSession();
  const x=await fetch(String(CFG.SUPABASE_URL).replace(/\/$/,'')+'/storage/v1/object/authenticated/'+EVI_BUCKET+'/'+r.path,{headers:{apikey:CFG.SUPABASE_KEY,Authorization:'Bearer '+session.access_token}});
  if(!x.ok)throw new Error('HTTP '+x.status);return await x.blob();
}
async function eviLoad(id){
  if(EVI_URL.has(id)||EVI_LOADING.has(id))return;const r=EVI.list.find(x=>x.id===id)||(EVI_DRAFT.get(id)||{}).r;if(!r)return;
  EVI_LOADING.add(id);
  try{const b=await eviFetchBlob(r);eviUrlSet(id,URL.createObjectURL(b));document.querySelectorAll('img[data-evimg="'+id+'"]').forEach(im=>{im.src=EVI_URL.get(id);im.closest('.evth')&&im.closest('.evth').classList.remove('evld')})}
  catch(e){document.querySelectorAll('img[data-evimg="'+id+'"]').forEach(im=>{const t=im.closest('.evth');if(t){t.classList.remove('evld');t.classList.add('everr')}})}
  finally{EVI_LOADING.delete(id)}
}
function eviHydrate(root){(root||document).querySelectorAll('img[data-evimg]').forEach(im=>{const id=im.dataset.evimg;const u=EVI_URL.get(id);if(u){if(im.src!==u)im.src=u}else eviLoad(id)})}
function eviThumb(r,draft){
  const u=EVI_URL.get(r.id);
  return `<button type="button" class="evth${u?'':' evld'}${r.del?' evdel':''}" data-act="evi_open:${r.id}${draft?':d':''}" aria-label="Ver ${esc(EVI_K[r.k]||'foto')}${r.del?' (borrada)':''}"><img data-evimg="${r.id}" alt="" ${u?`src="${u}"`:''}><span class="evk">${r.k==='tk'?'🧾':'📷'}</span>${r.pend?'<span class="evp" title="Pendiente de subir">⏳</span>':r.hpOnly?'<span class="evp" title="La sube a la nube quien la tomó">⏳</span>':''}</button>`;
}

/* ---- caja de fotos (Entrada de Fruta y ventana de destino) ---- */
function eviBtns(key,ctx,ref,k){
  if(EVI_MENU===key+'|'+k)return `<span class="evmenu"><button class="btn sm primary" data-act="evi_cam:${ctx}:${ref}:${k}">📷 Cámara</button><button class="btn sm" data-act="evi_gal:${ctx}:${ref}:${k}">🖼 Galería</button><button class="icon sm" data-act="evi_menu:${ctx}:${ref}:x" aria-label="Cancelar">×</button></span>`;
  return `<button class="btn sm" data-act="evi_menu:${ctx}:${ref}:${k}">${k==='tk'?'🧾 Agregar ticket':'📷 Foto de fruta'}</button>`;
}
function eviBox(ctx,ref,opt){
  opt=opt||{};const key=ctx+'|'+ref,L=ctx==='sal'?[...EVI_DRAFT.values()].map(x=>x.r):eviOf(ctx,ref),can=eviCan()&&!opt.ro,full=L.length>=EVI_MAX;
  if(!L.length&&!can)return '';
  EVI_OPT.set(key,opt);setTimeout(()=>eviHydrate(),0);
  EVI_OPT.set(key,opt);
  return `<div class="evbox" data-evk="${esc(key)}"><div class="evhd"><span class="k">${esc(opt.t||'Fotos y tickets')}</span><small class="note">${L.length?fmt(L.length)+' de '+EVI_MAX:'Hasta '+EVI_MAX}${opt.sub?' · '+esc(opt.sub):''}</small></div>${L.length?`<div class="evrow">${L.map(r=>eviThumb(r,ctx==='sal')).join('')}</div>`:''}${can&&!full?`<div class="pact evbtns">${eviBtns(key,ctx,ref,'fr')}${eviBtns(key,ctx,ref,'tk')}</div>`:''}${can&&full?'<p class="note">Ya tiene '+EVI_MAX+' fotos. Borra una para agregar otra.</p>':''}</div>`;
}
function sdDraftN(){return EVI_DRAFT.size}
function eviDraftClear(){EVI_DRAFT.forEach((x,id)=>{const u=EVI_URL.get(id);if(u)try{URL.revokeObjectURL(u)}catch(e){}EVI_URL.delete(id)});EVI_DRAFT.clear()}
/* al registrar la salida: las fotos quedan ligadas al grupo de movimientos (g) y entran a la cola de subida */
async function eviDraftCommit(g,meta){
  const D=[...EVI_DRAFT.values()];EVI_DRAFT.clear();if(!D.length)return 0;let n=0;
  for(const x of D){const r=Object.assign(x.r,meta,{ref:g,pend:1});r.path=eviPath(r);
    try{await eviBlobPut(r.id,x.blob);EVI.list.push(r);n++}catch(e){toast('No se pudo guardar una foto en este teléfono')}}
  saveEvi();eviPump();return n;
}

/* ---- visor ---- */
let EVV=null; /* {ids,i,draft,del:''} */
function eviViewIds(id,draft){
  if(draft)return [...EVI_DRAFT.keys()];
  const r=EVI.list.find(x=>x.id===id);if(!r)return [id];return eviOf(r.ctx,r.ref,true).filter(x=>!x.del||x.id===id).map(x=>x.id);
}
function eviRec(id){return EVI.list.find(x=>x.id===id)||(EVI_DRAFT.get(id)||{}).r}
function eviView(){
  let ov=document.getElementById('evov');
  if(!EVV){if(ov)ov.remove();return}
  if(!ov){ov=document.createElement('div');ov.id='evov';ov.className='evov';ov.setAttribute('role','dialog');ov.setAttribute('aria-modal','true');ov.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(e.target===ov){EVV=null;eviView();return}if(!el)return;const p=el.dataset.act.split(':');eviAct(p[0],p,el)});
    ov.addEventListener('input',e=>{if(EVV&&e.target.id==='evv-why')EVV.why=e.target.value});document.body.appendChild(ov)}
  const id=EVV.ids[EVV.i],r=eviRec(id);if(!r){EVV=null;eviView();return}
  const u=EVI_URL.get(id),n=EVV.ids.length,canDel=EVV.draft||eviDelCan(r);
  const info=[EVI_K[r.k],r.t?EVI_T[r.t]:'',r.lab||'',fmtTs(r.at),r.by||'',r.w?r.w+'×'+r.h+' px · '+eviKb(r.sz||0)+' WebP':'',r.pend?'pendiente de subir':''].filter(Boolean).map(esc).join(' · ');
  ov.innerHTML=`<div class="evvw"><div class="evvh"><b>${esc(EVI_K[r.k]||'Foto')}${n>1?' · '+(EVV.i+1)+' de '+n:''}</b><button class="icon" data-act="evi_close" aria-label="Cerrar">×</button></div>
<div class="evvi" id="evvi">${u?`<img src="${u}" alt="${esc(EVI_K[r.k]||'Foto')}" draggable="false">`:'<p class="note">Cargando…</p>'}${n>1?`<button class="evnav evl" data-act="evi_nav:-1" aria-label="Anterior">‹</button><button class="evnav evr" data-act="evi_nav:1" aria-label="Siguiente">›</button>`:''}</div>
${u?`<div class="evzb" role="group" aria-label="Acercar o alejar"><button class="btn sm" data-act="evi_z:-1" aria-label="Alejar">−</button><button class="btn sm" data-act="evi_z:0" id="evzp" aria-label="Ajustar a la pantalla">Ajustar</button><button class="btn sm" data-act="evi_z:1" aria-label="Acercar">+</button><small class="note">Pellizca, usa la rueda o doble toque para acercar; arrastra para moverte.</small></div>`:''}
<p class="note evinf">${info}</p>${r.del?`<p class="warnbox">Borrada por ${esc(r.del.by||'—')} el ${esc(fmtTs(r.del.at))}. Motivo: ${esc(r.del.why||'—')}</p>`:''}
${EVV.del?`<label class="fld" for="evv-why"><span>¿Por qué se borra? (obligatorio)</span><textarea class="in txt" id="evv-why" rows="2" placeholder="Ej.: foto equivocada, era de otro productor">${esc(EVV.why||'')}</textarea></label><div class="srow2"><button class="btn" data-act="evi_delx">Cancelar</button><button class="btn danger" data-act="evi_delok">Borrar foto</button></div>`
:`<div class="srow2">${!r.del&&u?`<button class="btn primary" data-act="evi_dl">Descargar JPG</button>`:''}${canDel&&!r.del?`<button class="btn danger" data-act="evi_del">Borrar…</button>`:''}</div>`}</div>`;
  if(!u)eviLoad(id).then(()=>{if(EVV&&EVV.ids[EVV.i]===id)eviView()});else eviZoomInit();
  if(EVV.del){const t=document.getElementById('evv-why');if(t&&document.activeElement!==t)t.focus()}
}
async function eviJpg(id){
  const r=eviRec(id);if(!r)return;let u=EVI_URL.get(id);if(!u){await eviLoad(id);u=EVI_URL.get(id)}if(!u){toast('No se pudo cargar la foto');return}
  const im=new Image();await new Promise((res,rej)=>{im.onload=res;im.onerror=rej;im.src=u});
  const cv=document.createElement('canvas');cv.width=im.naturalWidth;cv.height=im.naturalHeight;const c=cv.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,cv.width,cv.height);c.drawImage(im,0,0);
  const b=await new Promise(res=>cv.toBlob(res,'image/jpeg',0.92));try{cv.width=cv.height=0}catch(e){}
  const d=new Date(r.at),st=d.getFullYear()+pad(d.getMonth()+1,2)+pad(d.getDate(),2)+'_'+pad(d.getHours(),2)+pad(d.getMinutes(),2);
  const nm=fileSafe([r.k==='tk'?'Ticket':'Fruta',r.t?EVI_T[r.t]:'',r.lab||'',st].filter(Boolean).join('_'))+'.jpg';
  await saveFile(nm,b,EVI_K[r.k]);
}
async function eviDelete(id,why){
  if(EVV&&EVV.draft){const u=EVI_URL.get(id);if(u)try{URL.revokeObjectURL(u)}catch(e){}EVI_URL.delete(id);EVI_DRAFT.delete(id);return true}
  const r=EVI.list.find(x=>x.id===id);if(!r||!eviDelCan(r))return false;
  r.del={by:whoName(),at:Date.now(),why:why};r.ts=Date.now();
  if(r.pend){r.pend=0;eviBlobDel(id).catch(()=>{});EVI.list=EVI.list.filter(x=>x.id!==id)}
  else{if(EVI.dirty.indexOf(id)<0)EVI.dirty.push(id);
    if(cfgOK()&&session)try{await ensureSession();await fetch(String(CFG.SUPABASE_URL).replace(/\/$/,'')+'/storage/v1/object/'+EVI_BUCKET+'/'+r.path,{method:'DELETE',headers:{apikey:CFG.SUPABASE_KEY,Authorization:'Bearer '+session.access_token}})}catch(e){}}
  saveEvi();logAdd({k:'note',where:'Evidencias',ctx:{t:'e',id:r.ref,cod:r.lab||''},lab:EVI_K[r.k]+' borrada',o:fmtTs(r.at),n:why});
  const u=EVI_URL.get(id);if(u)try{URL.revokeObjectURL(u)}catch(e){}EVI_URL.delete(id);
  if(canAuto())syncEvi().catch(()=>{});return true;
}
function eviAct(act,p,el){
  if(act==='evi_menu'){EVI_MENU=p[3]==='x'?'':p[1]+'|'+p[2]+'|'+p[3];eviBoxRefresh();return}
  if(act==='evi_cam'||act==='evi_gal'){
    if(!eviCan())return;const ctx=p[1],ref=p[2],k=p[3];let meta={},lab='';
    if(ctx==='ent'){const e=INV.entradas.find(x=>x.id===ref);if(!e)return;lab=(e.codigo?pad(e.codigo,3)+' ':'')+(e.nombre||'');meta={wk:wkOfDate(e.fecha),lab:lab,f:e.fecha}}
    EVI_IN={ctx:ctx,ref:ref,k:k,meta:meta,lab:lab};EVI_MENU='';
    const inp=eviFileInput(act==='evi_cam');inp.click();setTimeout(eviBoxRefresh,50);return;
  }
  if(act==='evi_open'){EVV={ids:eviViewIds(p[1],p[2]==='d'),i:0,draft:p[2]==='d',del:false,why:''};EVV.i=Math.max(0,EVV.ids.indexOf(p[1]));eviView();return}
  if(!EVV)return;
  if(act==='evi_close'){EVV=null;eviView();return}
  if(act==='evi_z'){const d=+p[1];if(!d)eviZ.set(1,0,0);else eviZ.by(d>0?1.6:1/1.6);return}
  if(act==='evi_nav'){EVV.i=(EVV.i+(+p[1])+EVV.ids.length)%EVV.ids.length;EVV.del=false;eviView();return}
  if(act==='evi_dl'){eviJpg(EVV.ids[EVV.i]).catch(()=>toast('No se pudo descargar'));return}
  if(act==='evi_del'){EVV.del=true;EVV.why='';eviView();return}
  if(act==='evi_delx'){EVV.del=false;eviView();return}
  if(act==='evi_delok'){
    const why=String(EVV.why||'').trim();if(!EVV.draft&&why.length<4){toast('Escribe por qué se borra la foto');return}
    const id=EVV.ids[EVV.i];eviDelete(id,why).then(ok=>{if(!ok){toast('No tienes permiso para borrar esta foto');return}toast('Foto borrada');EVV.ids=EVV.ids.filter(x=>x!==id);EVV.del=false;if(!EVV.ids.length||!EVV.draft){EVV=null}else EVV.i=Math.min(EVV.i,EVV.ids.length-1);eviView();eviBoxRefresh()});return;
  }
}
document.addEventListener('keydown',e=>{if(!EVV)return;if(e.key==='Escape'){EVV=null;eviView()}else if(!EVV.del&&EVV.ids.length>1&&(e.key==='ArrowLeft'||e.key==='ArrowRight')){EVV.i=(EVV.i+(e.key==='ArrowLeft'?-1:1)+EVV.ids.length)%EVV.ids.length;eviView()}});

/* ---- zoom del visor: pellizco (dos dedos), rueda del ratón, doble toque o doble clic, y arrastrar para moverse ---- */
const eviZ={s:1,x:0,y:0,max:6,
  el(){return document.getElementById('evvi')},img(){const b=this.el();return b&&b.querySelector('img')},
  apply(){const im=this.img(),b=this.el();if(!im||!b)return;
    const W=b.clientWidth,H=b.clientHeight,w=im.offsetWidth*this.s,h=im.offsetHeight*this.s,mx=Math.max(0,(w-W)/2),my=Math.max(0,(h-H)/2);
    this.x=Math.max(-mx,Math.min(mx,this.x));this.y=Math.max(-my,Math.min(my,this.y));
    im.style.transform=`translate(${this.x}px,${this.y}px) scale(${this.s})`;b.classList.toggle('evzin',this.s>1.01);
    const z=document.getElementById('evzp');if(z)z.textContent=this.s>1.01?Math.round(this.s*100)+' %':'Ajustar'},
  set(s,x,y){this.s=Math.max(1,Math.min(this.max,s));this.x=this.s>1?x:0;this.y=this.s>1?y:0;this.apply()},
  /* acercar alrededor de un punto (cx,cy relativos al centro del cuadro) para que lo que está bajo el dedo se quede ahí */
  at(f,cx,cy){const s0=this.s,s1=Math.max(1,Math.min(this.max,s0*f)),k=s1/s0;this.set(s1,cx-(cx-this.x)*k,cy-(cy-this.y)*k)},
  by(f){this.at(f,0,0)}
};
function eviZoomInit(){
  const b=eviZ.el(),im=eviZ.img();if(!b||!im||b.dataset.zi)return;b.dataset.zi='1';eviZ.s=1;eviZ.x=eviZ.y=0;
  const setMax=()=>{const r=im.naturalWidth/Math.max(1,im.offsetWidth);eviZ.max=Math.max(4,Math.min(12,r*2));eviZ.apply()};
  if(im.complete)setMax();else im.addEventListener('load',setMax,{once:true});
  const P=new Map();let g=null,tap=0;
  const rel=e=>{const r=b.getBoundingClientRect();return [e.clientX-r.left-r.width/2,e.clientY-r.top-r.height/2]};
  b.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;b.setPointerCapture(e.pointerId);P.set(e.pointerId,rel(e));
    if(P.size===2){const [a,c]=[...P.values()];g={d:Math.hypot(a[0]-c[0],a[1]-c[1])||1,s:eviZ.s,x:eviZ.x,y:eviZ.y,m:[(a[0]+c[0])/2,(a[1]+c[1])/2]}}
    else if(P.size===1){const now=Date.now(),q=rel(e);if(now-tap<300){eviZ.s>1.01?eviZ.set(1,0,0):eviZ.at(2.5,q[0],q[1]);tap=0;g=null;return}tap=now;g={p:q,x:eviZ.x,y:eviZ.y}}});
  b.addEventListener('pointermove',e=>{if(!P.has(e.pointerId)||!g)return;P.set(e.pointerId,rel(e));
    if(P.size>=2&&g.d){const [a,c]=[...P.values()],d=Math.hypot(a[0]-c[0],a[1]-c[1])||1,m=[(a[0]+c[0])/2,(a[1]+c[1])/2];
      const s1=Math.max(1,Math.min(eviZ.max,g.s*d/g.d)),k=s1/g.s;eviZ.set(s1,m[0]-(g.m[0]-g.x)*k,m[1]-(g.m[1]-g.y)*k)}
    else if(P.size===1&&g.p&&eviZ.s>1.01){const q=P.get(e.pointerId);eviZ.x=g.x+q[0]-g.p[0];eviZ.y=g.y+q[1]-g.p[1];eviZ.apply()}});
  const up=e=>{P.delete(e.pointerId);if(P.size===1){const q=[...P.values()][0];g={p:q,x:eviZ.x,y:eviZ.y}}else if(!P.size)g=null};
  b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);
  b.addEventListener('wheel',e=>{e.preventDefault();const q=rel(e);eviZ.at(Math.exp(-e.deltaY*(e.ctrlKey?0.01:0.0025)),q[0],q[1])},{passive:false});
  b.addEventListener('dblclick',e=>{e.preventDefault()});
}

/* ---- Evidencias de cargas (Recepción › Segundas y Excel de la semana) ---- */
function eviGrpAnul(g){
  /* una salida está anulada cuando todos sus movimientos (almMov o jugEnv con g) están anulados */
  let n=0,a=0;const chk=x=>{['almMov','jugEnv'].forEach(f=>{const m=x&&x[f];if(!m)return;Object.keys(m).forEach(id=>{const z=m[id];if(z&&z.g===g){n++;if(z.anul)a++}})})};
  orders.forEach(o=>{if(!o.deleted)(o.productores||[]).forEach(chk)});INV.entradas.forEach(chk);
  return n>0&&a===n;
}
function eviSalWeek(wk,emp){
  const G=new Map();EVI.list.forEach(r=>{if(r.ctx!=='sal'||r.del||r.wk!==wk)return;if(emp&&emp!=='ALL'&&Array.isArray(r.emps)&&r.emps.length&&r.emps.indexOf(emp)<0)return;
    let g=G.get(r.ref);if(!g){g={g:r.ref,t:r.t,at:r.at,by:r.by,tk:r.tk||'',n:r.n||0,kg:r.kg||0,cods:r.cods||[],prods:r.prods||[],emps:r.emps||[],fotos:[]};G.set(r.ref,g)}g.fotos.push(r);if(r.at<g.at)g.at=r.at});
  return [...G.values()].map(g=>Object.assign(g,{anul:eviGrpAnul(g.g),fotos:g.fotos.sort((a,b)=>a.at-b.at)})).sort((a,b)=>a.at-b.at);
}
function eviSalHtml(wk,emp){
  const L=eviSalWeek(wk,emp);
  if(!L.length)return '<p class="note">Sin fotos de salidas en esta semana. Se agregan en Almacén, en Venta nacional, Torreón, Juguera o Pasar a desecho, antes de registrar.</p>';
  setTimeout(()=>eviHydrate(),0);
  return '<div class="cgrid">'+L.map(g=>`<div class="panel evsal${g.anul?' anul':''}"><div class="kv"><span><b>${esc(EVI_T[g.t]||g.t)}</b><small> · ${esc(fmtTs(g.at))} · ${esc(g.by||'—')}${g.anul?' · <b>anulada</b>':''}</small></span><b>${fmt(g.n)} cajas</b></div><p class="note">${g.tk?'Folio '+esc(g.tk)+' · ':''}${esc(g.cods.join(', '))}${g.prods.length?' · '+esc(g.prods.slice(0,6).join(', '))+(g.prods.length>6?' y '+(g.prods.length-6)+' más':''):''}${g.kg?' · '+fmt(g.kg,1)+' kg báscula':''}</p><div class="evrow">${g.fotos.map(r=>eviThumb(r)).join('')}</div></div>`).join('')+'</div>';
}
/* miniaturas en JPG para el Excel (Excel no muestra WebP) */
async function eviXlThumbs(L){
  const out=new Map(),all=[].concat(...L.map(g=>g.fotos));
  for(const r of all){try{const b=await eviFetchBlob(r),u=URL.createObjectURL(b),im=new Image();await new Promise((res,rej)=>{im.onload=res;im.onerror=rej;im.src=u});
    const s=Math.min(1,520/Math.max(im.naturalWidth,im.naturalHeight)),w=Math.round(im.naturalWidth*s),h=Math.round(im.naturalHeight*s),cv=document.createElement('canvas');cv.width=w;cv.height=h;const c=cv.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,w,h);c.drawImage(im,0,0,w,h);
    out.set(r.id,{b64:cv.toDataURL('image/jpeg',0.85).split(',')[1],w:w,h:h});URL.revokeObjectURL(u);cv.width=cv.height=0}catch(e){}}
  return out;
}

